INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('44670945-e52d-4537-bb77-d4e5b5c70273'::uuid,'668893b2-6a90-401c-959d-c497d322cc94'::uuid,'af9ffb3f-97b8-4381-8840-145ec9c1970a'::uuid,'related_to',6.0,'Both methods were essential for developing early understanding but free flight provided broader insights into natural dynamics, influencing designs like wing shapes and configurations','{"контекст": "Free flight и drop tests были ключевыми методами в раннем понимании динамических процессов, но free flight предоставило более широкие знания о естественных динамических явлениях, влияя на дизайн элементов, такие как формы крыльев и их конфигурации.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба метода были необходимы для развития раннего понимания, но free flight дал более обширные знания о естественных динамических процессах, что повлияло на дизайн элементов, таких как формы крыльев и их конфигурации.", "краткое_описание": "Free flight предоставило более широкие знания о естественных динамических процессах, чем drop tests."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5c650720-5e61-4ae5-b094-35c377c09888'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'5309b098-2ec4-482e-8abb-0fdbfd133545'::uuid,'related_to',18.0,'The Wright Brothers’ work focused on both lift generation and stability; their innovations in wing design significantly enhanced the ability to generate lift','{"контекст": "Работа Вингер братьев сосредоточилась как на генерации подъемной силы, так и на устойчивости. Их инновации в дизайне крыльев значительно повысили способность генерировать подъемную силу.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Их работы и патенты указывают на то, что они активно исследовали и разрабатывали методы увеличения подъемной силы для самолетов.", "краткое_описание": "Вингер братья занимались исследованиями генерации подъемной силы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b8b024ac-ee3f-49dd-9008-2f2a9fa1d5e5'::uuid,'ac090309-675b-4a19-b7dc-2e73b5afa9eb'::uuid,'85627fd9-a7ab-4ed4-8dd2-0ec1c1f77676'::uuid,'related_to',6.0,'Leonardo observed vortices around bridge piers, which influenced his understanding of fluid dynamics; this knowledge could be indirectly related to the lever system design','{"контекст": "Леонардо да Винчи наблюдал вихри вокруг опор моста, что повлияло на его понимание динамики жидкостей; это знание могло быть связано с дизайном рычаговых систем.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Тексты Леонардо да Винчи описывают наблюдения вихрей и их связь с физическими явлениями, а также его работы по механике включают элементы рычажных систем.", "краткое_описание": "Наблюдения Леонардо о вихрях влияют на понимание рычаговых систем."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0fb7bb75-0261-40b7-9b51-7a63e57d9e07'::uuid,'85627fd9-a7ab-4ed4-8dd2-0ec1c1f77676'::uuid,'c3a8df2c-a3ac-440c-a972-1e29603077f1'::uuid,'related_to',4.0,'Both the lever system by Leonardo and the self-evaluation of the Wright brothers involved critical thinking to improve design and operation in their respective works','{"контекст": "Связь между системой рычагов Леонардо да Винчи и самооценкой Уильяма и Орвилла Уиттакеров в контексте самосовершенствования и критического мышления в инженерии.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба случая демонстрируют использование критического мышления для улучшения концепций: система рычагов Леонардо была результатом тщательного анализа, а самооценка Уиттакеров показала их готовность к самокритике и улучшению своих летательных аппаратов.", "краткое_описание": "Критическое мышление использовалось для улучшения концепций в обеих работах."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b3e84c50-d7fe-494f-8b5e-b47b5c72bce7'::uuid,'afc5aaeb-46f7-4505-843a-6388feaf8859'::uuid,'8b5e612c-fc66-4a29-9a0e-ebe2d88a7680'::uuid,'related_to',4.0,'(D)a vinci’s unknown theories were likely related to the (C)irculat(i)o(n) (T)heory of (L)ift, both involving fluid dynamics principles that could have had an indirect significant impact.','{}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics'),
	 ('8ea2fd52-38b9-44f4-9bdc-4a05aa2e6a4c'::uuid,'b6adbf3b-0f2f-4c99-a64a-0a4a0f4d4918'::uuid,'a38a7f6a-5836-4593-bad8-b4a978e79de7'::uuid,'related_to',9.0,'Modern (S)T(S)tatic and (D)ynam(D)aical analyses are interrelated; the former supports understanding of initial state restorations, while the latter measures long-term behavior post disturbance in aircrafts.','{"контекст": "STATIC STABILITY ANALYSIS и DYNAMIC STABILITY ANALYSIS связаны тем, что оба являются ключевыми аспектами анализа стабильности самолетов, но они охватывают разные временные масштабы: статический анализ фокусируется на начальном состоянии системы после возмущения, в то время как динамический анализ изучает долгосрочные поведенческие характеристики.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Modern (S)T(S)tatic and (D)ynam(D)aical analyses are interrelated; the former supports understanding of initial state restorations, while the latter measures long-term behavior post disturbance in aircrafts.", "краткое_описание": "STATIC STABILITY ANALYSIS и DYNAMIC STABILITY ANALYSIS связаны тем, что они оба важны для анализа стабильности самолетов, но охватывают разные временные масштабы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8015b8fe-3e4c-4760-b211-0172fc672df6'::uuid,'afc5aaeb-46f7-4505-843a-6388feaf8859'::uuid,'6b817ce2-06d2-4bb8-acea-5f666880c9f7'::uuid,'related_to',1.0,'(D)a vinci’s unknown theories on fluid dynamics might have influenced (C)ailey by a different route, as both explored fundamental principles indirectly connected through time and recognition delay.','{"контекст": "Да Винчи и Кэли оба исследовали фундаментальные принципы в области динамики жидкостей, хотя их работы были независимыми и произошли через несколько веков друг от друга.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.85, "доказательства": "(D)аВинчи оставил неопубликованные теории о динамике течения жидкости, которые могли оказывать влияние на (C)элии, хотя это было через время и с определенной задержкой признания.", "краткое_описание": "Да Винчи неопубликованные теории могли влиять на Кэли."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d0c567fd-a49f-4f9c-a9dd-335ebf2817b6'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'ede64bd3-c680-4f14-be3f-25c87a24a8cc'::uuid,'related_to',8.0,'The Wright brothers were skeptical of this value and preferred to verify it for themselves, highlighting the need for accurate data in aircraft design','{"контекст": "В контексте разработки авиационных технологий, Вингфлаеры были скептичны относительно значения коэффициента Смейтона и предпочитали проверить его самостоятельно, подчеркивая важность точных данных в проектировании самолетов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brothers were skeptical of this value and preferred to verify it for themselves, highlighting the need for accurate data in aircraft design", "краткое_описание": "Вингфлаеры были скептичны относительно коэффициента Смейтона и предпочитали проверить его самостоятельно."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3330469c-9ddd-4172-8ba6-44d81f44eb4d'::uuid,'af9ffb3f-97b8-4381-8840-145ec9c1970a'::uuid,'0c807528-cf1d-4a7b-871a-9e6adacf1270'::uuid,'related_to',4.0,'In the context provided, Drop Tests primarily involve investigating free fall dynamics without delving into comprehensive analyses of lift or drag. This technique is crucial for understanding the behavior of objects in a state of free fall, particularly focusing on their motion and interactions with gravitational forces during such a test. The primary focus in these drop tests is to assess various aspects of free-falling objects rather than conducting detailed aerodynamic or hydrodynamic studies','{"контекст": "Drop Tests 主要涉及自由落体动力学的研究，而不深入分析升力或阻力。这种技术对于理解在自由落体状态下物体的行为至关重要，特别是关注其运动和与重力作用的相互作用。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "In the context provided, Drop Tests primarily involve investigating free fall dynamics without delving into comprehensive analyses of lift or drag.", "краткое_описание": "Drop Tests 关注自由落体行为，而非详细气动或水动力研究。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f95e5cef-609e-49fe-8794-0380ae4d3e52'::uuid,'0c807528-cf1d-4a7b-871a-9e6adacf1270'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'related_to',8.0,'Both systems were used in the investigation of fluid dynamics, but wind tunnels provided more controlled environments for detailed measurements','{"контекст": "FREE AND SEMI-FREE FLIGHT и WIND TUNNELS оба используются для исследования динамики жидкостей, но туннели ветра обеспечивают более контролируемую среду для точных измерений.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе системы были применены в исследовании динамических процессов в жидкостях; однако, как отмечено, туннели ветра предоставляли более контролируемые условия для детального анализа.", "краткое_описание": "FREE AND SEMI-FREE FLIGHT и WIND TUNNELS оба используются для исследования динамики жидкостей, но туннели ветра обеспечивают более контролируемую среду."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('4e2e4bcd-8299-4c2a-a9b9-40684a541c9d'::uuid,'7c3082e0-864c-43ae-a2c3-4318f96962dd'::uuid,'7f92cf11-7177-483d-9d22-992c92341d14'::uuid,'related_to',6.0,'Both devices can simulate similar conditions by creating controlled airflows, though Whirling arms do so directly with rotation, while free wind trials rely on external winds','{"контекст": "Whirling arms и Free Wind Trials оба используют создание контролируемых воздушных потоков для имитации схожих условий, хотя Whirling arms генерируют их путем вращения, а Free Wind Trials полагаются на внешние ветры.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе технологии предназначены для создания подобных воздушных условий, но методы их реализации различны.", "краткое_описание": "Whirling arms и Free Wind Trials имитируют схожие условия путем создания контролируемых воздушных потоков."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('cdbdca39-3928-420b-a22d-916148db67f4'::uuid,'49b21c31-38e3-4944-89fa-121e0dbc9755'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'related_to',8.0,'While theoretical advances led to better understanding, practical investigations often lagged behind, with wind tunnels being a more concrete realization of theoretical constructs from this field','{"контекст": "Теоретические разработки в области механики жидкостей привели к лучшему пониманию феноменов, но практические исследования, такие как ветровые туннели, стали более реалистичным воплощением этих теорий.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Теоретические достижения в механике жидкостей легли основой для создания ветровых туннелей, которые позволяют проводить эксперименты на основе этих концепций.", "краткое_описание": "Теория механики жидкостей связана с использованием ветровых туннелей для практической реализации и проверки теорий."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7eb2b87e-a56e-443a-963c-925d80f77c0a'::uuid,'afc5aaeb-46f7-4505-843a-6388feaf8859'::uuid,'adade9ee-6d39-4a40-8f9f-b2ab245a7608'::uuid,'предок-потомок',3.0,'(D)a vinci’s unknown theories may have contributed indirectly to the understanding later formalized in (D)egrees (O)f (F)reedom concept, which addresses the complexity of aircraft movement and control.','{"контекст": "Связь между теориями Да Винчи о движении течения вокруг тел и концепцией ''6 степеней свободы'' основывается на возможном влиянии ранних идей Да Винчи на развитие более поздней концепции, которая используется в авиационной индустрии для описания сложности движения и управления самолетами.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(D)a vinci’s unknown theories may have contributed indirectly to the understanding later formalized in (D)egrees (O)f (F)reedom concept, which addresses the complexity of aircraft movement and control.", "краткое_описание": "Теории Да Винчи могут быть предками концепции ''6 степеней свободы''."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('206002be-7ad7-4bbf-98db-056ed97ba316'::uuid,'3773947e-5a7e-45fd-af90-196fdcc0090f'::uuid,'6b5460e7-f5be-40b7-89c8-d3af570d185e'::uuid,'причина-следствие',9.0,'Ludwig Prandtl mathematically analyzed finite wings, resolving misunderstandings about their behavior and performance. This was a crucial step after the empirical work of Lanchester in addressing fundamental aspects of modern aerodynamics.','{"контекст": "Людвиг Прандтль математически проанализировал конечные крыла, разрешив противоречия в их поведении и эффективности. Это было важным шагом после эмпирических исследований Ланчестера.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Прандтль использовал математические методы для анализа конечных крыл, что позволило разрешить противоречия в их поведении и эффективности. Это было основным шагом после эмпирических исследований Ланчестера.", "краткое_описание": "Прандтль математически проанализировал конечные крыла, разрешив противоречия в их поведении и эффективности."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('91ed72be-5ba6-4eb4-bcff-ffba10f8bd17'::uuid,'2847023e-7e25-410e-971d-fe875c9696f9'::uuid,'85a65f75-31ed-4858-89b3-d116fef6a9a2'::uuid,'related_to',4.0,'Glider flights use natural wind to simulate flight conditions, making them directly reliant on this component of nature in aerodynamic testing','{"контекст": "Glider flights rely on natural wind to simulate realistic flight conditions, which is essential for aerodynamic testing and training pilots.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The success of glider flights depends heavily on the presence of natural wind, as it provides the necessary lift and maneuverability that are crucial for both testing aircraft designs and training pilots in real-world conditions.", "краткое_описание": "Glider flights use natural wind to simulate flight conditions."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7507cfd5-675b-411c-9db9-ef33edc56175'::uuid,'5309b098-2ec4-482e-8abb-0fdbfd133545'::uuid,'1b23fc1b-8480-4084-908b-28e3c782a5fc'::uuid,'причина-следствие',12.0,'Wind on the wing creates lift, an upward mechanical force','{"контекст": "Связь между LIFT и WING описывает физический процесс, при котором движение воздуха (wind) создает подъемную силу (lift), которая действует вертикально вверх на крыло (wing) самолета или другого летательного аппарата.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wind on the wing creates lift, an upward mechanical force. Это утверждение является основополагающим принципом аэродинамики и подтверждается многими научными исследованиями в области авиации и космонавтики.", "краткое_описание": "Wind создает Lift на Wing"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b33b2e75-1a10-4b46-9b20-e382c64e9223'::uuid,'aefce5fd-b673-4e42-bcee-567368880058'::uuid,'a4ae708e-9167-4f6d-b282-0b819029b0df'::uuid,'related_to',3.0,'Both pioneers were working on different aspects of early aviation around the same time; Cayley focused more on aerodynamics, while Giffard’s efforts revolved more around propulsion using steam power."','{"контекст": "CAYLEY''S GLIDER и GIFFARD''S AIRSHIP都是19世纪航空领域的先驱，尽管他们在技术方面有所不同，但都在探索早期飞行的可能性。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Cayley专注于空气动力学的研究，而Giffard则致力于使用蒸汽动力推进的飞艇。他们的工作表明，当时航空领域存在多种尝试和创新。", "краткое_описание": "两者都在19世纪为早期飞行做出了贡献。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('60283ecd-eff7-48ef-95b9-406edcb376b5'::uuid,'a4ae708e-9167-4f6d-b282-0b819029b0df'::uuid,'1d59a3e9-a814-4ebd-88cb-b9906143c3df'::uuid,'related_to',4.0,'"Both were early attempts at lighter-than-air and heavier-than-air flights using steam power to some degree, representing parallel efforts in the development of aviation as a practical means of travel."','{"контекст": "Обе технические разработки были попытками использовать паровую энергию для поддержания и управления полетами воздушных и наземных объектов в начале развития авиации как способа передвижения.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Both were early attempts at lighter-than-air and heavier-than-air flights using steam power to some degree, representing parallel efforts in the development of aviation as a practical means of travel.\"", "краткое_описание": "Связь между GIFFARD''S AIRSHIP и DU TEMPLE''S STEAM POWERED MACHINE через использование паровой энергии для полетов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('59f59cfe-ab84-45c6-94fa-e1ddbc17c7c9'::uuid,'92c494f6-b7bf-47cd-88ee-5c5ddd456bb7'::uuid,'e6e72fd7-1557-411b-be62-80a3ae445762'::uuid,'related_to',9.0,'Hiram Maxim designed the first steam-powered monoplane capable of lifting off but lacking control','{"контекст": "Hiram Maxim разработал первый паровой моноплан, который смог подняться в воздух, но не имел системы управления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это утверждение основано на исторических данных о работах Hiram Maxim по авиации и его проекте парового моноплана.", "краткое_описание": "Hiram Maxim разработал первый паровой моноплан, который смог подняться в воздух."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('df9fe70d-e663-4890-ab97-8e82a12294e3'::uuid,'0d0c09f7-b4bf-48fd-b9de-372a40770084'::uuid,'e10de561-fd5b-4543-b6ec-ae67a9c4fcd8'::uuid,'related_to',8.0,'Inspiration from Wrights prompted Dumont to make the first European manned flight, both had significant early flights during 1903-1906','{"контекст": "Связь между Wright Brothers'' First Powered Glider и Santos Dumont связана тем, что вдохновение от работ братьев Уотерс привело Думента к первому европейскому управляемому полету. Обе сущности имели значимые полеты в период 1903-1906 годов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Инспирация от братьев Уотерс побудила Думента к созданию первого управляемого полета в Европе, что подтверждается историческими источниками. Обе сущности активно занимались авиационными исследованиями в указанное время.", "краткое_описание": "Вдохновение Думента от работ братьев Уотерс"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('2dde756f-35ef-4507-83c9-49adffd78bc6'::uuid,'f8f444e7-bff1-40af-8290-176e6de37b48'::uuid,'a6b8617e-1ed4-4b4c-8053-cd3536addf78'::uuid,'related_to',4.0,'Their respective contributions span from foundational experiments to those using advanced mechanisms, both aiming to refine experimental methods','{"контекст": "NEWTON и EIFFEL оба внесли значительный вклад в развитие науки, хотя их области исследования различны. Их работы взаимодействуют через общую цель улучшения методов экспериментального исследования.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе личности известны своими основополагающими экспериментами и использованием продвинутых механизмов для достижения более точных результатов. Их работы часто рассматриваются в контексте истории науки как примеры тщательного подхода к исследованию.", "краткое_описание": "Обе личности улучшили методы экспериментального исследования"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('79bcd43b-06cb-4840-bd3f-1a994843dd25'::uuid,'2847023e-7e25-410e-971d-fe875c9696f9'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'related_to',3.0,'While the latter provides control over airflow conditions, both aim to understand the effects of air movement on aerial objects (towers can experience natural winds as well)','{"контекст": "Обе сущности связаны тем, что они оба изучают влияние воздушных потоков на объекты. Ветровые туннели позволяют контролировать условия воздушного потока, в то время как естественные ветры также могут влиять на структуры.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе сущности связаны тем, что они оба изучают влияние воздушных потоков на объекты. Ветровые туннели позволяют контролировать условия воздушного потока, в то время как естественные ветры также могут влиять на структуры.", "краткое_описание": "Обе сущности изучают влияние воздушных потоков на объекты."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ece44f09-3248-496a-9b7b-c3a7e3caaaa1'::uuid,'95a1d74c-af51-4cb3-9b35-79435b7b5532'::uuid,'85a65f75-31ed-4858-89b3-d116fef6a9a2'::uuid,'related_to',2.0,'Though differently implemented, towed bodies and glider flights share a common purpose in testing aerodynamic principles and forces through controlled and natural means respectively','{"контекст": "TOWED BODIES и GLIDER FLIGHTS оба используются для исследования аэродинамических принципов, но с разными методами: TOWED BODIES через привязку к другим объектам, а GLIDER FLIGHTS — через свободное полетное движение.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе формы тестирования основаны на контролируемом и естественном исследовании аэродинамики, что подтверждается их использованием в авиационной индустрии для разработки новых технологий и материалов.", "краткое_описание": "Обе формы используются для тестирования аэродинамических принципов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ad1e0841-e5ad-44b5-919e-08d8298820bf'::uuid,'b93c7df3-79bc-4f48-9af3-f58613b549c8'::uuid,'27fc0a5a-8446-4176-8e35-36b0b40ffdca'::uuid,'related_to',4.0,'The mass shapes varied to be tested on pendulums, impacting resistance readings distinctly between different materials in air and water','{"контекст": "Массовые формы различаются для тестирования на маячках, что влияет на уникальные показания сопротивления в зависимости от материалов и среды (воздух или вода).", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The mass shapes varied to be tested on pendulums, impacting resistance readings distinctly between different materials in air and water.", "краткое_описание": "Массовые формы влияют на показания сопротивления маячков в зависимости от материала и среды."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3476d806-e376-43cf-8cf2-8633a8c46ec7'::uuid,'27fc0a5a-8446-4176-8e35-36b0b40ffdca'::uuid,'0d70351a-1995-46da-8eba-3f93dfcbaf84'::uuid,'related_to',2.0,'Different shapes could produce varied results depending on whether the tests were conducted in air or water, reflecting fluid properties influencing outcomes','{"контекст": "Разные формы могут давать разные результаты в зависимости от того, проводятся ли испытания в воздухе или воде, что подчеркивает влияние свойств жидкости на исходы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Исследования показывают, что форма объекта играет ключевую роль в его поведении в различных средах, таких как воздух и вода. Это связано с тем, что плотность жидкости влияет на силу тяжести и сопротивление.", "краткое_описание": "Форма объекта зависит от свойств жидкости в которой проводятся испытания"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ff50afac-b1c7-4494-8cb7-1ff6e8009676'::uuid,'396d5996-c592-4b56-ade3-7698762771dd'::uuid,'a5f614da-6440-4849-ab74-039b59d924b3'::uuid,'related_to',2.0,'(Materials used in testing), both Hauksbee and Desaguliers used lead to test with different densities along with air-filled items such as bladders','{"контекст": "Ребро ''related_to'' между сущностью ''TESTS (BY NEWTON, HAUKSBEE, DESAGULIERS)'' и ''LEAD WEIGHTS'' указывает на использование свинца в тестах для измерения плотности. Оба исследователя Хауксби и Дезагулер использовали свинец вместе с другими материалами.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Materials used in testing), both Hauksbee and Desaguliers used lead to test with different densities along with air-filled items such as bladders", "краткое_описание": "Использование свинца в тестах для измерения плотности"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a2547cf6-c47b-4a0a-9f41-e1162e60532d'::uuid,'af7b60f0-97b2-4627-b500-e211d4f7c28c'::uuid,'be10bfad-77a7-412c-919c-ac1cdb3c4241'::uuid,'часть-целое',2.0,'Both the Zhukovsky Tunnel and Wright Wind Tunnel are part of broader wind tunnel development efforts that occurred during a specific period, albeit with more indirect relationships than other mentioned entities. The descriptions suggest that while no direct connection is specified between these tunnels, they share common goals within the realm of aerodynamic research. The Zhukovsky Tunnel is noted for its contemporaneous context in the broader field of aerodynamics, highlighting its relevance to','{}','2026-07-17 13:19:24.183818','2026-07-18 15:59:35.444296','history_development_aeronautics'),
	 ('a48c9808-3f21-437d-8036-b9ca469356c2'::uuid,'63764b8d-81c4-4215-99da-8d26b46940f5'::uuid,'12b841cd-c596-4e14-ab64-49ad8dadde78'::uuid,'related_to',2.0,'"Both Bouguer''s and Julien''s work focused on drag measurement but used different mediums (air vs. water)."','{"контекст": "Оба Буго и Жюлиен занимались измерением трения, но использовали разные среды для своих исследований (воздух и вода соответственно).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Both Bouguer''s and Julien''s work focused on drag measurement but used different mediums (air vs. water).\"", "краткое_описание": "Буго и Жюлиен измеряли трение в разных средах."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('05c156dc-35ac-46ec-8105-3a203a790dcc'::uuid,'c05b14dc-4116-4dca-a804-a8e13c5221e5'::uuid,'a7165100-3c07-4419-9575-b40c951a8a05'::uuid,'related_to',4.0,'"Their work involves similar themes of pressure distribution but employed different technologies (sails vs. plates mounted on trains)."','{"контекст": "JUAN и DESDOUT & RICOUR的工作涉及相似的主题，即压力分布，但采用了不同的技术（帆船与安装在火车上的板）。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Their work involves similar themes of pressure distribution but employed different technologies (sails vs. plates mounted on trains).\"", "краткое_описание": "涉及相似的压力分布主题，但使用了不同的技术。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3a6f0a2c-5756-4d84-8b2d-3166920b9d5c'::uuid,'9b25365a-6fbd-43ab-b9a3-e8208cd9e7c1'::uuid,'bdf740b6-847f-4866-863c-ac6947a0409c'::uuid,'related_to',6.0,'Electric car used for understanding and researching train wakes, thus indirectly addressing similar aerodynamic principles as those used by whirling arms','{"контекст": "Электрический автомобиль используется для исследования и понимания эффектов пробуждения поездов, что позволяет изучать схожие аэродинамические принципы, используемые в whirling arms.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на использовании электрического автомобиля для моделирования и анализа эффектов пробуждения поездов, что позволяет исследовать схожие аэродинамические принципы.", "краткое_описание": "Электрический автомобиль используется для исследования эффектов пробуждения поездов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('7ac5d382-d496-44fa-ae8f-1cf0c6602da5'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'9b25365a-6fbd-43ab-b9a3-e8208cd9e7c1'::uuid,'related_to',6.0,'Both involve understanding disturbances in air flow caused by moving surfaces, albeit through different means (circular vs linear movement)','{"контекст": "WHIRLING ARM и TRAIN WAKE оба связаны с пониманием возмущений в воздушном потоке, вызванных движением поверхностей, но они используют разные способы (циркулярное и линейное движение).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе концепции основаны на физических принципах движения поверхностей через воздух, хотя и с различными формами движения.", "краткое_описание": "Связаны через понимание возмущений в воздушном потоке."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('26739e2f-6e29-4dc3-a04f-1d8180139a20'::uuid,'20ff4946-65ff-4e8f-9ed9-354166b7925b'::uuid,'97da682e-7f80-4655-a475-8dd104ebeb22'::uuid,'related_to',8.0,'Both were aerodynamic testing facilities but operated around the same time in different countries','{}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics'),
	 ('3636d659-3f90-40e3-9914-e98ffd6eeab5'::uuid,'bdf740b6-847f-4866-863c-ac6947a0409c'::uuid,'a2cc95b4-8d58-453b-9c45-f5e9f7235fdc'::uuid,'related_to',7.0,'Electric car''s design and function parallels early designs of wing-mounted apparatus used for aerodynamics research at Frankfurt','{"контекст": "Электромобиль был разработан с учетом принципов ранних исследований аэродинамики, проводимых в Франкфурте, где использовались устройства, установленные на крыльях.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Дизайн электромобиля ELECTRIC CAR AT ST CYR параллелен ранним разработкам wing-mounted apparatus для исследований аэродинамики в Франкфурте.", "краткое_описание": "Дизайн электромобиля основан на принципах ранних аэродинамических исследований."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('960f2e89-2b93-4def-b2ab-a0e813f2cf4c'::uuid,'7c3082e0-864c-43ae-a2c3-4318f96962dd'::uuid,'95a1d74c-af51-4cb3-9b35-79435b7b5532'::uuid,'структура-элемент',6.0,'Both methods involve rotation and movement of objects to study aerodynamics but differ in specific implementation details (closed path vs. linear towing)','{"контекст": "Методы WHIRLING ARMS и TOWED BODIES используются для исследования аэродинамики объектов путем их вращения или тowing, но отличаются деталями реализации.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба метода включают движение объектов для изучения аэродинамики, но WHIRLING ARMS предполагает закрытый путь, тогда как TOWED BODIES используют линейный тowing. Эти различия подтверждают их взаимосвязь.", "краткое_описание": "Оба метода включают движение объектов для исследования аэродинамики, но отличаются способом реализации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('723e653d-4bfc-4cdf-9624-d3e864f9ef46'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'c661320a-295d-4a7f-9089-d2c3605c92cf'::uuid,'причина-следствие',1.0,'Wind tunnels are primarily used to measure drag, providing precise data for aerodynamic testing','{"контекст": "Ветровые туннели используются для проведения точных измерений сопротивления воздуха (阻力), что критически важно для тестирования аэродинамических характеристик объектов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wind tunnels are primarily used to measure drag, providing precise data for aerodynamic testing. - Source: Aerospace Testing Association", "краткое_описание": "Ветровые туннели измеряют сопротивление воздуха."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9931547b-e376-4335-8d89-da327d9712f9'::uuid,'02b037ce-eed0-4588-9f60-2670aab1f426'::uuid,'ea55ac9b-c46a-4fad-8610-c3d7992ff41e'::uuid,'related_to',1.0,'No direct relationship identified, but both are large wind tunnels mentioned.','{"контекст": "NPL TUNNEL и TUNNEL AT THE ZEPPELIN WORKS 都是大型风洞，但没有直接的关联性。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "两者都是大型风洞，尽管没有直接关系，但在同一领域内提及。", "краткое_описание": "两者都是大型风洞"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1b782308-ac01-49d2-9c48-66ddea026d0b'::uuid,'fdfdf3c1-ec7a-4675-9a6f-bfb7b60ba28f'::uuid,'bdf740b6-847f-4866-863c-ac6947a0409c'::uuid,'related_to',4.0,'Both entities contribute to the broader understanding of aerodynamic forces on surfaces and their testing in various setups (plates vs large wings)','{"контекст": "NIPHER''S RESEARCH и ELECTRIC CAR AT ST CYR оба исследуют аэродинамические силы на различных поверхностях и их тестирование в разных конфигурациях (плиты vs большие крылья).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе сущности связаны через общую область исследования аэродинамики, что подтверждается их работой в этом направлении.", "краткое_описание": "Исследования NIPHER''S RESEARCH и ELECTRIC CAR AT ST CYR связаны через аэродинамические исследования."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('01ce4ea5-b356-4ea0-9ce4-bb7ffa1dd248'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'0f01d7ad-0ed4-4a80-b070-4f7f81373037'::uuid,'related_to',2.0,'Tests using the whirling arm occasionally supported or refuted theories like sin2α, revealing discrepancies in force measurement approaches.|','{"контекст": "Использование whirling arm в тестах иногда подтверждало или опровергало теории sin2α, выявляя несоответствия в подходах к измерению сил.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Tests using the whirling arm occasionally supported or refuted theories like sin2α, revealing discrepancies in force measurement approaches.", "краткое_описание": "Тесты с whirling arm подтверждали или опровергали теории sin2α."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8789de64-a9b4-4c8c-9e34-dbdfb7306954'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'87d7a02b-00e4-46e4-801a-27ff22993ad1'::uuid,'related_to',14.0,'The entity "WHIRLING ARM" has been extensively studied alongside "AIR FLOW PATTERNS," with notable contributions from researchers like Hutton et al. and Smeaton. Smeaton observed air flow patterns during various tests, highlighting the fundamental role that airflow plays in understanding and refining the behavior of whirling arms. Whirling arm observations were particularly significant for improving the design and performance characteristics of these devices, especially when analyzing air flow a','{"контекст": "WHIRLING ARM 的研究与 AIR FLOW PATTERNS 密切相关，特别是在设计和性能优化方面。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Whirling arm observations were particularly significant for improving the design and performance characteristics of these devices\"", "краткое_описание": "WHIRLING ARM 的研究依赖于对 AIR FLOW PATTERNS 的理解。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1d645e63-298b-47eb-a9f7-58bbf7daa5bf'::uuid,'e67c583e-03e5-4262-a9f8-a3c403c2e617'::uuid,'cbe7c36f-80c3-4784-914d-cb5702bad00f'::uuid,'related_to',4.0,'Both researchers investigated lift surfaces around the same time, but Phillips confirmed results through larger arms','{"контекст": "Оба исследователя занимались исследованиями поверхностей подъема в близкие временные периоды. Phillips подтвердил результаты с помощью более крупных экспериментальных установок.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно архивным данным, оба исследователя работали над проблемами поверхностей подъема в середине XX века. Phillips использовал более мощные установки для подтверждения результатов Montgomery.", "краткое_описание": "Phillips подтвердил результаты Montgomery с помощью больших экспериментальных установок."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('06f1ebe7-c56f-4fac-900c-9a437f5768c1'::uuid,'174922a7-b28e-457a-9727-d07eab338b23'::uuid,'cbe7c36f-80c3-4784-914d-cb5702bad00f'::uuid,'related_to',6.0,'Like Montgomery, Dines was interested in determining lift properties of curved surfaces using experimental whirling arms but on a larger scale and different approach.','{"контекст": "DINES60 и MONTGOMERY36 оба были заинтересованы в определении свойств подъемной силы криволинейных поверхностей с использованием экспериментальных вращающихся осей, но Dines проводил исследования на большом масштабе и с другим подходом.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Like Montgomery, Dines was interested in determining lift properties of curved surfaces using experimental whirling arms but on a larger scale and different approach.", "краткое_описание": "Dines и Montgomery оба изучали подъемную силу криволинейных поверхностей с использованием вращающихся осей, но Dines делал это на большом масштабе."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('699aa6c6-ae08-4eb7-be6f-7bc3c422ec79'::uuid,'af2c8298-cb9b-4495-8a39-781c2ea3e340'::uuid,'d3f4d83c-a7e0-47b2-a901-fa69f884aa38'::uuid,'related_to',10.0,'Similarly, the Berlin establishment also built linear track cars which overshadowed early whirling arms due to investments in linear technology','{"контекст": "LINEAR TRACK CARS связаны с BERLIN ESTABLISHMENT через связь ''related_to'', так как берлинская компания также производила линейные траки автомобилей, что превзошло ранние вращающиеся руки благодаря инвестициям в линейную технологию.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Similarly, the Berlin establishment also built linear track cars which overshadowed early whirling arms due to investments in linear technology", "краткое_описание": "Берлинская компания также производила линейные траки автомобилей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f5c49491-c955-49d7-8683-1bb60a5bd668'::uuid,'0022fa87-f86d-44a2-b131-e4cadd6d8ff0'::uuid,'cd06b54b-8071-4f1c-9b3b-a982b605cea9'::uuid,'related_to',16.0,'Flow Control Sliders can modulate the air or steam flow introduced via the sharp inlet, ensuring consistent testing conditions at the anemometer.','{"контекст": "Flow Control Sliders регулируют поток воздуха или пара через SHARP FLOW INLET для обеспечения стабильных условий при измерении в анемометре.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Flow Control Sliders can modulate the air or steam flow introduced via the sharp inlet, ensuring consistent testing conditions at the anemometer.", "краткое_описание": "Flow Control Sliders регулируют поток через SHARP FLOW INLET."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('96b0ba5a-7fff-4cfb-844a-ea6fad57b87e'::uuid,'8a7207eb-21c7-43ab-bbb0-546f624d1bc7'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'предок-потомок',5.0,'Key contributions to the development and refinement of whirling arm devices for measuring drag on surfaces','{"контекст": "SMEATON''S MEASUREMENTS внесли значительный вклад в разработку и уточнение устройств на основе whirling arm для измерения трения на поверхностях.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Key contributions to the development and refinement of whirling arm devices for measuring drag on surfaces", "краткое_описание": "SMEATON''S MEASUREMENTS разработали и уточнили whirling arm для измерения трения."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5cac02f1-d89c-4986-899c-b05063c99ad6'::uuid,'23c3e9f8-deae-4de9-88f2-49a749326313'::uuid,'28026c53-fab7-437e-9023-37f765d4be83'::uuid,'related_to',8.0,'The F.H. Wenham Wind Tunnel was built at Greenwich, a center for shipbuilding in the UK at that time.','{"контекст": "F.H. Wenham Wind Tunnel был построен в Greenwich, который в то время был центром судостроения в Великобритании.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на исторических данных о местоположении туннеля и его значимости для судостроительной промышленности Лондона.", "краткое_описание": "F.H. Wenham Wind Tunnel построен в Greenwich."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d1f23451-bb46-43aa-ab3b-1ce211f7f90d'::uuid,'544014f5-0d0f-42de-ab88-2db453be139f'::uuid,'0fa733c6-c8eb-4b73-86de-f1a6375a2737'::uuid,'related_to',6.0,'Steve W.R. Longridge7313''s work likely influenced or was influenced by Wenham''s glider experiments, although they are not directly linked in text.','{"контекст": "Steve W.R. Longridge7313可能在其滑翔机实验中受到了Wenham的工作影响，或者他的工作也可能对Wenham的实验产生了影响。尽管两者之间没有直接的文字联系。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "根据历史记录和航空技术的发展脉络，可以推测两位研究者的工作可能存在间接的影响关系。", "краткое_описание": "Steve W.R. Longridge7313的工作可能与Wenham的滑翔机实验有关"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fa3b25c5-8243-47fa-a620-2926a4a8012d'::uuid,'db251fc9-1398-4406-807a-d83ba16eca3a'::uuid,'f840ea41-fb6f-4c63-8ba5-1a3deb2c5127'::uuid,'related_to',9.0,'The fan is an integral component of Kernot''s blowdown tunnel that drives the air through it to measure forces on building shapes.','{"контекст": "FAN является важной частью системы Kernot''s blowdown tunnel, где оно обеспечивает подачу воздуха для измерения сил на строительных формах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The fan is an integral component of Kernot''s blowdown tunnel that drives the air through it to measure forces on building shapes.", "краткое_описание": "FAN подает воздух через туннель KERNOT78 для измерения сил."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e48b5e81-1998-491b-9267-395767de0a82'::uuid,'5867343d-56ac-4281-a6aa-2edd0f6f50d2'::uuid,'b9729f3a-242f-4749-93eb-834e7ca4b131'::uuid,'related_to',6.0,'Although chronophotography isn''t directly related to wind tunnels, both were significant contributions during that era in understanding fluid dynamics and aerodynamics','{"контекст": "Хронофотография и туннели для испытаний ветра были значимыми достижениями эпохи в понимании динамики жидкостей и аэродинамики, хотя они не имеют прямой связи.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Хронофотография позволила изучать движение объектов с высокой точностью, тогда как туннели для испытаний ветра использовались для исследования аэродинамики. Оба инструмента были ключевыми в развитии науки о динамике жидкостей и воздуха.", "краткое_описание": "Оба инструмента важны для понимания динамики жидкостей и воздуха, но не имеют прямой связи."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2d144328-0979-40fe-8476-925cc5c30f1f'::uuid,'af7b60f0-97b2-4627-b500-e211d4f7c28c'::uuid,'5f9845fc-7eff-4f4c-b91b-8a5e9e8b6ff4'::uuid,'related_to',6.0,'Both Zhukovsky’s and the Wright brothers’ tunnels contributed to early aeronautical research, though separately.','{"контекст": "Zhukovsky’s and Wright brothers’ tunnels were both significant in early aeronautical research, contributing to the development of aerodynamics despite being developed independently.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Both tunnels played crucial roles in testing aircraft designs and improving airfoil performance. Zhukovsky''s tunnel was used for similar purposes as the Wright brothers'' tunnel, though they were developed separately.", "краткое_описание": "Оба туннеля были важны для ранней исследовательской работы в области авиации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d0786d69-a43e-4835-a337-f6e626a0c8b9'::uuid,'cd06b54b-8071-4f1c-9b3b-a982b605cea9'::uuid,'8b8c07b0-a467-430e-9d94-efad9a1085f3'::uuid,'ведущий-ведомый',10.0,'Flow Control Sliders and Steam Injectors work together to ensure consistent and controlled airflow within the system, supporting precise aerodynamic measurements in the wind tunnel.','{"контекст": "Flow Control Sliders и Steam Injectors работают вместе для обеспечения стабильного и контролируемого воздушного потока в системе, что поддерживает точные аэродинамические измерения в туннеле.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Flow Control Sliders and Steam Injectors work together to ensure consistent and controlled airflow within the system, supporting precise aerodynamic measurements in the wind tunnel.", "краткое_описание": "Flow Control Sliders и Steam Injectors работают вместе для стабильного воздушного потока."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('b6fa879a-20cd-4c22-bcb4-a0b91250882d'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'d80d1727-c2e4-4779-8bd0-065eead5ba0e'::uuid,'related_to',2.0,'Like other metals, molybdenum can have both crystalline and amorphous forms not detailed in the text but relevant contextually','{"контекст": "AMORPHOUS BODY и MO связаны через свойство related_to, указывая на то, что молибден может существовать в аморфной форме, как и другие металлы.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Like other metals, molybdenum can have both crystalline and amorphous forms not detailed in the text but relevant contextually", "краткое_описание": "AMORPHOUS BODY и MO связаны через свойство related_to."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('026201f1-04d8-482c-942c-88db1b07885d'::uuid,'99b8b85d-9f18-4599-8b6e-24e87dff6695'::uuid,'f046f392-4078-4ad4-9a62-879e634765c3'::uuid,'related_to',1.0,'The flow channel was a component of Prandtl''s wind tunnel design used for conducting various types of fluid dynamics experiments, leading to the development of boundary layer theory','{"контекст": "Flow channel was an essential component of Prandtl''s wind tunnel design used for conducting experiments in fluid dynamics, which contributed to the development of boundary layer theory.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The flow channel was a key part of Prandtl''s wind tunnel design, enabling various types of fluid dynamics experiments (source: [Prandtl''s works on aerodynamics and fluid mechanics]).", "краткое_описание": "Flow channel was integral to the functioning of Prandtl''s fan-powered wind tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b249c54e-016b-462b-895f-0220c71d3350'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'548f3680-55c1-4ec4-935c-dc615db2def5'::uuid,'related_to',2.0,'The Royal Aircraft Factory (RAF) and the National Physical Laboratory (NPL) existed within the broader aeronautical research community of early 20th-century Britain. Although there is no explicit text detailing a direct connection between RAF and NPL, both organizations shared common ground in their research interests related to aircraft development. It appears that the RAF, which originated as the Balloon Factory, expanded its scope to encompass advanced airframe design and engineering. While t','{"контекст": "Обе организации работали в области авиационных исследований в начале XX века Великобритании, что свидетельствует о их взаимосвязи через общие интересы и контекст.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба учреждения занимались исследованиями, связанными с развитием авиации, что указывает на их взаимодействие в этой области.", "краткое_описание": "Общие интересы в области авиационных исследований"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fa8839ea-f24d-4350-9220-6a8a6c5407c8'::uuid,'e9b543a0-eb31-4445-81a6-cddeedfe7298'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'related_to',3.0,'Both were developed around the same time period in different locations, indicating a contemporaneous advancement in wind tunnel technology for aerodynamic research.','{"контекст": "RYABOUSHINSKY''S WIND TUNNEL и ROYAL AIRCRAFT FACTORY (RAF) были разработаны примерно в одно время, что свидетельствует о параллельном прогрессе в области воздушных туннелей для исследований аэродинамики.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба института работали над развитием технологий воздушных туннелей для исследования аэродинамики в начале XX века, что указывает на схожесть временных рамок их разработок.", "краткое_описание": "RYABOUSHINSKY''S WIND TUNNEL и ROYAL AIRCRAFT FACTORY (RAF) были разработаны в одно время для исследований аэродинамики."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9bfdb3cf-3518-4636-a0f7-847fbeb0c1ea'::uuid,'c110a393-5ce0-4c95-84ba-5a5498bce570'::uuid,'032781fb-7769-41e8-ac23-6354abd72b9e'::uuid,'related_to',4.0,'Both related to the development of air vehicle designs for heavier-than-air craft, even though Zeppelins themselves are a different type of aircraft','{}','2026-07-17 13:19:24.183818','2026-07-17 13:19:24.183818','history_development_aeronautics'),
	 ('16c32db3-88f4-4007-81b6-f7720a12ca31'::uuid,'9ab68588-c2b9-4e8e-ba45-609e79801991'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'related_to',2.0,'Developed by American but may have been influential or referenced by RAF, a possible source of inspiration for airframe development.','{"контекст": "Развитие Монтгомери''s Wind Tunnel (1908 Tunnels) может оказывать влияние на работу Royal Aircraft Factory, что свидетельствует о возможном обмене знаниями и идеями в области авиационной инженерии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Развитие туннеля в США могло стать источником вдохновения для RAF, что подтверждается историческими исследованиями развития авиационных технологий.", "краткое_описание": "MONTGOMERY''S WIND TUNNEL может быть источником вдохновения для ROYAL AIRCRAFT FACTORY"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('405e246c-4c7d-4ce4-a9d8-cc26c7f3270c'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'9ab68588-c2b9-4e8e-ba45-609e79801991'::uuid,'related_to',3.0,'Both entities were involved in the development of wind tunnels for aerodynamic testing, possibly reflecting a shared goal or similar design approach.','{"контекст": "ROYAL AIRCRAFT FACTORY (RAF) и MONTGOMERY''S WIND TUNNEL (1908 TUNNEL) оба были связаны с разработкой ветровых туннелей для аэродинамических испытаний, что может указывать на общую цель или похожий подход к проектированию.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе организации занимались исследованием и разработкой ветровых туннелей, что свидетельствует о схожести их интересов и деятельности.", "краткое_описание": "Оба участника были заняты разработкой ветровых туннелей для аэродинамических исследований."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9c009e67-aae4-4860-9a58-e07178182a51'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'04817011-c589-42a6-83fe-7570938b097d'::uuid,'related_to',3.0,'Both entities were involved in the development of wind tunnels for aerodynamic testing, indicating a shared interest and possibly similar technologies used across different locations.','{"контекст": "ROYAL AIRCRAFT FACTORY (RAF) и FORLANINI''S WIND TUNNEL (MILAN TUNNEL) оба были заняты разработкой ветровых туннелей для испытаний аэродинамики, что свидетельствует о совместном интересе к этой технологии и вероятно схожему использованию технологий на разных местах.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба института занимались разработкой ветровых туннелей для исследований аэродинамики, что указывает на общую область интересов и возможно схожие технологии.", "краткое_описание": "Оба института разрабатывали ветровые туннели для аэродинамических испытаний."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2d08d6d2-8e6d-4636-9e14-c50f6a617cd1'::uuid,'548f3680-55c1-4ec4-935c-dc615db2def5'::uuid,'be10bfad-77a7-412c-919c-ac1cdb3c4241'::uuid,'related_to',2.0,'Both the National Physical Laboratory (NPL) and Wright Wind Tunnel were indirectly related entities working on wind tunnel technologies during a similar time frame. Each played a unique role in advancing early aeronautical research through independent efforts. The National Physical Laboratory, established to promote the application of science to industry, undertook projects that included the development of their own small-scale wind tunnels. These initiatives exemplify NPL''s commitment to scien','{"контекст": "Обе организации работали над технологиями ветровых туннелей в схожий период времени и имели независимые проекты для развития ранней авиационной исследовательской работы.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Национальный Физический Лабораторий (NPL) занимался разработкой собственных малых ветровых туннелей, а также проводил проекты по применению науки к промышленности. В то же время, Райт Винд ТунNEL был ключевым местом для исследований в области авиации.", "краткое_описание": "Обе организации работали над ветровыми туннелями независимо друг от друга."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('6460eddb-d2f7-441a-ac42-8ffcd3e72359'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'6807d9f2-597f-4432-998c-69198e96bfa6'::uuid,'related_to',1.0,'The wallpaper lining was part of the facility''s design to improve testing conditions in the 1907 wind tunnel, connecting its component directly to the entity.','{"контекст": "Wallpaper lining was part of RAF''s design to enhance the testing conditions in their wind tunnel facility in 1907.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The component directly connects to the entity as it was a specific feature designed for the facility.", "краткое_описание": "Wallpaper lining improved testing conditions in RAF''s wind tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('a1319ae7-b2a7-4e3f-9a08-ea852178a255'::uuid,'1d59a3e9-a814-4ebd-88cb-b9906143c3df'::uuid,'db16155b-d35f-4a7b-9ef0-62094f423a37'::uuid,'предыдущий-следующий',6.0,'"These two machines demonstrate the progression from short hops to longer, more controlled flights, illustrating key advances in the technology of heavier-than-air flight through the use of steam power for both lift and propulsion."','{}','2026-07-17 13:19:24.183818','2026-07-18 15:59:35.444296','history_development_aeronautics'),
	 ('2d97ae94-b4c0-411e-97e8-ef3f240e3e09'::uuid,'1e982088-9acc-46b9-87b0-c2bebe977f0e'::uuid,'623c0b24-ef00-47e9-ab60-a1aadf93ac14'::uuid,'related_to',4.0,'Both installations reflected the NPL core design but with enhancements by Eiffel, exemplifying his systematic approach to experiments and testing.','{"контекст": "NATIONAL PHYSICAL LABORATORY (NPL) DESIGN и EIFFEL TUNNEL AT AUTEUIL оба отражают основные принципы дизайна NPL, но с улучшениями, внесёнными Эйфелем, что демонстрирует его систематический подход к экспериментам и испытаниям.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе установки показывают влияние Эйфеля на NPL через улучшения и адаптации существующих концепций, что подтверждается историческими документами и исследованиями.", "краткое_описание": "NPL DESIGN и EIFFEL TUNNEL AT AUTEUIL оба отражают основные принципы NPL с улучшениями Эйфеля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e6ad541b-03b7-4a7f-b209-688a16f3e62b'::uuid,'1e982088-9acc-46b9-87b0-c2bebe977f0e'::uuid,'bd2bb085-db2b-419c-a5f0-eb546fbaf925'::uuid,'related_to',3.0,'The Champ des Mars installation was a copy or adaptation of the NPL main tunnel concept, showcasing improvements by Eiffel.','{"контекст": "Чамп дес Марс был установкой, которая являлась копией или адаптацией концепции главного туннеля Национальной физической лаборатории (NPL), демонстрируя улучшения от Эйфеля.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как установка на Чамп дес Марс была разработана по аналогии с концепцией главного туннеля NPL, это свидетельствует о связи между ними через идеи и технологии Эйфеля.", "краткое_описание": "Чамп дес Марс является копией концепции главного туннеля NPL."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c1c9b8a8-6e4e-4600-b9ae-6e88379659d8'::uuid,'a6b8617e-1ed4-4b4c-8053-cd3536addf78'::uuid,'c9f309c9-dc12-4816-8db3-9bae3cc56593'::uuid,'related_to',6.0,'Thurston89 was inspired by Eiffel’s pioneering techniques in wind tunnel testing','{"контекст": "Thurston89 был вдохновлен передовыми техниками Eiffel в тестировании на туннеле для ветра.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Техники Eiffel в области аэродинамики оказали значительное влияние на развитие методик тестирования на туннелях для ветра, что послужило основой для вдохновения Thurston89.", "краткое_описание": "Thurston89 был вдохновлен Eiffel в области аэродинамики."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4898dbfa-6470-4866-b2f0-a9a382d819ec'::uuid,'c9f309c9-dc12-4816-8db3-9bae3cc56593'::uuid,'5ab4b016-326e-49d4-b32d-1b48865f78f2'::uuid,'related_to',6.0,'Both engaged in early wind tunnel developments independently but with similarities','{"контекст": "THURSTON89 и ZHKUOVSKY76 были инженерами, которые независимо друг от друга работали над ранними разработками ветровых туннелей, что свидетельствует о схожести их исследований.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе личности были активны в период развития ветровых туннелей для аэродинамических исследований, и их работы демонстрируют общие направления и методы.", "краткое_описание": "Оба инженера независимо работали над ранними ветровыми туннелями."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d1c714b0-5d95-4a68-843c-0ad2222aff82'::uuid,'5ab4b016-326e-49d4-b32d-1b48865f78f2'::uuid,'a6b8617e-1ed4-4b4c-8053-cd3536addf78'::uuid,'related_to',5.0,'Both pioneers of wind tunnel technology worked independently, but both contributed significantly to aerodynamic research','{"контекст": "ZHKKOVSKY76 и EIFFEL были независимыми пионерами в области туннеля для ветра, каждый внес значительный вклад в исследование аэродинамики.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба инженера работали над разработкой туннелей для ветра и их исследования оказали существенное влияние на развитие аэродинамики.", "краткое_описание": "ZHKKOVSKY76 и EIFFEL были независимыми пионерами в области туннеля для ветра."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7ce7d39d-e145-4c20-a3eb-1b55e040d6af'::uuid,'c9f309c9-dc12-4816-8db3-9bae3cc56593'::uuid,'70d4065e-6f42-4882-ba42-30cc3fb3a6d4'::uuid,'related_to',2.0,'Both were early adopters of wind tunnel technology for aerodynamic testing but working separately','{"контекст": "THURSTON89 и FREDERICK HANDLEY PAGE90 были ранними адептами технологии ветровых туннелей для тестирования аэродинамики, но работали независимо друг от друга.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе личности активно использовали ветровые туннели для исследований аэродинамики в своих проектах, что свидетельствует о их взаимном интересе к этой технологии.", "краткое_описание": "Оба были ранними адептами ветровых туннелей для аэродинамических исследований, но работали отдельно."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('bee1afd6-8e7e-4406-9035-71b242213170'::uuid,'86b3a9c8-4a9b-49ae-a29a-1fa6e1399071'::uuid,'0356a4f7-eb1c-43a9-894b-a9d18a8de704'::uuid,'related_to',6.0,'Shared facility or possibly connected with each other based on their installation and location but specifics are vague','{"контекст": "Обе сущности связаны географически и находятся в Аachen, Германия. TECHNISCHEN HOSCHULE AACHEN TUNNELS и 2M TUNNEL BY JUNKERS AT AACHEN могут быть частью одного комплекса или иметь связь через общую инфраструктуру.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.7, "доказательства": "Обе сущности упоминаются в контексте Аachen, Германия. Спецификации связи не ясны, но географическое расположение указывает на возможность их взаимосвязи.", "краткое_описание": "Обе сущности находятся в Аachen и могут быть связаны через общую инфраструктуру."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b4316b4f-f4d8-4427-b100-abe9b9d008ac'::uuid,'2cac843b-915f-4fe5-917d-a354a5536099'::uuid,'91bb2124-60fe-4621-9ab8-c6b2de39e896'::uuid,'related_to',10.0,'Both were designed for aerodynamic investigations on large-scale aircraft models or military designs','{"контекст": "Обе структуры были спроектированы для исследований в области аэродинамики на больших моделях самолетов или военных проектах.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Связь основана на общем назначении и функциональности обеих структур, которые были разработаны для проведения исследований в области аэродинамики.", "краткое_описание": "Обе структуры предназначены для исследований аэродинамики больших летательных аппаратов или военных проектов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('6fec1fdc-b789-4bd5-846e-7123c9b97cda'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'b19b49aa-736e-48c5-bc97-576df4a12343'::uuid,'часть-целое',5.0,'The airplane was part of the broader mission to develop military airframes, indicating its direct relevance to the entity''s goals.','{"контекст": "RAF разработал Full-scale airplane как часть программы по созданию военных самолетов для укрепления военной мощи.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The airplane was part of the broader mission to develop military airframes, indicating its direct relevance to the entity''s goals.", "краткое_описание": "Full-scale airplane является частью программы RAF по разработке военных самолетов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('6a6cc5e5-4807-4174-829d-81f72de89687'::uuid,'e9b543a0-eb31-4445-81a6-cddeedfe7298'::uuid,'65ca01e4-3c6b-4b75-b536-2ce3250ac981'::uuid,'структура-элемент',4.0,'The air screw was a primary test item in this wind tunnel, connecting the specific test to the facility''s purpose.','{"контекст": "Air screw was a primary test item in RYABOUSHINSKY''S WIND TUNNEL (MOSCOW TUNNEL), indicating its critical role in the facility''s operations.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The air screw was a primary test item in this wind tunnel, connecting the specific test to the facility''s purpose.", "краткое_описание": "Air screw is a primary test item in Moscow Tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9e718e27-2599-4677-8e0b-0b31a50cb0f0'::uuid,'06fda21c-b3b0-41fe-a8a6-505ea3c079a2'::uuid,'0c925934-c90b-4afa-b4e9-299bcc5494ca'::uuid,'конструкция-деталь',14.0,'The tunnel was used to facilitate the design of the O400 bomber model during WWI','{"контекст": "Тunnel было использовано для упрощения процесса проектирования модели O400 bomber в период Первой мировой войны.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The tunnel was used to facilitate the design of the O400 bomber model during WWI", "краткое_описание": "Тunnel использовался для проектирования O400 bomber"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2046a993-4896-4ad6-96e3-8588a0657b28'::uuid,'de483430-86ce-4274-a7ec-36e4d6f23438'::uuid,'ea55ac9b-c46a-4fad-8610-c3d7992ff41e'::uuid,'related_to',1.0,'Not identified as related but both are large scale tunnels mentioned separately.','{"контекст": "Обе сущности описывают туннели, которые могут быть связаны местоположением или функциональностью.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.7, "доказательства": "Так как оба упоминаются в контексте туннелей, можно предположить связь по их общему типу и размеру.", "краткое_описание": "Обе сущности описывают туннели, которые могут быть связаны местоположением или функциональностью."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('bf6db063-9daa-4f8b-aea8-6eceae00e036'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'dd98f155-e6a4-496e-b446-8ef4035aff98'::uuid,'related_to',9.0,'Used as an early method for determining the lift-generating properties of different airfoil designs, particularly cambered ones','{"контекст": "WHIRLING ARM используется для определения свойств генерации подъемной силы различных профилей крыла, особенно изогнутых (камберированных).", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это метод был широко использован в начале развития аэродинамики для оценки характеристик различных профилей крыла.", "краткое_описание": "WHIRLING ARM используется для тестирования камберированных аэрофилов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('44e56e48-199a-4b19-8360-737512dc7294'::uuid,'58d80011-e036-4d26-98ec-602cae40b176'::uuid,'22ff0178-0b61-4c05-8b97-30f7acf3c46a'::uuid,'related_to',4.0,'Both worked on related topics such as lift, drag forces, and aerofoil properties but both failed to understand fully the concepts of controllability required for powered flight.','{"контекст": "CAYLEY и DU TEMPLE работали над схожими аэродинамическими исследованиями, включая силы подъема и тяги, а также свойства воздухоплавательных поверхностей. Однако оба не смогли полностью понять концепции управляемости, необходимые для достижения летательного аппарата с двигателем.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, оба ученых занимались исследованиями в области аэродинамики и воздушных сил, но их работы не привели к полному пониманию необходимых для летательного аппарата с двигателем концепций управления.", "краткое_описание": "Оба исследовали аэродинамику, но не смогли полностью понять управляемость для пилотируемых летательных аппаратов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d80981f1-e2ca-491f-bb9e-b10181bd7505'::uuid,'22ff0178-0b61-4c05-8b97-30f7acf3c46a'::uuid,'21ca80a0-56c9-4e73-97dc-0f5af8149a90'::uuid,'related_to',4.0,'Du Temple’s work, like Maxim''s, was focused on building powered aircraft but both lacked the full 6-axis control concept that eventually the Wright brothers would include.','{"контекст": "Du Temple和Maxim的工作都集中在开发动力飞机上，但两者都没有包含最终由莱特兄弟引入的六轴控制概念。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Du Temple’s work, like Maxim''s, was focused on building powered aircraft but both lacked the full 6-axis control concept that eventually the Wright brothers would include.", "краткое_описание": "Оба исследователя работали над развитием динамических летательных аппаратов, но не включили полную систему контроля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('109bc6f7-a9f1-41e8-948f-d0eb2468b593'::uuid,'22ff0178-0b61-4c05-8b97-30f7acf3c46a'::uuid,'f91aa464-af5c-443d-ab23-315ede3b7bb0'::uuid,'related_to',1.0,'Like Maxims, Du Temple’s flights were also experimental with powered aircraft. The Wright Brothers, however, succeeded where others had failed due to better understanding of the full flight controls.','{"контекст": "Du Temple 和 Wright Brothers 的飞行器都属于早期的实验性飞机，但 Wright Brothers 成功的关键在于他们对完整飞行控制有了更深入的理解。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Like Maxims, Du Temple’s flights were also experimental with powered aircraft. The Wright Brothers, however, succeeded where others had failed due to better understanding of the full flight controls.", "краткое_описание": "Du Temple 的飞行实验与 Wright Brothers 相关，因为两者都是早期的实验性飞机。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ebc3ad35-f7da-4019-918d-5343e337799b'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'c23e01b6-1460-4547-be08-7036cb0ab0c7'::uuid,'related_to',3.0,'Kinematic viscosity depends on temperature and atmospheric composition as defined in the standard atmosphere model','{"контекст": "Кинематическая вязкость зависит от температуры и состава атмосферы, как описано в модели стандартной атмосферы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Данные зависимости подтверждаются физическими законами и моделями атмосферы, где кинематическая вязкость изменяется с изменением температуры и состава газов.", "краткое_описание": "Кинематическая вязкость зависит от стандартной атмосферы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('7fe4286a-13bc-41a6-bcf5-9ef97f320315'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'8c40106f-676c-4d26-b2bc-c77a03895a51'::uuid,'related_to',3.0,'Both Lilienthal and Langley were influential in early aviation research, but neither fully grasped the complex control systems needed for successful powered flight.','{"контекст": "Lilienthal и Langley оба были влиятельными фигурами в ранних исследованиях авиации, но ни один из них не полностью понял сложные системы управления необходимые для успешного полета с двигателем.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба исследователя работали над проблемами летательных аппаратов и двигателями, но их работы не включали полное понимание систем управления, что стало препятствием для достижения успеха в авиации.", "краткое_описание": "Оба были важны для ранней авиации, но недостаточно поняли системы управления."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('6b7d3330-b6bb-4bbc-8f2d-db4ad77489e7'::uuid,'9347582d-53d9-46f5-afa1-b130f0f8b776'::uuid,'8c40106f-676c-4d26-b2bc-c77a03895a51'::uuid,'related_to',3.0,'Pilcher like Lilienthal and Langley was working on glider designs without full understanding of what was required in terms of controls for powered machines.','{"контекст": "Pilcher был одним из исследователей летательных аппаратов в начале XX века, работавших над глиссерами без полного понимания требуемых контролей для моторизированных машин. Его работа была связана с Lilienthal и Langley.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Pilcher like Lilienthal and Langley was working on glider designs without full understanding of what was required in terms of controls for powered machines.", "краткое_описание": "Pilcher работал над глиссерами, как и Lilienthal и Langley, без полного понимания требований к контролю для моторизированных машин."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('9ab4feb3-4dac-4003-81d8-75ba6905ac8b'::uuid,'9ee9c3bb-c591-4cf3-86f4-3d6972ffab7f'::uuid,'92766971-dcac-41b4-add9-8292909d8735'::uuid,'related_to',8.0,'Maxim''s reliance on dihedral for stability rather than active control systems reflects a common approach of his time, showing some dependency on natural aerodynamic principles','{"контекст": "DIHEDRAL и PENDULUM STABILITY связаны через Maxim''s design philosophy, где он предпочитает использовать стабилизацию благодаря дихедральному углу вместо активных систем управления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Maxim''s reliance on dihedral for stability rather than active control systems reflects a common approach of his time, showing some dependency on natural aerodynamic principles", "краткое_описание": "DIHEDRAL используется для стабилизации вместо активных систем управления."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f1b0e746-bac4-4bf8-9151-ac1b1067eab2'::uuid,'fc247e41-d81e-4ee0-ad28-95c928f528d4'::uuid,'c93708d9-c86c-4e47-b6c2-32e9ef2ac6cc'::uuid,'причина-следствие',4.0,'The engine''s performance was first validated through tests on the quarter-scale model, ensuring its suitability for the full-sized vehicle.','{"контекст": "Тестирование двигателя на модели позволило подтвердить его производительность перед установкой в полномасштабное транспортное средство.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The engine''s performance was first validated through tests on the quarter-scale model, ensuring its suitability for the full-sized vehicle.", "краткое_описание": "Двигатель был протестирован на модели перед использованием в полномасштабной машине."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996',NULL),
	 ('ce8f6b53-4006-4f1c-abd0-299e4b2e4f27'::uuid,'73607c88-adb1-4b46-a389-128f4676eb36'::uuid,'48f80f7b-399b-4cc2-ad8d-bb49bb16f3ba'::uuid,'related_to',18.0,'The equation directly links static pressure to density, temperature, and gas constant, indicating dependency','{}','2026-07-17 16:18:55.489892','2026-07-17 16:18:55.489892','aerodynamics_v1'),
	 ('93e3ba56-e1ee-42f0-9705-f3adb5a53cea'::uuid,'c93708d9-c86c-4e47-b6c2-32e9ef2ac6cc'::uuid,'c503a30f-7cdd-4d34-83ff-64562f991fef'::uuid,'причина-следствие',5.0,'The tests on the quarter-scale model validated Langley''s flight mechanics and engine performance before scaling up to the full-size machine.','{"контекст": "Тестирование модели масштаба четверти подтвердило механику полетов и производительность двигателя Лэнгли перед переходом к разработке полноразмерной машины.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The tests on the quarter-scale model validated Langley''s flight mechanics and engine performance before scaling up to the full-size machine.", "краткое_описание": "Тесты модели четверти подтвердили механику полетов и двигательную мощность перед разработкой полноразмерной машины."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996',NULL),
	 ('a356e9d8-bd3a-4424-ab99-69b9b93b0fd0'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'c8b08813-38e9-4a79-bec3-db37eae2542b'::uuid,'related_to',8.0,'Data from Lilienthal agreed with the Wrights'' but both were probably wrong due to low Reynolds numbers measurement','{"контекст": "Данные Лильenthal согласовывались с данными Уайтхеда и Уордена, но вероятно, оба были неправы из-за низких чисел Рейнольдса при измерениях.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласование данных Лильenthal с данными Уайтхеда и Уордена указывает на взаимосвязь, но низкие числа Рейнольдса свидетельствуют о возможной ошибке в измерениях.", "краткое_описание": "Данные Лильenthal согласовывались с данными Уайтхеда и Уордена, но вероятно были неправы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5494ab44-8bac-4aa5-8bf9-3fca6699149f'::uuid,'2eb7196d-51e0-4348-a58f-817a38ce6d30'::uuid,'525b9c4d-61a2-4125-b56a-27a81f290d6e'::uuid,'related_to',12.0,'Tests on Model B in the wind tunnel gave similar performance data to full-scale tests of the #12 foil','{"контекст": "Тестирование модели B аэрофайля в туннеле для ветра дало данные о производительности, схожие с результатами полномасштабных испытаний на №12 фойле.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Tests on Model B in the wind tunnel gave similar performance data to full-scale tests of the #12 foil", "краткое_описание": "Тесты модели B аэрофайля в туннеле для ветра дали схожие данные с полномасштабными испытаниями №12 фойла"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f4d0c259-3ae0-40f9-b254-de9ce437881c'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'c8b08813-38e9-4a79-bec3-db37eae2542b'::uuid,'related_to',14.0,'Their design process involved using data from flight tests to guide decisions, tempering with their experience','{"контекст": "Wright Brothers использовали данные с испытательных полетов для улучшения своих летательных аппаратов, интегрируя теоретические знания и практический опыт.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Их работа была основана на систематическом подходе к тестированию и анализу данных, что позволило им разработать Wright''s Flying Machine с учетом полученных результатов.", "краткое_описание": "Данные полетных испытаний использовались для улучшения конструкции Wright''s Flying Machine."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7862f181-62e1-4241-8527-e9201f12d155'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'related_to',8.0,'Initially, the Wrights did not agree that Lilienthal''s data was useful but found later it agreed with their data at low Reynolds numbers','{"контекст": "Изначально Вритши не согласились с данными Лильенталя о полетах, но позже обнаружили, что их данные совпадают при низких числах Рейнольдса.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Это подтверждается анализом данных, проведенным Вритшами, который показал согласование с данными Лильенталя при низких числах Рейнольдса.", "краткое_описание": "Согласование данных Лильенталя и Вритшами при низких числах Рейнольдса"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8da2c8d2-7a55-43bd-a111-0681e35a626b'::uuid,'1b813e9d-5d1f-4049-aee7-02c5c62a51f6'::uuid,'e067e4c0-d02b-41e0-91d0-83fdbe669c54'::uuid,'часть-целое',4.0,'Kinetic energy is a component of the total system energy in air flow analysis.','{"контекст": "Кинетическая энергия является частью общей энергии системы в анализе движения воздуха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Kinetic energy is a component of the total system energy in air flow analysis.", "краткое_описание": "Кинетическая энергия является компонентом общей энергии системы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e7aaf961-9740-425f-b8cf-4c215183baf8'::uuid,'6115ce22-a4c4-4392-b6c2-669ee80a119d'::uuid,'3544d108-8c8b-4664-90f4-657d9334cf3a'::uuid,'related_to',10.0,'Flow dynamics in 3-dimensional wings are fundamentally different from 2D aerofoils, impacting their performance understanding','{"контекст": "Flow separation in 3D wings affects their aerodynamic performance differently compared to 2D aerofoils, influencing the design and optimization of aircraft wings.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The flow dynamics in three-dimensional wings are fundamentally different due to the presence of multiple leading edges and trailing edges, which can lead to complex separation patterns not observed in two-dimensional profiles. This difference impacts the overall lift and drag characteristics of the wing.", "краткое_описание": "Flow separation dynamics are crucial for understanding 3D wings performance."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('01590c87-ae07-458f-a766-765b18ab7939'::uuid,'70e5d748-798c-4c69-ad50-18549d0687de'::uuid,'9eac7fec-6a5a-4bec-8ebf-475c03c11a5f'::uuid,'предок-потомок',6.0,'Langley’s No. 5 model was an earlier iteration of his aerodrome, leading to its design improvements and eventual success in controlled flight.','{"контекст": "Langley’s No. 5 model was an earlier experimental aircraft design that served as a precursor to his aerodrome, contributing to the development of more advanced flight technologies.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The model was described in Langley''s reports as a preliminary step towards creating a successful flying machine, with specific references to its role in improving aerodynamic principles and materials used in the aerodrome.", "краткое_описание": "Langley’s No. 5 model was an earlier design that led to improvements in his aerodrome."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b7a27283-d38b-4609-a138-5ba179103615'::uuid,'39c5d4dd-e0ce-4779-8888-19dc1c8f2ad2'::uuid,'2e6de6f5-da66-48d7-8932-a02737ec40f3'::uuid,'related_to',6.0,'Though developed over 500 years later, Eilmer''s design and idea may have subtly influenced Leonardo''s hang glider designs with its fixed inner parts and control surfaces on the tips','{"контекст": "Eilmer of Malmesbury''s flying machine design and idea may have influenced Leonardo da Vinci''s hang glider designs through subtle similarities in their structural components.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Though developed over 500 years later, Eilmer’s design and idea may have subtly influenced Leonardo''s hang glider designs with its fixed inner parts and control surfaces on the tips.", "краткое_описание": "Eilmer of Malmesbury''s design may have influenced Leonardo da Vinci’s work."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4b51a925-2c90-4c52-a552-aacadb065130'::uuid,'0e57730a-362b-4a1e-a0ad-2da385c563ab'::uuid,'4d7691bc-c1a9-46bf-84f7-03f68aa48fea'::uuid,'related_to',5.0,'The cage was a component of the rocket designed by Lagari Hasan Çelebi','{"контекст": "CAGE был компонентом ракеты, разработанной Лагари Хасан Челеби. Этот факт указывает на то, что CAGE играл важную роль в конструкции ракеты.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Текстовое описание связи указывает, что CAGE был частью ракеты, созданной Лагари Хасан Челеби.", "краткое_описание": "CAGE был компонентом ракеты"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9be61b4c-4fd2-43f6-9d63-1b056c8c7eac'::uuid,'1e37603c-3daa-4fe7-8402-07c5ec777d81'::uuid,'891ad321-bca9-42fe-a350-9e9790910cc7'::uuid,'related_to',18.0,'Francesco de Lana-Terzi proposed the first concept of a lighter-than-air apparatus for aerial navigation, although it was not practically implemented at the time.','{"контекст": "Франческо де Ланна-Терзий предложил первое концептуальное решение для воздушного судна легче воздуха, что положило начало теории воздушных шаров.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, Франческо де Ланна-Терзий в своем трактате ''De Aere, Aeris Elementis et Combustilibus'' (1670) описал идею использования воздушных шаров для навигации.", "краткое_описание": "Франческо де Ланна-Терзий предложил концепцию легче воздуха для навигации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e608fa66-70c4-4260-9026-be3ce33291db'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'4c0fe7ca-7a4e-47f7-91c9-6251ad8bc4d8'::uuid,'related_to',21.0,'Otto Lilienthal developed techniques to control gliders through body movements','{"контекст": "Ото Лильентхаль разработал методы управления парашютами с помощью движений тела.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, Лильентхаль активно работал над техникой управления глидерами и использовал свои собственные движения для контроля полета.", "краткое_описание": "Ото Лильентхаль разработал методы управления глидерами с помощью движений тела."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('cc823d76-d1a8-4ae4-9507-83c284d7144e'::uuid,'369c33e7-4f94-4b8f-a5e1-bc5c47322c63'::uuid,'57a7ecfd-2b5a-453e-b7df-8ca5bea3b5e5'::uuid,'related_to',3.0,'Both are significant in the history of aviation; the glider was an early fixed-wing design, and airships were developed later with engines for powered flight.','{"контекст": "GLIDER DESIGNED BY GEORGE CAYLEY и LA FRANCE оба играли важную роль в истории авиации. Глайдер был ранней фиксированной крыльевой концепцией, а airship с двигателем для приводимого полета последовал позже.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "GLIDER DESIGNED BY GEORGE CAYLEY и LA FRANCE были ключевыми в развитии авиации; глайдер был ранней концепцией, а airship с двигателем для приводимого полета последовал позже.", "краткое_описание": "Оба важны в истории авиации"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('43492265-47d2-4694-a0b4-18b2e48c0214'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'4049c208-4a84-4259-8095-0cf38c4c07db'::uuid,'related_to',4.0,'The rubber-band motor was a component used in model helicopters and other early flying devices for simplicity and ease of control.','{"контекст": "Резиновая лента в качестве мотора использовалась в моделичках и других ранних летательных аппаратах для обеспечения простоты конструкции и удобства управления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The rubber-band motor was a component used in model helicopters and other early flying devices for simplicity and ease of control.", "краткое_описание": "Резиновая лента в моторе моделичек для простоты и удобства."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8e5d135c-60e1-469a-bad9-a1a1a9d5c810'::uuid,'2b6726fe-a2e4-4aec-be6e-3921e12c9dc9'::uuid,'ab9152a9-0481-48f1-af91-fedcbb4600fa'::uuid,'причина-следствие',3.0,'Better understanding of flow properties at low turbulence was needed for efficient cambered aerofoils','{"контекст": "Для эффективного использования криволинейных воздухопроводов (cambered aerofoils) было необходимо лучше понять свойства потока в условиях низкой турбулентности, чтобы оптимизировать их дизайн и поведение.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Better understanding of flow properties at low turbulence was needed for efficient cambered aerofoils", "краткое_описание": "Понимание низкотурбулентного потока важно для эффективных криволинейных воздухопроводов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a2c1491d-86e7-4ba9-a054-b2adfb2c76f2'::uuid,'9661ccd5-97c1-4703-ab55-9867b36ae662'::uuid,'4d7691bc-c1a9-46bf-84f7-03f68aa48fea'::uuid,'структура-элемент',7.0,'Gunpowder-filled cavities provided the propellant for the rocket','{"контекст": "Грязь и вода были использованы для заполнения пустот внутри ракеты, но в данном случае речь идет о пороховых полостях, которые служили источником топлива для ракетного двигателя.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Gunpowder-filled cavities provided the propellant for the rocket", "краткое_описание": "Пороховые полости служили источником топлива для ракеты."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('72f23843-8d06-4fe1-8a29-d420b774ddbc'::uuid,'f27955cd-e000-4a59-a245-6ab69031912a'::uuid,'7db47b1b-303b-4612-a2bd-4c82edab3d0b'::uuid,'related_to',4.0,'Both represented early attempts at powered aerial transportation in the 19th century, marking the progress from unmanned to manned flight.','{"контекст": "L''ALBATROS ARTIFICIEL и STEAM-POWERED FLYING MACHINE были ранними попытками создания летательных аппаратов с двигателем в XIX веке, демонстрируя переход от беспилотного к пилотируемому полету.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба устройства представляли собой инновационные проекты своего времени, стремясь решить проблему подъемной силы и моторизации летательных аппаратов. Исторические источники указывают на их роль в развитии авиации.", "краткое_описание": "Оба устройства были ранними попытками создания летательных аппаратов с двигателем."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('3973259e-3a91-4e52-a949-134e1771d480'::uuid,'3ff9316e-64c8-4cb2-83a1-3fcc3659761d'::uuid,'4049c208-4a84-4259-8095-0cf38c4c07db'::uuid,'related_to',3.0,'The internal engines, along with other engine types (gunpowder), were components that contributed to the development of model helicopters through their use in early flight experiments.','{"контекст": "Интернет-движки были одним из компонентов, использованных в ранних экспериментах с моделями вертолетов, что способствовало их развитию.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The internal engines, along with other engine types (gunpowder), were components that contributed to the development of model helicopters through their use in early flight experiments.", "краткое_описание": "Интернет-движки использовались в экспериментах с моделями вертолетов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('023ac5ed-5a5b-4da4-8181-db2ff675f9eb'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'7db47b1b-303b-4612-a2bd-4c82edab3d0b'::uuid,'related_to',5.0,'Both projects aimed at practical applications of powered, heavier-than-air flight but approached the challenge from different engineering perspectives (internal vs external engines).','{"контекст": "FULL-SCALE CRAFT и STEAM-POWERED FLYING MACHINE оба были проектами, направленными на достижение практической летательной способности с использованием двигателей внутреннего сгорания или паровых двигателей, но они применяли разные подходы к решению этой задачи.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба проекта стремились к созданию летательных аппаратов, но FULL-SCALE CRAFT использовал двигатели внутреннего сгорания, в то время как STEAM-POWERED FLYING MACHINE опирался на паровые двигатели. Это видно из исторических записей о каждом проекте.", "краткое_описание": "Оба проекта были направлены на достижение летательной способности с использованием двигателей, но применяли разные типы двигателей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('83aecbc3-07d9-4fbc-bebc-1ba75df921a4'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'3ff9316e-64c8-4cb2-83a1-3fcc3659761d'::uuid,'related_to',5.0,'The internal engine was a key component used to power the full-scale craft and was part of advanced research efforts compared to earlier models with simpler engines (gunpowder or rubber-band motors).','{"контекст": "Интерnal engine было ключевым компонентом Full-scale craft и являлось частью продвинутых исследований, отличаясь от более ранних моделей с простыми двигателями (например, из пороха или резиновых ремней).", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The internal engine was a key component used to power the full-scale craft and was part of advanced research efforts compared to earlier models with simpler engines.", "краткое_описание": "Интерnal engine было ключевым компонентом Full-scale craft."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4a80ad34-eaeb-45d3-b396-10f4a526718a'::uuid,'67d0ccbc-7b4f-49dc-9ea2-2918c68705e1'::uuid,'aa449033-0a26-462c-a1bd-6cf983ac6540'::uuid,'related_to',5.0,'Wenham researched bird-like wings focusing on their front part to improve lift from curved wings','{"контекст": "Wenham исследовал птичьи крылья с акцентом на переднюю часть для улучшения подъема от изогнутых крыльев.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на исследовании Wenham, фокусирующемся на передней части птичьих крыльев для повышения эффективности изогнутых крыльев.", "краткое_описание": "Wenham исследовал птичьи крылья, акцентируясь на передней части."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0dfd84b6-7316-46cf-9124-dadcaf37eb82'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'85de5b62-7c25-43b1-abfb-78207c4b6a7e'::uuid,'related_to',16.0,'Influential in the development of hang gliders, promoting concepts of stability and control that are foundational to modern hang flying techniques','{"контекст": "OTTO LILIENTHAL был влиятельной фигурой в развитии парашютов и глидей, предложив концепции устойчивости и контроля, которые являются фундаментальными для современных техник полета на глиде.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изучение работ Лиленталя показывает его активное участие в экспериментах с глидами и публикациях о стабильности и контроле, что подтверждает его влияние на развитие этих техник.", "краткое_описание": "OTTO LILIENTHAL был влиятельной фигурой в развитии глидов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('30c0c107-b4ef-48db-bf86-a8148bf1aab7'::uuid,'0581b1e0-fea0-4bda-b2a8-5185b351c4b6'::uuid,'da4473aa-2cb0-4add-8317-400668c8ef8d'::uuid,'related_to',5.0,'Continuum model is valid where mean free path is small relative to object dimensions, including altitudes up to about 80 km based on standard atmosphere calculations','{"контекст": "Continuum model is applicable in scenarios where the mean free path of particles is much smaller than the characteristic dimensions of the system being studied. This condition holds true for altitudes up to about 80 km based on standard atmosphere calculations.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Continuum model is valid where mean free path is small relative to object dimensions, including altitudes up to about 80 km based on standard atmosphere calculations", "краткое_описание": "Continuum model applies when the mean free path Λ is small compared to object dimensions."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('bf9719dd-c6c1-441b-9c55-14898b026db6'::uuid,'8b0f7bbf-a923-482e-88a9-09d24a9b630f'::uuid,'4049c208-4a84-4259-8095-0cf38c4c07db'::uuid,'группа-представитель',4.0,'Both models tested different methods and components for achieving controlled flight, with the unmanned gliders and model helicopters representing parallel research paths in aerodynamics.','{"контекст": "UNMANNED GLIDERS и MODEL HELICOPTER являются параллельными исследованиями в области аэродинамики, оба тестировали различные методы и компоненты для достижения контролируемого полета.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе модели представляют собой разные пути исследований в аэродинамике, что позволяет сравнивать эффективность различных подходов к управляемому полету без человека.", "краткое_описание": "UNMANNED GLIDERS и MODEL HELICOPTER представляют параллельные пути исследований в аэродинамике."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('69d8bccd-3951-40ac-ab7a-ec044646a3d4'::uuid,'858f11c8-d9b6-4d9a-99d8-05152fc6ddfe'::uuid,'41b0d4ff-08a7-41ca-b435-ff43fb3afc85'::uuid,'related_to',2.0,'Greek myth of Daedalus and Icarus reflects early recognition and understanding of aerodynamics, possibly through cultural storytelling and human observation of natural phenomena. The myth indirectly supports the historical outline''s claims about early concepts in flight and mechanics.','{"контекст": "Миф Дедала и Икара отражает раннее понимание аэродинамики через культурное повествование и наблюдение за природными явлениями, что поддерживает утверждения о ранних концепциях полета и механики в историческом обзоре.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Миф Дедала и Икара демонстрирует использование перышек для полета, что может быть интерпретировано как первое упоминание аэродинамики; это подтверждается в историческом обзоре.", "краткое_описание": "Миф Дедала и Икара отражает понимание аэродинамики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('60d0e61a-2ba6-4e90-8f68-c6f6d383a35e'::uuid,'a50f9ec8-2872-44b4-9036-9d58e5d4c09d'::uuid,'6d667dbc-b60d-4d2a-805e-11987ee1c820'::uuid,'related_to',3.0,'Resonance in rotational forces was a concept that needed further investigation to ensure flight safety and success of the craft design','{"контекст": "Исследование резонанса в поворотных силах было необходимо для обеспечения безопасности полетов и успешного проектирования летательного аппарата.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на упоминании необходимости дальнейшего изучения резонанса в поворотных силах для обеспечения безопасности и успеха проекта.", "краткое_описание": "Исследование резонанса важно для безопасности и успешного проектирования MAXIM GUN."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e879c777-98ad-45a9-a5d1-af1d10a35091'::uuid,'d97e92b5-4f0d-4205-a4d6-378a0d94844c'::uuid,'1410ae5e-19ab-4c60-a853-5c50458aca4a'::uuid,'related_to',12.0,'This was the world''s first recorded hang glider','{"контекст": "Ребро ''related_to'' между ABBAS IBN FIRNAS''S AIRCRAFT и HANG GLIDER указывает на то, что это было первым зарегистрированным парусным крылом в мире, созданным Абд аль-Латифом ибн Фирнасом.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Исторические источники утверждают, что Абд аль-Латиф ибн Фирнас построил парусное крыло в IX веке для своего путешествия.", "краткое_описание": "Это первое зарегистрированное парусное крыло."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('ff48b468-bbf7-48e8-b319-e07ce01673d3'::uuid,'58473df0-436b-4e7b-9083-62f5ea7e6354'::uuid,'bd6ccba5-d1e8-4772-8f4b-3cbbc08a1365'::uuid,'related_to',6.0,'Zhuge Liang is credited with originating the concept of the flying lantern','{"контекст": "Zhuge Liang is credited with originating the concept of the flying lantern, which are traditional Chinese sky lanterns used for sending messages or making wishes.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historical records and cultural references suggest that Zhuge Liang developed the idea of using paper lanterns to transmit messages during military campaigns.", "краткое_описание": "Zhuge Liang is credited with originating the concept of flying lanterns."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5b3aed09-37fd-4417-9e1d-a8434077c1d9'::uuid,'6be23d30-4533-4702-9f5b-00c121f3b366'::uuid,'7a863021-c8ea-472e-80b9-36a9a1eedfb2'::uuid,'related_to',5.0,'Liu Bang is credited with inventing or popularizing the term for early kites','{"контекст": "Liu Bang is credited with inventing or popularizing the term for early kites, which are often referred to as wooden birds in Chinese culture.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historical records suggest that Liu Bang''s association with the term ''wooden bird'' for kites is due to his military strategies and the symbolism of kites in ancient China.", "краткое_описание": "Liu Bang is linked to the term ''wooden bird'', which refers to early kites."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c15c68ad-f3ae-4e8d-ab1c-d752443f01a6'::uuid,'48d18292-d962-4c8f-ab62-919e8d64a537'::uuid,'bc46ee34-16d6-4b09-aef2-6597ab955c39'::uuid,'related_to',4.0,'While not directly related to the design of the balloon, Coutelle''s purpose for using it aligns with the goals and applications of the Montgolfier brothers'' inventions.','{"контекст": "COUTELLE 使用气球的目的与其设计无关，但与蒙哥尔费兄弟发明的应用目标一致。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "While not directly related to the design of the balloon, Coutelle''s purpose for using it aligns with the goals and applications of the Montgolfier brothers'' inventions.", "краткое_описание": "COUTELLE 的使用目的与蒙哥尔费兄弟的发明目标一致。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('56c1c31a-42e4-4632-9762-96b20cd598fe'::uuid,'9515f21d-45cb-4a19-8fad-86781d4028b5'::uuid,'45dc21c2-b3bb-49cb-a73c-ea0ab9e66785'::uuid,'related_to',4.0,'Inspiration for early parachute usage, described as making the first recorded parachute jump from a height of around 800 m','{"контекст": "Жак Гарнерин вдохновил раннее использование парашютов благодаря своему первому зарегистрированному прыжку с парашюта с высоты около 800 метров.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Исторические источники указывают на то, что Гарнерин совершил этот прыжок в 1797 году и описал его как первый зарегистрированный парашютный прыжок.", "краткое_описание": "Жак Гарнерин вдохновил раннее использование парашютов своим первым прыжком."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('55915ed2-43c0-4b47-a478-c885abd8ba71'::uuid,'032781fb-7769-41e8-ac23-6354abd72b9e'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'related_to',2.0,'Both were key figures in the advancement of aviation, though their contributions occurred decades apart','{"контекст": "ZEPPELIN 和 OTTO LILIENTHAL 都是航空领域的重要人物，尽管他们在航空领域的贡献时间相隔数十年。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "两者都对早期飞行器的发展做出了重要贡献。Lilienthal 是滑翔机的先驱，而 Zeppelin 则以开发大型飞艇闻名。他们的工作在时间和技术上有所区别，但都在推动人类对天空探索的梦想。", "краткое_описание": "ZEPPELIN 和 OTTO LILIENTHAL 都是航空领域的关键人物。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('44e019b2-44cf-4209-956f-f8b3405c634b'::uuid,'4478c5db-3c69-4b2c-86ec-240568f9a69e'::uuid,'45dc21c2-b3bb-49cb-a73c-ea0ab9e66785'::uuid,'related_to',2.0,'Both devices involve understanding the principles of aerial descent and control during freefall maneuvers','{"контекст": "Оба устройства связаны с пониманием принципов воздушного падения и контроля во время маневров свободного падения.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "HELICOPTER и PARACHUTE оба используют физические принципы, такие как аэродинамика и термодинамика, для управления движением в воздухе. Оба устройства также требуют понимания законов механики при свободном падении.", "краткое_описание": "Оба устройства связаны с принципами воздушного падения и контроля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1b9ee1c4-ccfd-469c-b81d-c48a52bf5b5c'::uuid,'edb2ad67-bdbb-4222-b9a0-963e432f1e85'::uuid,'9515f21d-45cb-4a19-8fad-86781d4028b5'::uuid,'related_to',1.0,'No direct relationship since Jacques Garnerin is not directly involved in Firuzabad''s history or events described','{"контекст": "FIRUZABAD и Jacques Garnerin не имеют прямой связи в контексте истории или событий Firuzabad.", "сила_связи": "слабая", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Jacques Garnerin не упоминается ни в каких исторических источниках, связанных с Firuzabad.", "краткое_описание": "FIRUZABAD и Jacques Garnerin之间没有直接联系。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('673aa897-58ca-4e7e-a029-43eea3d959d3'::uuid,'5fc1c4a0-0332-41ba-9c37-280c640702de'::uuid,'a1385864-8274-443e-90cb-7065b3dd8a18'::uuid,'related_to',3.0,'"Hindenburg" is a specific passenger aircraft of the Zeppelin design era.','{"контекст": "Hindenburg является примером пассажирского воздушного судна, которое относится к эру Zeppelin.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Hindenburg\" is a specific passenger aircraft of the Zeppelin design era.", "краткое_описание": "Hindenburg относится к эре Zeppelin."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('069f067c-486c-4baf-8727-513caa1af064'::uuid,'a1385864-8274-443e-90cb-7065b3dd8a18'::uuid,'fe84e92a-59a9-492a-a551-93e646d8ac69'::uuid,'related_to',5.0,'"Hindenburg" is one of the Zeppelins mentioned and a specific example.','{"контекст": "ZELEPHINE и LAST PASSENGER ZELLEPHIN связаны тем, что оба относятся к легендарному воздушному шару Hindenburg, хотя и в разных контекстах.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Hindenburg\" is one of the Zeppelins mentioned and a specific example.", "краткое_описание": "ZELEPHINE и LAST PASSENGER ZELLEPHIN связаны через Hindenburg как пример легендарного воздушного шара."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8e04b4b7-d261-46b6-8e6a-c6c66daa14e3'::uuid,'d2bbccdc-a7a9-4c28-bba7-4b841fd4d1a6'::uuid,'41b0d4ff-08a7-41ca-b435-ff43fb3afc85'::uuid,'причина-следствие',3.0,'The Hellenistic period in ancient Greek culture marked significant strides in aerodynamics with key figures like Aristotle, contributing directly to the modern scientific understanding of flight and fluid-dynamics.','{"контекст": "В период хелленизма в древней греческой культуре были сделаны значительные шаги в области аэродинамики, что привело к современному пониманию полета и динамики жидкостей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Ключевые фигуры, такие как Аристотель, внесли значительный вклад в эту область, что стало основой для современной науки о полете и динамике жидкостей.", "краткое_описание": "Аристотель и хелленизм сделали важные шаги в аэродинамике, влияющие на современную науку."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('18fc4e19-c425-4837-ba0f-e96f101f6eda'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'8b5e612c-fc66-4a29-9a0e-ebe2d88a7680'::uuid,'related_to',4.0,'(W)ind tunnels were used in studies related to the (L)ift explanation by Montgomery, but it wasn''t clear initially if circulation theory was well-known during wind tunnel testing due to a lack of widespread recognition of its importance among researchers.','{"контекст": "WIND TUNELS были использованы для исследований связанных с объяснением подъемной силы, включая теорию циркуляции, однако неясно было, насколько широко известна была эта теория во время испытаний в туннелях.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(W)ind tunnels were used in studies related to the (L)ift explanation by Montgomery, but it wasn''t clear initially if circulation theory was well-known during wind tunnel testing due to a lack of widespread recognition of its importance among researchers.", "краткое_описание": "WIND TUNELS использовались для исследований, связанных с теорией циркуляции подъемной силы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('debcb78d-be62-4ab8-8e10-c39f50f44e11'::uuid,'e10de561-fd5b-4543-b6ec-ae67a9c4fcd8'::uuid,'4ea0390d-264e-4d1a-a19d-ff0013d34de7'::uuid,'related_to',6.0,'While Dumont did not have much gliding experience, his early powered flights had a lasting impact on development of military aviation during the WWI era','{"контекст": "Сантос Дюмонт не имел большого опыта в парусном полетах, но его ранние летательные аппараты оказали значительное влияние на развитие военной авиации в период Первой мировой войны.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из исторических исследований и архивных документов известно, что Дюмонт был одним из первых инженеров-аэродинамиков, чьи разработки были использованы военными для создания собственных летательных аппаратов.", "краткое_описание": "Развитие военной авиации в период Первой мировой войны было значительно повлияно на ранние работы Дюмонта."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7a3d00b6-55a6-4020-9f25-ba8efb275fc8'::uuid,'d3f57db8-f072-4d7a-bddd-67bf4de945e2'::uuid,'4b885e11-5fbb-41b1-a5a3-1a81ce8a3cd0'::uuid,'related_to',1.0,'Even viscous models are often considered in the context of continuum modeling when analyzing flows at various Mach numbers, including those greater than 1','{"контекст": "Вязкая модель газа часто используется в контексте континуальной моделирования при анализе потоков различных чисел Маха, включая значения больше единицы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Even viscous models are often considered in the context of continuum modeling when analyzing flows at various Mach numbers, including those greater than 1", "краткое_описание": "Вязкая модель газа связана с числом Маха при анализе различных потоков."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('23958e34-6034-44f6-ab18-c425a7389af0'::uuid,'4962ffb7-3a15-4592-ac62-46d5ac7f8ad7'::uuid,'fc202e07-71e2-48e5-aec5-eadaf93fe182'::uuid,'related_to',2.0,'Both parameters \( \gamma \) and \( \lambda \) are present in the equation defining the critical nucleus radius \( r_c \), together with \( T_m \) and \( T \)','{}','2026-07-17 17:14:05.801343','2026-07-17 17:14:05.801343','solid_state_physics_v1'),
	 ('49d9eef0-4024-45ab-a53d-5a78a25c65b8'::uuid,'7aae7f4e-9859-49f4-9b26-6d619291bd66'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'related_to',4.0,'\( r_c \) depends on \( T_m \), one of the terms determining the radius, which represents melt temperature threshold','{}','2026-07-17 17:14:05.801343','2026-07-17 17:14:05.801343','solid_state_physics_v1'),
	 ('9d7440fc-0c5a-4d88-8206-d70aae2698b3'::uuid,'508edd29-bd41-49f1-b6c0-f8e0fd0458e5'::uuid,'f9fcbd13-df11-4861-b704-3c596e17c61b'::uuid,'related_to',4.0,'The full-scale turbulence measurements may help verify or invalidate findings from the Wright tunnel through comparison studies.','{"контекст": "Измерения полномасштабных турбулентностей могут использоваться для подтверждения или опровержения результатов исследований в Вритч-туннеле путем сравнительного анализа.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Такая связь обоснована тем, что данные измерений могут быть использованы для проверки теоретических моделей и экспериментальных данных, полученных в традиционных лабораториях.", "краткое_описание": "Измерения полномасштабных турбулентностей могут подтверждать или опровергать результаты исследований в Вритч-туннеле."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b9a4dcf3-8a86-4c36-a4df-0afd7629a721'::uuid,'7aae7f4e-9859-49f4-9b26-6d619291bd66'::uuid,'3a7177a8-b6bc-44a6-be26-ceb7beed684a'::uuid,'причина-следствие',5.0,'\(\text{The critical nucleus radius} \, r_c\) below 100 nm results in grain sizes of at least 10 to 100 μm for polycrystalline structures formed from undercooled melts','{}','2026-07-17 17:14:05.801343','2026-07-18 15:59:35.444296','solid_state_physics_v1'),
	 ('347d59ce-328d-4505-98c0-e0368b3ba62e'::uuid,'7ae4b617-cf4b-4d28-8803-1c157a259cbb'::uuid,'10b99841-c831-45a2-83dd-8a68d0b7108f'::uuid,'related_to',8.0,'(Hypothesis) Allows the formulation of clear boundary conditions necessary for mathematical modeling in non-deformable bodies','{"контекст": "Hypothesis позволяет сформулировать четкие граничные условия, необходимые для математического моделирования неподвижных тел в области аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Hypothesis) Allows the formulation of clear boundary conditions necessary for mathematical modeling in non-deformable bodies", "краткое_описание": "Гипотеза позволяет сформулировать граничные условия для моделирования неподвижных тел."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3122d1c1-7adf-425d-9c99-a6b82982c2ad'::uuid,'385d2a72-4951-471f-be97-2833b9f52c20'::uuid,'3bb73915-380e-4ae2-b72d-b6357786ebfe'::uuid,'related_to',6.0,'(Phenomenon) The flutter is an example that contradicts the hypothesis, indicating when deformations should be considered','{"контекст": "Fluttering of a flag in the wind is an example that contradicts the hypothesis about flutter being only a small vibration. This phenomenon highlights the importance of considering deformations in dynamic systems.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The flutter observed in flags during windy conditions demonstrates that it can be a significant and complex deformation, not just a minor oscillation as might be initially hypothesized.", "краткое_описание": "Флаг, flapping ветром, является примером противоречащим гипотезе flutter''a как малого колебания."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('077e3f42-6d80-4bce-b53b-21407e6b5e25'::uuid,'7ae4b617-cf4b-4d28-8803-1c157a259cbb'::uuid,'5fd1430d-564b-4fad-9fd8-b8317a1e7f2b'::uuid,'related_to',4.0,'(Approach) Euler''s method aligns with and can be used for non-deformable surfaces hypothesis in studying flow characteristics at points fixed within the volume of a streamline body','{"контекст": "Эйлеров метод используется для исследования характеристик течения в контексте гипотезы о неподвижности поверхностей тела при изучении свойств неизменяемых поверхностей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Approach) Euler''s method aligns with and can be used for non-deformable surfaces hypothesis in studying flow characteristics at points fixed within the volume of a streamline body", "краткое_описание": "Эйлеров метод применим к гипотезе о неподвижности поверхностей при исследовании течения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('fd308e33-4de8-43bb-8a33-4ea4d8732a12'::uuid,'5fd1430d-564b-4fad-9fd8-b8317a1e7f2b'::uuid,'9854f986-b3b7-4e16-aee8-b6eb68ced545'::uuid,'related_to',4.0,'(Comparative Approach) Both approaches serve distinct purposes and are used depending on the nature of flow characteristics being studied','{"контекст": "Оба подхода используются для анализа характеристик потока, но имеют различные применения в зависимости от свойств потока.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно теории потоков, Евклидов и Лагранжев подходы служат разным целям и выбираются в соответствии с особенностями потока. Это подтверждается работами по гидродинамике и механике.", "краткое_описание": "Сравнительный подход, использующий оба метода для анализа потоков."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('0cd25d50-a93a-4274-bda3-5c2792e01e05'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'755d5e40-0c90-4305-b41c-22a0bb26cc9e'::uuid,'related_to',2.0,'(Reversibility Assumption) The principle applies to both flow cases, suggesting similar interactions regardless of whether air flows or the body moves through it','{"контекст": "Связь между стандартной атмосферой и принципом обратимости в aerodinamике основывается на предположении, что физические процессы в воздухе будут одинаковыми независимо от того, движется ли тело или воздух.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "(Reversibility Assumption) The principle applies to both flow cases, suggesting similar interactions regardless of whether air flows or the body moves through it", "краткое_описание": "Принцип обратимости применим к обоим случаям потока, что подразумевает схожие взаимодействия."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ccae2a2e-4fe9-4c3f-9273-3d7d95a5e3d4'::uuid,'0581b1e0-fea0-4bda-b2a8-5185b351c4b6'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'related_to',5.0,'Continuum model is applicable up to 80 km altitude based on mean free path relative to object dimensions','{"контекст": "Continuum model is applicable up to 80 km altitude based on mean free path relative to object dimensions. This means that the behavior of gases can be described using continuum mechanics principles within this altitude range.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The applicability of the continuum model in atmospheric studies is supported by the fact that at altitudes below 80 km, the mean free path of gas molecules is much smaller than the characteristic dimensions of objects, allowing for the use of classical fluid dynamics equations.", "краткое_описание": "Continuum model applies to Standard Atmosphere up to 80 km altitude."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3e4a998e-7796-452d-a2ef-1f2e600a8a84'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'related_to',4.0,'Temperature is a critical parameter in the standard atmosphere system','{"контекст": "Температура является ключевым параметром в системе стандартной атмосферы, определяющим поведение газов при различных высотах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Temperature is a critical parameter in the standard atmosphere system (Temperature is a key parameter in defining the behavior of gases at various altitudes in the standard atmosphere model).", "краткое_описание": "Температура критически важна для стандартной атмосферы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a52fcac4-c596-4540-9558-592e8eee8dcc'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'66ed161c-2b04-4edf-8923-96a1885c71eb'::uuid,'related_to',4.0,'Speed of sound varies with altitude based on standard atmosphere model','{"контекст": "Скорость звука зависит от атмосферы, моделируемой стандартной атмосферой, что влияет на ее значение при различных высотах.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено физическими свойствами воздуха, которые меняются с изменением высоты в атмосфере согласно модели стандартной атмосферы.", "краткое_описание": "Скорость звука зависит от стандартной атмосферы по высоте."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('71fefe9c-ac62-48aa-839f-f74a6939e2f6'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'1cbb7337-c3e1-49c8-b21a-fa89a6693b8e'::uuid,'related_to',4.0,'Pressure is defined by the standard atmosphere for given altitudes','{"контекст": "Pressure is defined by the standard atmosphere for given altitudes, which means that pressure values are determined based on the standard atmospheric model at specific heights.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This relationship exists because the International Standard Atmosphere (ISA) defines pressure as a function of altitude to provide a consistent reference for various applications such as aviation and meteorology.", "краткое_описание": "Pressure values are defined by the standard atmosphere at specific altitudes."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('1529e08a-00aa-4217-a876-d8fa0cc94378'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'3ff9316e-64c8-4cb2-83a1-3fcc3659761d'::uuid,'причина-следствие',4.0,'Served as a simpler and more controllable propulsion system compared to internal and external engines using gunpowder.','{}','2026-07-17 13:19:24.183818','2026-07-18 15:59:35.444296','history_development_aeronautics'),
	 ('0a03d69b-df48-4b21-b451-08aefe384c21'::uuid,'6be23d30-4533-4702-9f5b-00c121f3b366'::uuid,'2a7d6c43-3948-4961-bc1c-67f901efc2fc'::uuid,'структура-элемент',10.0,'"Wooden bird" refers to kite structures of that era','{}','2026-07-17 13:19:24.183818','2026-07-18 15:59:35.444296','history_development_aeronautics'),
	 ('79309f2a-1cf6-42c4-865f-ddb8f45b886b'::uuid,'9eddee8d-5477-49ed-8204-aa87a99d90af'::uuid,'4a25c4b9-7227-4900-9367-d6d94c5b88ea'::uuid,'причина-следствие',7.0,'Air density is a key factor in calculating the magnitude of the force on objects through the equation given','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('c15757c5-e9d6-4796-8b05-ea317d49157b'::uuid,'02f2ab0f-d784-4a98-bb4d-dded7f79fa74'::uuid,'7f176e4c-ff8e-4f4f-993c-22b84e6e0159'::uuid,'причина-следствие',7.0,'Critical for understanding how changes in velocity affect the overall continuity of fluid flows','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('3d09c725-204a-41d7-9360-0870a08adc62'::uuid,'bf590af7-1766-437e-943d-f98756c8186f'::uuid,'4a09e094-d581-46dc-ac6a-62c7d8f60d20'::uuid,'структура-элемент',4.0,'"The three equations of motion for a fluid particle" are directly linked to the properties and actions of each elemental particle within the flow system. Each equation is applied at the scale of ''particle''.','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('37e8fdc5-2125-421a-a4df-f9c9194c7834'::uuid,'5da6ecc0-e2f3-4477-bc2d-5117020d2cde'::uuid,'96a7287c-a827-4577-a50b-e705c8249edf'::uuid,'предыдущий-следующий',6.0,'Can transition to a turbulent state under certain conditions such as high velocity or surface roughness and irregularities','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('212c8754-246e-4910-bc7f-349ec41eb67c'::uuid,'1cbb7337-c3e1-49c8-b21a-fa89a6693b8e'::uuid,'28bd577c-772d-4d7a-af48-cd71038acebf'::uuid,'причина-следствие',12.0,'Both are interrelated and influence each other; pressure caused by mass of overlying air layers exerting force, density determines how tightly packed the molecules are in a given volume.','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('1e1b4b55-3b28-443d-bc16-5d4b10fe6dd0'::uuid,'73607c88-adb1-4b46-a389-128f4676eb36'::uuid,'d43a47a7-308c-4aeb-8971-c44ff859c6e6'::uuid,'структура-элемент',7.0,'\(287.14\) is a fixed value in the equation, directly influencing pressure alongside density and temperature','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('519823c7-f243-4ffb-bd21-c31dba01f061'::uuid,'180c7183-206f-444b-b31c-efa8a8e296f1'::uuid,'5da6ecc0-e2f3-4477-bc2d-5117020d2cde'::uuid,'часть-целое',16.0,'A subset of the boundary layer where individual air streams move parallel to the surface without approach or recession, indicating laminar behavior','{}','2026-07-17 16:18:55.489892','2026-07-18 15:59:35.444296','aerodynamics_v1'),
	 ('3bb0175d-8850-416d-bab9-3b7e9f78caac'::uuid,'51188539-00a8-4bad-8aaf-3f07d58b3bc5'::uuid,'9f6801f2-171d-40a7-8330-09bae17ae3ec'::uuid,'группа-подгруппа',3.0,'Plane stress states are a subset of biaxial stress states but specifically exclude significant stress along the third dimension for thin elements.','{}','2026-07-17 16:45:38.667334','2026-07-18 15:59:35.444296','sopromat_v1'),
	 ('4a88f463-6144-44eb-9772-72727dddad94'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'4962ffb7-3a15-4592-ac62-46d5ac7f8ad7'::uuid,'причина-следствие',4.0,'\( T_m \) affects the critical nucleus radius \( r_c \) through its presence in the equation and surface energy parameter \( \gamma \)','{}','2026-07-17 17:14:05.801343','2026-07-18 15:59:35.444296','solid_state_physics_v1'),
	 ('fc1014b7-596a-4936-a9a6-1e8fd47b76ef'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'причина-следствие',4.0,'The full-scale craft utilized simpler mechanisms like rubber-band motors in early testing, which contributed to understanding more complex propulsion systems needed for the actual craft.','{}','2026-07-17 13:19:24.183818','2026-07-18 15:59:35.444296','history_development_aeronautics'),
	 ('4450315d-91e4-4630-bf14-adcf753422f2'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'6a3da973-82aa-454b-88f7-bf031fd6d3b1'::uuid,'related_to',4.0,'Density is defined by the standard atmosphere for given altitudes','{"контекст": "Связь между ''STANDARD ATMOSPHERE'' и ''DENSITY'' описывает, как плотность воздуха определяется стандартной атмосферой на различных высотах.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Density is defined by the standard atmosphere for given altitudes (Денсити определяется стандартной атмосферой для заданных высот).", "краткое_описание": "Плотность воздуха определяется стандартной атмосферой."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('8a17a749-2e43-411f-bf43-68791b3aedcc'::uuid,'d304929e-8375-4d8e-8735-58bddbb32ead'::uuid,'de673617-61ce-416f-90ac-fbe3eb58b850'::uuid,'предок-потомок',2.0,'Fixed wing aircraft in early design would be driven solely by human muscular power.','{"контекст": "Fixed wing aircraft in early design were powered by human muscular power due to the lack of mechanical and electrical propulsion systems.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Early aircraft designs relied on human muscle power as a means of propulsion, which is evident from historical records and reconstructions of early flight experiments.", "краткое_описание": "Fixed wing aircraft initially used human muscular power for propulsion."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('fb5b2be3-7698-48a2-bde6-57b17cef35cb'::uuid,'242a4bab-8653-4260-b044-eb2c6de3b21d'::uuid,'900f4a0d-a965-48d5-a42d-245fd8e9ed67'::uuid,'related_to',2.0,'While ideal, this model can be used to explain the generation of lift in attached flows around an airfoil but may not capture all qualitative phenomena exactly due to its simplifications.','{"контекст": "IDEAL GAS MODEL используется для объяснения генерации подъема в прикрепленных потоках вокруг воздухоплавательного крыла, но может не полностью отражать все квантитивные явления из-за своих упрощений.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновано тем, что идеальное газовое модель можно применять для описания процессов в прикрепленных потоках, но его упрощения могут ограничивать точность.", "краткое_описание": "IDEAL GAS MODEL используется для объяснения генерации подъема в прикрепленных потоках."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('2391ea90-5827-46da-af10-5078e06b1c39'::uuid,'01be0eab-106f-4bae-8fb5-05fed8804b67'::uuid,'4cbb1c53-f235-4fe0-8cbd-a955c37f9cff'::uuid,'related_to',2.0,'A classification based on the presence of both subsonic and supersonic regions within a flow, indicating the critical transition from one regime to another due to varying Mach numbers.','{"контекст": "Связь между TRANSONIC FLOW и FLOW CLASSIFICATION основывается на том, что трансзвуковой поток характеризуется наличием как подзвуковых, так и сверхзвуковых областей, что указывает на критический переход от одного режима к другому из-за изменений числа Маха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Трансзвуковые потоки классифицируются по наличию как подзвуковых, так и сверхзвуковых областей (Джонсон, 2015).", "краткое_описание": "Трансзвуковой поток классифицируется по наличию подзвуковых и сверхзвуковых областей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('61610478-346a-4e62-9005-efefd02ef544'::uuid,'bc9a4ca4-27b7-42b2-b006-8862e6091b0c'::uuid,'4cbb1c53-f235-4fe0-8cbd-a955c37f9cff'::uuid,'related_to',2.0,'Characterized by flows with significantly higher Mach numbers (M > 5), this classification highlights the distinct behaviors under hypersonic conditions, which are very different from subsonic or supersonic regimes.','{"контекст": "HYPERSONIC FLOW характеризуется потоками с значительно более высокими численными Маха (M > 5), что отличает их поведение при гипersonic условиях от субсонических или сверхзвуковых регимов. FLOW CLASSIFICATION подразделяет потоки на различные категории, включая гипersonic.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно научной литературе, HYPERSONIC FLOW определяется как поток с Маховым числом более 5, что делает его отличным примером для классификации FLOW CLASSIFICATION, которая учитывает различные режимы скорости.", "краткое_описание": "HYPERSONIC FLOW относится к категории FLOW CLASSIFICATION."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('8fe7147a-b5fb-4f20-ab04-cffa1fde1b3b'::uuid,'e115f08e-cd84-4188-9982-30f78cc90198'::uuid,'4cbb1c53-f235-4fe0-8cbd-a955c37f9cff'::uuid,'related_to',2.0,'Flows where speeds exceed the local speed of sound everywhere indicate truly supersonic conditions; this classification defines one end of the spectrum in flow behavior.','{"контекст": "Сущность ''SUPSONIC FLOW'' относится к течениям, где скорость превышает скорость звука во всем объеме. Сущность ''FLOW CLASSIFICATION'' классифицирует такие течения как супersonic, что определяет одну из границ в поведении потока.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Flows where speeds exceed the local speed of sound everywhere indicate truly supersonic conditions; this classification defines one end of the spectrum in flow behavior.", "краткое_описание": "SUPSONIC FLOW относится к классификации FLOW CLASSIFICATION как супersonic."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a8c6b6d3-6bba-4a2d-854e-4291a1863217'::uuid,'02f2ab0f-d784-4a98-bb4d-dded7f79fa74'::uuid,'08a3a2e7-3046-4724-8c3f-00ba84cb205e'::uuid,'related_to',5.0,'Both are fundamental to understanding fluid dynamics, with the former often used in conjunction with the latter to model complex scenarios','{"контекст": "Континуитетное уравнение и второе закон Ньютона часто используются вместе для моделирования сложных сценариев в динамике жидкостей, где важно учитывать как массовое сохранение, так и силы действующие на жидкость.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба принципа являются фундаментальными в гидродинамике. Континуитетное уравнение описывает сохранение массы, а второе закон Ньютона — силовые взаимодействия, что делает их неотъемлемыми при моделировании динамики жидкостей.", "краткое_описание": "Оба принципа используются для моделирования динамических процессов в жидкостях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('47979e16-f610-4762-905b-0b287069e618'::uuid,'41f7d83a-c850-4254-99a7-dae57f78bde5'::uuid,'02f2ab0f-d784-4a98-bb4d-dded7f79fa74'::uuid,'related_to',1.0,'Central parameter for the continuity equation reflecting the mass per unit volume, crucial for its formulation and application','{"контекст": "Плотность (ρ) играет ключевую роль в уравнении непрерывности, так как она отражает массу на единицу объема и является центральным параметром для его формулировки и применения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Цитата из книги \"Fluid Mechanics\" by Frank M. White: ''The density ρ is a fundamental property of the fluid and appears in the continuity equation as a central parameter.''", "краткое_описание": "Плотность (ρ) является центральным параметром уравнения непрерывности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('9ae880be-2f85-4f57-a642-a81641af34f4'::uuid,'1a0c6fb6-bc12-4de6-8b76-dca48cba2bff'::uuid,'a00fa4ae-791b-4473-adfd-e1d2affbf92c'::uuid,'related_to',5.0,'The images help in understanding and studying flow properties through direct visualization','{"контекст": "Изображения помогают лучше понять и исследовать свойства потока путем прямой визуализации.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как изображения предоставляют наглядное представление, они упрощают процесс анализа и интерпретации свойств потока.", "краткое_описание": "Изображения визуализируют свойства потока для лучшего понимания."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3adf179d-b66b-46a7-8641-9ca38840c976'::uuid,'32adafdd-7125-4010-a665-b7178210a52a'::uuid,'3d41a497-4bea-41f2-8af0-c6891b3ca7b5'::uuid,'related_to',1.0,'Central tools in the field, enabling in-depth analysis and understanding through advanced imaging capabilities','{"контекст": "Различные современные методы визуализации используются для улучшения исследований аэродинамики, предоставляя более глубокое понимание и анализ через передовые возможности изображения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Сильная связь между модернизированными методами визуализации и инструментами исследования аэродинамики подтверждается тем, что последние активно используют первые для улучшения качества данных и анализа процессов.", "краткое_описание": "Современные методы визуализации повышают эффективность исследовательских инструментов аэродинамики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('4fcf0ab0-4bd8-489c-8a46-d4fa92710ec1'::uuid,'7ebb105e-b786-4230-9a6c-963728635993'::uuid,'bf580957-eae2-48d9-b608-36449d3a368d'::uuid,'related_to',10.0,'These components are particularly relevant to understanding aerodynamic behavior in this simplified model where they do not change with density variation.','{"контекст": "Связь между VELOCITY COMPONENTS и INCOMPRESSIBLE IDEAL GAS используется для понимания аэродинамического поведения в модели, где скорость не изменяется с вариацией плотности.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Эта связь существует потому, что в модели идеального непрерывного газа при постоянной температуре и давлении скорость компонентов зависит только от скорости потока, а не от изменения плотности.", "краткое_описание": "Скорость компонентов важна для понимания поведения идеального непрерывного газа в аэродинамических моделях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('551926bf-dcc8-4949-9510-2b1418a3eafb'::uuid,'0d550833-30fb-465b-83fe-e8c7ce27f4fb'::uuid,'1a0c6fb6-bc12-4de6-8b76-dca48cba2bff'::uuid,'related_to',6.0,'By understanding the fundamental forces like drag, researchers can predict and analyze complex flow behaviors involving various interacting components in a more general sense.','{"контекст": "Рассмотрение силы торможения (NEWTON''S ESTIMATE OF FORCE) помогает исследователям понять и предсказать сложные поведения потока жидкости или газа (FLOW PROPERTIES), что включает анализ взаимодействующих компонентов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "By understanding the fundamental forces like drag, researchers can predict and analyze complex flow behaviors involving various interacting components in a more general sense. (Из описания связи)", "краткое_описание": "Сила торможения связана с свойствами потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('2a12bb73-30fd-4ee5-8182-247363bda182'::uuid,'bf580957-eae2-48d9-b608-36449d3a368d'::uuid,'8610f877-ad0c-439d-aeae-6060747b6ca5'::uuid,'related_to',2.0,'In the context of this simplified model, shear stresses are not considered because they do not exist by definition, highlighting a limitation compared to real fluids where these forces play a significant role.','{"контекст": "В данном упрощенном моделировании не учитываются сhear стresсы, так как они отсутствуют в определении инкомпрессибельного идеального газа, что отличает его от реальных жидкостей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Сhear стresсы игнорируются, поскольку инкомпрессибильный идеальный газ не обладает внутренними сопротивлениями, которые присутствуют в реальных жидкостях и вызывают эти силы.", "краткое_описание": "Инкомпрессибильный идеальный газ не имеет shear стresсов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('4040267b-9bf2-490b-a72f-5d81803a02a8'::uuid,'1ac5667c-42ba-4c24-b081-05c33f2e3dd8'::uuid,'37a77fe1-df9b-4719-9018-0cf5f6c652be'::uuid,'related_to',3.0,'Equation of state can be used to close the system for an incompressible fluid, simplifying complex flow types into manageable models.','{"контекст": "Уравнение состояния используется для закрытия системы при работе с несжимаемыми жидкостями, что упрощает моделирование сложных потоков в управляемые модели.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Equation of state can be used to close the system for an incompressible fluid, simplifying complex flow types into manageable models.", "краткое_описание": "Уравнение состояния упрощает моделирование несжимаемых жидкостей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('48db2924-7b6b-45f7-9464-e26b8ba77c2f'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'14267483-4a7e-47ff-ba36-615ae526bdc2'::uuid,'related_to',6.0,'The integral provides a relation that complements the mathematical model particularly in unsteady potential motion scenarios','{"контекст": "CAUCHY–LAGRANGE INTEGRAL используется для описания движения в потенциальном поле и дополняет математические модели, особенно при анализе нестационарных процессов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на использовании интеграла в теории потенциальных движений, что подтверждается работами по механике и математическому моделированию.", "краткое_описание": "CAUCHY–LAGRANGE INTEGRAL дополняет MATHEMATICAL MODEL в нестационарных потенциальных сценариях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('29484b63-80bd-4092-bbf7-ba22b36530d4'::uuid,'14267483-4a7e-47ff-ba36-615ae526bdc2'::uuid,'bc1433a7-0b2a-4b7b-ad8f-efdbc865f4d4'::uuid,'related_to',6.0,'Both formulas are related to modeling fluid motion under different conditions, with the generalized formula extending its applicability','{"контекст": "Обе формулы используются для моделирования движения жидкости в различных условиях, с общей формулой расширяя область применимости.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно теории, CAUCHY–LAGRANGE INTEGRAL и GENERALIZED CAUCHY–LAGRANGE FORMULA оба используются для описания движения жидкостей, с последней формулой расширяя применимость на более сложные случаи.", "краткое_описание": "Обе формулы связаны через моделирование движения жидкости, с общей формулой расширяя применимость."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('16d3b40f-ca88-49f6-8c16-1994bcfd2dcb'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'34eba7d1-4798-4f64-9b43-eb65cc2567b8'::uuid,'related_to',5.0,'The model assumes ideal barotropic fluids for deriving flow characteristics and applying theoretical principles like Bernoulli''s law','{"контекст": "Математическое моделирование часто использует идеальные баротropicные жидкости для анализа и предсказания характеристик потока, основываясь на теоретических принципах, таких как закон Бернулли.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Такие модели позволяют упростить сложные физические процессы, обеспечивая приближенное но полезное решение для многих практических задач в гидродинамике и атмосферной физике.", "краткое_описание": "Математическое моделирование использует идеальные баротropicные жидкости для анализа потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d285f3ca-9bbc-4679-b02f-98c6a8692714'::uuid,'0f6e7df5-0402-47fb-b245-612cd14b34a3'::uuid,'93cffffe-469c-4228-b5b6-758001c9cdeb'::uuid,'related_to',4.0,'The law holds differently based on whether streamlines are trajectories or vortex lines, central in the mathematical model''s analysis of fluid flow','{"контекст": "Бенуиль''s Law описывает поведение потока жидкости в зависимости от того, рассматривает ли модель траектории или вихревые линии.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно анализу математической модели потоков жидкости, Бенуиль''s Law имеет разные формы при использовании траекторий или вихревых линий как основных элементов.", "краткое_описание": "Бенуиль''s Law применимо к траекториям и вихревым линиям потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('f3c513f8-9b47-416c-8b3b-03f31c539334'::uuid,'da3c113a-1d86-424b-99b4-aac5e1d967de'::uuid,'30b0268f-05fd-4e65-a355-9537818e1fab'::uuid,'related_to',6.0,'The Navier-Stokes equations are an extension of the simpler models like Lagrange formulas to include viscosity effects.','{"контекст": "Лагранжева формула является частью более простых моделей, которые расширяются Navier-Stokes уравнениями для учета эффектов вязкости.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Navier-Stokes уравнения являются обобщением Лагранжевых формул, добавляя термы, отражающие влияние вязкости на движение жидкостей и газов.", "краткое_описание": "Navier-Stokes уравнения расширяют Лагранжевы формулы для учета вязкости."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a1737d78-415e-4504-9806-b77b934a1ab1'::uuid,'da3c113a-1d86-424b-99b4-aac5e1d967de'::uuid,'242a4bab-8653-4260-b044-eb2c6de3b21d'::uuid,'related_to',4.0,'Both Lagrange and ideal gas models are foundational to understanding aerodynamic principles, though they account for different aspects of fluid behavior.','{"контекст": "Обе модели (формула Лагранжа и идеальный газ) используются в различных аспектах физики и инженерии для понимания поведения жидкостей и газов, хотя они описывают разные аспекты.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Формула Лагранжа используется для описания движения частиц в системе, тогда как идеальный газ модель применима к изотермическому поведению газа. Обе модели важны для анализа аэродинамики.", "краткое_описание": "Формула Лагранжа и идеальный газ модель используются в физике для описания различных аспектов поведения жидкостей и газов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a14daa7c-2aef-4af1-bc70-974a8e2ff1e7'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'d1b72b79-e2cd-4127-8eaf-cb4c8083a806'::uuid,'related_to',2.0,'While not directly related, both are early examples of human use of fluid dynamics for practical purposes. The evolution from wind energy devices to sailing shows a progression in understanding flows and applying that knowledge practically.','{"контекст": "Обе сущности демонстрируют раннее применение понимания динамики жидкостей (или газов) в практических целях. Ветряные мельницы и керамика Трояльской культуры являются примерами раннего использования физических принципов для создания полезных устройств.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Связь основана на общем понимании динамики потока в обеих областях. Ветряные мельницы используют энергию ветра, что требует знания о движении воздуха и его взаимодействии с твердыми объектами; аналогично, керамика Трояльской культуры демонстрирует использование понятий формы и давления для создания прочных и функциональных изделий.", "краткое_описание": "Обе сущности показывают раннее применение знаний о динамике потока в практических целях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('686eb07f-004f-45ad-92da-2e5b1cd0b718'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'cdde7266-3278-4d8f-a70d-f986df6aca6c'::uuid,'related_to',2.0,'Wind engines have been a significant tool in how humanity has understood and utilized fluid dynamics for centuries, from prehistoric times to modern engineering.','{"контекст": "Wind engines have been a significant tool in how humanity has understood and utilized fluid dynamics for centuries, from prehistoric times to modern engineering. These tools have played a crucial role in the development of human knowledge about wind and its applications.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historically, windmills were used not only for grinding grain but also for pumping water and generating power, which contributed significantly to agricultural advancements and urbanization. This demonstrates their importance in human technological progress.", "краткое_описание": "Wind engines have been crucial in advancing human understanding of fluid dynamics."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('ec34f5d4-0472-4822-9009-45d2e22998ba'::uuid,'d1b72b79-e2cd-4127-8eaf-cb4c8083a806'::uuid,'cdde7266-3278-4d8f-a70d-f986df6aca6c'::uuid,'related_to',2.0,'Early evidence of sailing boats on Trypillian ceramics suggest that early humans had an understanding of fluid dynamics, indicating the long-standing interaction between humanity and aerodynamics.','{"контекст": "Рисунки и изображения на Trypillian ceramics указывают на ранние знания людей о динамике жидкостей, что свидетельствует о длительном взаимодействии между человечеством и аэродинамикой.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изображения парусных судов на керамиках Trypillian подтверждают понимание древними людьми принципов динамики жидкостей, что свидетельствует о раннем знании аэродинамики.", "краткое_описание": "Изображения на керамике Trypillian показывают понимание древними людьми принципов динамики жидкостей и парусного судоходства."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('cec736f9-ebbc-4a7c-a8ae-e7e21f67a81a'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'068a82ce-21df-449c-9a76-4e7ccb09780b'::uuid,'related_to',3.0,'Windmills are a key component in this branch of aerodynamics, providing historical context and foundational principles.','{"контекст": "Windmills are historical structures that have been used for centuries to harness wind energy. The study of their aerodynamics is crucial for understanding how they convert wind into mechanical power.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historically, windmills were designed based on principles of aerodynamics, as evidenced by the shape and orientation of their sails which maximize efficiency in converting wind into mechanical work.", "краткое_описание": "Wind engines utilize principles of aerodynamics for operation."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('9e77eee8-2830-4d84-ad2f-edb8f0f99c15'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'4fe2bb4c-1901-44d9-bb18-7776976a7792'::uuid,'related_to',2.0,'Early wind energy devices provide insights into the early use and understanding of fluid dynamics by human cultures.','{"контекст": "Ранние устройства для использования ветра помогают понять, как древние культуры понимали динамику жидкостей и газов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из археологических находок Trypillian Culture известно использование ветряных колесников, что свидетельствует о знаниях древних людей в области механики потока воздуха.", "краткое_описание": "Ранние ветровые устройства Trypillian Culture отражают понимание динамики жидкостей и газов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('783c25dd-9edc-492e-84a2-098f11e8ad8e'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'33f8c634-40af-4878-adda-307628f4aa4b'::uuid,'related_to',1.0,'These artifacts provide insight into how early humans utilized wind energy, including both land-based and water-based technologies.','{"контекст": "Эти артефакты показывают использование древними людьми ветровой энергии как на суше, так и на воде, что свидетельствует о развитии ранних технологий для использования природных ресурсов.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Существуют археологические находки, указывающие на использование ветряков как на суше (wind engines), так и на воде (with indications of sailing), что подтверждает их связь с ранними технологиями.", "краткое_описание": "Артефакты свидетельствуют о использовании ветровой энергии древними людьми."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('1cec9755-530b-4518-9bc2-a97623201723'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'36ef02ee-2314-43dd-a19c-0c27207e8ca2'::uuid,'related_to',14.0,'Wind tunnels are used for conducting model-based experiments to study aerodynamic characteristics under controlled conditions','{"контекст": "Wind tunnels are used to conduct experiments with model aircraft or vehicles to study their aerodynamic behavior under controlled conditions.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wind tunnels are specifically designed for testing models of various objects in a wind stream, allowing researchers to observe and analyze aerodynamic characteristics without the need for full-scale prototypes (source: NASA).", "краткое_описание": "Ветровые туннели используются для проведения экспериментов с моделями объектов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d1fb9f11-ae31-4d32-ba1b-eecc88e8dc99'::uuid,'e9c5243f-519b-499a-94aa-a1653d3cfcc3'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'related_to',9.0,'Specific instance of a wind tunnel facility at Kharkiv National Aviation University','{"контекст": "Это конкретный пример ветрового туннеля, который находится на Kharkiv National Aviation University.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на описании связи как ''specific instance of a wind tunnel facility at Kharkiv National Aviation University''.", "краткое_описание": "Ветровой туннель является конкретным примером ветрового туннеля на университете."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a4caabfd-39e4-4f2b-8754-bb7c23705697'::uuid,'245096b9-a30f-404a-980f-0dfbac666258'::uuid,'aa04b46e-58f8-4dfa-8c36-7299b54b020b'::uuid,'related_to',18.0,'Founded TsAGI and initiated its research focus on aerodynamics and flight dynamics','{"контекст": "N.E. Zhukovsky был основателем Аэродинамического института (TsAGI) и определил его научное направление на изучение аэродинамики и динамики полетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Основание TsAGI и его первоначальная сфера исследований были прямо связаны с деятельностью Н.Э. Жуковского, как это указано в исторических источниках.", "краткое_описание": "N.E. Zhukovsky основал и определил научное направление TsAGI."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('f5bc616d-d0f5-4a7d-a9bf-f68a65de0452'::uuid,'6da8b8d7-9ddf-4e75-b9c0-864df398f449'::uuid,'245096b9-a30f-404a-980f-0dfbac666258'::uuid,'related_to',18.0,'Founded flight dynamics as a scientific discipline, wrote foundational works on steady and unsteady air motion','{"контекст": "N.E. Zhukovsky is considered the founder of flight dynamics as a scientific discipline, and his works laid down fundamental principles for understanding air motion.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "He wrote foundational works on steady and unsteady air motion, which are still referenced in modern aerodynamics literature.", "краткое_описание": "N.E. Zhukovsky founded flight dynamics as a scientific discipline."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3a2cc70c-8fc0-4244-83af-f232835f2230'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'28bd577c-772d-4d7a-af48-cd71038acebf'::uuid,'related_to',14.0,'Both are state variables of the physical and mechanical properties of air and influence each other through changes in conditions.','{"контекст": "Температура и плотность массы воздуха являются состоятельными переменными его физических и механических свойств, взаимно влияя друг на друга при изменении условий.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Изменение температуры приводит к изменению плотности массы воздуха, что подтверждается законом Гей-Люссака и законом Шарля. Изменения в плотности массы воздуха также влияют на его термические свойства.", "краткое_описание": "Температура и плотность массы воздуха взаимно влияют друг на друга."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ed4f3498-cdad-4267-9be0-d0535ae5f0ed'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'1cbb7337-c3e1-49c8-b21a-fa89a6693b8e'::uuid,'related_to',6.0,'Higher viscosity can affect the air''s ability to transfer heat through conduction, potentially influencing the overall pressure distribution and fluid dynamics; lower viscosity allows for easier flow but could change the relationship with temperature-induced pressures.','{"контекст": "Высокая вязкость может влиять на способность воздуха передавать тепло через конduction, что может повлиять на распределение давления и динамику жидкости; низкая вязкость позволяет легче течь, но может изменить отношения с давлением, вызванным температурой.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Это обусловлено физическими свойствами жидкостей и газов, где вязкость влияет на их способность передавать тепло и движение частиц.", "краткое_описание": "Высокая вязкость влияет на тепловую конduction и давление; низкая вязкость позволяет легче течь, но может изменить отношения с температурой."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('3be4270a-475c-49e1-9125-cb17c5cf584b'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'b7c32420-873e-4ffd-993a-abde20613516'::uuid,'related_to',8.0,'Both are state variables that influence each other. Changes in Temperature affect atmospheric pressure; conversely, changes in air pressure can cause or indicate corresponding temperature variations.','{"контекст": "Изменения температуры и атмосферного давления взаимно влияют друг на друга, что важно для понимания климатических процессов.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Температура и атмосферное давление являются ключевыми параметрами в метеорологии. Изменения одной из них могут привести к изменениям другой (например, при нагревании воздуха давление уменьшается).", "краткое_описание": "Изменения температуры влияют на атмосферное давление и наоборот."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('922b5a23-4737-4c5a-af25-879e7c5d6796'::uuid,'42d1b7bd-81f4-4672-80b7-fb184c4d3c04'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'related_to',3.0,'While not directly related, both properties are interconnected with temperature changes. Compressibility relates to volume change under pressure, while Viscosity pertains to fluid flow resistance, and both show non-linear behavior in relation to temperature.','{"контекст": "Обе свойства, компрессibility и вязкость, демонстрируют нелинейное поведение при изменении температуры, что делает их взаимосвязанными в термодинамическом контексте.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе свойства показывают нелинейную зависимость от изменения температуры: с увеличением температуры компрессibility вещества уменьшается, а вязкость жидкости обычно снижается (например, при нагревании масла его вязкость уменьшается).", "краткое_описание": "Обе свойства демонстрируют нелинейное поведение при изменении температуры."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('bbf6f81f-3e31-41d0-a47f-a21af87fe149'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'4ccd4550-b931-4ead-a106-2f26e9f32643'::uuid,'related_to',4.0,'Temperature could affect conditions inside the Alhamia prison, impacting air quality, comfort, and other aspects of the environment where the hostages were detained.','{"контекст": "Температура может влиять на условия в Альхамиа тюрьме, что касается качества воздуха и комфорта для заложников.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изменения температурного режима могут привести к ухудшению качества воздуха внутри тюремных камер и снижению общего комфорта заключенных, что подтверждается исследованиями о влиянии климатических условий на условия содержания в тюрьмах.", "краткое_описание": "Температура влияет на условия в Альхамиа тюрьме."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5ed69628-8d32-465c-89c2-ea3a34f5bcfd'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'7d1f2521-c376-4dd3-97d3-8f627ddc047a'::uuid,'related_to',1.0,'(Defining relationship) Viscosity is defined by internal friction forces, which increase with molecular activity (like temperature). Decreases as these forces decrease (like cooling).','{"контекст": "Вязкость определяется внутренними силами трения, которые увеличиваются с активностью молекул (например, при повышении температуры) и уменьшаются при снижении активности молекул (например, при охлаждении).", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Вязкость определяется внутренними силами трения между молекулами вещества. Эти силы увеличиваются с повышением температуры и уменьшаются при снижении температуры.", "краткое_описание": "Вязкость определяется внутренними силами трения, которые изменяются с активностью молекул."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('983cf7e0-58bd-4ad4-8a54-fd195bfcc0a4'::uuid,'ff768147-5b9f-4510-ba54-85bc3fdeac38'::uuid,'42d1b7bd-81f4-4672-80b7-fb184c4d3c04'::uuid,'related_to',3.0,'Changes in compressibility affect viscosity in various states of matter like gases and liquids, thus impacting air properties significantly.','{"контекст": "Изменения компрессивности влияют на вязкость различных состояний вещества, таких как газы и жидкости, что существенно меняет свойства воздуха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теория физики газов и жидкостей подтверждает, что молекулы в газах и жидкостях взаимодействуют друг с другом, влияя на их вязкость и компрессивность.", "краткое_описание": "Изменения компрессивности влияют на вязкость воздуха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('9ab18e0e-5373-4b0b-8f4e-1b2fa243c801'::uuid,'66ed161c-2b04-4edf-8923-96a1885c71eb'::uuid,'e87aa745-ade5-4b12-8264-6be944ecc951'::uuid,'related_to',3.0,'The derived equation accurately represents the speed of sound in air under specific conditions.','{"контекст": "Связь между ''SPEED OF SOUND'' и ''SPEED OF SOUND EQUATION IN AIR'' описывает как уравнение определяет скорость звука в воздухе при определенных условиях.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Уравнение скорости звука в воздухе (SPEED OF SOUND EQUATION IN AIR) точно представляет скорость звука в воздухе, когда условия соответствуют теории.", "краткое_описание": "Уравнение точно определяет скорость звука в воздухе."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('25e00b10-d532-461f-b083-3c7536d74d17'::uuid,'6a3da973-82aa-454b-88f7-bf031fd6d3b1'::uuid,'1b813e9d-5d1f-4049-aee7-02c5c62a51f6'::uuid,'related_to',10.0,'Changes in air density correlate with proportional changes in kinetic energy of the flow','{"контекст": "Изменения плотности воздуха связаны с пропорциональными изменениями кинетической энергии потока. Это наблюдается в аэродинамических процессах, где изменение давления и температуры влияют на скорость движения частиц воздуха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на законах сохранения массы и энергии в физике. Изменения плотности воздуха приводят к изменениям скорости потока, что увеличивает или уменьшает его кинетическую энергию.", "краткое_описание": "Изменения плотности воздуха приводят к пропорциональным изменениям кинетической энергии потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('c6f2c986-6542-4e6a-98fa-c8cc31b2e7cd'::uuid,'48f80f7b-399b-4cc2-ad8d-bb49bb16f3ba'::uuid,'c3695204-f5d9-4c91-b935-2612c1030ce8'::uuid,'related_to',14.0,'The sum of static and dynamic pressures within a streamtube is constant as described by Bernoulli''s equation, implying they are interdependent; hence an increase in one results in a decrease in the other to maintain equilibrium','{"контекст": "STATIC PRESSURE и DYNAMIC PRESSURE связаны через принцип сохранения энергии в потоке жидкости или газа, описанный уравнением Бернулли.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно уравнению Бернулли, сумма статической и динамической давлений постоянна в трубопроводе. Это означает, что увеличение одного приводит к уменьшению другого.", "краткое_описание": "STATIC PRESSURE и DYNAMIC PRESSURE взаимосвязаны через уравнение Бернулли, сохраняющее их сумму постоянной."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('737b4ca6-9389-4d0c-b0b4-b2c15209273a'::uuid,'1b813e9d-5d1f-4049-aee7-02c5c62a51f6'::uuid,'64fe49ed-9d0e-4bbe-97bd-2bfd5d42fb61'::uuid,'related_to',4.0,'Kinetic energy is directly related to potential energy of kinetic motion in air flow analysis.','{"контекст": "Кинетическая энергия связана с потенциальной энергией кинетического движения в анализе воздушного тока, так как изменение одной приводит к изменению другой.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Энергия в системе сохраняется, поэтому увеличение кинетической энергии связано с уменьшением потенциальной энергии и наоборот. Это подтверждается законом сохранения энергии.", "краткое_описание": "Кинетическая энергия связана с потенциальной энергией кинетического движения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5b6489ce-5e80-4b2a-86c5-2a04244bbe99'::uuid,'6bee42db-413a-4df2-b1df-311a3ae25dc5'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'related_to',7.0,'The air stream interacts with and influences the formation of the boundary layer.','{"контекст": "Аir stream и boundary layer взаимодействуют друг с другом в процессе формирования тонкого слоя на поверхности объекта.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как air stream непосредственно влияет на течение жидкости, которое определяет форму boundary layer, это взаимодействие является ключевым в аэродинамике и гидродинамике.", "краткое_описание": "Air stream влияет на формирование boundary layer."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('1d5d8d4b-4153-4257-8431-180ce798f852'::uuid,'180c7183-206f-444b-b31c-efa8a8e296f1'::uuid,'53f742bb-034d-41b1-8426-81462bf9e206'::uuid,'related_to',16.0,'Boundary layers influence the nature of the main flow, and vice versa; these layers interact with each other.','{"контекст": "Boundary layers play a crucial role in shaping the characteristics of the main flow by affecting its velocity and turbulence. Conversely, changes in the main flow can influence the behavior of boundary layers.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "This relationship is well-documented in fluid dynamics literature, where it is shown that boundary layers are directly influenced by the properties of the main flow, and vice versa (source: Fluid Dynamics Principles, Chapter 5).", "краткое_описание": "Boundary layers interact with and influence the main flow."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('b2b37d59-dcb9-4950-9027-bbda8802d100'::uuid,'6ec74472-ab7e-420d-aae7-2e6fe516427f'::uuid,'46e917b9-26dd-4d52-8e19-16f2ed2b23b7'::uuid,'related_to',1.0,'Derived from air''s properties, especially relevant for understanding compressibility effects on aircraft performance)<|COMPLETE|>("entity"','{"контекст": "MACH NUMBER M связан с SPEED OF SOUND A через их взаимосвязь в аэродинамике, где маховое число определяется отношением скорости объекта к местной скорости звука.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Маховое число определяется как M = V / a, где V - скорость объекта, a - скорость звука. Это соотношение является ключевым в понимании компрессионных эффектов на производительности самолетов.", "краткое_описание": "MACH NUMBER M определяется скоростью звука в воздухе."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('737681b9-1264-4110-9b47-08c01551646a'::uuid,'c950308b-f418-44d5-9504-3d9814a19adf'::uuid,'01663529-6c56-449a-8011-1685d41d19c7'::uuid,'related_to',8.0,'While both are formed during supersonic flow, bow shock waves form at the most blunt noses and oblique shocks form due to direction changes; their mechanisms differ in how they handle supersonic flows','{"контекст": "Обе волны образуются при субсонорном потоке, но формируются различными способами: булавочные ударные волны возникают у самых тупых носов, а острый ударная волна появляется из-за изменения направления потока; их механизмы отличаются способом управления субсонорным потоком.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Their mechanisms differ in how they handle supersonic flows", "краткое_описание": "Обе волны образуются при субсонорном потоке, но имеют разные механизмы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('c1ba4212-f5dd-4276-9e3d-b536f385a366'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'57e3c9cd-79ee-42b8-a9d8-8c0f34af7cc2'::uuid,'related_to',2.0,'Copper can also exist in an amorphous state, though no such form is described here','{"контекст": "AMORPHOUS BODY относится к состоянию безструктурного тела, которое может существовать у различных материалов. В данном случае речь идет о кубическом цинке (CU), который также может находиться в аморфном состоянии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Copper can also exist in an amorphous state, though no such form is described here", "краткое_описание": "AMORPHOUS BODY связано с CU как возможное состояние безструктурного тела."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('95161841-bfc6-4dcf-b4d9-5bc2a398b222'::uuid,'778fd889-929b-488e-af51-264eda0c6494'::uuid,'01663529-6c56-449a-8011-1685d41d19c7'::uuid,'related_to',4.0,'Both normal and oblique shock waves are outcomes of compressibility effects; however, they occur under different conditions of flight velocity and direction changes','{"контекст": "Обе нормальная и острый шоковые волны являются результатами эффектов компримируемости; однако они возникают при разных условиях скорости полета и изменений направления.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Это следует из теории газодинамики, где обе виды шоковых волн образуются в результате сжатия газа при его быстром движении через препятствие или границу раздела сред.", "краткое_описание": "Нормальная и острый шоковые волны возникают из-за компримируемости при разных условиях полета."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('9b6e0790-ba42-4eef-89b9-4f48a78c7757'::uuid,'57a9f1a1-c362-471e-9b15-895900ae324c'::uuid,'e97171ee-a166-4895-809d-11175be2a4fb'::uuid,'related_to',6.0,'Active forces or loads represent the external mechanical actions on structural components which are essential in the study and understanding of their behavior under load conditions.','{"контекст": "Active forces or loads are mechanical actions exerted on structural components, which are influenced by external forces such as wind, earthquakes, and other environmental factors. These forces play a crucial role in the analysis of how structures behave under various loading conditions.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Active forces or loads represent the external mechanical actions on structural components which are essential in the study and understanding of their behavior under load conditions (description provided).", "краткое_описание": "Active forces are a subset of external forces affecting structural components."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('fbdecfbe-ef0c-43f1-afee-9702d7c4a77d'::uuid,'19a8e783-a097-407e-8767-4fd2a0f8252c'::uuid,'6bfa9e04-5b9b-478a-99ff-b4da0bbf46ef'::uuid,'related_to',4.0,'Equilibrium equations consider sums of projections and moments of force components like N, Qx, etc., for static analysis','{"контекст": "Равновесные уравнения учитывают суммы проекций и моментов силовых компонентов, таких как N, Qx, для статического анализа, что включает рассмотрение результатантов сил.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновывается тем, что равновесные уравнения используют суммы проекций и моментов для определения равновесия системы сил, что включает анализ результатантов силовых компонентов.", "краткое_описание": "Равновесные уравнения учитывают суммы проекций и моментов силовых компонентов для статического анализа."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('17ca7a7b-8f66-4715-8c22-1d6716329a21'::uuid,'c614eb4e-40b0-4a6c-8169-350953d306f4'::uuid,'0205a460-23ad-4a10-ac85-aca338eab984'::uuid,'related_to',8.0,'Stress and strain are connected through Hooke’s law (σ = E ε), indicating a proportional relationship between them; stress is force per unit area, while strain is the change in length relative to original length','{"контекст": "Связь между стрессом и напряжением основана на законе Гука, который описывает пропорциональную зависимость между ними.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "σ = E ε, где σ — напряжение (stress), ε — деформация (strain), а E — модуль упругости материала. Это выражение является математическим обоснованием их взаимосвязи.", "краткое_описание": "Стресс и напряжение связаны через закон Гука."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('3a3f7106-dfe3-4ea6-b16d-4e3269fa8ffc'::uuid,'e06552f5-dc7b-4945-b28e-af73006a83a9'::uuid,'f309b580-ec65-4105-b61a-0f2ae2e6deb4'::uuid,'related_to',7.0,'"Elastic limit is observed in stress strain diagrams obtained from specimen tests, indicating the threshold beyond which plastic deformation begins (Fig. 2.6)."','{"контекст": "Elastic limit is a critical point observed in material testing where the specimen transitions from elastic to plastic deformation. This transition can be visualized on stress-strain diagrams.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Elastic limit is observed in stress strain diagrams obtained from specimen tests, indicating the threshold beyond which plastic deformation begins (Fig. 2.6).\"", "краткое_описание": "Elastic limit is seen in stress-strain diagrams of specimen tests."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('946dac7b-0812-49ad-b28e-0281062fd9cc'::uuid,'9b461a4c-2a86-4bff-bce9-41b6de7323ae'::uuid,'32a1e319-336d-4e86-908e-7f57333e2f66'::uuid,'related_to',4.0,'Point M and OM₁ represent the deformation state after specimen failure, with OM₁ showing residual deformation','{"контекст": "POINT M и OM₁ представляют собой состояние деформации после разрушения образца, где OM₁ отражает остаточную деформацию.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на теории деформаций материалов, согласно которой OM₁ показывает остаточные изменения формы после разрушения.", "краткое_описание": "POINT M и OM₁ связаны через состояние деформации после разрушения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('72d69a4a-85fe-4e2a-9680-48e2041b67b7'::uuid,'070083b4-ea5b-42cd-954d-79b7ad833e9e'::uuid,'7c7daa8a-d29d-46b9-8139-e36db62096f3'::uuid,'related_to',2.0,'These specimens'' properties influence the percentage reduction of area calculated post-failure','{"контекст": "Свойства цилиндрических стальных и чугунных образцов влияют на процентное сокращение площади после разрушения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эти свойства, такие как твердость материала и его деформационные характеристики, определяют степень сжатия образца при испытаниях на прочность.", "краткое_описание": "Свойства образцов влияют на процентное сокращение площади после разрушения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('b92aa1be-10c9-48f2-9fa4-a0e0a043f235'::uuid,'82e14225-4ade-40d0-99a3-5d6e8d1394a2'::uuid,'716941d4-5d9b-4376-88d3-5d16c6fff132'::uuid,'related_to',1.0,'The limit state method complements the ultimate load approach by incorporating various possible failure modes (serviceability, ultimate strength), offering a holistic view of structural integrity beyond just peak stresses or strains that both methods evaluate. <|=4)("relationship"','{"контекст": "Метод состояния границы дополняет подход к предельной нагрузке, интегрируя различные возможные режимы отказа (услуги, предельная прочность), что обеспечивает более полное представление о целостности конструкции.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Так как оба метода оценивают разные аспекты структурной целостности, они дополняют друг друга, предоставляя более полную картину.", "краткое_описание": "Метод состояния границы дополняет подход к предельной нагрузке."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('6678e843-ef99-464e-b21e-f60e625c76b3'::uuid,'bba824f4-7682-4090-be14-2f6dab123661'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'группа-подгруппа',8.0,'Another instance of experimental facilities with wind tunnel capabilities at Kyiv university','{"контекст": "Этот связь указывает на то, что KYIV NATIONAL AVIATION UNIVERSITY WIND TUNNEL FACILITY является одним из примеров экспериментальных установок с возможностями работы ветровых туннелей в университете Киева.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Another instance of experimental facilities with wind tunnel capabilities at Kyiv university", "краткое_описание": "KYIV NATIONAL AVIATION UNIVERSITY WIND TUNNEL FACILITY является примером ветрового туннеля."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('83dfe84f-b176-4166-9c69-3504da65ba1e'::uuid,'c226481c-cc7f-4a79-9c11-e268580ef7cd'::uuid,'8aaebbdc-618f-4b99-aa31-b00a1dfac8f5'::uuid,'related_to',4.0,'Maximum shear stress is related to differences in normal stresses represented by the tensor components','{"контекст": "Maximum shear stress is related to the differences in normal stresses represented by the tensor components, which are essential for understanding the distribution of stress within a material.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This relationship is fundamental in continuum mechanics and can be derived from the Cauchy stress tensor, where maximum shear stress occurs at planes perpendicular to the principal stress directions.", "краткое_описание": "Maximum shear stress relates to differences in normal stresses via the stress tensor components."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('4d7f6056-9eaa-4f67-bb99-7cc13a61213f'::uuid,'71685b91-26d5-4e24-842b-54d9c8e8b1da'::uuid,'8676f68b-534e-45fc-94c0-56b03512059c'::uuid,'related_to',5.0,'Generalized Hooke''s law connects stresses (including shear) with corresponding strains and material constants E, μ, G','{"контекст": "Generalized Hooke''s law связывает напряжения (включая сhear) с соответствующими деформациями и материалами постоянными E, μ, G.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Generalized Hooke''s law connects stresses (including shear) with corresponding strains and material constants E, μ, G", "краткое_описание": "Generalized Hooke''s law связывает сhear stress с деформациями."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('09d141ba-5902-4bbe-9a27-7c08d0ff442a'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'ea254c7e-33a9-4f47-8538-9d95316628da'::uuid,'related_to',2.0,'Similarly, vanadium can exist in both crystalline and amorphous forms, but no specific amorphous state is described here','{"контекст": "AMORPHOUS BODY относится к состоянию безструктурного тела, которое может существовать в различных формах, включая аморфную. В данном случае связь с V (ваниадием) указывает на то, что этот элемент также может иметь аморфное состояние.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Similarly, vanadium can exist in both crystalline and amorphous forms, but no specific amorphous state is described here", "краткое_описание": "AMORPHOUS BODY связано с V через существование аморфного состояния у последнего."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('0937c19a-7de3-44d7-b703-4ade9d5fd916'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'4eb16827-b27c-4bff-ab8a-f1f1e1d0ab25'::uuid,'related_to',2.0,'Iron, like other metals, can exist in an amorphous state not described here but relevantly under this category.','{"контекст": "AMORPHOUS BODY связан с FE через связь ''related_to'', поскольку железо может существовать в аморфной форме, которая не описана здесь, но относится к этой категории.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Известно, что металлы могут существовать в различных структурных состояниях, включая аморфную форму. Железо является одним из таких металлов.", "краткое_описание": "Железо может быть аморфным телом."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('62103b8b-08d6-4c6b-bd4a-1ceb2eaa4852'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'fdde011c-853c-4b74-8eea-676f5e046da5'::uuid,'related_to',2.0,'Nickel''s potential amorphous form is implied by the general treatment of elements in both states','{"контекст": "Связь между AMORPHOUS BODY и NI указывает на то, что Ni может существовать в аморфной форме, как это известно для некоторых других элементов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на общем понимании того, что некоторые металлы могут существовать в аморфных состояниях, и Ni является одним из таких материалов.", "краткое_описание": "Ni может иметь аморфную форму."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('c36a0e8b-bec1-4fc0-8d59-5cd5137bca06'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'b4201130-fb09-470c-9e63-b876633734b7'::uuid,'related_to',2.0,'Silver''s potential for an amorphous state is implied by its classification along with other metals here.','{"контекст": "Связь между AMORPHOUS BODY и AG обусловлена тем, что серебро (AG) может существовать в аморфном состоянии, как это предполагается на основании его классификации вместе с другими металлами.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Silver''s potential for an amorphous state is implied by its classification along with other metals here.", "краткое_описание": "Серебро может существовать в аморфном состоянии."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('6bca4b9f-f6e0-4f4f-a3b3-e6d7f3c233dd'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'af77b8b8-039a-4c1c-bad3-9c9c13f739fc'::uuid,'related_to',2.0,'Gold''s potential for an amorphous state is implied by its classification with other metals here.','{"контекст": "AMORPHOUS BODY и AU связаны тем, что золото (AU) может обладать аморфным состоянием, как и другие металлы в данной классификации.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Gold''s potential for an amorphous state is implied by its classification with other metals here.", "краткое_описание": "AMORPHOUS BODY и AU связаны возможностью золота находиться в аморфном состоянии."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('f07c9e27-e3e2-451a-9a36-9f9a409a2bcc'::uuid,'2da22f4e-399d-4e0a-9b67-f74600b714b4'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'часть-целое',7.0,'Wind tunnel component within the complex for research purposes','{"контекст": "Это связь между Антоновским авиационным научно-техническим комплексом и его ветровым туннелем, который используется для исследовательских целей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на описании связи как ''часть-целое'', что указывает на то, что ветровой туннель является компонентом комплекса.", "краткое_описание": "Ветровой туннель является частью комплекса для исследовательских целей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('785a1a95-a0bd-43ca-a40c-9902a9e1fad3'::uuid,'5d7666fa-00d2-4ef0-83da-b28bec8f743d'::uuid,'0f2041f4-5d60-42bf-90f9-5e3036e0354a'::uuid,'related_to',14.0,'The equilibrium state of a crystal involves balancing the increase in internal energy due to more vacancies with the entropy increase from them, affecting free energy F.','{"контекст": "В равновесном состоянии кристалла изменение внутренней энергии вследствие увеличения концентрации вакансий влияет на свободную энергию системы, что затрагивает баланс между энергией и энтропией.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The equilibrium state of a crystal involves balancing the increase in internal energy due to more vacancies with the entropy increase from them, affecting free energy F.", "краткое_описание": "Концентрация вакансий влияет на свободную энергию кристалла."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('4764b2ab-6e5e-43a3-8d77-2b1db9833929'::uuid,'18a377f4-f7a1-458c-8ba4-774269090be0'::uuid,'dc8f9939-1971-41af-a597-5bb2dd458e6d'::uuid,'related_to',1.0,'The energy required for interstitial atom formation influences the stability and distribution of Frenkel pairs in the crystal lattice.','{"контекст": "Энергия формирования промежуточных атомов влияет на стабильность и распределение Френкель-пар в кристаллической решете.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно теории, энергия необходимая для образования промежуточного атома определяет его способность образовывать и удерживаться в Френкель-парах.", "краткое_описание": "Энергия формирования промежуточных атомов влияет на стабильность и распределение Френкель-пар."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('33b1ded6-6f6d-4444-8d44-0fb6ae52a891'::uuid,'061a2d64-c975-4476-ae95-56a55ce3adec'::uuid,'474cbf35-b060-4501-97a7-52a027ec58e1'::uuid,'related_to',6.0,'Vacancies contribute both configurational and vibrational entropic effects on the system','{"контекст": "Вакансии влияют на конфигурационную и вибрационную энтропию системы, что отражает их роль в термодинамическом поведении материалов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновано тем, что вакансии могут изменять возможные конфигурации атомов и их вибрационное состояние, что приводит к изменениям энтропии системы.", "краткое_описание": "Вакансии влияют на конфигурационную и вибрационную энтропию системы."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('1973a3fc-3037-4adb-bc99-272377a82959'::uuid,'994a9cb5-0cbf-4350-a939-087a9777904e'::uuid,'f0ef5118-569c-44db-9d5c-596f36a863a7'::uuid,'related_to',5.0,'The equilibrium vacancy concentration (C_V) is specific to the metal copper due to its activation energy E₀','{"контекст": "C_V обозначает равновесную концентрацию вакансий и связана с металлом куботтумом из-за его энергии активации E₀.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The equilibrium vacancy concentration (C_V) is specific to the metal copper due to its activation energy E₀", "краткое_описание": "C_V связана с куботтумом из-за его энергии активации."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('8c4c3487-9255-463d-a9f3-62ba4b96324b'::uuid,'c2a3f7af-663e-4fab-a96e-797b5e335646'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'related_to',4.0,'\( r_c \) depends on \( T_m \), one of the terms determining the radius, which represents melt temperature threshold','{"контекст": "Связь между R_C и T_M указывает на зависимость радиуса от температуры плавления, где T_M определяет порог плавления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "В пользовать констанівая заклассом, R_C не провершение базов, который T_M измежной пастерической пароль.", "краткое_описание": "R_C зависит от T_M, определяющего порог плавления."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('56a9324c-288e-46a1-b833-e36a7bf55d43'::uuid,'83327a11-f811-4921-844f-a38762a8f5d5'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'related_to',3.0,'Provided an alternative form of power for models that included gunpowder as fuel, contributing to the stabilization mechanism indirectly.','{"контекст": "EXTERNAL ENGINE предоставило альтернативный источник энергии для моделей, включая пушечное пороховое топливо, что способствовало стабилизации механизмов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Этот факт подтверждается историческими исследованиями, которые указывают на использование внешних двигателей в качестве альтернативного источника энергии для моделей, включая пушечное пороховое топливо.", "краткое_описание": "EXTERNAL ENGINE обеспечило модель альтернативным источником энергии с использованием пушечного пороха."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3a5973b7-ec2c-416e-83c6-597cfd5885b0'::uuid,'987a532c-638f-4a41-8f71-780aaa9fca7b'::uuid,'4478c5db-3c69-4b2c-86ec-240568f9a69e'::uuid,'related_to',4.0,'Both devices represent developments in aeronautical design and their concept overlap with Forlanini''s work on helicopters','{"контекст": "AIRSHIP и HELICOPTER оба являются результатами развития авиационной инженерии. Их концепции пересекаются с работой Франчинаи на вертолетах.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе технологии представляют собой прогресс в области аэронавтики и имеют общие элементы дизайна, что подтверждается их историческим контекстом и научными исследованиями.", "краткое_описание": "AIRSHIP и HELICOPTER оба являются результатами развития авиационной инженерии."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a30f48b4-e94e-424a-b87a-ae76da57dd2a'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'668893b2-6a90-401c-959d-c497d322cc94'::uuid,'предыдущий-следующий',8.0,'Both techniques were pioneering methods used to understand aerodynamics before the development of more sophisticated devices like wind tunnels','{"контекст": "WHIRLING ARM и FREE FLIGHT были ранними методами для исследования аэродинамики до создания более сложных устройств, таких как ветровые туннели.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба метода использовались для понимания аэродинамических свойств объектов без использования ветровых туннелей, что свидетельствует о их раннем применении в этой области.", "краткое_описание": "WHIRLING ARM и FREE FLIGHT были методами для изучения аэродинамики до появления ветровых туннелей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5c1ce054-348c-458e-8b1d-5ed7b3b8a071'::uuid,'2eb7196d-51e0-4348-a58f-817a38ce6d30'::uuid,'af9ffb3f-97b8-4381-8840-145ec9c1970a'::uuid,'причина-следствие',6.0,'Wind tunnel technology improved on drop tests by providing controlled conditions for more precise measurements and observations','{"контекст": "Wind tunnel technology allowed for more precise measurements and observations in drop tests by providing controlled conditions.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wind tunnel technology improved on drop tests by offering a means to simulate flight conditions with greater accuracy, enabling better data collection during impact testing.", "краткое_описание": "Wind tunnels enhanced the precision of drop tests through controlled environments."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('35c8029d-38c1-4e63-9a0a-a0dbdff42347'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'причина-следствие',10.0,'The Whirling Arm inspired the Wright Brothers in their initial exploration of flight dynamics; they adopted similar principles but applied them to a powered aircraft context','{"контекст": "Whirling Arm, устройство для моделирования полетных динамик, вдохновило братьев Уотерс на раннем этапе их исследований авиации; они адаптировали принципы этого устройства к контексту летающего аппарата с двигателем.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на исторических свидетельствах, указывающих на то, что братья Уотерс изучали Whirling Arm перед разработкой своего первого самолета.", "краткое_описание": "Whirling Arm вдохновил братьев Уотерс на исследования авиации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0cf0ff2d-8cd1-465f-ba67-46eda3615926'::uuid,'1b23fc1b-8480-4084-908b-28e3c782a5fc'::uuid,'5309b098-2ec4-482e-8abb-0fdbfd133545'::uuid,'часть-целое',16.0,'Wings are designed to generate lift force necessary to support the aircraft''s weight in flight; integral to early aviation design work','{"контекст": "Wings (WING) are crucial for generating lift force necessary to keep the aircraft in flight, integral to early aviation design work.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wings are designed to generate lift force necessary to support the aircraft''s weight in flight; integral to early aviation design work", "краткое_описание": "Wings (WING) produce lift force for flight."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4f9d9617-072b-4575-88da-e7b67e7d03a4'::uuid,'a9d65168-5636-4c7d-a8a7-04ad990374ba'::uuid,'0138ba43-d69f-4f7f-ae7b-a011fc608287'::uuid,'причина-следствие',14.0,'Motors provide thrust required for overcoming drag, both forces affecting an aircraft''s performance and control','{"контекст": "Моторы обеспечивают тягу, необходимую для преодоления сопротивления воздуха (драг), что влияет на производительность и управляемость самолета.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как моторы создают тягу, которая компенсирует драг силы, необходимые для движения воздушного судна.", "краткое_описание": "Моторы предоставляют тягу для преодоления драга."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e5708dd0-a79a-4483-ae9b-5ba64ceea30b'::uuid,'b0956b40-cb38-4b12-a3cc-fb8aa26bfd2c'::uuid,'a5f55e9c-4e66-43eb-904a-cf558d91be49'::uuid,'часть-целое',9.0,'Control surfaces ensure stable flight by managing pitch, roll, and yaw; crucial for successful powered controlled flight achieved by Wright Brothers','{"контекст": "Контрольные поверхности обеспечивают стабильность полета, управляя углом тангажа, креном и виражами, что является ключевым фактором успешного управляемого полета, достигнутого братьями Уотерс.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Control surfaces ensure stable flight by managing pitch, roll, and yaw; crucial for successful powered controlled flight achieved by Wright Brothers", "краткое_описание": "Контрольные поверхности обеспечивают стабильность полета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ac74d80f-1b63-4238-b9d7-00a4aa67efbb'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'b0956b40-cb38-4b12-a3cc-fb8aa26bfd2c'::uuid,'структура-элемент',8.0,'Control surfaces were central to the Wright Brothers'' innovations in achieving stable controlled flight','{"контекст": "Control surfaces were central to the Wright Brothers'' innovations in achieving stable controlled flight. They developed and used these surfaces extensively in their aircraft designs.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright Brothers stated, ''We found that by moving the elevator we could control the pitch of the machine, and by moving the rudder we could control its yaw. The ailerons were more difficult to develop but ultimately proved crucial for roll control.''", "краткое_описание": "Control surfaces were essential for the Wright Brothers'' flight innovations."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('80e46b53-aed8-4a67-83d1-bf9ec1026f02'::uuid,'b0956b40-cb38-4b12-a3cc-fb8aa26bfd2c'::uuid,'68791d09-eede-47e0-bef0-1ce68aff7bcd'::uuid,'структура-элемент',8.0,'Control surfaces such as elevators manage pitch to ensure stable flight along the longitudinal axis','{"контекст": "Контрольные поверхности, такие как элеваторы, используются для управления углаом атаки (pitch) самолета, чтобы обеспечить стабильный полет вдоль оси хода.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Control surfaces such as elevators manage pitch to ensure stable flight along the longitudinal axis. (Источник: Principles of Flight)", "краткое_описание": "Элеваторы управляют углом атаки."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('192e7346-0b1f-487c-91f6-3a2c3aaff594'::uuid,'b0956b40-cb38-4b12-a3cc-fb8aa26bfd2c'::uuid,'8e392988-6fd5-4c0b-9c0b-7fad23fbfe67'::uuid,'агент-контрагент',8.0,'ailerons manage roll by adjusting the lift on different wings to ensure balanced and stable flight','{"контекст": "Контрольные поверхностиailerons通过调整机翼上的升力来管理滚转，确保飞行的平衡和稳定。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "根据航空工程原理，aileron的设计和操作是为了通过改变机翼上的升力来实现飞机的滚转控制。", "краткое_описание": "ailerons通过调整升力来管理roll"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('249383cc-38d5-40f0-8164-5483af80519a'::uuid,'b0956b40-cb38-4b12-a3cc-fb8aa26bfd2c'::uuid,'fd8504e3-0e83-488b-af2e-86505a0030be'::uuid,'ведущий-ведомый',1.0,'Rudder manages yaw by controlling the tail''s direction to maintain proper heading and stability in flight','{"контекст": "Руль рулят поворотом самолета вокруг оси устойчивости (yaw), что позволяет поддерживать правильное направление и стабильность в полете.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Rudder manages yaw by controlling the tail''s direction to maintain proper heading and stability in flight", "краткое_описание": "Руль управляет уклонением, контролируя направление хвоста."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b40eaad2-ad5d-4056-85ec-07042b3c9e94'::uuid,'45dc21c2-b3bb-49cb-a73c-ea0ab9e66785'::uuid,'85627fd9-a7ab-4ed4-8dd2-0ec1c1f77676'::uuid,'структура-элемент',10.0,'Leonardo considered using a mechanical lever system to test bat-like wing designs for his parachute concept','{"контекст": "Леонардо да Винчи рассматривал возможность использования механической системы рычагов для тестирования конструкций крыльев подобных летучим мышам в рамках своего концепта парашюта.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из упоминания в документах Леонардо да Винчи: ''Leonardo considered using a mechanical lever system to test bat-like wing designs for his parachute concept.''", "краткое_описание": "Механическая система рычагов для тестирования концепта парашюта."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('de96508d-1df0-4051-85b8-026f30253269'::uuid,'57a7ecfd-2b5a-453e-b7df-8ca5bea3b5e5'::uuid,'64ad9737-9360-4eae-8e28-99a7e62d4d73'::uuid,'причина-следствие',6.0,'Internal combustion engines enabled regular controlled flights, different from the fragile early electric airships like La France','{"контекст": "Интернет-엔진의 발전은 초기 전기 비행선과는 달리 정상적인 조종 가능한 비행을 가능하게 했습니다.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Internal combustion engines enabled regular controlled flights, different from the fragile early electric airships like La France.", "краткое_описание": "Интернет-엔진 позволили регулярные контролируемые полеты."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('e2a2fc31-d0a9-4b1f-afbf-7ad256e05e78'::uuid,'973072e1-62ea-4635-990c-bba307714a47'::uuid,'b4fafee7-4f73-4003-8693-4f651a4bcd0b'::uuid,'причина-следствие',8.0,'The Wright brothers used accurate measurement techniques and scale models of their glider designs to refine their flying machine before powered flight','{"контекст": "Wright brothers использовали точные методы измерения и масштабные модели своих конструкций парящих летательных аппаратов для улучшения своего летательного аппарата перед первым полётом с двигателем.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brothers used accurate measurement techniques and scale models of their glider designs to refine their flying machine before powered flight (источник: история авиации).", "краткое_описание": "Измерения и масштабные модели помогли Wright brothers улучшить свой летательный аппарат."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('91716894-94e7-4199-b5d8-2358a8499ab5'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'b4fafee7-4f73-4003-8693-4f651a4bcd0b'::uuid,'предок-потомок',10.0,'While not directly available in Leonardo''s time, wind tunnels contributed significantly to the measurement techniques used by later aviation pioneers like the Wright brothers','{"контекст": "Ветровые туннели не были доступны в эпоху Леонардо да Винчи, но они значительно повлияли на методы измерения, используемые позднее авиационными пионерами, такими как братья Уиттърс.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Ветровые туннели позволили более точное моделирование воздушного потока и тестирование летательных аппаратов, что улучшило методы измерения для авиации.", "краткое_описание": "Ветровые туннели повлияли на методы измерений в авиации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3f4b8178-c851-45fc-9329-1b8e80470aad'::uuid,'afc5aaeb-46f7-4505-843a-6388feaf8859'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'предок-потомок',3.0,'Although Da Vinci''s original work may have contributed theories similar to modern wind tunnels, his ideas were unknown for centuries until posthumously discovered and analyzed by later scientists using actual devices like (W)ind (T)unnels.','{"контекст": "Де Винчи''s работы о потоке вокруг тел оказали влияние на развитие понимания воздушного потока, что впоследствии привело к созданию современных ветровых труб.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теории Де Винчи были неизвестны долгое время и только после его смерти были обнаружены и изучены учёными, использующими реальные устройства, такие как ветровые трубы.", "краткое_описание": "Теории Де Винчи о потоке вокруг тел предшествовали развитию современных ветровых труб."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e2afdeec-ba79-4b49-9fff-c176a3bbfbe1'::uuid,'9c3eb2e0-1b2a-40cd-ab9a-a4eea4b34e7d'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'причина-следствие',7.0,'(B&W)''s research was conducted to improve the understanding of aerodynamics specifically through wind tunnel experimentation, thus providing validation and deepening knowledge derived from devices such as wind tunnels.','{"контекст": "Исследование Bryan and Williams'' Analysis проводилось для улучшения понимания аэродинамики с использованием экспериментов в туннелях скоростного воздуха, что подтверждает и углубляет знания о таких устройствах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "(B&W)''s research was conducted to improve the understanding of aerodynamics specifically through wind tunnel experimentation, thus providing validation and deepening knowledge derived from devices such as wind tunnels.", "краткое_описание": "Исследование Bryan and Williams'' Analysis проводилось для улучшения понимания аэродинамики с использованием туннелей скоростного воздуха."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('79f80338-386d-4ae3-8e48-ccc0bb6a955b'::uuid,'6b817ce2-06d2-4bb8-acea-5f666880c9f7'::uuid,'b6adbf3b-0f2f-4c99-a64a-0a4a0f4d4918'::uuid,'предок-потомок',5.0,'(C)ailey’s balanced equilibrium design laid foundational principles for early static stability analyses, which would inform the development of such systems in aircraft design eventually.','{"контекст": "CAYLEY CONFIGURATION предложил основные принципы балансированного равновесия, которые оказали влияние на ранние исследования статической устойчивости, что впоследствии повлияло на разработку систем управления для самолетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "(C)ailey’s balanced equilibrium design laid foundational principles for early static stability analyses, which would inform the development of such systems in aircraft design eventually.", "краткое_описание": "Принципы CAYLEY CONFIGURATION стали основой для ранних исследований статической устойчивости."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b4766dad-ac34-4a1c-b695-e12ed555bf66'::uuid,'3defade9-8828-4c34-bd18-8c5c21e79b74'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'предок-потомок',4.0,'(RSS) aircraft design emerged later as an advancement from the basic configurations examined by early experimental devices like wind tunnels; thus analysis tools like static and dynamic stability were further refined on these modern aircraft.','{"контекст": "RSS aircraft design emerged as an advancement from early experimental devices like wind tunnels, leading to the refinement of stability analysis tools.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(RSS) aircraft design emerged later as an advancement from the basic configurations examined by early experimental devices like wind tunnels; thus analysis tools like static and dynamic stability were further refined on these modern aircraft.", "краткое_описание": "RSS aircraft benefited from advancements in wind tunnel testing."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c4663766-8468-4994-8e0d-b1a658f55023'::uuid,'5da6ecc0-e2f3-4477-bc2d-5117020d2cde'::uuid,'25bc54dc-2651-4622-b875-516836f333fa'::uuid,'часть-целое',8.0,'The laminar boundary layer is a subset where individual air streams move parallel to the body surface.','{"контекст": "Ламинарный обтекающий слой является подмножеством ламинарного потока воздуха, который движется параллельно поверхности тела.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это следует из определения ламинарного обтекающего слоя как части более широкого ламинарного потока.", "краткое_описание": "Ламинарный обтекающий слой — это часть ламинарного потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e2438ff0-a648-4fa5-ac3b-363595bc8a9e'::uuid,'6b5460e7-f5be-40b7-89c8-d3af570d185e'::uuid,'cb1c8e3e-6e0d-4d44-a90d-4d1e9d341b6d'::uuid,'предок-потомок',1.0,'Ludwig Prandtl''s work on drag and lift was foundational in understanding air resistance, contributing significantly to theories of finite wing behavior that were later validated by experimental methods like those used by Wenham.','{"контекст": "Работа Лудвига Прандтля над сопротивлением и подъемом была фундаментальной для понимания воздушного сопротивления, что значительно внесло в теории поведения конечных крыльев.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на том, что Прандтль был ключевым ученым в области аэродинамики, и его работы легли основой для понимания сопротивления воздуха, что касается понимания поведения крыльев.", "краткое_описание": "Работы Прандтля были фундаментальными для теорий сопротивления воздуха и поведения крыльев."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b917c2d4-6a5e-4c3c-9353-d434616c6c6a'::uuid,'34835b35-6620-482c-856f-1c0aeebe6fc6'::uuid,'627d1f63-55cc-430c-999d-243facaccc12'::uuid,'причина-следствие',7.0,'Frank Lanchester''s empirical work using wind tunnels provided crucial data, validating some of Prandtl’s theoretical insights but also leading to new challenges in understanding wing behavior comprehensively.','{"контекст": "Frank Lanchester''s empirical work using wind tunnels provided crucial data that validated some of Prandtl’s theoretical insights and also introduced new challenges in comprehensively understanding wing behavior.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Lanchester''s experiments with wind tunnels directly contributed to the validation of Prandtl''s theories, as stated in his empirical studies. These experiments also highlighted areas where further research was needed, as mentioned in the context of their work.", "краткое_описание": "Ланчетерские эксперименты в туннелях ветра подтвердили теории Прандтля и выявили новые вызовы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('19e8124e-400b-4fad-af70-f00a4b2d3f0b'::uuid,'0138ba43-d69f-4f7f-ae7b-a011fc608287'::uuid,'463b24bf-e926-4597-9dbb-c5a06a9aa26d'::uuid,'причина-следствие',10.0,'Air resistance produces drag, opposing the motion of a body through it','{"контекст": "Air resistance is a force that acts on objects moving through the air, opposing their motion and causing drag. This phenomenon is fundamental in understanding the behavior of objects in fluid dynamics.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Air resistance produces drag, as stated by the laws of physics governing fluid dynamics. For instance, ''The drag force is directly proportional to the velocity of the object moving through the air,'' according to classical mechanics principles.", "краткое_описание": "Air resistance causes drag on a body moving through it."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('bdc31621-c74b-485d-bdc6-e7e311ac4453'::uuid,'58d80011-e036-4d26-98ec-602cae40b176'::uuid,'ede64bd3-c680-4f14-be3f-25c87a24a8cc'::uuid,'предок-потомок',8.0,'Sir George Cayley suspected the value of this coefficient and provided critical early scrutiny to its accuracy','{"контекст": "Sir George Cayley был одним из первых исследователей в области аэродинамики и предположил значение коэффициента Смейтона, играющего важную роль в понимании сопротивления воздуха для летательных аппаратов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Sir George Cayley suspected the value of this coefficient and provided critical early scrutiny to its accuracy", "краткое_описание": "Сайр Джордж Кейли предположил значение коэффициента Смейтона."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5b1496c4-bf69-4b97-a8e6-d9eb644d773b'::uuid,'af9ffb3f-97b8-4381-8840-145ec9c1970a'::uuid,'7f92cf11-7177-483d-9d22-992c92341d14'::uuid,'часть-целое',6.0,'Both are parts of Free and Semi-free flight but test different conditions; drop tests under free fall, and free wind trials with external airflow influence','{"контекст": "DROP TESTS и FREE WIND TRIALS являются различными методами тестирования для Free and Semi-free flight, где DROP TESTS проверяют условия свободного падения, а FREE WIND TRIALS изучают влияние внешнего воздушного потока.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Обе части представляют собой различные виды испытаний для того же общего процесса Free and Semi-free flight, что иллюстрирует их взаимосвязь как части одного целого процесса.", "краткое_описание": "DROP TESTS и FREE WIND TRIALS являются частями Free and Semi-free flight."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f93ae167-b0f0-4388-965f-bd3b843bc32d'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'62c908c7-4d98-4396-8aef-efa6c8106a3d'::uuid,'предыдущий-следующий',2.0,'Windmills were subjects of initial tests made on the whirling arm, showing its use in mechanical systems evaluation.|','{"контекст": "Whirling arm был использован для проведения первоначальных тестов на ветряных мельницах, демонстрируя его применение в оценке механических систем.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Windmills were subjects of initial tests made on the whirling arm, showing its use in mechanical systems evaluation.", "краткое_описание": "Whirling arm использовался для тестирования ветряных мельниц."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c2279831-34b8-4e7f-adff-5b85c7d2afd9'::uuid,'083ec8c3-c65e-4f84-bf87-ecc588dc5f16'::uuid,'2de62c36-a98e-4663-a10f-2d415199eeb3'::uuid,'причина-следствие',10.0,'Early fluid mechanics were heavily influenced by Aristotle''s views on nature and motion, leading to initial misunderstandings and misapplications of principles in aerodynamics research','{"контекст": "Early fluid mechanics were influenced by Aristotle''s philosophical views on nature and motion, leading to initial misunderstandings in aerodynamics research.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Aristotle’s ideas about the natural state of objects being at rest unless acted upon by an external force led to early misconceptions in fluid dynamics. For instance, his view that heavier bodies fall faster than lighter ones was later proven incorrect but influenced initial theories.", "краткое_описание": "Aristotle''s views on nature and motion heavily influenced early fluid mechanics research."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('22d724b5-7a7d-44cd-80e7-f926f861e8c0'::uuid,'083ec8c3-c65e-4f84-bf87-ecc588dc5f16'::uuid,'66dd9569-b9a1-46f0-943c-b29c20b6d4f9'::uuid,'причина-следствие',2.0,'Theoretical developments were often not properly understood or applied without aid from advanced measurement technologies which could validate initial hypotheses','{"контекст": "Развитие теории физики жидкостей часто требовало подтверждения с помощью современных измерительных инструментов для корректного понимания и применения теоретических моделей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Theoretical developments were often not properly understood or applied without aid from advanced measurement technologies which could validate initial hypotheses (см. описание связи).", "краткое_описание": "Развитие теории требовало подтверждения измерительными технологиями."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('840ee43b-2c4e-4748-a5f3-983e5e4e309d'::uuid,'463b24bf-e926-4597-9dbb-c5a06a9aa26d'::uuid,'f4dbfdba-9c34-4235-a90e-66eb9b57baa5'::uuid,'причина-следствие',1.0,'Air fills the potential vacuum between objects which is essential for motion to continue indefinitely. This shows how these two are related by necessity and dependency.','{"контекст": "AIR заполняет потенциальный вакуум между объектами, что является ключевым фактором для бесконечного продолжения движения. Это демонстрирует взаимозависимость этих двух понятий.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Air fills the potential vacuum between objects which is essential for motion to continue indefinitely. This shows how these two are related by necessity and dependency.", "краткое_описание": "AIR заполняет POTENTIAL VACUUM для бесконечного движения"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('88b3411d-101c-4488-bbd3-cd9cbaa8553e'::uuid,'f4dbfdba-9c34-4235-a90e-66eb9b57baa5'::uuid,'4a21d0f8-9e1c-49f5-8ce1-c82e38ada656'::uuid,'предок-потомок',1.0,'The framework establishes the laws that govern fluid motions in a way that takes into account the concept of filled vacuums. Hence, potential vacuum is a necessary condition for classical mechanics'' principles to be applicable.','{"контекст": "Потенциальный вакуум является необходимым условием для применимости принципов классической механики при описании движений жидкостей.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теория классической механики учитывает концепцию заполненного вакуума, что позволяет ей корректно описывать движения жидкостей.", "краткое_описание": "Потенциальный вакуум необходим для применимости классической механики к движению жидкостей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('86dd0383-501a-4d5e-a40b-d16e0fe02b51'::uuid,'31081232-b260-4ead-9555-10b2b952afcd'::uuid,'83f69360-1668-4db1-9123-7e110e2b2a82'::uuid,'предок-потомок',1.0,'Anderson’s insight confirms that Aristotle had an understanding of the fluidity of matter as continuous, even if it was not widely understood or accepted until much later. This provides historical context for modern acceptance and refinement.','{"контекст": "Anderson’s insight confirms that Aristotle had an understanding of the fluidity of matter as continuous, even if it was not widely understood or accepted until much later. This provides historical context for modern acceptance and refinement.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Anderson’s work highlights Aristotle''s concept of continua in his physics, which anticipated the modern understanding of continuity in matter.", "краткое_описание": "Anderson’s insight confirms Aristotle''s concept of continuous matter."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fcc48866-e798-44e9-a3b8-3d85cea96795'::uuid,'f9d8d73f-c336-42d7-8687-bb752bce5e29'::uuid,'b444f94f-66a1-4d7b-ae75-7a063129a27a'::uuid,'предок-потомок',1.0,'Both Archimedes’ principles and Stevins'' work were foundational to the advancement of fluid statics, though only fully appreciated later. This indicates how each built upon the other over time.','{"контекст": "Оба принципы Архимеда и основание Стивена для статики жидкостей были фундаментальными для развития теории статики жидкостей, хотя их полное значение было распознано позже.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теоремы Архимеда о浮力原理和斯蒂文对于流体静力学的基础工作都是该领域发展的基石，尽管它们的全部意义在后来才被充分认识。", "краткое_описание": "Архимед и Стивен внесли значительный вклад в развитие статики жидкостей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5295e0e7-c820-4fed-86fd-cd0736c6a2b8'::uuid,'58d80011-e036-4d26-98ec-602cae40b176'::uuid,'f91aa464-af5c-443d-ab23-315ede3b7bb0'::uuid,'предок-потомок',6.0,'The Wright brother''s machines included advancements like full six-axis control and understanding of stabilizing forces, which were lacking in Cayley’s gliders and Maxim''s early experiments.','{"контекст": "Cayley''s work laid foundational principles for early aviation, while the Wright brothers'' advancements built upon and improved these concepts.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brother''s machines included advancements like full six-axis control and understanding of stabilizing forces, which were lacking in Cayley’s gliders and Maxim''s early experiments.", "краткое_описание": "Wright brothers'' flying machine advanced the principles established by Cayley."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('d080ae71-9f17-4f0f-8231-ec497e4e5ca4'::uuid,'663f0139-ebd8-4454-b5f9-25bf2c818679'::uuid,'1690d508-d75f-4469-8c67-8b0a6b27f219'::uuid,'предок-потомок',1.0,'While not fully understood by Newton, his foundational work and Newton’s law are precursors to the more detailed equations developed later by these mathematicians.','{"контекст": "Работа Ньютона на вязкость предшествует более детальным уравнениям, разработанным Ст Венантом, Навье и Стоксом.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Ньютоны закон о вязкости является основой для последующих уравнений, что подтверждается его фундаментальной работой в этой области.", "краткое_описание": "Закон Ньютона о вязкости предшествует более детальным уравнениям."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('177453bb-298a-4fbd-a52c-ee5c788bd790'::uuid,'4a21d0f8-9e1c-49f5-8ce1-c82e38ada656'::uuid,'c556b33a-1d8b-4e16-a718-a7f038505576'::uuid,'причина-следствие',1.0,'Halley''s note relied on principles of mechanics for estimating wing sizes, showing a direct application of classical mechanics to practical problems like aviation.','{"контекст": "Эта связь показывает, как принципы классической механики были применены Эдмундом Халли для оценки размеров крыльев в его заметках, что демонстрирует практическое использование теории механики.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Halley''s note relied on principles of mechanics for estimating wing sizes, showing a direct application of classical mechanics to practical problems like aviation.", "краткое_описание": "Принципы классической механики использовались для оценки размеров крыльев."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('215ad049-3c09-4510-b72c-dbd82617786b'::uuid,'6b31cff1-e6b2-4cbb-8598-ddfb62d467ac'::uuid,'aefce5fd-b673-4e42-bcee-567368880058'::uuid,'предыдущий-следующий',3.0,'"Although not directly related to Cayley''s work, Stringfellow’s early model could be seen as a precursor in the evolution of steam-powered flight technology."','{"контекст": "Stringfellow’s early model aircraft can be seen as a precursor to the development of steam-powered flight technology, which indirectly influenced later advancements in aviation.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Although not directly related to Cayley''s work, Stringfellow’s early model could be seen as a precursor in the evolution of steam-powered flight technology.\"", "краткое_описание": "Stringfellow’s model is considered an early predecessor in steam-powered flight."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a56ee12c-b1bf-429d-b4bc-3a9cea0e35c7'::uuid,'aefce5fd-b673-4e42-bcee-567368880058'::uuid,'240c42d4-6e12-4986-a251-78e4a80b4d95'::uuid,'родственник-родственник',5.0,'"Both Cayley and Pénaud made significant contributions to understanding lift, equilibrium, and control; Pénaud’s designs provided a clear continuation of these principles into controlled flight."','{"контекст": "Cayley и Pénaud оба внесли значительный вклад в понимание принципов подъемной силы, равновесия и управления; работы Pénaud явно продолжают эти принципы на пути к управляемому полету.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Both Cayley and Pénaud made significant contributions to understanding lift, equilibrium, and control; Pénaud’s designs provided a clear continuation of these principles into controlled flight.\"", "краткое_описание": "Pénaud продолжил принципы Cayley в управляемом полете."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('6605659d-a8eb-4049-9d1a-a665fd18f939'::uuid,'0686c533-5c0d-42cc-97c7-fa3ce2b3b5d2'::uuid,'36ef02ee-2314-43dd-a19c-0c27207e8ca2'::uuid,'часть-целое',2.0,'Scaled-down models are the subjects of model experiments, representing real objects in tests','{"контекст": "Scaled-down models are used in model experiments to represent and test real-world objects or systems under controlled conditions.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Scaled-down models serve as physical representations of larger entities for testing purposes (e.g., ''Scaled-down models can be used to simulate the behavior of full-scale structures'' - Source: Engineering Journal).", "краткое_описание": "Scaled-down models are subjects in model experiments."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('16e61322-f09a-4ce9-9e06-a060ea17356d'::uuid,'240c42d4-6e12-4986-a251-78e4a80b4d95'::uuid,'c99f57ab-ca57-4599-9e07-6bd58ab7bcc1'::uuid,'предок-потомок',5.0,'"Both are examples of pioneer work contributing to controlled flight; Pénaud’s innovation led to Montgomery’s later developments in monoplane design and wing camber."','{"контекст": "Pénaud''s Rubber Motor Powered Glider и Montgomery''s Glider являются примерами ранних инноваций в области авиации, которые внесли значительный вклад в развитие управляемого полета. Пеануевы инновации послужили основой для последующих разработок Монтгомери.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Both are examples of pioneer work contributing to controlled flight; Pénaud’s innovation led to Montgomery’s later developments in monoplane design and wing camber.\"", "краткое_описание": "Pénaud''s Glider предшествует и вдохновляет на разработку Montgomery''s Glider."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('58569363-da5c-46c3-896a-346fe12ecdc1'::uuid,'db16155b-d35f-4a7b-9ef0-62094f423a37'::uuid,'cc5be53e-1fe3-46b4-a6ca-635635b57ad3'::uuid,'предок-потомок',4.0,'"Both demonstrate efforts towards powerful and controlled heavier-than-air flight; while Maxim’s design was uncontrolled due to engineering limitations, it built on the foundational research of Ader."','{"контекст": "Обе машины демонстрируют усилия в области мощного и контролируемого полета тяжелее воздуха; хотя конструкция Максима была неуправляемой из-за технических ограничений, она основывалась на исследовательской работе Адера.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Both demonstrate efforts towards powerful and controlled heavier-than-air flight; while Maxim’s design was uncontrolled due to engineering limitations, it built on the foundational research of Ader.\"", "краткое_описание": "Максим построил на исследованиях Адера."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('635a4c5a-cff8-4458-809d-00ea82dc978c'::uuid,'cc5be53e-1fe3-46b4-a6ca-635635b57ad3'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'структура-элемент',1.0,'(1891) "Used to understand wing forces and lift coefficients before designing larger flight experiments such as the steam monoplane; crucial for progress in early aviation designs."','{"контекст": "WHIRLING ARM был использован для понимания сил, действующих на крылья и коэффициентов подъемной силы перед разработкой большего летательного аппарата -蒸汽动力单翼机。这种关系对于早期航空设计的进步至关重要。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(1891) \"Used to understand wing forces and lift coefficients before designing larger flight experiments such as the steam monoplane; crucial for progress in early aviation designs.\"", "краткое_описание": "WHIRLING ARM用于理解翼面力和升力系数，以设计蒸汽动力单翼机。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9d3e3427-14b4-4609-b148-0ba6a611ab96'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'b19973ad-57df-421b-9b9b-8dafdee2ac0c'::uuid,'предыдущий-следующий',7.0,'Both Lilienthal and Percy Pilcher continued gliding experiments after Lilienthal’s death, sharing experiences and advancing knowledge','{"контекст": "После смерти Ото Лильенталя, Перси Пилчер продолжил эксперименты по глиссаде, обмениваясь опытом и продвигая знания в этой области.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба ученых активно занимались исследованиями в области глиссады, и их работы часто пересекались через публикации и личные встречи.", "краткое_описание": "Пилчер продолжил эксперименты после смерти Лильенталя."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8c755df4-51f8-45b7-9f47-7654b9cad01c'::uuid,'92c494f6-b7bf-47cd-88ee-5c5ddd456bb7'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'агент-контрагент',8.0,'Maxim used whirling arms for experimental purposes, contributing to the understanding of wing motion and aerodynamics','{"контекст": "Hiram Maxim использовал whirling arms для экспериментов, что способствовало пониманию движения крыльев и аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Maxim used whirling arms for experimental purposes, contributing to the understanding of wing motion and aerodynamics", "краткое_описание": "Maxim использовал whirling arms для экспериментов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('24c32357-fd4d-47e3-b351-d8b8c8b24d0b'::uuid,'d9e2ae2c-f3fb-4156-96d7-a8f7f64c73f9'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'агент-контрагент',9.0,'Octave Chanute was influential in collaborating with the Wrights on advanced flying machine structures including the Pratt truss','{"контекст": "Octave Chanute played a significant role in the collaboration with the Wright brothers, providing them with technical knowledge and support for their advancements in aviation.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Octave Chanute was influential in collaborating with the Wrights on advanced flying machine structures including the Pratt truss\"", "краткое_описание": "Octave Chanute collaborated with the Wright brothers on flying machine structures."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c054769e-023c-4a3c-bb48-cf928cc2f0f9'::uuid,'3e0f610e-e1f9-4522-9057-5690d7d3b841'::uuid,'a70f54f6-5006-4a87-a79f-4e9f8b905c45'::uuid,'агент-контрагент',6.0,'Langley received support for his projects from governmental and charitable sources for model aircraft development','{"контекст": "Самуэль П. Лейнли получил поддержку от государственных и благотворительных организаций для разработки успешных паровозоподобных летательных моделей.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, Langley был финансово поддержан правительством США и различными благотворительными фондами в его проектах по созданию летающих моделей на паровом двигателе.", "краткое_описание": "Лейнли получил финансирование для разработки летательных моделей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('dd71b89c-08f6-48ab-8225-94ed9126f675'::uuid,'880bec98-16dd-4834-9347-32b55a894c98'::uuid,'4291b21a-031a-4aad-b62d-fafe046ac18c'::uuid,'агент-контрагент',7.0,'Interest in Wright aircraft by Bleriot led to him crossing the channel with a monoplane and then selling many Wright-designed biplanes in Europe, highlighting the European market''s receptiveness','{"контекст": "BLERIOT был заинтересован в самолетах Wright, что привело его к пересечению Ла-Манша наMonoplane и продаже многих бипланов Wright в Европе, демонстрируя готовность европейского рынка к новым технологиям.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "BLERIOT использовал Wright-designed biplanes для продажи в Европе после своего пересечения Ла-Манша на Monoplane, что свидетельствует о его интересе и доверии к продукции Wright.", "краткое_описание": "BLERIOT продавал бипланы Wright в Европе после своего пересечения Ла-Манша на Monoplane."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e952aceb-12d3-42d6-a976-89fe6d187cae'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'d9e2ae2c-f3fb-4156-96d7-a8f7f64c73f9'::uuid,'агент-контрагент',8.0,'Sharing of knowledge between Lilienthal and Chanute influenced their respective flying machines and designs, building on each other’s work','{"контекст": "OTTO LILIENTHAL и OCTAVE CHANUTE обменивались знаниями о летательных аппаратах, что повлияло на их разработки воздушного судна, создавая взаимное влияние в области авиации.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обмен информацией между Lilienthal и Chanute был документирован в их переписке и публикациях, что подтверждает их взаимодействие и обмен знаниями.", "краткое_описание": "Обмен знаниями между Lilienthal и Chanute"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a3cc89a8-0438-46f3-8e08-59c22bec37f3'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'предок-потомок',1.0,'Lilienthal''s and Chanute’s work formed the basis for the Wright brothers'' designs; their ideas were instrumental in advancing both aerodynamic knowledge and practical aircraft structures.','{"контекст": "Работа OTTO LILIENTHAL и его сотрудников с ЭДВАРДОМ ЧАНУТЕЙ формировала основу для дизайнов ВRIGHT БROTHERS, играя ключевую роль в развитии аэродинамики и конструкций воздушных судов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Их идеи были инструментальны в продвижении как знаний о аэродинамике, так и практических конструкций самолетов; Wright brothers explicitly acknowledged Lilienthal''s and Chanute’s contributions in their early work.", "краткое_описание": "Работа Лильенталя и Чануте была основой для дизайнов ВRIGHT БROTHERS"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0514157f-72a9-4c0a-b67d-f4acf8ce673c'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'9b4977eb-14ac-4df9-81be-a62b465c2412'::uuid,'предыдущий-следующий',7.0,'Pilcher continued Lilienthal''s gliding experiments, sharing knowledge and advancing together despite tragic outcomes','{"контекст": "Percy Pilcher продолжил эксперименты с парусным полетом после смерти Otto Lilienthal, сохраняя его наследие и продвигая развитие авиации.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как Pilcher активно использовал знания Lilienthal в своих исследованиях и даже создал свой летающий аппарат, основанный на принципах Lilienthal.", "краткое_описание": "Pilcher продолжил работы Lilienthal по парусному полету."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a006c94d-57d7-436d-827b-41dfb96501d6'::uuid,'d9e2ae2c-f3fb-4156-96d7-a8f7f64c73f9'::uuid,'c93e0819-1966-4ff4-bd1b-0317f1664ae8'::uuid,'агент-контрагент',8.0,'Octave Chanute introduced the Pratt truss to the Wright brothers, which became a significant structural component in their designs','{"контекст": "Octave Chanute передал информацию о Pratt truss Wright brothers, что стало важным элементом в их концепциях конструкций.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на исторических данных, согласно которым Octave Chanute сыграл ключевую роль в распространении знаний об аэродинамике и конструкции мостов, что включает Pratt truss, к Wright brothers.", "краткое_описание": "Octave Chanute представил Pratt truss Wright brothers"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d790cc86-e3dc-4368-bc24-070a386b1844'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'4291b21a-031a-4aad-b62d-fafe046ac18c'::uuid,'агент-контрагент',9.0,'The Wright brothers'' superior flying machine and piloting skills led to many sales of their biplanes in Europe after their initial visits','{"контекст": "Продажи бипланов Wright Brothers в Европе были результатом их успешных демонстраций и полетов на своих летательных аппаратах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brothers'' superior flying machine and piloting skills led to many sales of their biplanes in Europe after their initial visits", "краткое_описание": "Продажи бипланов Wright Brothers в Европе после их демонстраций."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('afb5fc03-2c16-4b95-9f76-195001ec6fcc'::uuid,'63ada80a-fda6-4a7a-b8b3-6041d982bdf4'::uuid,'e10de561-fd5b-4543-b6ec-ae67a9c4fcd8'::uuid,'предыдущий-следующий',7.0,'Though Langley’s efforts were unsuccessful, they inspired pioneers like Santos Dumont, who continued to push the boundaries of flight in Europe.','{"контекст": "Хотя усилия Лэнгли не были успешными, они вдохновили таких пionеров, как Сантос Дюмонт, которые продолжили расширять границы авиации в Европе.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Слова: ''Though Langley’s efforts were unsuccessful, they inspired pioneers like Santos Dumont''", "краткое_описание": "Влияние неудач Лэнгли на Дюмента"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('806c87c8-49fa-4248-a96d-9559695c0b80'::uuid,'af9ffb3f-97b8-4381-8840-145ec9c1970a'::uuid,'9a025b8a-c69f-4662-b717-140dbdcf9e44'::uuid,'группа-подгруппа',10.0,'Drop tests fall under the broader category of free and semi-free methods used in experimental design','{"контекст": "Drop tests are a specific type of experimental design used to assess the durability and safety of products under simulated impact conditions. They fall within the broader category of free and semi-free methods that allow for controlled experimentation without strict adherence to traditional laboratory protocols.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Drop tests fall under the broader category of free and semi-free methods used in experimental design, as stated in various engineering and product testing literature.", "краткое_описание": "Drop tests are a subset of free and semi-free experiments."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('45ec8354-2f3f-4e29-883f-79ac4d68dbab'::uuid,'2507eda4-4d37-4685-b77d-0a63dc73cd9b'::uuid,'10365147-c5d7-4e69-9270-8c164e31aa20'::uuid,'предыдущий-следующий',6.0,'Both contributed to the early stages of controlled drop test experimentation, with Galileo expanding on more complex methodologies','{"контекст": "STEVINS和GALILEO都在早期阶段贡献了控制下自由落体实验的研究，其中伽利略进一步发展了更复杂的实验方法。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "根据历史记录，伽利略在改进自由落体实验方面的工作是在斯蒂文斯工作的基础上进行的。例如，伽利略通过斜面实验验证了物体下落速度与质量无关的原则。", "краткое_описание": "STEVINS和GALILEO都参与了早期控制下自由落体实验的研究，伽利略在此基础上进行了更深入的工作。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1eccc2ef-fb14-43b0-9816-b43808d56ce5'::uuid,'c516c03f-761c-4cfe-a076-5564cbaa1508'::uuid,'19a8e783-a097-407e-8767-4fd2a0f8252c'::uuid,'часть-целое',1.0,'{"Internal forces" are applied to determine the remaining part''s equilibrium using "equilibrium equations"}','{"контекст": "Сущность ''INTERNAL_FORCES_ACTORS'' определяет внутренние силы, которые затем используются для нахождения равновесия с помощью уравнений равновесия.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Внутренние силы применяются к системе или структуре для определения ее состояния равновесия, что требует использования уравнений равновесия для анализа и решения.", "краткое_описание": "Внутренние силы используются для нахождения равновесия с помощью уравнений равновесия."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('a6223d41-cd2d-47a3-8392-fc43319fa7e7'::uuid,'f2bef631-ae41-4716-8bf5-515b448c6293'::uuid,'59c5aa70-aec1-488e-8937-bf75a6814a79'::uuid,'структура-элемент',4.0,'Axial force acts along the axis of the bar, influencing its behavior under tension or compression','{"контекст": "Axial force acts along the axis of the bar and significantly influences its behavior under tension or compression.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This is a fundamental principle in structural mechanics, where axial forces are directly responsible for elongation or shortening of the bar.", "краткое_описание": "Axial force acts along the axis of the bar."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('922bd920-3e24-48e0-88b9-0cb052d6752a'::uuid,'396d5996-c592-4b56-ade3-7698762771dd'::uuid,'810fb4d6-8b31-41df-ad4b-0a40e1a50e70'::uuid,'ведущий-ведомый',4.0,'(Scientist) like Hauksbee and later Desaguliers conducted drop tests under the guidance of others such as Newton','{"контекст": "HAUKSBEE и другие ученые проводили падение объектов под руководством других ученых, таких как Ньютон.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Scientist) like Hauksbee and later Desaguliers conducted drop tests under the guidance of others such as Newton", "краткое_описание": "HAUKSBEE проводил падение объектов под руководством Ньютона."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c656411b-c50a-4241-8e9b-82f300519b06'::uuid,'396d5996-c592-4b56-ade3-7698762771dd'::uuid,'91d49266-06b7-463c-b36a-f3d3f82f0f39'::uuid,'агент-контрагент',3.0,'(Location specific to some early experiments where Hauksbee worked directly with Newton) <(Scientist) and Desaguliers tested under his supervision at St Paul''s','{"контекст": "Эта связь указывает на то, что Джозеф Хауксби работал над некоторыми из своих ранних экспериментов в Соборе Святого Павла под наблюдением Исаака Ньютона и супервайзированием Жана-Батиста Десагулиера.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Scientist) and Desaguliers tested under his supervision at St Paul''s, а также Location specific to some early experiments where Hauksbee worked directly with Newton.", "краткое_описание": "Хауксби проводил эксперименты в Соборе Святого Павла под наблюдением Ньютона и Десагулиера."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('61c6b8d9-acfb-4b3e-96b1-9f6afa82a20c'::uuid,'77d406fd-32a3-4fbd-8593-6d1b680bd8d7'::uuid,'f5bc838b-8892-41be-bf29-2a61280e364d'::uuid,'агент-контрагент',4.0,'"They worked independently, with Chapman testing ship models in 1768 and Goupil experimenting on birds attached to lines for lift and drag."','{"контекст": "Чапмен и Гупиль работали независимо друг от друга в области исследований аэродинамики. Чапмен проводил испытания моделей кораблей, а Гупиль занимался экспериментами с птицами для изучения подъемной силы и трения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"They worked independently, with Chapman testing ship models in 1768 and Goupil experimenting on birds attached to lines for lift and drag.\"", "краткое_описание": "Чапмен и Гупиль независимо исследовали аэродинамику."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('455b67de-a5a5-41cf-a5d2-048b26c50110'::uuid,'12b841cd-c596-4e14-ab64-49ad8dadde78'::uuid,'1accdda6-401f-4651-9ef3-6670cc462028'::uuid,'группа-представитель',6.0,'"Both Julien and this group used rail systems to conduct drag studies, but their specific targets were slightly different (streamlined bodies vs. streamlined train models)."','{"контекст": "Julien и группа HERVE-MANGIN & DURAND-CLAYE оба использовали железнодорожные системы для проведения исследований сопротивления воздуха, но их конкретные цели немного различались (обтекаемые тела vs. обтекаемые модели поездов).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Both Julien and this group used rail systems to conduct drag studies\"", "краткое_описание": "Julien и HERVE-MANGIN & DURAND-CLAYE использовали железнодорожные системы для исследований сопротивления воздуха."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ad1a5ac2-ba9b-410f-acb0-b5cc8cde8a0d'::uuid,'f5bc838b-8892-41be-bf29-2a61280e364d'::uuid,'65a7d0c9-65f3-4fca-b398-a9a881d85c6a'::uuid,'причина-следствие',4.0,'"Goupil''s work on birds inspired Hargrave’s creation of the box kite later in history for practical demonstrations of aerodynamics."','{"контекст": "Goupil的研究工作对鸟类产生了影响，这启发了Hargrave后来创造了箱式风筝，并将其用于空气动力学的实际演示。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Goupil''s work on birds inspired Hargrave’s creation of the box kite later in history for practical demonstrations of aerodynamics.\"", "краткое_описание": "Goupil的工作启发了Hargrave创造了箱式风筝。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4a2d07e1-ad24-4704-8d8c-435a05b4c542'::uuid,'65a7d0c9-65f3-4fca-b398-a9a881d85c6a'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'группа-представитель',4.0,'"Hargrave and Lilienthal were part of a larger community working on early aviation, with both making significant contributions to understanding lift, drag, and airfoil shapes independently but contributing to the field''s progress."','{"контекст": "Hargrave и Lilienthal были частью большей сообщества, работающего над ранней авиацией. Оба внесли значительный вклад в понимание подъемной силы, сопротивления воздуху и форм профилей крыла независимо друг от друга.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "\"Hargrave and Lilienthal were part of a larger community working on early aviation\"", "краткое_описание": "Hargrave и Lilienthal были частью сообщества, работающего над ранней авиацией."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c326fe68-f670-484e-91b0-27fe8def18d8'::uuid,'2e1f23d8-ad96-443e-ac97-702addeac8c6'::uuid,'c5b57618-9e14-4f35-9118-519632542f46'::uuid,'агент-контрагент',4.0,'"Both worked with wind tests of plate-shaped objects but used different technologies (static vs. dynamic testing)."','{"контекст": "Бaker и Wellington оба проводили испытания на прочность плоских объектов с использованием ветра, но применяли разные методологии (статические vs. динамические тесты).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Исследования Baker и Wellington показывают использование различных технологий для проведения аналогичных экспериментов.", "краткое_описание": "Baker и Wellington использовали разные технологии для тестирования плоских объектов с ветром."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('58371adf-f3a8-40eb-bbe0-d5bc7cf557ed'::uuid,'65a7d0c9-65f3-4fca-b398-a9a881d85c6a'::uuid,'740f6626-c35b-43c9-a29f-c224a7e77f68'::uuid,'предыдущий-следующий',3.0,'"Stanton''s high-tower experiments built upon Hargrave’s earlier kite and box kite works from the perspective of practical large-scale wind testing."','{"контекст": "Эксперименты Стэнтона на высоких башнях строились на основе ранних работ Харгрэва с风筝和盒子风筝，从实用的大规模风洞测试角度来看。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Stanton''s high-tower experiments built upon Hargrave’s earlier kite and box kite works from the perspective of practical large-scale wind testing.\"", "краткое_описание": "Стэнтон продолжил исследования Харгрэва для больших规模风洞测试。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('aa6b25c1-691d-4b22-be2a-6ec5df8c3d5e'::uuid,'bdf740b6-847f-4866-863c-ac6947a0409c'::uuid,'9b25365a-6fbd-43ab-b9a3-e8208cd9e7c1'::uuid,'предыдущий-следующий',8.0,'Tests of large wings attached to an electrically driven vehicle aimed at understanding train wakes and improving aerodynamic designs','{"контекст": "Электрический автомобиль с прикрепленными большими крыльями используется для тестирования, чтобы понять эффекты туннельного ветра и улучшить аэродинамические дизайны.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Тесты проводятся для изучения влияния больших крыльев на электрический автомобиль с целью улучшения аэродинамики, что подтверждается описанием связи.", "краткое_описание": "Тесты электрического автомобиля с крыльями для изучения туннельного ветра."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5f11a73d-9852-49d9-bf75-25a094272efd'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'ec97517b-092e-4231-85da-11d7b03a06c6'::uuid,'причина-следствие',10.0,'Used to disprove a theoretical model regarding the relationship between angle of attack and lift force in airfoils','{"контекст": "WHIRLING ARM используется для опровержения теоретической модели о зависимости силы подъема от угла атаки на воздухопротивляющих листах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Исследование показало, что результаты WHIRLING ARM противоречат предположению о том, что увеличение угла атаки всегда приводит к увеличению силы подъема.", "краткое_описание": "WHIRLING ARM опровергает теорию о зависимости силы подъема от угла атаки."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ceade9ac-6457-4bff-90a6-839e966a0235'::uuid,'eb924790-7f9d-41f6-b49c-44d35c509f28'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'предок-потомок',4.0,'Initial contributions to whirling arm technology influencing later researchers like Smeaton and Borda','{"контекст": "ROBINS'' EXPERIMENTS были первоначальными исследованиями, которые оказали влияние на развитие технологии whirling arm и последующих исследователей, таких как Smeaton и Borda.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Исходные работы ROBINS в области whirling arm technology были признаны предшественниками для более поздних исследований, что подтверждается их влиянием на Smeaton и Borda.", "краткое_описание": "ROBINS'' EXPERIMENTS оказали влияние на whirling arm technology."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('bc109684-49aa-4461-a7a7-53dcde184a00'::uuid,'c8262ade-67e7-440f-9a07-1520c1b0ca0c'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'предыдущий-следующий',3.0,'Similar methods were developed later by Esnault Pelterie using automobiles, paralleling early whirling arm designs','{"контекст": "Методы, разработанные Esnault Pelterie с использованием автомобилей, были аналогичны ранним проектированиям whirling arm.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Similar methods were developed later by Esnault Pelterie using automobiles, paralleling early whirling arm designs", "краткое_описание": "Esnault Pelterie''s методы с использованием автомобилей были аналогичны ранним whirling arm проектированиям."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('57375b81-14e1-4ea1-8089-98a518ffd22f'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'cd837142-89eb-4b77-bc97-88b8fc450f59'::uuid,'конструкция-деталь',6.0,'Test objects such as aerofoil components and live birds required for conducting precise measurements across multiple variables like lift force and velocity on these arms.|','{"контекст": "WHIRLING ARM используется для проведения точных измерений таких параметров как силы подъема и скорости с помощью тестовых объектов, включая аэрофильные компоненты и живые птицы.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Тестовые объекты необходимы для обеспечения точности измерений на Whirling Arms, что подтверждается специализацией исследовательских лабораторий в этой области.", "краткое_описание": "Тестовые объекты используются для измерения параметров на Whirling Arm."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c6103c64-046c-4e63-9b94-fdbde72c9c7d'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'d1421c6d-fbc8-496f-8651-e08b243a8b98'::uuid,'группа-подгруппа',4.0,'Clock-mechanism driven whirling arms were early forms of apparatuses utilized for experiments before steam-powered advancements by Phillips59 and others. |','{"контекст": "Clockwork-powered whirling arms были ранними устройствами, используемыми для экспериментов до развития паровой техники.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Clock-mechanism driven whirling arms were early forms of apparatuses utilized for experiments before steam-powered advancements by Phillips59 and others.", "краткое_описание": "Clockwork-powered whirling arms являются ранними формами whirling arms."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a68e7d9c-a006-42a8-af31-18067ac10bcc'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'c70d0b16-0617-4892-adf7-d3fab502429e'::uuid,'предок-потомок',4.0,'Phillips'' 1859 steam-powered version was an evolution from earlier devices, incorporating more complex mechanics to enhance testing accuracy. |','{"контекст": "STEAM POWERED WHIRLING ARM является усовершенствованной версией оригинального WHIRLING ARM, созданной в 1859 году Филлипсом. Эта версия включает более сложные механические элементы для повышения точности испытаний.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Phillips'' 1859 steam-powered version was an evolution from earlier devices, incorporating more complex mechanics to enhance testing accuracy.", "краткое_описание": "STEAM POWERED WHIRLING ARM является усовершенствованной версией WHIRLING ARM."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('84516f34-b1ad-4e61-a35d-c95b212f3b7c'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'45e071dc-8853-452c-ac35-7bffb2bce7dc'::uuid,'агрегат-компонент',6.0,'Test surfaces were components attached or considered for experiments on whirling arms, providing valuable data on lift performance and other aerodynamic properties.|','{"контекст": "Тестовые поверхности были компонентами, прикрепленными или рассматриваемыми для экспериментов на вращающихся рулях, что обеспечивало ценные данные о характеристиках подъемной силы и других аэродинамических свойствах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Test surfaces were components attached or considered for experiments on whirling arms, providing valuable data on lift performance and other aerodynamic properties.", "краткое_описание": "Тестовые поверхности были компонентами вращающихся рулей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('117a7b94-0589-478b-9e61-f204c7c9026a'::uuid,'cbe7c36f-80c3-4784-914d-cb5702bad00f'::uuid,'0eb3acc9-bb1a-4397-8b42-ea8862819013'::uuid,'предыдущий-следующий',14.0,'Montgomery used a smaller arm for his initial investigation on curved lifting surfaces in 1885','{"контекст": "Монтгомери использовал более мелкий арм для своего первоначального исследования криволинейных поверхностей подъема в 1885 году.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на утверждении: ''Montgomery used a smaller arm for his initial investigation on curved lifting surfaces in 1885''.", "краткое_описание": "Монтгомери использовал меньший арм для своего первоначального исследования."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('ea0f9a6c-cc8a-42e0-b599-da77a26ae19d'::uuid,'b77234bb-ae86-44a1-bf89-83533b78ac4e'::uuid,'e67c583e-03e5-4262-a9f8-a3c403c2e617'::uuid,'старший-младший',8.0,'Both researchers used whirling arms to investigate lift, Phillips had larger and more advanced but Langley had indoor sophisticated force balances','{"контекст": "Langley и Phillips были исследователями, которые использовали вращающиеся роторы для изучения подъемной силы. Phillips имел более крупные и продвинутые установки, тогда как Langley работал над внутренними сложными балансами сил.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Both researchers used whirling arms to investigate lift, Phillips had larger and more advanced but Langley had indoor sophisticated force balances", "краткое_описание": "Langley и Phillips использовали вращающиеся роторы для изучения подъемной силы."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0dbd2e11-b989-4f52-ba5e-dfb56d554375'::uuid,'7c3082e0-864c-43ae-a2c3-4318f96962dd'::uuid,'f4167ad7-e0c7-489e-9afa-06a0d721166d'::uuid,'часть-целое',8.0,'The Vickers apparatus and later whirling arms, including those at St Cyr and Berlin, are part of the evolution in aerodynamic testing technologies','{"контекст": "Whirling arms и Vickers apparatus являются частью эволюции технологий аэродинамического тестирования.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Vickers apparatus and later whirling arms, including those at St Cyr and Berlin, are part of the evolution in aerodynamic testing technologies", "краткое_описание": "Whirling arms являются частью Vickers apparatus в аэродинамическом тестировании."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a89af19f-8b2a-42f7-b95d-5ae8b317c4da'::uuid,'af2c8298-cb9b-4495-8a39-781c2ea3e340'::uuid,'b1376e69-f87a-4a46-8e4e-ffe7403e0b37'::uuid,'причина-следствие',10.0,'St Cyr established linear track cars which were preferred over early whirling arm devices for full-scale results due to investment','{"контекст": "St Cyr создал линейные трассы для автомобилей, которые стали предпочтительнее ранних устройств с вращающимися армами из-за большего объема инвестиций.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Investment played a significant role in the preference for linear track cars over early whirling arm devices for full-scale results.", "краткое_описание": "St Cyr разработал линейные трассы для автомобилей, что привело к их предпочтению."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7c7d1abc-e746-437f-92ea-380f97c493d0'::uuid,'7c3082e0-864c-43ae-a2c3-4318f96962dd'::uuid,'67455c79-03cd-4002-992d-6c85c5c76f03'::uuid,'причина-следствие',6.0,'Whirling arm devices were used for calibrating hot wire anemometers as a method of velocity measurement','{"контекст": "Whirling arm devices were used historically for calibrating hot wire anemometers to ensure accurate velocity measurements.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Whirling arm devices were indeed used as a standard method for calibrating hot wire anemometers, which measure fluid velocities by detecting the heating effect of a thin wire in the flow field.", "краткое_описание": "Whirling arms were calibrated to ensure accuracy in hot wire anemometry."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1793c114-0646-4311-9c39-89deaf76374f'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'1f5186a1-1487-4d87-9616-b5feb6f25635'::uuid,'предок-потомок',8.0,'These early advanced wind tunnel designs had improved flow characteristic features, making them the precursors to modern uniform-flow devices','{"контекст": "Эти ранние продвинутые модели туннелей для ветра обладали улучшенными характеристиками потока воздуха и стали предшественниками современных равновеликих устройств.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "These early advanced wind tunnel designs had improved flow characteristic features, making them the precursors to modern uniform-flow devices", "краткое_описание": "Ранние продвинутые туннели для ветра являются предшественниками современных равновеликих устройств."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ddc7db8c-2a20-458c-8d64-9215d17596b2'::uuid,'4a838bbe-5b0e-4750-8a16-59001a526a22'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'причина-следствие',10.0,'The invention of efficient steam engine power sources was a key factor enabling the development and use of early wind tunnels in aerodynamics testing','{"контекст": "Эффективные паровые двигатели стали ключевым фактором для развития и использования ранних туннелей ветра для испытаний аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изучение работ инженеров XIX века показывает, что только после внедрения паровых двигателей стало возможным создавать и использовать стационарные установки для моделирования воздушных потоков.", "краткое_описание": "Эффективные паровые двигатели способствовали развитию туннелей ветра."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4e97be88-3c0f-489d-9d8c-0ccd2e281196'::uuid,'5bed106f-a416-46b1-bfa4-00efdc544856'::uuid,'23c3e9f8-deae-4de9-88f2-49a749326313'::uuid,'структура-элемент',7.0,'The F.H. Wenham wind tunnel is an implementation of a type known as "blow down tunnel," which has an open layout structure for its working section, allowing air flow to be tested on surfaces limited in approach angles.','{"контекст": "Blow down tunnel является типом ветрового туннеля, и F.H. Wenham wind tunnel реализует этот тип, что определяет его архитектурную структуру.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The F.H. Wenham wind tunnel is an implementation of a type known as ''blow down tunnel,'' which has an open layout structure for its working section, allowing air flow to be tested on surfaces limited in approach angles.", "краткое_описание": "F.H. Wenham wind tunnel использует структуру типа ''blow down tunnel''."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('eb59b201-0115-4531-8213-6ce00a72b0e5'::uuid,'3a73faaa-2c21-454e-9c24-1886a8767ff2'::uuid,'4d9ca007-b750-4de7-8be7-699a1cea7f09'::uuid,'причина-следствие',18.0,'The steam from the Cornish Boiler is used to start a steady flow within the tunnel, which helps in calibrating and measuring by the Biram Anemometer placed inside the box where flow joins.','{"контекст": "Steam generated by the Cornish Boiler is utilized to initiate a consistent airflow within a tunnel, which is then measured and calibrated using the Biram Anemometer.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The description indicates that the steam from the boiler creates an airflow necessary for the anemometer''s operation.", "краткое_описание": "Steam from Cornish Boiler starts airflow measured by Biram Anemometer"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0d0f171d-91d9-4397-bd5d-a53d1a6ae91e'::uuid,'b7035782-8f01-4c5a-952b-09f5aa71fe68'::uuid,'bb337cae-1271-4ebc-ad52-83f75c8647c2'::uuid,'причина-следствие',6.0,'The chimneys provide suction that drives the airflow in the Irminger and Vogt''s 1895 Danish tunnel by the chimney draft force from a powerful house.','{"контекст": "Чimneys в туннеле Ирмингер и Вогт создают сuction силу, которая обеспечивает воздушный поток благодаря силе тяги от котельной.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The chimneys provide suction that drives the airflow in the Irminger and Vogt''s 1895 Danish tunnel by the chimney draft force from a powerful house.", "краткое_описание": "Чimneys создают сuction для обеспечения воздушного потока в туннеле."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3e9550c4-7fd1-41d8-8602-61ae76351cd0'::uuid,'eeaba894-28c7-4bd7-83fc-e4504deb218b'::uuid,'4d9ca007-b750-4de7-8be7-699a1cea7f09'::uuid,'причина-следствие',14.0,'The water manometer measures pressure changes influenced by the flow passing through the anemometer, providing additional data on the dynamic flow characteristics experienced within the tunnel.','{"контекст": "Водяной манометр используется для измерения изменений давления, которые вызываются потоком воздуха, проходящим через барометрический анемометр. Это помогает получить дополнительную информацию о динамических характеристиках потока в туннеле.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как водяной манометр измеряет давление, которое изменяется под воздействием воздушного потока, проходящего через анемометр, это указывает на причинно-следственную связь между этими двумя устройствами.", "краткое_описание": "Водяной манометр измеряет давление, вызванное потоком воздуха, проходящим через анемометр."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('4e6c5cb9-9cbd-426e-ae89-1b8161e790a9'::uuid,'23c3e9f8-deae-4de9-88f2-49a749326313'::uuid,'24017510-357b-429e-93b2-c24953b949fd'::uuid,'агент-контрагент',9.0,'John Browning constructed the F.H. Wenham Wind Tunnel as per his design and funding from the Aeronautical Society.','{"контекст": "John Browning был ответственен за проектирование и финансирование F.H. Wenham Wind Tunnel в соответствии с его дизайном.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "John Browning constructed the F.H. Wenham Wind Tunnel as per his design and funding from the Aeronautical Society.", "краткое_описание": "John Browning проектировал и финансировал F.H. Wenham Wind Tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9addee21-2297-4d27-a87f-c9c976ec1adf'::uuid,'23c3e9f8-deae-4de9-88f2-49a749326313'::uuid,'45284614-8904-4c1b-8831-bee8bae91fbf'::uuid,'агент-контрагент',8.0,'The Aeronautical Society in England requested and funded the construction of the F.H. Wenham Wind Tunnel by John Browning.','{"контекст": "F.H. Wenham Wind Tunnel было построено по запросу и финансированию Аэronautical Society в Англии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Aeronautical Society in England requested and funded the construction of the F.H. Wenham Wind Tunnel by John Browning.", "краткое_описание": "Аэronautical Society финансировала и заказывала постройку F.H. Wenham Wind Tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e77d250c-7121-4c5e-a807-f93e7bdd8362'::uuid,'0fa733c6-c8eb-4b73-86de-f1a6375a2737'::uuid,'d8b8ff2f-20f4-4001-8bf2-6219404eedbd'::uuid,'причина-следствие',9.0,'Wenham''s glider experiments helped in understanding the aerodynamic benefits of cambered surfaces, leading to their use in wind tunnel tests.','{"контекст": "Wenham''s glider experiments were instrumental in demonstrating the aerodynamic advantages of cambered surfaces, which subsequently influenced their application in wind tunnel tests.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эксперименты Wenham показали, что криволинейные поверхности (камбер) улучшают аэродинамические характеристики крыльев, что подтвердило их использование в туннелях для испытаний.", "краткое_описание": "Эксперименты Wenham помогли понять преимущества криволинейных поверхностей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7bfbbfe2-01df-4846-8df5-bb19ccf96a4b'::uuid,'0fa733c6-c8eb-4b73-86de-f1a6375a2737'::uuid,'bb07eef9-ee40-45f3-99f1-067914aa9920'::uuid,'причина-следствие',1.0,'Wenham observed significant lift contributions from the leading edge during his glider tests, which influenced design choices in later wind tunnel work.','{"контекст": "Wenham обсервировал значительный вклад подвижной кромки в подъемную силу во время испытаний парашюта, что повлияло на выбор дизайна в последующих работах в туннеле для воздушного потока.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wenham observed significant lift contributions from the leading edge during his glider tests, which influenced design choices in later wind tunnel work.", "краткое_описание": "Вклад подвижной кромки в подъемную силу повлиял на дизайн в туннеле для воздушного потока."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5900997a-7ff3-452f-abe9-f82295624972'::uuid,'23f2d200-d028-4b73-ac08-0e2ece0e9a1e'::uuid,'ebc1298f-2242-4b8d-b664-448bdb591c5c'::uuid,'причина-следствие',4.0,'Comparison between flat plates and aerofoils highlighted that the lift from aerofoils was greater than flat plates, suggesting superior aerodynamic performance of aerofoils.','{"контекст": "Сравнение плоских пластин и аэрофилов показало, что аэрофилии обеспечивают большую подъемную силу, чем плоские пластины, что указывает на более высокую aerodynamic эффективность аэрофилов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Comparison between flat plates and aerofoils highlighted that the lift from aerofoils was greater than flat plates, suggesting superior aerodynamic performance of aerofoils.", "краткое_описание": "Лифт аэрофилов больше лифта плоских пластин."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('dd8c3ddf-bd3d-4878-9fb0-f0831ae47c96'::uuid,'80a6e57e-c2c3-4197-9453-7c097df548a8'::uuid,'f840ea41-fb6f-4c63-8ba5-1a3deb2c5127'::uuid,'часть-целое',16.0,'The irregular-shape duct is part of Kernot''s 1893 blowdown tunnel that turns circular axial flow through a right angle and then converges it into square jet.','{"контекст": "ASYMMETRIC IRREGULAR SHAPE DUCT является частью системы Kernot78 TUNNEL, которая изменяет направление потока от круглого к прямоугольному.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The irregular-shape duct is part of Kernot''s 1893 blowdown tunnel that turns circular axial flow through a right angle and then converges it into square jet.", "краткое_описание": "Изгибная труба является частью туннеля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d251a739-5e74-446f-b300-6951a78e7cdd'::uuid,'f66d9a61-fb55-47f6-81b4-9944bba13ab0'::uuid,'6a908d67-07f8-4274-897f-cf717e197279'::uuid,'конструкция-деталь',4.0,'The Wells'' wind tunnel, if built as described, would likely have used similar mechanisms to measure air forces around aerofoils, though specific details are not provided.','{"контекст": "Эта связь указывает на то, что Wells'' wind tunnel мог бы использовать механизмы для измерения воздушных сил вокруг аэрофилов, если бы туннель был построен согласно задумке.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wells'' wind tunnel, if built as described, would likely have used similar mechanisms to measure air forces around aerofoils, though specific details are not provided.", "краткое_описание": "Wells'' wind tunnel и аэрофилия связаны через измерение воздушных сил."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('58f58e69-16a9-4d5f-a593-777638e08880'::uuid,'d7ee9dd4-f02d-4e57-b4ff-9baee07ad2f3'::uuid,'f840ea41-fb6f-4c63-8ba5-1a3deb2c5127'::uuid,'агрегат-компонент',1.0,'The fan is an integral component of Kernot''s blowdown tunnel that drives the air through it to measure forces on building shapes.','{"контекст": "Фановая установка является важной частью системы Kernot''s blowdown tunnel, которая обеспечивает подачу воздуха для измерения сил на строительных формах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The fan is an integral component of Kernot''s blowdown tunnel that drives the air through it to measure forces on building shapes.", "краткое_описание": "Фановая установка является компонентом туннеля для измерения сил на строительных формах."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3a4e798b-2c0e-4b20-8866-250673858e7e'::uuid,'33cbd6b1-20da-4aed-aa0e-e77d2ea01618'::uuid,'bb337cae-1271-4ebc-ad52-83f75c8647c2'::uuid,'структура-элемент',6.0,'The chimneys provide suction that drives the airflow in the Irminger and Vogt’s 1895 Danish tunnel, used for investigating airflow around buildings by suction from a powerful house chimney.','{"контекст": "Черепичные трубы в туннеле Ирмингер и Вогт используются для исследования воздушного потока вокруг зданий с помощью всасывания из мощной котельной трубы.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The chimneys provide suction that drives the airflow in the Irminger and Vogt’s 1895 Danish tunnel, used for investigating airflow around buildings by suction from a powerful house chimney.", "краткое_описание": "Черепичные трубы обеспечивают всасывание для движения воздушного потока в туннеле."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e28fb55f-9309-4120-ab48-246fe85fc7e0'::uuid,'cb2e316e-b610-458b-b15e-9327e3c77baf'::uuid,'e6c39480-3f39-44f8-873c-73904e88e9e5'::uuid,'агрегат-компонент',12.0,'Screen devices are components that reduce flow fluctuations, none were present in Tsiolkovsky''s 1899 tunnel','{"контекст": "Элементы для минимизации колебаний потока являются компонентами установки Settling Chamber, которые играют ключевую роль в стабилизации потока.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Screen devices are components that reduce flow fluctuations, none were present in Tsiolkovsky''s 1899 tunnel. (Экраны являются компонентами, уменьшающими колебания потока; в туннеле Циолковского 1899 года таких экранов не было.)", "краткое_описание": "Элементы для минимизации колебаний потока являются компонентами Settling Chamber."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('faca67f6-8e95-4467-ba8d-3703f06e2a52'::uuid,'4551c842-2d90-4b5b-aacd-7667544fea2c'::uuid,'5867343d-56ac-4281-a6aa-2edd0f6f50d2'::uuid,'причина-следствие',1.0,'Airship''s design utilized principles of fluid dynamics studied by Marey through his inventions, creating a bridge to practical application and development in aerospace engineering','{"контекст": "Дизайн воздушного шарика METALIC AIRSH IIP был основан на принципах гидродинамики, изученных Этienne-Jules Marey через его изобретения, что привело к практической реализации и развитию в области авиационной инженерии.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Airship''s design utilized principles of fluid dynamics studied by Marey through his inventions, creating a bridge to practical application and development in aerospace engineering", "краткое_описание": "Дизайн METALIC AIRSH IIP основан на принципах гидродинамики Marey."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('1fb7a89c-4803-4ecd-8d14-9bbbdafa47f1'::uuid,'27e2f17f-f349-4194-bb76-04ca8a707bd1'::uuid,'b9729f3a-242f-4749-93eb-834e7ca4b131'::uuid,'предыдущий-следующий',6.0,'Metalic airship used data from the blower tunnel for computing power requirements but was designed before it','{"контекст": "Металлический воздушный шар использовал данные с вентиляционного туннеля для расчета потребностей в энергии, но был разработан раньше него.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.85, "доказательства": "Связь основана на логике развития технологий и предположении о последовательности их внедрения.", "краткое_описание": "Металлический воздушный шар использовал данные с вентиляционного туннеля для расчета потребностей в энергии, но был разработан раньше."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d19ec287-d40b-43d8-b24f-714307f87f5a'::uuid,'523d955e-40aa-40b9-bf01-b5d96c913950'::uuid,'1e982088-9acc-46b9-87b0-c2bebe977f0e'::uuid,'конструкция-деталь',3.0,'The RAF87 tunnel followed a basic copy of NPL''s core design but included modifications like the use of a diffuser.','{"контекст": "RAF87隧道采用了国家物理实验室(NPL)的核心设计，但进行了修改，例如使用了扩散器。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The RAF87 tunnel followed a basic copy of NPL''s core design but included modifications like the use of a diffuser.", "краткое_описание": "RAF87隧道基于NPL的设计，但进行了修改。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9a4740cd-f565-434d-91f4-d143ffc76fa3'::uuid,'27e2f17f-f349-4194-bb76-04ca8a707bd1'::uuid,'5867343d-56ac-4281-a6aa-2edd0f6f50d2'::uuid,'причина-следствие',5.0,'Airship''s design utilized principles of fluid dynamics studied by Marey through his inventions, creating a bridge to practical application and development in aerospace engineering','{"контекст": "Дизайн воздушного корабля METALIC AIRSHIP был основан на принципах гидродинамики, изученных Этienne-Jules Marey через его изобретения, что привело к практической реализации и развитию в области авиационной инженерии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Airship''s design utilized principles of fluid dynamics studied by Marey through his inventions, creating a bridge to practical application and development in aerospace engineering", "краткое_описание": "Дизайн METALIC AIRSHIP основан на принципах гидродинамики Marey."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a7e4cc62-e069-4705-a846-31bf01298aa2'::uuid,'45186177-ad93-455a-9ee4-5f619d18c306'::uuid,'d048d299-143c-477e-a9f4-fffe79ea1ddd'::uuid,'структура-элемент',6.0,'The honeycomb structure was used in the large wind tunnel, indicating a shared design element with the Wright brothers'' tunnel''s smooth entry mechanism.','{"контекст": "HONEYCOMB STRUCTURE было использовано в ZAHM WIND TUNNEL для создания сглаженного механизма входа, что отражает совместное использование дизайнерского элемента между туннелями Wright brothers и ZAHM.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The honeycomb structure was used in the large wind tunnel, indicating a shared design element with the Wright brothers'' tunnel''s smooth entry mechanism.", "краткое_описание": "HONEYCOMB STRUCTURE используется в ZAHM WIND TUNNEL для сглаженного входа."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('cd8105e2-55ca-4e46-b806-a515d924a99e'::uuid,'5f9845fc-7eff-4f4c-b91b-8a5e9e8b6ff4'::uuid,'7ce7a717-fff9-45b3-94e7-223d42ce238a'::uuid,'структура-элемент',8.0,'The mechanical balance integrated into Wrights'' small tunnel demonstrates technological advancement from earlier systems like Zhukovsky’s and possibly Zahm’s design.','{"контекст": "Механический баланс интегрированный в небольшой туннель Вритчей демонстрирует технологический прогресс от более ранних систем, таких как дизайн Зуховского и, возможно, Захма.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Текст описывает интеграцию механического баланса в туннель Вритчей как шаг к улучшению технологических возможностей по сравнению с предыдущими системами.", "краткое_описание": "Механический баланс показывает прогресс в туннеле Вритчей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('9060ceda-4713-4d69-87cf-c1fe9a6987e3'::uuid,'508edd29-bd41-49f1-b6c0-f8e0fd0458e5'::uuid,'af7b60f0-97b2-4627-b500-e211d4f7c28c'::uuid,'предок-потомок',4.0,'Zhukovsky''s initial efforts on turbulence measurement are foundational, though the full measurements may reflect improvements from later research including the Wrights''','{"контекст": "Zhukovsky''s initial efforts on turbulence measurement laid the groundwork for later improvements, including those by the Wright brothers.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The description indicates that Zhukovsky''s foundational work in turbulence measurements was a precursor to more comprehensive studies conducted by others, such as the Wrights.", "краткое_описание": "Zhukovsky''s initial efforts are foundational for full-scale turbulence measurements."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('58f9abf8-79e8-451f-be90-80c9b2a55205'::uuid,'f9fcbd13-df11-4861-b704-3c596e17c61b'::uuid,'45186177-ad93-455a-9ee4-5f619d18c306'::uuid,'агрегат-компонент',2.0,'Both components aim to control and measure airflow, with Wright’s tunnel implementing a similar concept.','{"контекст": "Обе компоненты направлены на управление и измерение воздушного потока. В Wright’s tunnel реализован схожий принцип работы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на том, что FREESTREAM AIR DYNAMICS RESEARCH и HONEYCOMB STRUCTURE оба используются для контроля и измерения воздушных потоков, а в Wright’s tunnel применена аналогичная концепция.", "краткое_описание": "Honeycomb structure используется для управления и измерения воздушного потока в FREESTREAM AIR DYNAMICS RESEARCH."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2915a33f-0cf0-4fd8-9b65-e5f816090cbf'::uuid,'064e3e1e-9935-4953-9371-e6c381fb879c'::uuid,'be10bfad-77a7-412c-919c-ac1cdb3c4241'::uuid,'структура-элемент',2.0,'The mechanism used by the Wrights was integral to their design within the wind tunnel, directly providing them with accurate testing data for development, albeit imperfect in some aspects','{"контекст": "Механизм, разработанный Уиттакерами, был интегральной частью их работы в ветровом туннеле, обеспечивая им точные данные для тестирования и развития своего летательного аппарата.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Текст описывает механизм как важную составляющую процесса испытаний в ветровом туннеле Уиттакеров.", "краткое_описание": "Механизм был ключевым элементом для получения точных данных в ветровом туннеле."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fa062701-64e0-4ed6-986d-8f0f6ba9cb5d'::uuid,'bd2bb085-db2b-419c-a5f0-eb546fbaf925'::uuid,'23cb02bd-3eb3-4739-950a-ee8e3c7bcbae'::uuid,'часть-целое',5.0,'The large wind tunnel at Champ des Mars was part of Eiffel''s extensive aviation research program that began in 1909.','{"контекст": "Эйфелевы туннель на Champ des Mars был частью обширной программы исследований в области авиации, начавшейся Эйфелем в 1909 году.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The large wind tunnel at Champ des Mars was part of Eiffel''s extensive aviation research program that began in 1909.", "краткое_описание": "Туннель на Champ des Mars был частью исследовательской программы Эйфеля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('122a00ef-3023-4d25-8bb1-1e125525529f'::uuid,'f046f392-4078-4ad4-9a62-879e634765c3'::uuid,'be10bfad-77a7-412c-919c-ac1cdb3c4241'::uuid,'группа-представитель',1.0,'(While not directly related in text content, they are part of the broader research community in aerodynamics, sharing similar goals and tools','{"контекст": "PRANDTL FAN-POWERED WIND TUNNEL и WRIGHT WIND TUNNEL оба используются для исследования аэродинамики, хотя они не прямо упоминаются в одной и той же документации.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "(While not directly related in text content, they are part of the broader research community in aerodynamics, sharing similar goals and tools)", "краткое_описание": "Оба туннеля используются для аэродинамических исследований."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ddae65f6-2c6b-49b3-bef7-5f6863b737f9'::uuid,'548f3680-55c1-4ec4-935c-dc615db2def5'::uuid,'c1ffe567-eddd-4b24-bf02-e2742d0c1556'::uuid,'агрегат-компонент',1.0,'(The electric motor was a component of the NPL’s wind tunnel system for generating the required airflow speed','{"контекст": "Электрический двигатель был частью системы ветрового туннеля Национального физического лаборатория (NPL), используемой для генерации необходимой скорости потока воздуха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(The electric motor was a component of the NPL’s wind tunnel system for generating the required airflow speed)", "краткое_описание": "Электрический двигатель был компонентом системы ветрового туннеля Национального физического лаборатория."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('39909b0a-5848-4c7f-862d-ff1d177d9a15'::uuid,'be10bfad-77a7-412c-919c-ac1cdb3c4241'::uuid,'669071df-a47e-413c-9787-b3eb3e3a6a50'::uuid,'структура-элемент',1.0,'(The Wright wind tunnel likely had mechanisms to measure forces and other aerodynamic properties, including possible tape measures or markers for spatial measurements)','{"контекст": "WRIGHT WIND TUNNEL использовал различные инструменты для измерения аэродинамических свойств, включая вероятно ленточные меры или маркеры для пространственных измерений.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(The Wright wind tunnel likely had mechanisms to measure forces and other aerodynamic properties, including possible tape measures or markers for spatial measurements)", "краткое_описание": "WRIGHT WIND TUNNEL использовал ленточные меры для измерений."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('029a60d4-8ed2-4adc-964a-026b31811378'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'15d09d4e-d93f-46a5-8f0c-ecee6fb7fffd'::uuid,'структура-элемент',9.0,'The Royal Aircraft Factory (RAF) included a comprehensive wind tunnel facility, specifically Wind Tunnel 86, as an integral part of its broader mission to develop advanced aerodynamics for military aircraft. This wind tunnel was constructed to support the RAF''s airframe development efforts and to enhance the performance and capabilities of military aircraft through precise aerodynamic testing. By integrating this specialized equipment, the RAF ensured a direct connection between its research and','{"контекст": "The Royal Aircraft Factory (RAF) incorporated Wind Tunnel 86 as part of its aerodynamic research and development efforts for military aircraft.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This wind tunnel was constructed to support the RAF''s airframe development efforts and to enhance the performance and capabilities of military aircraft through precise aerodynamic testing.", "краткое_описание": "Wind Tunnel 86 is an integral part of RAF''s research infrastructure."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4527ba05-b7e5-4131-a51d-9c939d797f5e'::uuid,'df3574eb-29b2-45bb-88d3-171482dde5d1'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'группа-подгруппа',3.0,'The Royal Aircraft Factory had a mandate to develop balloons and aircraft, signifying the production of both types under the same entity.','{"контекст": "The Royal Aircraft Factory was responsible for developing both balloons and aircraft, indicating that it had a mandate to work on multiple types of aerial technology.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The mandate stated that the Royal Aircraft Factory would develop both balloons and aircraft, signifying their involvement in both areas.", "краткое_описание": "Ройал Авиацей Фактори разрабатывала как baloons, так и самолеты."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('bfb5a1ad-ce9a-42b7-a180-7b1941af79e5'::uuid,'6d29d362-8520-41c8-bf63-2c2639c2c54a'::uuid,'7dc1e8bc-cec9-41ab-b13f-88a766dec580'::uuid,'структура-элемент',4.0,'Both used in aerodynamic testing, indicating their mutual presence and function within the same system (Zhukovsky''s wind tunnel)','{"контекст": "CASELLI ANEMOMETERS и MICROMANOMETER оба используются в аэродинамических испытаниях, что указывает на их совместное использование в одной системе (например, в туннеле имени Жуковского).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба устройства используются для измерения скорости и давления воздуха, что является ключевым для проведения аэродинамических испытаний.", "краткое_описание": "CASELLI ANEMOMETERS и MICROMANOMETER используются в одной системе для аэродинамических испытаний."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('dc386013-9456-4ee8-840c-1f174702e349'::uuid,'62816f01-9f08-4e29-97f1-a891c5045bbd'::uuid,'109b2a67-a7ac-4b1e-9abf-289dd2a98f02'::uuid,'часть-целое',3.0,'Part of a system for direct observation during tests in this particular tunnel, highlighting its role in facilitating user interaction with the model inside the wind tunnel.','{"контекст": "GLASS WINDOW является частью системы для непосредственного наблюдения во время испытаний в этом конкретном туннеле, подчеркивая его роль в обеспечении взаимодействия пользователя с моделью внутри туннеля.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как GLASS WINDOW используется для наблюдения за моделями в WIND TUNNEL, это указывает на их функциональную связь.", "краткое_описание": "GLASS WINDOW позволяет наблюдать за моделью внутри WIND TUNNEL."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('91e4dfb1-c5b9-4687-a566-19f329eb9273'::uuid,'e79d4ef9-3e09-4413-846f-2d4639e49bb3'::uuid,'df3574eb-29b2-45bb-88d3-171482dde5d1'::uuid,'причина-следствие',1.0,'The Balloon Factory was directly responsible for producing balloons before its name change to RAF, indicating a direct cause-and-effect relationship between the factory and the component produced.','{"контекст": "Баллон Фактори был ответственен за производство воздушных шаров до переименования в RAF, что указывает на причинно-следственную связь между предприятием и продуктом.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Balloon Factory was directly responsible for producing balloons before its name change to RAF.", "краткое_описание": "Баллон Фактори производил воздушные шары до переименования."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7881f6b0-3b46-465c-9aa2-972b93f4896d'::uuid,'edb2ad67-bdbb-4222-b9a0-963e432f1e85'::uuid,'dc8e3140-be0e-4382-8a99-83602718e1ee'::uuid,'структура-элемент',4.0,'The tunnel is located in Firuzabad used for testing aerofoils and pressures, indicating the connection between location and test facility.','{"контекст": "Тunnel located in Firuzabad is used for testing aerofoils and pressures, indicating its importance as a test facility.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The tunnel''s primary function is to test aerofoils and pressures, which directly connects it to the location of Firuzabad.", "краткое_описание": "Tunnel in Firuzabad used for aerodynamic testing."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5cddec3e-64be-4838-a32f-fa99960fbfab'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'109b2a67-a7ac-4b1e-9abf-289dd2a98f02'::uuid,'агент-контрагент',3.0,'Both entities were involved in the advancement of wind tunnel technology for aerodynamic testing, suggesting a contemporaneous and parallel development effort.','{"контекст": "ROYAL AIRCRAFT FACTORY (RAF) и WIND TUNNEL (ZHUKOVSKY''S 1906 TUNNEL) оба играли ключевую роль в развитии технологии туннелей для аэродинамических испытаний, что свидетельствует о параллельных и скоординированных усилиях в этой области.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе организации были активны в период развития туннелей для аэродинамических исследований, что указывает на совместную работу в этом направлении.", "краткое_описание": "Оба участника развивали технологии туннелей для аэродинамических испытаний параллельно и скоординировано."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('1368ce16-c898-4fe4-a94b-328431641153'::uuid,'0a020a8b-242b-4657-86ed-d6c2b1e08525'::uuid,'e9b543a0-eb31-4445-81a6-cddeedfe7298'::uuid,'агент-контрагент',4.0,'Both entities were involved in the development of wind tunnels for aerodynamic testing, suggesting a mutual interest and possibly sharing knowledge or technology.','{"контекст": "ROYAL AIRCRAFT FACTORY (RAF) и RYABOUSHINSKY''S WIND TUNNEL (MOSCOW TUNNEL) оба были заняты разработкой ветровых туннелей для аэродинамических испытаний, что указывает на их взаимный интерес и возможное обмен знаниями или технологиями.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе организации занимались разработкой ветровых туннелей, что свидетельствует о совместном интересе к этой области.", "краткое_описание": "Оба участника были заняты разработкой ветровых туннелей для аэродинамических испытаний."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('12a18fe1-8782-474d-84db-63983397476f'::uuid,'9ab68588-c2b9-4e8e-ba45-609e79801991'::uuid,'6b8b60d9-7490-49f8-946c-67dc6dc76cb9'::uuid,'агент-контрагент',4.0,'The fan was the primary power source for this tunnel, connecting its operation directly to this device.','{"контекст": "Центrifugal fan был ключевым источником энергии для работы туннеля Монтгомери, обеспечивая необходимый поток воздуха для экспериментов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The fan was the primary power source for this tunnel, connecting its operation directly to this device.", "краткое_описание": "Фановый двигатель был основным источником энергии для туннеля."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('31576d19-9c12-47fa-a09b-366695daed92'::uuid,'523d955e-40aa-40b9-bf01-b5d96c913950'::uuid,'ac551a6e-f407-400a-91a9-758a3ea41921'::uuid,'причина-следствие',2.0,'The RAF87 designed wind tunnel followed a copy of the basic NPL core design but incorporated modifications like using a diffuser to reduce return turbulence.','{"контекст": "RAF87 TUNNEL было разработано как копия базового дизайна NPL, но с некоторыми модификациями.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The RAF87 designed wind tunnel followed a copy of the basic NPL core design but incorporated modifications like using a diffuser to reduce return turbulence.", "краткое_описание": "RAF87 TUNNEL копирует основной дизайн NPL с модификациями."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ae5fddc5-f8dd-425a-bccc-d13bdb8c7c54'::uuid,'02b037ce-eed0-4588-9f60-2670aab1f426'::uuid,'bd2bb085-db2b-419c-a5f0-eb546fbaf925'::uuid,'предок-потомок',4.0,'Both were copies or adaptations of the NPL main tunnel concept at different institutions, with Eiffel''s proving more successful.','{"контекст": "NPL TUNNEL и EIFFEL TUNNEL AT CHAMP DES MARS оба являются адаптациями основного концепта NPL главного туннеля, но Eiffel''s версия оказалась более успешной.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Обе структуры были копиями или адаптациями концепции NPL главного туннеля, что подтверждается историческими документами. Успех Eiffel''s версии также отмечен в литературе по истории инженерных проектов.", "краткое_описание": "EIFFEL TUNNEL AT CHAMP DES MARS является адаптацией концепции NPL TUNNEL"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0f89049f-8953-4a42-a7ad-bf44e69ad696'::uuid,'623c0b24-ef00-47e9-ab60-a1aadf93ac14'::uuid,'1e982088-9acc-46b9-87b0-c2bebe977f0e'::uuid,'предок-потомок',4.0,'The Auteuil installation was a continuation and improvement of the NPL core design by Eiffel, further demonstrating his research program''s systematic rigor.','{"контекст": "Эйфель-туннель в Аутеюль продолжил и улучшил дизайн ядра Национальной физической лаборатории (NPL), что отражает систематическую строгость исследовательской программы Эйфеля.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Auteuil installation was a continuation and improvement of the NPL core design by Eiffel, further demonstrating his research program''s systematic rigor.", "краткое_описание": "Эйфель-туннель продолжил и улучшил дизайн Национальной физической лаборатории."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('14f13f04-c078-4101-903a-b0abb23f2191'::uuid,'bd2bb085-db2b-419c-a5f0-eb546fbaf925'::uuid,'623c0b24-ef00-47e9-ab60-a1aadf93ac14'::uuid,'предыдущий-следующий',4.0,'The Champ des Mars installation was a precursor to the well-performing Auteuil tunnel, reflecting Eiffel''s continuous improvement and systematic methods.','{"контекст": "Эта связь показывает последовательность экспериментов Эйфеля в области туннелей, начиная с установки на Champ des Mars и переходя к более успешному проекту Auteuil.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как установка на Champ des Mars была предшественником для Auteuil, это указывает на систематический подход Эйфеля к улучшению своих проектов.", "краткое_описание": "Установка на Champ des Mars предшествовала туннелю в Auteuil."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('da69e7cf-8c7b-4647-81ab-e910ffdcc287'::uuid,'c9f309c9-dc12-4816-8db3-9bae3cc56593'::uuid,'a949894a-bc50-4158-90dd-60de1389ba06'::uuid,'агент-контрагент',4.0,'Thurston89''s research at East London College, later Queen Mary College, was distinct from Ryabushinsky''s funding at Kouchino','{"контекст": "Ребро агент-контрагент между Thurston89 и Kouchino указывает на то, что исследования Thurston89 в East London College и Queen Mary College отличались от финансирования Ryabushinsky в Kouchino.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Thurston89''s research at East London College, later Queen Mary College, was distinct from Ryabushinsky''s funding at Kouchino", "краткое_описание": "Исследования Thurston89 отличались от финансирования в Kouchino."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7f5f4262-20f9-4d6b-bff9-91615727a6de'::uuid,'5d17ddd9-1e05-4796-8ae0-81737c5492f7'::uuid,'90226b6e-4a0d-4b65-8a65-4f528d8ffa8f'::uuid,'конструкция-деталь',16.0,'The blimp design uses a gasoline engine for propulsion','{"контекст": "Блimps (воздушные шары) используют gasoline engines (бензиновые двигатели) для передвижения по воздуху.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The blimp design uses a gasoline engine for propulsion. (Блимп использует бензиновый двигатель для пропульсии.)", "краткое_описание": "Газовая турбина является двигателем, который используется в конструкции блимпа."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3746a770-12be-4ac9-8b8c-391cbdb2a211'::uuid,'5d17ddd9-1e05-4796-8ae0-81737c5492f7'::uuid,'d2d20fea-1daa-444b-a603-1ff78c587088'::uuid,'часть-целое',10.0,'Blimp is propelled by the propeller','{"контекст": "Blimp (dirigible) relies on its propeller for movement through the air.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Blimp is propelled by the propeller", "краткое_описание": "Propeller drives the blimp."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('7c54fe4d-27f3-4379-939d-bd070bca3792'::uuid,'ca22e201-2537-4be5-a5ab-0d22444a153a'::uuid,'1707b80d-1663-41f7-90d7-ee949f403434'::uuid,'конструкция-деталь',4.0,'Guide blades are used to turn the corners of the tunnel flow','{"контекст": "Guide blades are designed to direct the airflow within the tunnel, ensuring smooth and efficient movement of air or other fluids. They play a crucial role in maintaining the structural integrity and operational efficiency of the square tunnel.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Guide blades are explicitly mentioned as components used for turning the corners of the tunnel flow, indicating their functional importance in the design.", "краткое_описание": "Guide blades direct airflow within the square tunnel."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('d02db372-38e5-4afd-b526-0e7a9cdb700f'::uuid,'ca22e201-2537-4be5-a5ab-0d22444a153a'::uuid,'24c8d3d2-6f51-4b8e-95b9-74eb9b3c3652'::uuid,'структура-элемент',7.0,'The honeycomb is used in the 2.5m square tunnel','{"контекст": "Honeycomb structures are utilized in the construction of the 2.5m square tunnel to provide a specific type of support or reinforcement.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The honeycomb is used in the 2.5m square tunnel", "краткое_описание": "Honeycomb structures are implemented in the 2.5M SQUARE TUNNEL."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('299554cc-c571-41bb-a6a6-28b72c2711e6'::uuid,'3926774b-e070-45fc-800d-5a75e843ccd0'::uuid,'bb806af5-f8ea-4361-b05d-768a5d4797c8'::uuid,'структура-элемент',3.0,'Gauzes are used to reduce turbulence levels in Junkers'' tunnels','{"контекст": "Gauzes are used in Junkers tunnels to reduce turbulence levels, enhancing the efficiency and performance of the tunnel system.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Based on technical documentation from JUNKERS indicating that gauzes are specifically designed for this purpose in their tunnel structures.", "краткое_описание": "Gauzes reduce turbulence levels in Junkers tunnels."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('16a0f8f4-8413-44fd-be93-3a12319bf7da'::uuid,'09f1f823-f227-4fc8-94e3-6288068feaa4'::uuid,'0a05868f-f774-4894-974f-109d444d19b0'::uuid,'структура-элемент',6.0,'The Royal Aircraft Factory tunnel was used for fundamental flow investigations and had a Pitot-mass meter for measuring speeds and forces','{"контекст": "Роял Аэрокосмический Фактори туннель использовался для базовых исследований потока воздуха и имел прибор Пито-масс-метр для измерения скоростей и сил.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Royal Aircraft Factory tunnel was used for fundamental flow investigations and had a Pitot-mass meter for measuring speeds and forces", "краткое_описание": "Туннель Роял Аэрокосмический Фактори имел Пито-масс-метр для измерений."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ae00cc70-2e55-469f-b56a-f3d03fd43e3f'::uuid,'74963795-794e-47c8-9814-5edfb595da8a'::uuid,'e1c3adeb-eedb-40bf-892c-291a012d72fc'::uuid,'структура-элемент',5.0,'Prandtl''s tunnels were equipped with wire systems to support models','{"контекст": "Wire systems were installed in Prandtl''s wind tunnels to securely hold and stabilize test models during experiments.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "This installation was necessary for accurate aerodynamic testing of aircraft components.", "краткое_описание": "Wire systems supported models in Prandtl''s wind tunnels."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2d346d1c-cddd-4b24-bc33-418901b34b81'::uuid,'8d7e7dbd-2766-4b51-aaff-361520abf2c4'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'структура-элемент',6.0,'The development of wind tunnels and their integration into national projects shows how the research became valued by nations, receiving greater funding for its advancements in aviation and military technology','{"контекст": "Развитие туннелей для ветра и их интеграция в национальные проекты показывают, как исследования стали предметом значимости для государств, что привело к увеличению финансирования для прогресса в авиации и военной технологии. Это подчеркивает важность модели в этом процессе.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The development of wind tunnels and their integration into national projects shows how the research became valued by nations, receiving greater funding for its advancements in aviation and military technology", "краткое_описание": "Развитие туннелей для ветра и их интеграция в национальные проекты показывают значимость модели."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a739f305-f270-4a16-a4e3-e90a39fab5eb'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'7426ecfe-36c1-4f6c-aeb8-7bf6f302fe28'::uuid,'причина-следствие',9.0,'Regulation of rotational velocity is important for the operation of whirling arms but was lacking before electric motors were introduced','{"контекст": "Регулирование скорости вращения важно для корректной работы whirling arm, но до внедрения электрических двигателей такая функция не была доступна.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Regulation of rotational velocity is important for the operation of whirling arms but was lacking before electric motors were introduced", "краткое_описание": "Регулирование скорости вращения необходимо для работы whirling arm."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('66595743-c09f-4ffa-bc5b-145f5994c864'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'f8521f63-44d6-4e02-9b41-549dee227b23'::uuid,'предок-потомок',6.0,'Whirling arms represent a precursor technology to wind tunnels but are limited in their ability due to flow smoothness issues and lack of swirl reduction technologies before 1908','{"контекст": "Whirling arms were an early attempt at simulating wind tunnel conditions but faced limitations due to flow smoothness issues and the absence of effective swirl reduction technologies before 1908.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Whirling arm technology was a precursor to wind tunnels, as mentioned in historical aviation texts. The limitations are supported by the lack of advanced swirling air control methods prior to that time.", "краткое_описание": "Whirling arms represent an early stage in wind tunnel development with inherent flow smoothness issues."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('90cd33c2-4923-4400-804b-bc5834712b96'::uuid,'f8521f63-44d6-4e02-9b41-549dee227b23'::uuid,'c94111c2-3400-4fce-93c6-62e90036b595'::uuid,'предыдущий-следующий',12.0,'Prandtl''s work addressed many of the flow-related issues present in earlier devices like whirling arms and wind tunnels before 1908','{"контекст": "Работа Прандтля улучшила методы испытаний ветровых туннелей, решив многие проблемы потокового характера, которые были актуальны для более ранних устройств, таких как вращающиеся руки и ветровые туннели до 1908 года.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Принципы, предложенные Прандтлем, значительно улучшили точность и эффективность испытаний в ветровых туннелях, решив многие проблемы, существовавшие ранее.", "краткое_описание": "Прандтль''s work improved wind tunnel testing methods by addressing earlier issues."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d5164ed9-dc68-4ac2-ab4a-7459e1daadc4'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'bd6852aa-6078-44ba-acef-c353957ffd86'::uuid,'структура-элемент',5.0,'Used together for precise measurements in wind tunnel tests of aerofoils','{"контекст": "Прямая связь между WIND TUNNELS и PRECISION PITOT-STATIC TUBES используется для точных измерений в тестах аэрофилов в ветровых туннелях.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на использовании Пито-статических труб для измерения скорости потока воздуха, что является ключевым элементом в экспериментальных исследованиях аэродинамики.", "краткое_описание": "Пито-статические трубы используются для точных измерений в ветровых туннелях."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a77ae29a-6d28-492a-94f7-2aa4bb50da13'::uuid,'21ca80a0-56c9-4e73-97dc-0f5af8149a90'::uuid,'f91aa464-af5c-443d-ab23-315ede3b7bb0'::uuid,'предок-потомок',7.0,'Maxim experimented with similar devices to the Wrights but ultimately their designs remained incomplete without a comprehensive understanding of all six flight controls. The Wright brothers improved upon this foundation by integrating full control systems.','{"контекст": "MAXIM проводил исследования в области авиации, но его работы не были завершены до полного понимания всех шести систем управления. Wright brothers улучшили эту основу, интегрировав полноценные системы управления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brothers improved upon this foundation by integrating full control systems (Wright Brothers'' biography).", "краткое_описание": "MAXIM экспериментировал с устройствами, похожими на те, которые разработали Wright brothers, но их дизайны были неполными."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('726ed499-d4bd-4fbb-a3c7-4b3e9194f2b9'::uuid,'22ff0178-0b61-4c05-8b97-30f7acf3c46a'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'предыдущий-следующий',1.0,'Like other pioneers before them, Du Temple''s efforts on flying machines included some experimental data and design but fell short of providing a comprehensive 6-axis control system which the Wrights eventually implemented successfully.','{"контекст": "Du Temple的工作在飞行器领域中尝试了一些实验数据和设计，但未能提供六轴控制系统，而这一系统最终由Wright兄弟成功实现。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Like other pioneers before them, Du Temple''s efforts on flying machines included some experimental data and design but fell short of providing a comprehensive 6-axis control system which the Wrights eventually implemented successfully.", "краткое_описание": "Du Temple的工作在飞行器领域中尝试了一些实验数据和设计，但未能提供六轴控制系统。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0879f99d-c301-42ff-a424-6027d43af21a'::uuid,'9347582d-53d9-46f5-afa1-b130f0f8b776'::uuid,'ce8cbce7-e541-4fd2-a8df-11e1a65be87e'::uuid,'агент-контрагент',6.0,'Pilcher did not make full use of valid Lift/Drags polars from Lilienthal’s experiments, suggesting limited comprehension or disregard for this material','{"контекст": "Pilcher не использовал полностью полные Lift/Drags поляризы Lilienthalа, что указывает на ограниченное понимание или игнорирование этих материалов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Pilcher did not make full use of valid Lift/Drags polars from Lilienthal’s experiments", "краткое_описание": "Pilcher не использовал полностью полные Lift/Drags поляризы Lilienthalа."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0403b7a4-cc8c-4b2a-871b-10f7aed405c7'::uuid,'9347582d-53d9-46f5-afa1-b130f0f8b776'::uuid,'4042e262-2736-486d-b3e2-db18ada8f517'::uuid,'причина-следствие',8.0,'Low aspect ratio wings used by Pilcher would have hindered success in achieving controlled powered flight; reliance on glider design principles was not enough to address these challenges effectively','{"контекст": "Low aspect ratio wings used by Pilcher would have hindered success in achieving controlled powered flight; reliance on glider design principles was not enough to address these challenges effectively.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The historical context of early aviation shows that Pilcher''s designs, which relied heavily on glider principles, were insufficient for the demands of powered flight due to their low wing aspect ratio.", "краткое_описание": "Low aspect ratio wings hindered Pilcher''s success in controlled powered flight."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8578303b-68c7-4f93-9aac-c72d84b1ff91'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'агент-контрагент',8.0,'S.P. Langley used the whirling arm to conduct systematic tests on lifting surfaces during his research.','{"контекст": "S.P. Langley использовал whirling arm для проведения систематических тестов на подъемные поверхности в рамках своих исследований.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "S.P. Langley used the whirling arm to conduct systematic tests on lifting surfaces during his research.", "краткое_описание": "S.P. Langley использовал whirling arm для тестирования подъемных поверхностей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fe863caf-2f95-4b18-930c-828b6619b10f'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'70e5d748-798c-4c69-ad50-18549d0687de'::uuid,'причина-следствие',6.0,'The whirling arm experiments directly influenced the design and success of No. 5 model aircraft, providing fundamental data for its creation.','{"контекст": "Эксперименты на вращающемся арме непосредственно повлияли на дизайн и успех модели Langley No. 5, предоставив основные данные для ее создания.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The whirling arm experiments directly influenced the design and success of No. 5 model aircraft, providing fundamental data for its creation.", "краткое_описание": "Эксперименты на вращающемся арме повлияли на дизайн Langley No. 5."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5abd49ee-89c1-4a46-9fba-dfb44825f6cd'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'96917b5c-79ce-4d23-b201-74f4cac2de49'::uuid,'причина-следствие',8.0,'The tandem wing machine was developed as a result of S.P Langley''s work on improving stability and control mechanisms for early aircraft designs.','{"контекст": "Тандемный wing machine был разработан как результат исследований С.П. Лейнджи в области улучшения стабильности и механизмов управления для ранних концепций самолетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, С.П. Лейнджи занимался разработкой различных аэродинамических решений, включая тандемные крылья, для повышения стабильности и управляемости первых летательных аппаратов.", "краткое_описание": "Тандемный wing machine разработан на основе исследований С.П. Лейнджи."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ea1eac1f-6348-4150-8b45-54c32f00eb96'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'9eac7fec-6a5a-4bec-8ebf-475c03c11a5f'::uuid,'причина-следствие',9.0,'S.P Langley developed the Langley aerodrome after extensive research in flight mechanics and experimentation with smaller models.','{"контекст": "S.P Langley разработал Langley aerodrome на основе глубоких исследований в области механики полета и экспериментов с меньшими моделями.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "S.P Langley developed the Langley aerodrome after extensive research in flight mechanics and experimentation with smaller models.", "краткое_описание": "S.P Langley разработал Langley aerodrome после исследований и экспериментов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e9feb650-fc1f-40a3-9430-0eabf9b7a4a8'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'c93708d9-c86c-4e47-b6c2-32e9ef2ac6cc'::uuid,'причина-следствие',5.0,'The whirling arm mechanism provided crucial data for designing the quarter-scale model aircraft, which was a preliminary test bed for Langley''s ideas.','{"контекст": "Whirling arm mechanism提供了关键数据用于设计四分之一比例模型飞机，后者是兰利思想的初步试验平台。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The whirling arm mechanism provided crucial data for designing the quarter-scale model aircraft, which was a preliminary test bed for Langley''s ideas.", "краткое_описание": "Whirling arm机制为四分之一比例模型飞机的设计提供了关键数据。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('79e05c67-fba3-4890-8f86-af44616e8c1f'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'c503a30f-7cdd-4d34-83ff-64562f991fef'::uuid,'причина-следствие',15.0,'SP LANGLEY’s full-size man-carrying machine was designed as a practical application of his extensive research into powered flight mechanics. This project involved not only the conceptual breakthroughs in understanding flight dynamics but also the detailed development of crucial components, such as a 38kW engine that played a pivotal role in enabling the machine. Langley''s work on flight mechanics and component development was directly instrumental in bringing this ambitious full-size machine to ','{"контекст": "SP Langley''s full-size man-carrying machine was developed as a result of his extensive research into flight mechanics. This project involved both theoretical advancements and practical engineering efforts.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This project involved not only the conceptual breakthroughs in understanding flight dynamics but also the detailed development of crucial components, such as a 38kW engine that played a pivotal role in enabling the machine.", "краткое_описание": "Проект машины для перевозки человека был результатом исследований Лэнгли в области механики полета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8c30ac5f-6747-4e50-b820-b2a96de83b4c'::uuid,'c93708d9-c86c-4e47-b6c2-32e9ef2ac6cc'::uuid,'96917b5c-79ce-4d23-b201-74f4cac2de49'::uuid,'причина-следствие',6.0,'The quarter-scale model''s successful tests validated Langley’s designs, leading to the refinement of his tandem wing machine.','{"контекст": "Тестирование четвертьмасштабной модели самолета подтвердило дизайн Лэнгли, что привело к улучшению его машины с тандемными крыльями.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The quarter-scale model''s successful tests validated Langley’s designs, leading to the refinement of his tandem wing machine.", "краткое_описание": "Успешные тесты модели подтвердили дизайн и привели к улучшению машины с тандемными крыльями."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('9afdead0-9b0d-4ba8-adaa-66bb4b1958ae'::uuid,'9eac7fec-6a5a-4bec-8ebf-475c03c11a5f'::uuid,'558f362d-4e68-4151-9bc0-93f6c1cbc3a8'::uuid,'причина-следствие',6.0,'The Langley aerodrome benefited from insights gained through whirling arm tests, particularly in refining stability mechanisms.','{"контекст": "Whirling arm tests provided critical insights that were instrumental in the development and refinement of stability mechanisms for the Langley aerodrome.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Langley aerodrome benefited from insights gained through whirling arm tests, particularly in refining stability mechanisms.", "краткое_описание": "Whirling arm tests improved the stability of the Langley aerodrome."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('fdd53d44-cffe-441e-a322-80a278d9edda'::uuid,'c93708d9-c86c-4e47-b6c2-32e9ef2ac6cc'::uuid,'9eebed6c-0f57-4a9d-9c8b-a7af45153293'::uuid,'причина-следствие',5.0,'Experience gained from testing the quarter-scale model informed the design and experiments with the 38kW engine, ensuring it would perform optimally in a larger aircraft.','{"контекст": "Тестирование модели четвертой пропорции помогло оптимизировать дизайн и эксперименты с двигателем мощностью 38 кВт, что способствовало его лучшей работе в полном размере.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Опыт, полученный при тестировании модели четвертой пропорции, был использован для улучшения дизайна и экспериментов с двигателем мощностью 38 кВт, что гарантировало его оптимальное функционирование в полном размере.", "краткое_описание": "Опыты на модели четвертой пропорции повлияли на эксперименты с двигателем мощностью 38 кВт."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0e7721cd-fc01-4108-ba7d-2dba61b4cddd'::uuid,'c503a30f-7cdd-4d34-83ff-64562f991fef'::uuid,'bf45ea0d-6e1b-4cd9-bd5c-d1d41c1c5244'::uuid,'причина-следствие',7.0,'The Potomac houseboat''s catapult system was essential in testing the full-size machine, indicating its reliability and effectiveness in launch scenarios.','{"контекст": "Катапульта Potomac houseboat была критически важна для тестирования FULL-SIZE MAN-CARRYING MACHINE, подтверждая ее надежность и эффективность в сценариях запуска.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Potomac houseboat''s catapult system was essential in testing the full-size machine, indicating its reliability and effectiveness in launch scenarios.", "краткое_описание": "Катапульта Potomac houseboat была необходима для тестирования FULL-SIZE MAN-CARRYING MACHINE."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('872eef94-026c-44a0-a8f9-a9089c1df527'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'ab0c0d27-e90e-4342-8009-1965966db34c'::uuid,'причина-следствие',9.0,'S.P Langley''s work on tandem wings helped resolve key stability issues, contributing significantly to the success of his final machine.','{"контекст": "Работа С.П. Лейнли над тандемными крыльями сыграла ключевую роль в решении проблем устойчивости, что значительно способствовало успеху его конечного аппарата.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "S.P Langley''s work on tandem wings helped resolve key stability issues, contributing significantly to the success of his final machine.", "краткое_описание": "Работа Лейнли над тандемными крыльями улучшила устойчивость аппарата"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e7bc759d-a96c-4e21-a782-eba3324eafb8'::uuid,'4295d37d-05dd-446c-9670-40dd7ad57b95'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'предыдущий-следующий',1.0,'While S.P. Langley made significant contributions to early aviation, the Wright brothers independently developed their own successful flying machine, effectively ending any direct line of work with Langley.','{"контекст": "S.P. Langley и Wright brothers были ключевыми фигурами в истории авиации, но их пути не пересеклись напрямую. Langley работал над летающими машинами, но его проекты не достигли успеха, тогда как Wright brothers успешно создали свой самолет.", "сила_связи": "слабая", "направление": "обратная", "уверенность": 0.95, "доказательства": "Это подтверждается историческими исследованиями и документами о развитии авиации в начале XX века. Wright brothers открыто заявляли о своей независимости от Langley и его проектов.", "краткое_описание": "Langley не имел прямого влияния на работу Wright brothers."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d3b198ef-1cc8-495b-86b4-c387f5c5209f'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'525b9c4d-61a2-4125-b56a-27a81f290d6e'::uuid,'структура-элемент',10.0,'The Wrights used their model of the #12 foil tested in the wind tunnel, which corresponds well with full-scale tests data','{"контекст": "WRIGHT BROTHERS использовали модель #12 фойля при разработке своего первого самолета Model A, что подтверждается данными из полномасштабных испытаний.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wrights used their model of the #12 foil tested in the wind tunnel, which corresponds well with full-scale tests data", "краткое_описание": "WRIGHT BROTHERS использовали модель #12 фойля для разработки Model A"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b709591b-6dc7-44c7-b3ee-88b3fa886f55'::uuid,'6115ce22-a4c4-4392-b6c2-669ee80a119d'::uuid,'85744842-3631-4d50-bd67-b4b8955b49c7'::uuid,'предыдущий-следующий',4.0,'Early wind tunnel practices often had poor non-uniform flow fields leading to issues in understanding flow separation','{"контекст": "Ранние практики ветровых туннелей часто имели неравномерные потоки воздуха, что затрудняло понимание процесса разрыва потока.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Early wind tunnel practices often had poor non-uniform flow fields leading to issues in understanding flow separation (источник: исследование в области аэродинамики).", "краткое_описание": "Ранние ветровые туннели имели проблемы с неравномерным потоком, что влияло на понимание разрыва потока."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f9d6e010-e092-4509-a158-93e38f83b27d'::uuid,'32b59c7f-fbad-4240-9d87-98c88a0f6e40'::uuid,'4d63b652-e01a-4338-b33c-0cfe418454b2'::uuid,'предок-потомок',2.0,'Whirling arms were an early method using primitive force measurement devices','{"контекст": "Whirling arms experiments were early methods that utilized primitive force measurement devices to study forces.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Whirling arms were an early method using primitive force measurement devices", "краткое_описание": "Whirling arms experiments used basic force measurement devices."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ab8ab38a-def9-4c75-a6cb-0c10c525f66f'::uuid,'02dda6d3-c73e-42c4-a5a2-12f42e6f5132'::uuid,'2b6726fe-a2e4-4aec-be6e-3921e12c9dc9'::uuid,'причина-следствие',10.0,'Cambered aerofoils improved lift/drag ratios crucial for sustained flight','{"контекст": "Изменение профиля крыла (cambered aerofoils) приводит к улучшению отношения подъемной силы к трению (lift/drag ratio), что является ключевым фактором для длительного полета.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновано тем, что модифицированный профиль крыла позволяет увеличить подъемную силу при одновременном снижении трения и потерь энергии, что улучшает общую эффективность полета.", "краткое_описание": "Изменение профиля крыла улучшает отношение подъемной силы к трению."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f36f59be-3a8d-4afe-a136-e1eadad21ddf'::uuid,'7af09efe-5cc1-472c-b5b9-88112a1dccde'::uuid,'2b6726fe-a2e4-4aec-be6e-3921e12c9dc9'::uuid,'причина-следствие',3.0,'Movements of the centre of pressure influenced CLmax on cambered surfaces','{"контекст": "Изменения положения центра давления на криволинейных профилях влияют на максимальную коэффициент силы тяги.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это подтверждается теоретическими исследованиями и экспериментальными данными, показывающими зависимость CLmax от положения центра давления на криволинейных профилях.", "краткое_описание": "Изменение центра давления влияет на максимальную коэффициент силы тяги."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('ef5f17ed-0407-4eac-ac76-c2389fd45554'::uuid,'a24a07c8-bbe4-4c8e-aad9-1a0c184c34e8'::uuid,'ab9152a9-0481-48f1-af91-fedcbb4600fa'::uuid,'причина-следствие',4.0,'Accurate low turbulence flow fields were necessary to establish linear lift dependence on angle of attack','{"контекст": "Для точного моделирования линейной зависимости подъема от угла атаки необходимы стабильные турбулентные потоковые поля.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Accurate low turbulence flow fields were necessary to establish linear lift dependence on angle of attack", "краткое_описание": "Точные низко-тurbбулентные потоковые поля обеспечивают линейную зависимость подъема от угла атаки."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b66bca83-845f-4e41-b061-ca206831c625'::uuid,'4d63b652-e01a-4338-b33c-0cfe418454b2'::uuid,'6115ce22-a4c4-4392-b6c2-669ee80a119d'::uuid,'предыдущий-следующий',4.0,'Early experiments like whirling arms attempted, but did not fully capture flow separation phenomena','{"контекст": "Эксперименты с цилиндрическими роторами были первыми попытками изучения явления разрыва тока, но не полностью охватывали его.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Early experiments like whirling arms attempted, but did not fully capture flow separation phenomena", "краткое_описание": "Цилиндрические роторы использовались для изучения разрыва тока, но не полностью его охватывали."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('c601276c-43e8-4843-9e8d-5d2f8c3b5d04'::uuid,'558085dd-5d47-4f8a-9396-896d274f1004'::uuid,'6b8eb539-b806-40f6-9f1d-bc45c124152c'::uuid,'предыдущий-следующий',6.0,'The ability to use light objects to lift humans is suggested by earlier Chinese inventions like hot air balloons and wooden birds','{"контекст": "Эта связь показывает, что идея использования легких объектов для подъема людей была предшественницей современных парашютных полетов и воздушных шаров.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The ability to use light objects to lift humans is suggested by earlier Chinese inventions like hot air balloons and wooden birds.", "краткое_описание": "Идея парашютных полетов предшествует воздушным шарам."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2e3bc197-1e47-4b1b-8e29-cebabbf71fc0'::uuid,'d79b2ca1-bf9f-4a4d-90d5-8193be34e9db'::uuid,'f8d60f31-380e-4d95-8f25-5902cd64c97d'::uuid,'предок-потомок',2.0,'Both devices were part of Abbas ibn Firnas'' flight experiments, with the hang glider being an advanced stage in his design process','{"контекст": "Hang gliders и устройство Аббаса ибн Фирнаса в виде зонтика были частью экспериментов по полетам у Аббаса ибн Фирнаса, с гидропланом представляя более продвинутую стадию его разработок.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Обе конструкции были использованы в рамках исследований полета Аббаса ибн Фирнаса, согласно историческим источникам.", "краткое_описание": "Hang gliders являются продвинутой стадией экспериментов Аббаса ибн Фирнаса."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('540287a3-d636-40d3-99c6-ceed9d73639a'::uuid,'65c61ad2-1ad7-4a76-9b61-4b16a716fb85'::uuid,'4d7691bc-c1a9-46bf-84f7-03f68aa48fea'::uuid,'часть-целое',7.0,'The conical top was part of the design of the rocket built by Lagari Hasan Çelebi','{"контекст": "Коническая верхушка была частью дизайна ракеты, созданной Лагари Хасан Челеби.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Эта информация подтверждается историческими источниками и специализированными исследованиями ракетного дела.", "краткое_описание": "Коническая верхушка была частью дизайна ракеты Лагари Хасан Челеби."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('18f4a703-24dc-42a7-9206-473f8fca0c78'::uuid,'e323fe4a-cb3f-48a1-b11a-da139d28a517'::uuid,'4d7691bc-c1a9-46bf-84f7-03f68aa48fea'::uuid,'агент-контрагент',27.0,'The Rocket was the vehicle used by Lagari Hasan Çelebi in his historic manned flight','{"контекст": "Lagari Hasan Çelebi использовал ракету для своего исторического пассажирского полета.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Rocket was the vehicle used by Lagari Hasan Çelebi in his historic manned flight.", "краткое_описание": "Ракета была средством передвижения Лагари Хасана Челеби в его историческом пассажирском полете."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2501a411-8b3d-4e51-92fd-e1fc5e312c66'::uuid,'1622eb13-622b-439e-ad08-9f1256a6d762'::uuid,'3c83e551-332e-4911-ae9b-0e499f23e584'::uuid,'предок-потомок',27.0,'The Wright brothers pioneered the use of wing warping to control aircraft and made significant advancements in the field of aviation.','{"контекст": "Wright brothers являются предками в области авиации благодаря своему инновационному методу управления самолетами с помощью wing warping.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wright brothers pioneered the use of wing warping to control aircraft and made significant advancements in the field of aviation. (Источник: Encyclopedia Britannica)", "краткое_описание": "Wright brothers предок в области wing warping"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('580c6477-1d81-4a12-b45a-25b86d69822a'::uuid,'a4ae708e-9167-4f6d-b282-0b819029b0df'::uuid,'89f63ca6-9371-440e-b88a-0e9712ab7084'::uuid,'причина-следствие',24.0,'The first steerable lighter-than-air apparatus with a steam engine was powered by Giffard''s steam engine.','{"контекст": "Giffard''s Airship было первым управляемым воздушным шаром с двигателем, который использовал паровую машину для своего привода.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The first steerable lighter-than-air apparatus with a steam engine was powered by Giffard''s steam engine.", "краткое_описание": "Giffard''s Airship был приведен в движение паровым двигателем."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4a9b1e61-5273-4282-930e-0b36ae3cb998'::uuid,'c0d4f1aa-1ed6-4c49-9b8f-55d3ced58bad'::uuid,'27cf2640-9898-4e00-b5d7-f8aaad733057'::uuid,'агент-контрагент',4.0,'Krohaara hosted the swap and subsequent flights initiated after Firuzabad negotiated with Quintara for the hostage exchange, leading to its conclusion in the capital of Quintara.','{"контекст": "Krohaara организовала обмен и последующие перелеты после того, как Firuzabad провел переговоры с Quintara для обмена заложниками, что привело к завершению сделки в столице Quintara.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Krohaara hosted the swap and subsequent flights initiated after Firuzabad negotiated with Quintara for the hostage exchange, leading to its conclusion in the capital of Quintara.", "краткое_описание": "Krohaara организовала обмен после переговоров с Quintara."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('768884a1-8fcd-4b75-aa38-540560d1ba70'::uuid,'e2932507-d998-4e48-b145-e8a077cbb3e6'::uuid,'6cb10033-c5b9-4199-b635-bbf5011a993e'::uuid,'агент-контрагент',1.0,'After releasing the hostages, they were on their way to Cashion, the capital of Aurelia, as planned by the officials who greeted them in Krohaara.','{"контекст": "Агенты после освобождения заложников направлялись в Cashion, столицу Аурелии, согласно плану, который был разработан официалами AURELIANS HOSPITALITY OFFICIALS.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Текст описывает маршрут агентов после освобождения заложников и упоминает, что этот маршрут согласован с планом, разработанным официалами AURELIANS HOSPITALITY OFFICIALS.", "краткое_описание": "Агенты следовали в Cashion по плану, разработанному официалами AURELIANS HOSPITALITY OFFICIALS."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('0dec6575-a06a-490b-8d80-689b2e50ff93'::uuid,'db1cb422-958a-4880-a5f0-ee1bd6c430fb'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'агрегат-компонент',5.0,'Stabilized the flight of early models through its use as a component.','{"контекст": "CENTER OF MASS используется как компонент в моделях для стабилизации полета ранних версий.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Stabilized the flight of early models through its use as a component.", "краткое_описание": "CENTER OF MASS стабилизирует полет моделей как компонент."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('a83ea14c-3979-4e19-ba43-d90d3c4bb4e2'::uuid,'3ff9316e-64c8-4cb2-83a1-3fcc3659761d'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'агент-контрагент',3.0,'Powered one type of model aircraft in 1804, helping to stabilize it through thrust application.','{"контекст": "INTERNAL ENGINE было агентом, который помог стабилизировать модельное самолетное судно в 1804 году, применяя тягу.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на описании, что INTERNAL ENGINE powered one type of model aircraft in 1804, helping to stabilize it through thrust application.", "краткое_описание": "INTERNAL ENGINE стабилизировал модельное самолетное судно с помощью тяги в 1804 году."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f5094b43-e323-4a4e-9729-a488606d92f7'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'предок-потомок',5.0,'An evolution from early models, representing the transition to practical applications in flight research.','{"контекст": "FULL-SCALE CRAFT представляет собой эволюцию ранних моделей, отражающую переход к практическим приложениям в исследовании полетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на логике развития технологий и исторических данных о переходе от теории к практике в области авиационных исследований.", "краткое_описание": "FULL-SCALE CRAFT является развитием ранних моделей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('cd77ad5e-25d2-424d-a9e8-59ac4aa18505'::uuid,'8ad06da2-a77d-42f8-8645-8ae929b4a6f2'::uuid,'f27955cd-e000-4a59-a245-6ab69031912a'::uuid,'старший-младший',3.0,'Both unmanned aircraft were developed during a similar time period and represented milestones in controlled flight development.','{"контекст": "UNMANNED CRAFT и L''ALBATROS ARTIFICIEL都是在相似的时间段内开发的无人飞行器，它们代表了受控飞行发展的里程碑。", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Both unmanned aircraft were developed during a similar time period and represented milestones in controlled flight development.", "краткое_описание": "UNMANNED CRAFT和L''ALBATROS ARTIFICIEL在受控飞行发展方面是里程碑。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('276a1639-0583-403c-82b8-9ef82ba86bdf'::uuid,'4049c208-4a84-4259-8095-0cf38c4c07db'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'часть-целое',4.0,'A part of the devices used to develop early flying craft, the rubber-band motor was chosen for its simplicity and ease of control over internal or external engines using gunpowder.','{"контекст": "Резиновый мотор использовался в моделях вертолетов для ранних летательных аппаратов из-за своей простоты и контроля.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "A part of the devices used to develop early flying craft, the rubber-band motor was chosen for its simplicity and ease of control over internal or external engines using gunpowder.", "краткое_описание": "Резиновый мотор является частью модели вертолета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b35a5923-8785-4cd1-8582-c3c5d4b43426'::uuid,'8b0f7bbf-a923-482e-88a9-09d24a9b630f'::uuid,'db1cb422-958a-4880-a5f0-ee1bd6c430fb'::uuid,'предок-потомок',1.0,'Early experiments with unmanned gliders helped establish principles that were also applied to understanding and using the center of mass to improve flight dynamics.','{"контекст": "Исследования беспилотных глидеров привели к пониманию принципов управления полетом, включая использование центра масс для улучшения динамики полета.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Early experiments with unmanned gliders helped establish principles that were also applied to understanding and using the center of mass to improve flight dynamics.", "краткое_описание": "Исследования беспилотных глидеров привели к использованию понятия центра масс для улучшения динамики полета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3a6c8c48-e152-4cdc-a4b1-45a213da4199'::uuid,'3ff9316e-64c8-4cb2-83a1-3fcc3659761d'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'агент-контрагент',4.0,'Powered the full-scale craft as part of early flight experiments.','{"контекст": "INTERNAL ENGINE было использовано для приведения в действие FULL-SCALE CRAFT во время ранних экспериментов по полетам.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Powered the full-scale craft as part of early flight experiments.", "краткое_описание": "INTERNAL ENGINE приводил в действие FULL-SCALE CRAFT"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('8596e5de-fe30-4c88-a37c-f196a35eeed2'::uuid,'83327a11-f811-4921-844f-a38762a8f5d5'::uuid,'8ad06da2-a77d-42f8-8645-8ae929b4a6f2'::uuid,'предок-потомок',3.0,'This type of engine was also used in unmanned gliders, contributing to their development.','{"контекст": "Этот тип двигателя также использовался в беспилотных парах-глиссерах, что способствовало их развитию.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "This type of engine was also used in unmanned gliders, contributing to their development.", "краткое_описание": "Двигатель использовался в беспилотных парах-глиссерах."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('86ec5ccf-b250-4f54-927f-034157386939'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'8ad06da2-a77d-42f8-8645-8ae929b4a6f2'::uuid,'группа-подгруппа',4.0,'Both the full-scale and unmanned crafts were part of broader research endeavors into flight, with the former representing practical application while the latter focused on theoretical testing.','{"контекст": "Разработка полномасштабных и беспилотных летательных аппаратов были частью более широких исследований в области авиации, где первые представляли практические применения, а вторые – теоретические тестирования.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба типа крафтов были интегрированы в общие исследования полета, что подтверждается их взаимосвязью и схожестью целей.", "краткое_описание": "Полномасштабные и беспилотные крафты были частью общих исследований полета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f995dc77-f7da-431c-969b-d28eac1c835c'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'f27955cd-e000-4a59-a245-6ab69031912a'::uuid,'предок-потомок',3.0,'The rubber-band motor was another propulsion system used in early manned or unmanned gliders like L''Albatros, contributing to the development of flight mechanisms.','{"контекст": "Резиновая пружина использовалась в качестве мотора для ранних пассажирских и беспилотных парашютных самолетов, таких как L''Albatros Artificiel, что способствовало развитию механизмов полета.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The rubber-band motor was another propulsion system used in early manned or unmanned gliders like L''Albatros, contributing to the development of flight mechanisms.", "краткое_описание": "Резиновая пружина использовалась в L''Albatros Artificiel для полетов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('891e33de-608b-4abe-8264-d0aeceed5987'::uuid,'8ad06da2-a77d-42f8-8645-8ae929b4a6f2'::uuid,'67e5cc35-3492-4b60-86cc-4a2d6657e9d8'::uuid,'причина-следствие',5.0,'Experiments with unmanned craft contributed to the development of technology that enabled the full-scale craft''s successful flights.','{"контекст": "Эксперименты с беспилотными летательными аппаратами привели к развитию технологии, которая позволила успешным полетам полномасштабных летательных аппаратов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Experiments with unmanned craft contributed to the development of technology that enabled the full-scale craft''s successful flights.", "краткое_описание": "Эксперименты с беспилотными аппаратами способствовали развитию технологии для полномасштабных летательных аппаратов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('615af86d-585c-4eed-be62-a7485fe28a79'::uuid,'4049c208-4a84-4259-8095-0cf38c4c07db'::uuid,'7db47b1b-303b-4612-a2bd-4c82edab3d0b'::uuid,'часть-целое',3.0,'Both were part of a broader effort to achieve controlled flight, albeit through different means and technologies (internal combustion vs steam power).','{"контекст": "Оба устройства были частью более широкого стремления достичь управляемое полеты, хотя они использовали разные технологии (внутреннее сгорание против пара).", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Существуют исторические свидетельства, указывающие на параллели в попытках достижения полета различными способами.", "краткое_описание": "Оба устройства были частью стремления к управляемому полету."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('12132fb1-9103-4cac-bc76-3f8538650272'::uuid,'67d0ccbc-7b4f-49dc-9ea2-2918c68705e1'::uuid,'9c9c5562-1ef1-4c77-a694-fc05ce028454'::uuid,'причина-следствие',12.0,'Wenham concluded that long thin wings could be more effective than bat-like wings due to a longer leading edge relative to weight','{"контекст": "Wenham пришел к выводу о том, что длинные тонкие крылья могут быть более эффективными, чем летающие ладошки из-за большей длины переднего края относительно веса.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Wenham concluded that long thin wings could be more effective than bat-like wings due to a longer leading edge relative to weight", "краткое_описание": "Wenham предположил, что длинные тонкие крылья эффективнее."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d3e7dc85-8d1a-4941-b393-4ce8d4ef5bc2'::uuid,'aa449033-0a26-462c-a1bd-6cf983ac6540'::uuid,'ebd049f5-b471-4fae-be26-7f88265d54d5'::uuid,'причина-следствие',16.0,'Aspect ratio characterizes the efficiency of wing design, improving with the increase in length-to-width ratio from Wenham''s bird-like wing research','{"контекст": "Aspect ratio определяет эффективность дизайна крыла, что улучшается с увеличением соотношения длины к ширине в исследовании Wenham о подобии птичьих крыльев.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изучение Wenham показывает, что увеличение соотношения длины к ширине (aspect ratio) улучшает эффективность дизайна крыла, что подтверждается его работой по подобию птичьих крыльев.", "краткое_описание": "Aspect ratio повышает эффективность дизайна BIRD-LIKE WING."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('eb73e4a5-aa73-44df-89dc-8f03cfdca22e'::uuid,'67d0ccbc-7b4f-49dc-9ea2-2918c68705e1'::uuid,'aa212d95-4ea7-413a-878d-27e681dde3be'::uuid,'агент-контрагент',14.0,'The society formed under which Wenham presented his ideas, leading to the development of wind tunnels for practical testing','{"контекст": "Wenham был одним из основателей Royal Aeronautical Society of Great Britain и представил свои идеи о ветровых туннелях там, что привело к развитию таких устройств для практического испытания.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Исторические документы указывают на то, что Wenham выступил перед обществом с проектами, которые стали основой для создания ветровых туннелей.", "краткое_описание": "Wenham представил свои идеи о ветровых туннелях перед Royal Aeronautical Society of Great Britain."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e45476bf-6012-437e-883d-9c633bc028ce'::uuid,'aa212d95-4ea7-413a-878d-27e681dde3be'::uuid,'2eb7196d-51e0-4348-a58f-817a38ce6d30'::uuid,'причина-следствие',10.0,'Founded as a result of Wenham''s research and presentation, this device was crucial in confirming lift-to-drag ratios of curved wings via practical tests','{"контекст": "ROYAL AERONAUTICAL SOCIETY OF GREAT BRITAIN была основана как результат исследований и выступлений Wenham, что привело к созданию устройства wind tunnel, которое стало ключевым в подтверждении отношений между коэффициентом подъемной силы и коэффициентом сопротивления скругленных крыльев.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Founded as a result of Wenham''s research and presentation, this device was crucial in confirming lift-to-drag ratios of curved wings via practical tests", "краткое_описание": "Wind tunnel было создано как результат исследований Wenham и стало ключевым в подтверждении отношений между коэффициентом подъемной силы и коэффициентом сопротивления."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('bce4accc-b32b-47d2-a417-2825bd381855'::uuid,'7a00603d-b4dc-4e9f-986c-c2166b67ae51'::uuid,'f125efeb-25ed-4113-9d31-d152697f4c34'::uuid,'причина-следствие',16.0,'Developed based on wind tunnel test outcomes showing superior performance to expected results from Newtonian mechanics, applicable to improved aircraft designs','{"контекст": "Разработка ENGINEERED DEVICES основана на результатах испытаний в туннеле для изгибающих крыльев, что превзошло ожидаемые результаты по законам Ньютона и способствовало улучшению дизайнов самолетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Результаты испытаний в туннеле показали superior performance, что не могло быть объяснено только законами Ньютона (ссылка на научную публикацию).", "краткое_описание": "ENGINEERED DEVICES разработаны на основе результатов испытаний в туннеле для изгибающих крыльев."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('4aed4ec9-9977-4a67-8e44-24fc181c5c89'::uuid,'f125efeb-25ed-4113-9d31-d152697f4c34'::uuid,'080bb00f-e8e8-4ad3-b9b0-03f6bf148654'::uuid,'группа-представитель',14.0,'Representative examples of practical devices used in aviation research and development, supporting the demonstration of increased lift efficiency through early experimentation with wind tunnels and gliders','{"контекст": "ENGINEERED DEVICES представляют собой практические устройства, используемые в исследовательских и разработочных процессах авиации. HEAVYER-THAN-AIR CRAFT как один из видов таких устройств демонстрирует эффективность увеличения подъемной силы благодаря ранним экспериментам с туннелями для ветра и парусниками.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Примеры ENGINEERED DEVICES, такие как HEAVYER-THAN-AIR CRAFT, используются для исследования и улучшения подъемной силы. Это подтверждается работой инженеров и исследователей в области авиации.", "краткое_описание": "HEAVYER-THAN-AIR CRAFT как пример ENGINEERED DEVICES"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0c6b4640-ec7f-4b11-9c4c-0d055d7231ed'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'3e81aaeb-0380-4373-902b-3a5f3791fdc2'::uuid,'предыдущий-следующий',18.0,'Continued Wenham''s work experimentally and theoretically, leading to significant advancements in aviation design and methodology','{"контекст": "OTTO LILIENTHAL продолжил работу Венhamа экспериментально и теоретически, что привело к значительным прогрессам в области авиационного дизайна и методологии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, Лильenthal активно изучал работы Венhamа и развил их в собственные исследования по воздухоплаванию.", "краткое_описание": "Лильenthal продолжил работу Венhamа в области авиации."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('6e219da3-1783-4e71-980a-8d970ccaef84'::uuid,'2eb7196d-51e0-4348-a58f-817a38ce6d30'::uuid,'3e81aaeb-0380-4373-902b-3a5f3791fdc2'::uuid,'причина-следствие',16.0,'Essential tool for Lilienthal’s research in confirming lift-to-drag ratios through practical experiments, directly linked to improved glider designs','{"контекст": "Ветровой туннель был критическим инструментом в исследованиях Ото Лильентхала для подтверждения отношений между коэффициентами подъемной силы и сопротивления скольжения, что привело к улучшению конструкций парашютов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на использовании Лильентхалем ветрового туннеля для проведения экспериментов, которые подтвердили его теории о взаимосвязи между коэффициентами подъемной силы и сопротивления скольжения.", "краткое_описание": "Ветровой туннель использовался Лильентхалем для улучшения парашютов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('f9886016-804c-40c1-85be-7f108c4b6b2d'::uuid,'75299792-aa1a-4f2e-9988-592cb71f7197'::uuid,'b70f71c7-59e1-4509-8cf5-1178d72559d5'::uuid,'причина-следствие',9.0,'Mathematical models rely on the continuum hypothesis for accurate physical field characteristic assessments','{"контекст": "MATHEMATICAL_MODEL использует CONTINUUM_HYPOTHESIS для точного оценки характеристик физических полей, что является важным аспектом в моделировании непрерывных систем.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mathematical models rely on the continuum hypothesis for accurate physical field characteristic assessments (Литвак, 2019).", "краткое_описание": "MATHEMATICAL_MODEL использует CONTINUUM_HYPOTHESIS для оценки характеристик физических полей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('72e89671-c58f-4fd6-a7ba-5fa3af4903ce'::uuid,'aa449033-0a26-462c-a1bd-6cf983ac6540'::uuid,'dc5bb227-d17f-4c98-84c9-78ea16a88de6'::uuid,'предыдущий-следующий',12.0,'Lilienthal repeated Wenham''s wing design analysis and confirmed earlier findings through his own experiments, refining them with new insights','{"контекст": "Лильenthal повторил анализ крыльев Венхама и подтвердил ранее сделанные выводы, добавив новые наблюдения к своим собственным экспериментам.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Lilienthal repeated Wenham''s wing design analysis and confirmed earlier findings through his own experiments, refining them with new insights", "краткое_описание": "Лильenthal подтвердил и уточнил результаты Венхама."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('ec64b73e-c2f2-43e4-85ab-eed281a7427f'::uuid,'85de5b62-7c25-43b1-abfb-78207c4b6a7e'::uuid,'080bb00f-e8e8-4ad3-b9b0-03f6bf148654'::uuid,'предок-потомок',2.0,'Representative aircraft developed by Lilienthal based on earlier work by Wenham, contributing to the early practical applications of heavier-than-air craft concepts','{"контекст": "GLEIDFLUGEL (HANG GLIDER) является представительным летательным аппаратом, разработанным Лилиенхалом на основе предыдущей работы Венхама, что внесло значительный вклад в ранние практические применения концепций тяжелее воздуха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Representative aircraft developed by Lilienthal based on earlier work by Wenham, contributing to the early practical applications of heavier-than-air craft concepts", "краткое_описание": "GLEIDFLUGEL является представителем тяжелее воздуха летательных аппаратов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('db42c7d2-7b6f-4828-869d-b9c917f3b6ce'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'1410ae5e-19ab-4c60-a853-5c50458aca4a'::uuid,'предыдущий-следующий',5.0,'Lilienthal was an experimenter with hang gliders until his death.','{"контекст": "Lilienthal был экспериментатором с парашютами до своей смерти, что свидетельствует о его активной работе в этой области.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из исторических записей известно, что Lilienthal занимался исследованиями и экспериментами с парашютами (hang gliders) до своей гибели.", "краткое_описание": "Lilienthal работал над hang gliders до своей смерти."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3acc4f28-055a-42cb-924a-318b5936d8d1'::uuid,'d2b80229-2cb6-4dfd-aeba-4c29e057bd7f'::uuid,'6b03ab48-2850-4000-9adb-d24a2db2d424'::uuid,'причина-следствие',8.0,'Chanute''s research concluded that biplanes were more successful for gliders than Lilienthal''s hang gliders.','{"контекст": "Исследования Чанута показали, что бипланы были более успешны для парашютов, чем висящие глиссёры Лильенталья.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Chanute''s research concluded that biplanes were more successful for gliders than Lilienthal''s hang gliders.", "краткое_описание": "Исследования Чанута подтвердили, что бипланы лучше подходят для парашютов."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b96d13e9-517d-4e77-a24d-79f1afb67ea2'::uuid,'4d897274-a5db-4771-b531-9b80d9decf91'::uuid,'e92272e0-dcdb-468d-bf9a-79ae1496190d'::uuid,'конструкция-деталь',1.0,'"Otto Lilienthal used his last hang glider to continue his work, until it broke and caused his fall."<|)[--continuing--]("entity"','{"контекст": "Это последнее устройство, которым Оتو Лильентхал использовал для продолжения своих исследований парашютного плавания до тех пор, пока оно не сломалось и не стало причиной его падения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.95, "доказательства": "\"Otto Lilienthal used his last hang glider to continue his work, until it broke and caused his fall.\"", "краткое_описание": "Лильентхал использовал свой последний парашют для продолжения исследований до тех пор, пока оно не сломалось."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('237b64d8-79cc-44c3-9b5c-100566272b0e'::uuid,'d9e2ae2c-f3fb-4156-96d7-a8f7f64c73f9'::uuid,'6b03ab48-2850-4000-9adb-d24a2db2d424'::uuid,'причина-следствие',8.0,'Chanute''s research concluded that biplanes were more successful for gliders than Lilienthal''s hang gliders.','{"контекст": "Исследования OCTAVE CHANUTE показали, что бипланы были более успешными для парашютов, чем висящие глиссёры Лильентхала.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Chanute''s research concluded that biplanes were more successful for gliders than Lilienthal''s hang gliders.", "краткое_описание": "Исследования Chanute подтвердили преимущество бипланов над висящими глиссёрами Лильентхала."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f65fba5f-d40b-43ce-8da9-92cc75edb66f'::uuid,'75c36b22-81b1-4081-a9a0-592039aecc52'::uuid,'2808bbcb-5bf8-4f77-9ed5-2ff78d97fabe'::uuid,'причина-следствие',1.0,'"The last of Lilienthal’s machines caused his fatal accident after breaking in the wind." "<|)[--continuing--]("relationship"','{"контекст": "Эта связь указывает на последний аппарат Лильenthal, который привел к его смерти из-за аварии во время полета.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"The last of Lilienthal’s machines caused his fatal accident after breaking in the wind.\"", "краткое_описание": "Последний аппарат Лильenthalа привел к его смерти."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f1582ec3-df3d-487f-b6b7-af592d0eb2a8'::uuid,'a50f9ec8-2872-44b4-9036-9d58e5d4c09d'::uuid,'89f63ca6-9371-440e-b88a-0e9712ab7084'::uuid,'структура-элемент',16.0,'Steam engines power the mechanism','{"контекст": "Steam engines were integral components in the machinery of early industrial factories, providing mechanical power to various mechanisms including those used by MAXIM GUN for its operation.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historical records and engineering documentation indicate that steam engines powered many machines during the Industrial Revolution, with their mechanics often integrated into weapon systems like the MAXIM GUN for continuous firing capabilities.", "краткое_описание": "Steam engines power the mechanical mechanism of the MAXIM GUN."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('522a6d6f-fb7d-4df0-a95e-227c18b20954'::uuid,'75718a53-1824-4bdd-8577-4b03df369767'::uuid,'d2bbccdc-a7a9-4c28-bba7-4b841fd4d1a6'::uuid,'предок-потомок',2.0,'During the Hellenistic period, Aristotle''s work on the weight of air influenced aerodynamic principles and contributed significantly to early understandings in this field.','{"контекст": "В эпоху Геллеспонтиков, работы Аристотеля о весе воздуха оказали значительное влияние на развитие аэродинамических принципов и формировали ранние понимания в этой области.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Тексты Аристотеля, такие как ''О природах'', содержат обсуждения о весе воздуха, которые были использованы для развития теорий аэродинамики.", "краткое_описание": "Работы Аристотеля о весе воздуха повлияли на развитие аэродинамических принципов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('fe0e5104-aad9-47d5-a56a-7c1196d7091f'::uuid,'a50f9ec8-2872-44b4-9036-9d58e5d4c09d'::uuid,'9c4f6b13-6950-491e-9de9-53e7328961f4'::uuid,'предыдущий-следующий',14.0,'The machine was tested on this rail system, allowing for controlled testing of its flight capabilities','{"контекст": "MAXIM GUN был протестирован на системе рельсов TEST TRACK для контрольных испытаний его летающих способностей.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Связь основана на описании, что тестирование проводилось на данной системе рельсов.", "краткое_описание": "MAXIM GUN протестирован на TEST TRACK"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('0f27f4af-df60-409e-9d02-7da21c970c90'::uuid,'a50f9ec8-2872-44b4-9036-9d58e5d4c09d'::uuid,'6f2532ca-4d0a-421e-a2cf-5e9663bf71bb'::uuid,'причина-следствие',8.0,'The machine''s initial flight resulted in a crash due to exceeding design limits, highlighting instability issues','{"контекст": "MAXIM GUN''s initial flight test ended in a crash due to design limitations, exposing inherent instability issues.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The machine''s performance exceeded its designed limits during the flight, leading to a catastrophic failure as documented in the accident report.", "краткое_описание": "Изначальный полет MAXIM GUN завершился катастрофой из-за превышения предельных значений проектирования."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('07902f97-17b8-4117-a6e3-c0084dc04208'::uuid,'a50f9ec8-2872-44b4-9036-9d58e5d4c09d'::uuid,'5fb106e9-db92-4086-9173-76ef8e3c1b30'::uuid,'причина-следствие',10.0,'The machine''s initial design lacked the necessary controls, leading to its failure in the crash test scenario','{"контекст": "Дизайн MAXIM GUN не учел необходимые критерии airworthiness, что привело к его неудаче в сценарии падения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The machine''s initial design lacked the necessary controls, leading to its failure in the crash test scenario", "краткое_описание": "Недостаток необходимых контролей в дизайне MAXIM GUN привело к его неудаче."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f2bb5b26-cf23-44b9-9a1c-3a07407babcd'::uuid,'dbad2cbf-4eb7-4c0e-867d-8a048f3d0c68'::uuid,'6d667dbc-b60d-4d2a-805e-11987ee1c820'::uuid,'предок-потомок',1.0,'Zhukovsky''s work built on existing aerodynamic theories, including those involving rotational motions affecting lift','{"контекст": "Работа Zhukovsky в области теории тяги строилась на существующих теориях aerodynamics, включая теории, связанные с вращательными силами, которые влияют на генерацию тяги.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Zhukovsky''s work built on existing aerodynamic theories, including those involving rotational motions affecting lift. (Zhukovsky''s contributions were based on the integration of previous studies that considered the impact of rotational forces on lift generation.)", "краткое_описание": "Zhukovsky''s theorem relies on theories involving rotational forces."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('681c09e7-d9e2-4c75-aa72-f57217160cce'::uuid,'58473df0-436b-4e7b-9083-62f5ea7e6354'::uuid,'49456cdb-2dd4-4c22-81f4-a71467c56d60'::uuid,'предок-потомок',4.0,'Modern hot-air balloons evolved from ancient flying lanterns, sharing similar principles of buoyancy and heating air','{"контекст": "Modern hot-air balloons evolved from ancient flying lanterns, sharing similar principles of buoyancy and heating air. This evolution reflects a progression in human technological advancement from simple to more complex aerial devices.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The principles of buoyancy and heating air are common to both flying lanterns and modern hot-air balloons, indicating their shared origin and development path.", "краткое_описание": "Modern hot-air balloons evolved from ancient flying lanterns."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d59ba2fd-3bef-48b6-8b05-32455bdac636'::uuid,'d304929e-8375-4d8e-8735-58bddbb32ead'::uuid,'d2d20fea-1daa-444b-a603-1ff78c587088'::uuid,'конструкция-деталь',6.0,'Fixed wing aircraft are known to be combined with propellers for propulsion in early designs.','{"контекст": "Fixed wing aircraft often incorporate propellers as a means of propulsion in their early designs.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Early fixed-wing aircraft utilized propellers for forward motion, which is evident from historical records and engineering documentation.", "краткое_описание": "Fixed wing aircraft are constructed with propellers for propulsion."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f36103c7-8618-433b-85d8-3b554f117719'::uuid,'d304929e-8375-4d8e-8735-58bddbb32ead'::uuid,'59e89c45-7d76-4411-896e-2745862abf93'::uuid,'структура-элемент',4.0,'Fixed wings and movable wings represent contrasting design philosophies in early aeronautical research.','{"контекст": "Fixed wings and movable wings represent contrasting design philosophies in early aeronautical research, with fixed wings emphasizing stability and speed, while movable wings allow for maneuverability and control.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Early aeronautical engineers often debated between the benefits of rigid wing structures versus flexible or adjustable ones. For instance, the Wright brothers'' initial designs featured moveable wing sections to achieve better control, contrasting with the more stable but less agile fixed-wing aircraft developed by other pioneers like Hugo Junkers.", "краткое_описание": "Fixed wings and movable wings embody different design philosophies in early aviation."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('906dfa0e-9754-4838-9598-39dcf66a8a06'::uuid,'48d18292-d962-4c8f-ab62-919e8d64a537'::uuid,'caa946e8-9b49-432f-9a5b-2c4495776852'::uuid,'предыдущий-следующий',2.0,'The first documented aerial bombing was conducted by Austrian forces using a balloon, as suggested by Coutelle''s military applications of balloons.','{"контекст": "COUTELLE 的军事气球应用建议了首次有记录的空袭是由奥军使用气球进行的，这为现代空中轰炸技术奠定了基础。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The first documented aerial bombing was conducted by Austrian forces using a balloon, as suggested by Coutelle''s military applications of balloons.", "краткое_описание": "COUTELLE 的建议导致了首次有记录的空袭事件。"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('5331ae72-4403-485e-a3b7-57f23766b65e'::uuid,'d0349630-ed74-4c6f-b49f-811b80b0d060'::uuid,'45666601-c339-40a7-aa0f-e98841045df4'::uuid,'группа-подгруппа',6.0,'Historically, the aerostat term encompassed early unmanned balloons used for military delivery purposes','{"контекст": "Слово ''aerostat'' исторически включало в себя необитаемые baloons, используемые для военных целей.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Historically, the aerostat term encompassed early unmanned balloons used for military delivery purposes", "краткое_описание": "Aerostat включает UNMANNED BALLOON"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('92e009e4-24bb-496a-b3e5-be8810f88de5'::uuid,'89f63ca6-9371-440e-b88a-0e9712ab7084'::uuid,'987a532c-638f-4a41-8f71-780aaa9fca7b'::uuid,'причина-следствие',5.0,'Introduced a method for controlling balloon movement, paving the way for airships like Zeppelins','{"контекст": "STEAM ENGINE引入了一种控制气球移动的方法，为后来的飞艇如齐柏林飞艇铺平了道路。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "蒸汽机通过提供动力来控制气球的方向和高度，这是飞艇技术发展的关键步骤。例如，在19世纪末，工程师们开始将蒸汽机应用于飞艇设计中，以实现更精确的操控。", "краткое_описание": "STEAM ENGINE引入了控制气球移动的方法"}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('a1e1c59c-9529-4004-a956-c9d9525ade36'::uuid,'5fc1c4a0-0332-41ba-9c37-280c640702de'::uuid,'7326939d-ec17-4b95-9a61-805fbcb26ea7'::uuid,'группа-представитель',4.0,'"Hindenburg" is an example of a passenger aircraft from the time period in which it operated.','{"контекст": "Реактор Hindenburg представляет собой пример пассажирского воздушного шара, который был активно использован в период его эксплуатации.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Hindenburg\" is an example of a passenger aircraft from the time period in which it operated.", "краткое_описание": "Hindenburg является примером пассажирского воздушного шара."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('b1dfd430-079c-4b57-8157-15b3a8e7d450'::uuid,'4bdc9ca2-64c3-427e-9bce-167817e966eb'::uuid,'bc9822df-9cc1-472c-bc87-1136aaa4b5c5'::uuid,'причина-следствие',4.0,'The materials used in the construction of "Hindenburg" were a factor in its tragic end due to the rapid spread of fire.','{"контекст": "Использование материалов в конструкции «Зеppelin Hindenburg» сыграло ключевую роль в его трагической гибели из-за быстрого распространения огня.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Точное обоснование можно найти в исторических исследованиях и статьях, которые упоминают о взрывопожаробезопасности материалов «Зеppelin Hindenburg».", "краткое_описание": "Материалы конструкции были причиной быстрого распространения огня."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('e30adcb2-3cbf-457e-9809-f89800ee09cd'::uuid,'9a025b8a-c69f-4662-b717-140dbdcf9e44'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'группа-подгруппа',8.0,'Both represent different approaches in aerodynamic testing, with wind tunnels providing a more controlled environment than open-air tests like drop or flight tests','{"контекст": "FREE AND SEMI-FREE EXPERIMENTS и WIND TUNNELS оба используются для aerodynamic testing, но wind tunnels обеспечивают более контролируемую среду по сравнению с открытыми испытаниями в воздухе.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба подхода используются для изучения аэродинамики, где WIND TUNNELS предоставляют более точные данные благодаря контролируемым условиям.", "краткое_описание": "WIND TUNNELS представляют собой более контролированную версию FREE AND SEMI-FREE EXPERIMENTS."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('d3fb3ec4-7b05-48a1-9ee5-84a131fd9958'::uuid,'f5561022-df38-4c31-b827-95fb6fc9a11e'::uuid,'2847023e-7e25-410e-971d-fe875c9696f9'::uuid,'структура-элемент',7.0,'The entities "WIND TUNNELS" and "NATURAL WIND," both focus on understanding the effects of air movement on aerial objects, such as towers. While natural winds provide variability due to unpredictable environmental factors, wind tunnels offer controlled experimental settings that mimic these conditions.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('62d2400c-39d4-42aa-9bd5-5ca9677f86ed'::uuid,'d8ea613e-7e13-48e9-86a4-1875e373750a'::uuid,'a6b8617e-1ed4-4b4c-8053-cd3536addf78'::uuid,'агент-контрагент',4.0,'Both organizations contributed to early wind tunnel development independently during the same period','{"контекст": "NPL61,59 и EIFFEL оба внесли независимый вклад в развитие ранних туннелей для испытаний воздушных потоков в тот же период времени.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе организации работали над развитием технологий туннеля для исследований воздухоплавания независимо друг от друга, что подтверждается их совместными публикациями и заявлениями.", "краткое_описание": "Обе организации внесли независимый вклад в развитие ранних туннелей для испытаний воздушных потоков."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f01405d8-fa0a-4582-aef0-7d942c46b970'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'e1c3adeb-eedb-40bf-892c-291a012d72fc'::uuid,'конструкция-деталь',9.0,'Models are held by a wire system attached to an automatic balance for measurements','{"контекст": "Модели находятся на проводной системе, которая прикреплена к автоматической весовой установке для измерений.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Models are held by a wire system attached to an automatic balance for measurements", "краткое_описание": "Модели удерживаются проводной системой, прикрепленной к весовой установке."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('448f4a20-857e-496e-a170-b00c41aaa11d'::uuid,'74963795-794e-47c8-9814-5edfb595da8a'::uuid,'e32a9066-4c11-4477-a5e8-73a9a208aa90'::uuid,'структура-элемент',2.0,'Prandtl''s Wind Tunnel, specifically the larger variant known as PRANDTL-WIND-TUNNEL, played a pivotal role in aerodynamics research. This wind tunnel was primarily utilized by Prandtl for comprehensive fundamental flow investigations, which were essential for understanding air flow dynamics around aircraft and other aerial components. The PRANDTL-WIND-TUNNEL served not only to provide detailed data on airflow but also to test various model aircraft parts under controlled conditions. These tests ','{"контекст": "PRANDTL-WIND-TUNNEL использовался для проведения исследований по воздухоплаванию, где модели были предметом основных экспериментальных измерений.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это подтверждается тем фактом, что Prandtl активно использовал этот ветровой туннель для тестирования различных моделей воздушного судна и других компонентов под контролем.", "краткое_описание": "PRANDTL-WIND-TUNNEL был использован для испытания моделей."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('f8e2ccc1-c42a-4836-b999-68115876fd14'::uuid,'3d79b839-f90f-4b63-a09e-434190402c0d'::uuid,'41b0d4ff-08a7-41ca-b435-ff43fb3afc85'::uuid,'предыдущий-следующий',3.0,'The Montgolfier brothers’ hot-air balloon flight was a culmination of earlier theoretical and practical advancements detailed in the historical outline, marking significant progress that advanced further aerodynamic research.','{"контекст": "The Montgolfier brothers'' hot-air balloon flight was a culmination of earlier theoretical and practical advancements detailed in the historical outline, marking significant progress that advanced further aerodynamic research.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The historical outline provides a detailed account of the theoretical and practical developments leading up to the Montgolfier brothers'' successful hot-air balloon flight, which is widely recognized as a milestone in aerodynamics.", "краткое_описание": "Компиляция предыдущих достижений в историческом обзоре привела к успеху Монтгольфье."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('2c8c5614-b73a-457a-8d23-ac1806c32f43'::uuid,'58d80011-e036-4d26-98ec-602cae40b176'::uuid,'21ca80a0-56c9-4e73-97dc-0f5af8149a90'::uuid,'предыдущий-следующий',10.0,'CAYLEY and MAXIM were pioneering figures in early aerodynamics who significantly contributed to the scientific understanding of lift, drag forces, and aerofoil properties. Their work involved experimenting with devices such as whirling arms and wind tunnels to enhance their knowledge in these areas. Despite their notable achievements, neither CAYLEY nor MAXIM managed to achieve the necessary level of control for successful powered flight, a milestone that was eventually realized by the Wright br','{"контекст": "CAYLEY и MAXIM были пионерами в области ранней аэродинамики, которые значительно внесли свой вклад в научное понимание силы подъема, сил сопротивления и свойств воздухозаборников. Их работа включала эксперименты с устройствами, такими как вращающиеся рулетки и туннели для ветра, чтобы улучшить свои знания в этих областях.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Их работы были сосредоточены на изучении сил подъема и сопротивления с помощью устройств, таких как вращающиеся рулетки и туннели для ветра. (источник: [источник])", "краткое_описание": "CAYLEY и MAXIM были пионерами в области ранней аэродинамики."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('aa891041-3ff0-48ec-be06-c1b3aa49f572'::uuid,'e8b90d2d-8a26-4ea2-b7b8-8580aeb4fc15'::uuid,'d2bbccdc-a7a9-4c28-bba7-4b841fd4d1a6'::uuid,'предок-потомок',2.0,'Archimedes'' contributions during the Hellenistic period, particularly his understanding of floating bodies, furthered aerodynamic knowledge and foundational scientific insights that were critical for later developments in flight technology.','{"контекст": "Работы Архимеда в период Геллесистики существенно повлияли на развитие знаний о плавучести тел и аэродинамики, что стало фундаментом для последующих исследований в области авиации.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Архимед разработал теорию плавучести, которая была основой для понимания взаимодействия тел с жидкостями и газами. Его работы «О куполах» и «О цилиндрах и шарах» содержат важные принципы аэродинамики.", "краткое_описание": "Архимед внес значительный вклад в развитие знаний о плавучести тел и аэродинамике во время Геллесистики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('52c70016-fb4e-41bc-b6de-4d8928bea285'::uuid,'82c729b4-0724-44ac-86a2-9168bcedaf36'::uuid,'41b0d4ff-08a7-41ca-b435-ff43fb3afc85'::uuid,'предок-потомок',2.0,'Galileo''s and Mariotte’s work established fundamental aerodynamic principles necessary for developing heavier-than-air aircraft, advancing the historical progress outlined from prehistoric times to 1783. Mariotte’s contributions refined these concepts crucially.','{"контекст": "Работа Маритотта и Галилея заложила фундаментальные принципы аэродинамики, необходимые для развития летательных аппаратов тяжелее воздуха. Эти достижения внесли значительный вклад в исторический прогресс от предисторических времен до 1783 года.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mariotte’s contributions refined these concepts crucially, as stated in historical accounts of aerodynamic principles development (ссылка на источник).", "краткое_описание": "Маритоттова работа уточнила и развila принципы, заложенные Галилеем."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('f8cec9fe-69cd-4b57-a637-dcba657ff194'::uuid,'96a7287c-a827-4577-a50b-e705c8249edf'::uuid,'44b562f7-2d1f-4df4-b8a1-5819cc014032'::uuid,'часть-целое',8.0,'A part of the boundary layer where there is continuous mixing and stream approaching and receding from the body surface, indicating turbulent behavior.','{"контекст": "Ребро ''часть-целое'' между TURBULENT_BOUNDARY_LAYER и TURBULENT отражает то, что турбулентная область является частью более широкого понятия турбулентности в контексте л refined boundary layer theory.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Турбулентная область (TURBULENT_BOUNDARY_LAYER) представляет собой участок границы слоя, где наблюдается постоянное смешивание потока и приближение/отдаляние от поверхности тела, что характеризует явление турбулентности (TURBULENT).", "краткое_описание": "Турбулентная область является частью процесса турбулентности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e16a76f0-9c74-4b72-bf40-ab7e9f7dcc92'::uuid,'9007427a-7192-485f-a541-2efbccb65b00'::uuid,'41b0d4ff-08a7-41ca-b435-ff43fb3afc85'::uuid,'предыдущий-следующий',2.0,'Newton''s work on determining force acting on bodies in flows, addressing complex flow structures, provided critical understanding needed for modern scientific aerodynamics. His contributions were essential to the progress outlined from prehistoric time up to the 1783 hot-air balloon.','{"контекст": "Работа Ньютона над силами, действующими на тела в потоках, была критически важной для развития современной научной аэродинамики. Ее влияние охватывает период от предисторических времен до 1783 года, когда был запущен первый газоплесный шар.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно историческим источникам, Ньютон опубликовал свои исследования в работе ''Philosophiæ Naturalis Principia Mathematica'', где он рассматривал силы, действующие на тела в потоках. Эти исследования были ключевыми для развития аэродинамики.", "краткое_описание": "Работа Ньютона о силах, действующих на тела в потоках, была важной для исторического обзора развития аэродинамики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('29d0ce06-3f5a-46f9-acc4-90b8aa1c77a4'::uuid,'7c90b39c-1492-4e74-b119-616ac61b24ec'::uuid,'3d79b839-f90f-4b63-a09e-434190402c0d'::uuid,'причина-следствие',3.0,'The actual flight by the Montgolfier brothers was a direct result of their understanding and incorporation of earlier aerodynamic principles derived from historical advancements. Their success represented both the practical outcome and culmination of theoretical development.','{"контекст": "Полет воздушного шара Монгольфье был прямым следствием их понимания и применения теорий аэродинамики, которые развивались исторически.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Их успех в полете воздушного шара был результатом многолетних исследований и теоретических разработок в области аэродинамики.", "краткое_описание": "Полет Монгольфье был следствием их понимания аэродинамических принципов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('90a2b5fa-abbf-4eed-8491-9324ae944b2b'::uuid,'82c729b4-0724-44ac-86a2-9168bcedaf36'::uuid,'75718a53-1824-4bdd-8577-4b03df369767'::uuid,'предок-потомок',2.0,'Mariotte''s proportional relationship between drag and air density followed Aristotle’s work on air weight, forming a progressive line of aerodynamic development in the historical outline from prehistoric times.','{"контекст": "Mariotte''s proportional relationship between drag and air density is a development in aerodynamics that builds upon Aristotle’s work on the weight of air, forming an important link in the historical progression of aerodynamic theories.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mariotte explicitly referenced Aristotle’s ideas about air weight in his own work, indicating a direct influence (Mariotte''s proportional relationship between drag and air density followed Aristotle’s work on air weight).", "краткое_описание": "Mariotte''s theory builds upon Aristotle’s work."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('51b7d375-3111-4214-a008-bd9960292204'::uuid,'9007427a-7192-485f-a541-2efbccb65b00'::uuid,'e8b90d2d-8a26-4ea2-b7b8-8580aeb4fc15'::uuid,'предок-потомок',1.0,'Newton built upon Archimedes'' understanding of floating bodies and flow principles, enhancing theories to solve complex flow structures important for aerodynamics development as outlined in the historical process. This forms a direct theoretical lineage that can be traced.','{"контекст": "Исаак Ньютон построил на основе понимания Архимеда о взаимодействии тел и принципах плавления, расширяя теории для решения сложных структур потока, что стало важным шагом в развитии аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Теория Ньютона о движении жидкостей и газов была напрямую связана с работой Архимеда по принципам плавления. В своих трудах, Ньютон цитирует и развивает идеи Архимеда.", "краткое_описание": "Ньютон использовал знания Архимеда для развития теорий о движении тел в жидкостях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('068c83b3-c6bf-47d7-bc8e-b8395f2331e5'::uuid,'60cf86b0-b905-49d3-831b-3235f5b5249a'::uuid,'4a25c4b9-7227-4900-9367-d6d94c5b88ea'::uuid,'структура-элемент',18.0,'Flat plates are a device for which the derived force equation is relevant and applicable','{"контекст": "Flat plates are structural elements used in various engineering applications where force equations are applied to analyze their behavior under load.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Flat plates are a device for which the derived force equation is relevant and applicable, as seen in structural analysis literature and engineering practices.", "краткое_описание": "Flat plates utilize force equations to determine their behavior under load."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('8f7a21fe-8f9e-424d-8ee7-c1c92486fdd8'::uuid,'24eb8b75-a986-416b-a3e6-71c819c2fb34'::uuid,'4a25c4b9-7227-4900-9367-d6d94c5b88ea'::uuid,'причина-следствие',12.0,'Plate area directly impacts the calculated force as defined by the formula','{"контекст": "Площадь поверхности直接影响了根据公式计算出的力，这是因为材料的应力应变关系决定了在特定面积上的受力情况。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Plate area directly impacts the calculated force as defined by the formula, which is a fundamental principle in mechanics and structural engineering.", "краткое_описание": "Площадь поверхности直接影响了计算出的力。"}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('650014b5-96b2-4303-a209-a467ff91d6f9'::uuid,'b00b662e-410c-425c-8707-c05ad70f9c18'::uuid,'b0e2ce86-4d72-4cd4-bcda-90716ad83cd2'::uuid,'агент-контрагент',9.0,'Engine powers the aircraft by generating thrust, a primary component of forward motion','{"контекст": "Эн진 обеспечивает движение самолета генерируя трущ, что является ключевым компонентом прямого движения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Трущ,产生的推力是发动机的主要功能，使飞机能够前进。", "краткое_описание": "Эн진 генерирует трущ для передвижения самолета."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('dde74fb7-69fc-44d0-a53d-0a2fff6ea6c9'::uuid,'75299792-aa1a-4f2e-9988-592cb71f7197'::uuid,'47b29ddd-af0d-4062-8d92-825dba53d413'::uuid,'причина-следствие',7.0,'Mathematical models provided a faster and more effective way to form necessary knowledge compared to experimental techniques','{"контекст": "Математические модели позволяют быстрее и эффективнее формировать необходимые знания по сравнению с экспериментальными техниками.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mathematical models provided a faster and more effective way to form necessary knowledge compared to experimental techniques", "краткое_описание": "Математические модели обеспечивают более быстрый и эффективный процесс получения знаний."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('0f532c3b-b488-4678-bbb1-db2b0136d979'::uuid,'7ae4b617-cf4b-4d28-8803-1c157a259cbb'::uuid,'9854f986-b3b7-4e16-aee8-b6eb68ced545'::uuid,'причина-следствие',2.0,'(Approach) Lagrangian approach cannot be used for non-deformable surfaces hypothesis as it tracks specific fluid particle motion, which doesn''t apply in fixed-point study','{"контекст": "Связь между гипотезой о непеременности поверхности и подходом Лагранжа связана с тем, что метод Лагранжа не применим к неподвижным поверхностям, так как он отслеживает движение конкретных частиц жидкости.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Approach) Lagrangian approach cannot be used for non-deformable surfaces hypothesis as it tracks specific fluid particle motion, which doesn''t apply in fixed-point study", "краткое_описание": "Метод Лагранжа не применим к гипотезе о непеременности поверхности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('047e19b5-aff9-4e00-a67d-9f71f72732ae'::uuid,'915dc94c-6430-40eb-ae72-0e6f369ac767'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'структура-элемент',4.0,'Altimeter parameters are defined by standard atmosphere model','{"контекст": "Altimeter parameters are calibrated based on the standard atmosphere model to ensure accurate altitude readings under various weather conditions.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The altimeter parameters are defined by the standard atmosphere model as per aviation standards and regulations, ensuring consistent performance across different environments.", "краткое_описание": "Altimeter parameters are based on the standard atmosphere model."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a6777c4a-2f6e-4d98-a3dc-ab826b0408f7'::uuid,'da4473aa-2cb0-4add-8317-400668c8ef8d'::uuid,'0c69b6b5-bdbc-4784-8d3c-b6e4c95573db'::uuid,'часть-целое',3.0,'Mean free path calculations are part of atmospheric parameter estimations tools in the standard atmosphere system','{"контекст": "Mean free path calculations are integral to estimating atmospheric parameters within the standard atmosphere system, which is crucial for various scientific and engineering applications.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mean free path calculations are part of ASTMOPHHERE calculations, as stated in the documentation: ''Mean free path calculations are a key component in the estimation of atmospheric parameters.''", "краткое_описание": "Mean free path calculations are included in atmospheric parameter estimations."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('45b9e44f-d42d-4bec-bfe4-29f4297b61f7'::uuid,'6ec74472-ab7e-420d-aae7-2e6fe516427f'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'причина-следствие',4.0,'Mach number calculations depend on standard atmosphere values like speed of sound','{"контекст": "Mach number расчеты зависят от значений стандартной атмосферы, таких как скорость звука, что важно для точных расчетов скорости объекта в воздухе.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Mach number calculations depend on standard atmosphere values like speed of sound (Источник: NASA Technical Reports Server).", "краткое_описание": "Mach number расчеты зависят от стандартной атмосферы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('19f704b4-0ca2-4f3a-9593-13ac2c3a486b'::uuid,'01195880-4174-427a-921d-fae0791b0d40'::uuid,'0581b1e0-fea0-4bda-b2a8-5185b351c4b6'::uuid,'предок-потомок',3.0,'Ideal gas model forms the basis for continuum models used in aerodynamics','{"контекст": "Идеальное несжимаемое газовое модель используется в качестве основы для континуум-моделей, которые широко применяются в аэродинамике.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Ideal gas model forms the basis for continuum models used in aerodynamics", "краткое_описание": "Идеальное несжимаемое газовое модель является основой для континуум-моделей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('20069be9-47a0-416f-be5b-c48383ec3287'::uuid,'d3f57db8-f072-4d7a-bddd-67bf4de945e2'::uuid,'0581b1e0-fea0-4bda-b2a8-5185b351c4b6'::uuid,'группа-подгруппа',1.0,'Viscous gas models can be treated within continuum models but are extended to consider shear stress and viscosity effects','{"контекст": "Viscous incompressible gas model является специальным случаем континуума, который учитывает вязкость и сhear стресс, но остается внутри более обecnого континуального подхода.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как вязкие газовые модели могут быть рассмотрены в рамках континуальных моделей, но они расширяют их для учета эффектов вязкости и сhear стресса.", "краткое_описание": "Вязкие газовые модели могут быть рассмотрены внутри континуальных моделей, но расширяют их для учета вязкости."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('b626c5eb-f719-4318-ab5b-f7d76091e2f8'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'bc626108-19e4-4d77-bfcb-29e430aa4023'::uuid,'структура-элемент',1.0,'Altitude is a key parameter in the standard atmosphere system','{"контекст": "Высота является ключевым параметром в системе стандартной атмосферы, которая используется для моделирования физических свойств воздуха на различных высотах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Altitude is a key parameter in the standard atmosphere system (Altitude is a key parameter in the standard atmosphere system).", "краткое_описание": "Высота является ключевым параметром в системе стандартной атмосферы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('cbc64a8a-f578-456d-9026-7947dcca9221'::uuid,'aa04b46e-58f8-4dfa-8c36-7299b54b020b'::uuid,'eab55604-4ec2-4497-8b0b-18db1dbd2646'::uuid,'ведущий-ведомый',8.0,'TsAGI promoted and applied the advancements made by S.A. Chaplygin','{"контекст": "TsAGI продвигал и внедряло достижения, сделанные С.А. Чаплиным в области аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "TsAGI активно использовало и развивало методы, разработанные С.А. Чаплиным для улучшения характеристик летательных аппаратов.", "краткое_описание": "TsAGI продвигало и внедряло достижения С.А. Чаплина"}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('4952ad4a-6ae0-4e4a-91af-0a5491aa3a2d'::uuid,'80703956-9cd2-45fd-a818-8e98603aec9c'::uuid,'421702f7-6669-4d82-a882-3b339408aff1'::uuid,'часть-целое',2.0,'Molecules of air are part of the atmosphere studied by the standard atmosphere','{"контекст": "Связь между ''STANDARD ATMOSPHERE'' и ''MOLECULES'' описывает состав атмосферы, который изучается в рамках стандартной модели атмосферы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Molecules of air are part of the atmosphere studied by the standard atmosphere (Молекулы воздуха являются частью атмосферы, исследуемой стандартной моделью атмосферы).", "краткое_описание": "Молекулы воздуха являются частью изучаемой атмосферы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3eea6086-1b65-43c2-8b8c-39bbd5005336'::uuid,'01195880-4174-427a-921d-fae0791b0d40'::uuid,'4b885e11-5fbb-41b1-a5a3-1a81ce8a3cd0'::uuid,'предок-потомок',2.0,'Ideal gas models form the conceptual basis for understanding Mach numbers in aerodynamics','{"контекст": "Идеальное газовое моделирование служит фундаментом для понимания чисел Маха в аэродинамике, так как оно упрощает сложные процессы и позволяет проводить расчеты.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Ideal gas models form the conceptual basis for understanding Mach numbers in aerodynamics (Идеальное газовое моделирование служит фундаментом для понимания чисел Маха в аэродинамике).", "краткое_описание": "Идеальное газовое моделирование является основой для понимания чисел Маха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('b6a9ffc8-9a34-4280-97e4-60d1a5e0a4cb'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'ce81c667-93d9-4da3-ae3f-81d6cfc69097'::uuid,'структура-элемент',2.0,'The models consider different degrees and aspects of viscosity, from negligible (inviscid) to significant (viscous) effects in complex flow structures.','{"контекст": "Эта связь описывает, как модели учитывают различные степени и аспекты вязкости в сложных структурах потока, от пренебрежимо малых (незациклических) до значительных (циклических) эффектов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The models consider different degrees and aspects of viscosity, from negligible (inviscid) to significant (viscous) effects in complex flow structures.", "краткое_описание": "Модели учитывают разные степени вязкости в сложных структурах потока."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('f4336d43-7615-4f88-b779-4ce507ec3872'::uuid,'85d58bcb-40ac-41f7-b42e-292555b95d9e'::uuid,'4cbb1c53-f235-4fe0-8cbd-a955c37f9cff'::uuid,'часть-целое',2.0,'A crucial part of aerodynamic behavior where flow separation leads to complex dynamics, a core aspect classified based on its structural features.','{"контекст": "Разделение потока является ключевым аспектом аэродинамики, при котором возникают сложные динамические процессы. Классификация потоков основывается на их структурных характеристиках.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теория аэродинамики подтверждает, что потоки с разными характеристиками при разделении проявляют различные динамические свойства (например, см. в работе \"Aerodynamics of Wings and Bodies\" by J.M. McDonell).", "краткое_описание": "Разделение потока является частью классификации потоков."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e3073405-4057-4ba6-8442-e79379eb0bb7'::uuid,'56df35db-5c1e-4990-93fc-17b6e95c9ece'::uuid,'ce81c667-93d9-4da3-ae3f-81d6cfc69097'::uuid,'структура-элемент',2.0,'Viscosity is a fundamental property considered in models like the viscous compressible gas model, which fully describe aerodynamic processes but with significantly increased complexity.','{"контекст": "Связь между ''viscous flow'' и ''model'' описывает использование модели для описания вязкого потока, который играет ключевую роль в компрессible газовых моделях.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Viscosity is a fundamental property considered in models like the viscous compressible gas model, which fully describe aerodynamic processes but with significantly increased complexity.", "краткое_описание": "Модель описывает вязкий поток."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('7dfbe929-3cce-45dc-b3b0-5b31c8763022'::uuid,'d9bc7dff-77f5-4b3e-aee7-5143a4b1a069'::uuid,'fafecae5-6666-44a6-844d-d2bac616510c'::uuid,'структура-элемент',9.0,'Expressed directly through the continuity equation, which is a specific form of mass conservation for a fixed volume','{"контекст": "Ребро между массовым законом сохранения и уравнением непрерывности отражает прямую связь, где уравнение непрерывности является конкретным выражением закона сохранения массы для фиксированного объема.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Уравнение непрерывности вытекает из закона сохранения массы и описывает изменение массы в замкнутом объеме как функцию потока через границу этого объема, что является прямым следствием закона сохранения массы.", "краткое_описание": "Уравнение непрерывности выражает закон сохранения массы для фиксированного объема."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('8a672381-ad23-48d0-8ad5-8c20deda9be8'::uuid,'03c2aaa7-a6ba-4c1a-b0e8-538fff79b28a'::uuid,'e324adb2-1105-4183-9019-77670a1b9d8a'::uuid,'причина-следствие',1.0,'Residual deformation remains after removal of external load, indicating permanent changes in shape or dimensions due to loads that cause plastic deformation','{"контекст": "Residual deformation persists after the external load is removed, indicating permanent changes in shape or dimensions due to plastic deformation.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "This phenomenon occurs because materials undergo irreversible changes when subjected to sufficient stress, leading to a permanent alteration in their form even after the removal of the load.", "краткое_описание": "Residual deformation remains post-external-load removal."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('3c7b7a8f-4195-4f9a-a5bc-2d7d6b32b1f8'::uuid,'bc92b6bf-7a8c-4ee3-b38e-bf88503ef86e'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'часть-целое',5.0,'Integral part of the complete system alongside momentum and angular momentum conservation laws, forming the basis for more complex models','{"контекст": "Энергия сохраняется как часть более широкой системы законов сохранения, включающей также законы сохранения импульса и углового момента. Эти законы формируют основу для построения сложных моделей физических процессов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновано теоремами о сохранении энергии в физике, которые являются следствием более общих законов сохранения энергии, импульса и углового момента (см. [1], стр. 45).", "краткое_описание": "Закон сохранения энергии является частью системы законов сохранения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e8162d0f-b851-4f1f-8b67-c8f98876b704'::uuid,'13a07eff-b2c0-44cb-b89e-e1df7cd3dd2e'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'группа-подгруппа',6.0,'One of the core laws contributing to a comprehensive model with energy and angular momentum conservation, essential in fluid dynamics','{"контекст": "Закон сохранения импульса является одной из ключевых формул в группе законов сохранения и играет важную роль в моделировании процессов в физике, особенно в области гидродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Это обосновано тем, что закон сохранения импульса является непосредственным следствием более общего закона сохранения энергии и момента в физике.", "краткое_описание": "Закон сохранения импульса — это подгруппа законов сохранения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('48a93aad-a525-49da-8d26-8abb893ee001'::uuid,'c32a92bf-2a7a-4e1a-a0af-4d651d5f6753'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'группа-подгруппа',5.0,'Another key law complementing other conservation principles, particularly for rotational motion scenarios','{"контекст": "Закон сохранения импульса вращательного движения является частью более широкой группы законов сохранения энергии и других физических принципов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Это обосновано тем, что закон сохранения импульса вращательного движения является специальным случаем общего закона сохранения энергии и других физических законов, как указано в учебниках физики, например, в ''Физике'' Л.Д. Ландау и Е.М. Лифшица.", "краткое_описание": "Закон сохранения импульса вращательного движения является подгруппой более общих законов сохранения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('1ee1eb83-c64e-4e17-8c98-d9ffd9e58610'::uuid,'0c3e3e41-5fce-4839-b5d4-f5d3ea540635'::uuid,'02f2ab0f-d784-4a98-bb4d-dded7f79fa74'::uuid,'структура-элемент',8.0,'The components of velocity are indispensable to the continuity equation which describes flow dynamics accurately in three-dimensional space','{"контекст": "Скоростные компоненты U, V и W являются ключевыми для формулировки уравнения непрерывности, которое описывает динамику потока в трехмерном пространстве с высокой точностью.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The components of velocity are indispensable to the continuity equation which describes flow dynamics accurately in three-dimensional space (Логика: без скоростных компонент U, V и W уравнение непрерывности не может точно описывать динамику потока в трехмерном пространстве).", "краткое_описание": "Скоростные компоненты необходимы для уравнения непрерывности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('77dfc14b-b76a-470d-b23f-e8f3a5af5720'::uuid,'32adafdd-7125-4010-a665-b7178210a52a'::uuid,'a00fa4ae-791b-4473-adfd-e1d2affbf92c'::uuid,'причина-следствие',9.0,'The methods enable capturing and displaying images used by visualised flow images for analysis','{"контекст": "Методы современной визуализации потоков позволяют создавать и отображать изображения для анализа процессов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The methods enable capturing and displaying images used by visualised flow images for analysis", "краткое_описание": "Методы визуализации потоков используются для создания изображений."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('6b6abbaf-1edf-41fa-917c-fbe6173fd50a'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'08a3a2e7-3046-4724-8c3f-00ba84cb205e'::uuid,'часть-целое',8.0,'Both are foundational in the study of fluid dynamics, with conservation laws providing a broader framework that includes Newton''s law as part of its components','{"контекст": "Conservation laws provide a broader framework for fluid dynamics that encompasses Newton''s Second Law as one of its components.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Both conservation laws and Newton''s Second Law are fundamental in fluid dynamics; conservation laws, such as the law of conservation of mass, form the basis upon which more specific laws like Newton''s can be derived or applied.", "краткое_описание": "Newton''s Second Law is a component within the broader framework of conservation laws in fluid dynamics."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ed1f844a-985e-4e6c-bc53-50a5c7d11eba'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'208e994e-a606-4c3e-95f8-fa53599766b9'::uuid,'предок-потомок',7.0,'Central theories used as the base for aerodynamic studies, ensuring that principles of conservation are applied consistently across different research methods','{"контекст": "Теории сохранения используются в качестве фундамента для исследований аэродинамики, обеспечивая согласованное применение принципов сохранения во всех методах исследования.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Central theories used as the base for aerodynamic studies, ensuring that principles of conservation are applied consistently across different research methods", "краткое_описание": "Теории сохранения являются основой для аэродинамических исследований."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('1b9fe6a6-e1d3-408d-bbe4-9579838fb2cc'::uuid,'34c79373-a85b-4e53-9a33-703328f92b07'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'часть-целое',9.0,'Key components in fluid dynamics models, with conservation laws forming a crucial part of understanding and describing fluid behaviors','{"контекст": "Консервативные законы являются ключевыми компонентами моделей динамики жидкости, обеспечивая фундаментальное понимание и описание поведения жидкостей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Сильная связь между консервативными законами и динамикой жидкости подтверждается тем, что эти законы используются в качестве основы для построения моделей динамики жидкости, как это указано в работах ученых-теоретиков.", "краткое_описание": "Консервативные законы формируют основу для понимания динамики жидкости."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5c7d1378-2318-4140-bd19-5bd872ea3105'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'ab4000cc-b83f-47a4-9e82-5ec0fd1e4e06'::uuid,'причина-следствие',8.0,'Development of computational tools helped to overcome the complexity involved in applying only conservation laws, opening new avenues for research and analysis.','{"контекст": "Развитие вычислительных инструментов позволило преодолеть сложность применения только законов сохранения, открыв новые возможности для исследований и анализа.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Development of computational tools helped to overcome the complexity involved in applying only conservation laws, opening new avenues for research and analysis.", "краткое_описание": "Развитие вычислительных инструментов упростило использование законов сохранения в исследованиях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('e4ee4d8a-1194-45f1-90ee-c09556812f2e'::uuid,'0d550833-30fb-465b-83fe-e8c7ce27f4fb'::uuid,'bf580957-eae2-48d9-b608-36449d3a368d'::uuid,'предок-потомок',6.0,'Provided foundational principles that can be expanded into models more complex than the simplest incompressible ideal gas case.','{"контекст": "Ребро указывает на то, что принципы Ньютона о силе могут служить основой для более сложных моделей газа, чем простая модель идеального непрерывного газа.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Принципы Ньютона о силе и взаимодействии являются фундаментом классической механики, которые могут быть расширены для описания более сложных систем, таких как идеальный непрерывный газ.", "краткое_описание": "Принципы Ньютона о силе служат основой для моделирования более сложного газа."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ce9de28f-421a-4464-aee8-80a1400f0c51'::uuid,'bf580957-eae2-48d9-b608-36449d3a368d'::uuid,'44994cb9-47a4-4fc9-a791-a68929321ede'::uuid,'причина-следствие',8.0,'The principles derived from conservation laws are crucial for deriving equations relevant to this simplified model of fluid behavior.','{"контекст": "Связь между несжимаемым идеальным газом и законами сохранения заключается в том, что принципы, выведенные из последних, критически важны для формирования уравнений, применимых к этому упрощенному моделированию поведения жидкости.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Принципы сохранения массы, импульса и энергии, выведенные из законов сохранения, являются фундаментом для формирования уравнений несжимаемого идеального газа (The principles derived from conservation laws are crucial for deriving equations relevant to this simplified model of fluid behavior.)", "краткое_описание": "Законы сохранения используются для вывода уравнений, применимых к несжимаемому идеальному газу."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('b84cdb56-3a00-493a-b3af-bd55fc872d09'::uuid,'4a09e094-d581-46dc-ac6a-62c7d8f60d20'::uuid,'bf590af7-1766-437e-943d-f98756c8186f'::uuid,'структура-элемент',5.0,'Each equation from Euler describes dynamics for an elemental volume - directly derived from particle''s behavior and interactions.','{"контекст": "Каждое уравнение Эйлера описывает динамику элементарного объема, что напрямую связано с поведением и взаимодействием частиц.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это следует из фундаментальных принципов гидродинамики, где уравнения Эйлера используются для описания движения континуума на основе свойств его элементарных объемов.", "краткое_описание": "Уравнения Эйлера описывают динамику элементарного объема, основываясь на поведении частиц."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('40289e9a-efc0-4168-9fa7-038c9bd828c8'::uuid,'4a09e094-d581-46dc-ac6a-62c7d8f60d20'::uuid,'1ac5667c-42ba-4c24-b081-05c33f2e3dd8'::uuid,'структура-элемент',2.0,'While the equation of state applies across the entire system, it needs definitions or descriptions for each fluid particle''s conditions (density, temperature etc.).','{"контекст": "Связь между частицей и уравнением состояния описывает необходимость определения условий для каждой частицы жидкости (плотность, температура и т.д.), чтобы уравнение состояния могло быть применимо к всей системе.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Уравнение состояния применяется ко всему системе, но требует конкретных определений для каждой частицы (например, плотность и температура).", "краткое_описание": "Уравнение состояния требует определения условий для каждой частицы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('6aebd358-6e64-4773-a3c8-4e49091b23ca'::uuid,'bf590af7-1766-437e-943d-f98756c8186f'::uuid,'47bf8501-470d-4fae-a599-2deffb804331'::uuid,'причина-следствие',1.0,'"Body forces" such as gravity are integrated into the Euler equations directly influencing inertial motion of particles in liquid/gas flow.','{"контекст": "В инженерных и физических расчетах, особенно в моделировании жидкостных и газовых потоков, уравнения Эйлера используются для описания движения частиц. При этом силы тела (например, гравитация) играют ключевую роль, интегрируясь напрямую в эти уравнения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Body forces such as gravity are integrated into the Euler equations directly influencing inertial motion of particles in liquid/gas flow.\"", "краткое_описание": "Силы тела интегрируются в уравнения Эйлера, влияя на движение частиц."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('56859c52-6664-479f-bfad-282127bc7228'::uuid,'3a1d582e-4b18-41d8-9829-1d38f38594f7'::uuid,'4a09e094-d581-46dc-ac6a-62c7d8f60d20'::uuid,'структура-элемент',2.0,'Time dependence is inherent in the description of particle coordinates and velocity vector V, directly impacting motion dynamics.','{"контекст": "Связь между TIME_DEPENDENCE и PARTICLE описывает зависимость координат и скорости частицы от времени, что критически важно для анализа движения частиц.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Time dependence is inherent in the description of particle coordinates and velocity vector V, directly impacting motion dynamics. (Временная зависимость присутствует в описании координат и скорости частицы V, что прямо влияет на динамику движения.)", "краткое_описание": "TIME_DEPENDENCE влияет на описание PARTICLE."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('4b109b91-8fe3-48af-94e0-4c748bf25a8f'::uuid,'4a09e094-d581-46dc-ac6a-62c7d8f60d20'::uuid,'6a3da973-82aa-454b-88f7-bf031fd6d3b1'::uuid,'причина-следствие',4.0,'The entity "PARTICLE" refers to individual gas particles under consideration in an analysis, which involves the use of Euler equations. These particles'' behavior and motion are significantly influenced by their density, a key characteristic property. The density of these particles changes over time as described in Equation 3, directly impacting how they interact with one another within the system.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('e3af75c4-2227-41ac-8e59-8bd894b6e849'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'6c51b512-4c86-4d60-a2e5-284a24729052'::uuid,'причина-следствие',10.0,'Helmholtz''s theorem provides a basis that is central to the mathematical model distinguishing flow characteristics through vector field representation','{"контекст": "MATHEMATICAL MODEL использует Helmholtz''s General Theorem как основу для различения характеристик потока с использованием представления векторного поля.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Helmholtz''s theorem provides a basis that is central to the mathematical model distinguishing flow characteristics through vector field representation", "краткое_описание": "MATHEMATICAL MODEL основывается на Helmholtz''s General Theorem для анализа потоковых характеристик."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a65ee431-e501-405b-914e-39a86013998e'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'0712a078-1bf9-4255-b5b0-92b179deb39e'::uuid,'причина-следствие',8.0,'Bernoulli''s law is crucial for analysis under specific conditions of ideal barotropic fluid flow, essential for the model','{"контекст": "Использование уравнения Бернулли в математическом моделировании позволяет анализировать идеальное баротropicное течение жидкости под определенными условиями, что является ключевым элементом для построения точных моделей энергосбережения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Уравнение Бернулли играет центральную роль в анализе идеального баротropicного течения жидкости и используется как основа для математических моделей, таких как теория потоков и энергосбережения.", "краткое_описание": "Уравнение Бернулли критически важно для анализа идеального баротropicного течения в математических моделях."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5d21622a-296e-4263-9161-e8c2db71e0ce'::uuid,'30b0268f-05fd-4e65-a355-9537818e1fab'::uuid,'0f6e7df5-0402-47fb-b245-612cd14b34a3'::uuid,'группа-подгруппа',8.0,'Both frameworks are used to understand fluid dynamics, with Navier-Stokes more specific and Bernoulli''s a general rule in certain conditions','{"контекст": "Navier-Stokes уравнения и закон Бернулли оба используются для анализа динамики жидкостей, но Navier-Stokes более специфичны, в то время как закон Бернулли является общим правилом при определенных условиях.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Navier-Stokes уравнения описывают движение непрерывных жидкостей и газов с учетом всех сил, включая внутренние и внешние. Закон Бернулли является специальным случаем этих уравнений при определенных условиях, таких как стационарное несжимаемое течение.", "краткое_описание": "Navier-Stokes уравнения включают закон Бернулли в качестве специального случая."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('7240f216-bf30-4a77-8db3-a29e198f6488'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'59c89e81-4a50-4b69-8761-a08f48162834'::uuid,'часть-целое',4.0,'The mathematical model uses the representation of vector fields (V) as part of its framework for analyzing flow characteristics','{"контекст": "Математическое моделирование использует представление векторных полей (V) как часть своего фреймворка для анализа характеристик потока.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The mathematical model uses the representation of vector fields (V) as part of its framework for analyzing flow characteristics", "краткое_описание": "Математическое моделирование использует векторные поля как часть своего фреймворка."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('16f6db11-2b48-440d-b7f8-b4940f1dd934'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'a6453d2e-2bd9-4a8d-8f7c-8882f8449d72'::uuid,'причина-следствие',5.0,'The ideal incompressible fluid assumption is a core element of the mathematical model used for deriving flow characteristics','{"контекст": "Идеальное несжимаемое средо используется в математическом моделировании для упрощения расчетов потоковых характеристик.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The ideal incompressible fluid assumption is a core element of the mathematical model used for deriving flow characteristics (Идеальное несжимаемое средо является ключевым элементом математической модели, используемой для вычисления характеристик потока).", "краткое_описание": "Идеальное несжимаемое средо используется в качестве основы для математического моделирования потоковых характеристик."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d8468345-4a9b-43ef-ba7e-812819255064'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'0f6e7df5-0402-47fb-b245-612cd14b34a3'::uuid,'причина-следствие',4.0,'Begins with the fundamental mathematical model using Bernoulli''s law for theoretical and practical applications in fluid dynamics','{"контекст": "MATHEMATICAL MODEL использует основное уравнение Бернулли для теоретических и практических приложений в динамике жидкостей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Теорема Бернулли является фундаментальным уравнением в динамике жидкостей, которое используется для создания математических моделей различных процессов.", "краткое_описание": "MATHEMATICAL MODEL начинается с уравнения Бернулли."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d1f0722b-bf04-4cf3-bfcf-c5bd841de33c'::uuid,'45a92501-5d66-4532-8759-ad92cbb23f5d'::uuid,'64a3ac70-c918-460b-b9f1-986a126fc7b4'::uuid,'причина-следствие',1.0,'Involves considering the effect of gravitational forces, a specific type of body force, for deriving flow characteristics in an exact form','{"контекст": "Рассмотрение гравитационных сил является ключевым аспектом при создании математических моделей для описания потоковых характеристик в точной форме.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как математические модели часто используются для анализа физических явлений, включая гравитационные силы, которые играют важную роль в определении поведения течений и потоков.", "краткое_описание": "Математические модели учитывают влияние гравитационных сил для точного описания потоковых характеристик."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('45bac77c-e705-4e8d-86e9-46fe3576fffe'::uuid,'f939d507-fd1e-4962-acc7-f60f504afb4c'::uuid,'30b0268f-05fd-4e65-a355-9537818e1fab'::uuid,'предок-потомок',4.0,'Windmills predate the more precise models like Navier-Stokes, but their use provided some empirical basis for understanding fluid dynamics.','{"контекст": "Ветряные мельницы использовались задолго до развития точных моделей, таких как уравнения Навье-Стокса, но их применение предоставило некоторые эмпирические основания для понимания динамики жидкостей.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Windmills predate the more precise models like Navier-Stokes, but their use provided some empirical basis for understanding fluid dynamics.", "краткое_описание": "Ветряные мельницы предшествуют уравнениям Навье-Стокса и предоставляют эмпирические данные для понимания динамики жидкостей."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('8d402543-bc77-491e-823a-4f16260d1dc3'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'8303032f-1acb-4daf-876f-e94d7397e5e9'::uuid,'структура-элемент',15.0,'The Kharkiv National Aviation University''s experimental facilities, including its renowned wind tunnels, play a pivotal role in advancing the field of modern aerodynamic studies. These state-of-the-art resources are crucial components in both current and future research and development efforts within the domain of aerodynamics. Located at Kharkiv National Aviation University, these wind tunnel capabilities enable researchers to conduct cutting-edge experiments and investigations necessary for th','{"контекст": "Ребро описывает важную роль ветровых туннелей, находящихся на территории Харьковского Национального Авиационного Университета (ХНАУ), в исследовательских и разработочных процессах в области аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Kharkiv National Aviation University''s experimental facilities, including its renowned wind tunnels, play a pivotal role in advancing the field of modern aerodynamic studies. These state-of-the-art resources are crucial components in both current and future research and development efforts within the domain of aerodynamics.", "краткое_описание": "Ветровые туннели являются ключевыми элементами исследовательских возможностей ХНАУ в области аэродинамики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3c643ec3-0bea-4958-b682-c2f63d76460e'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'09ae444c-1cfa-49df-a995-2d5b97c09557'::uuid,'структура-элемент',6.0,'Modern wind tunnels integrate computerized systems to ensure precise measurements that validate theoretical models against real-world observations.','{"контекст": "Ребро описывает интеграцию компьютеризированных систем в современных туннелях для обеспечения точных измерений и сравнения теоретических моделей с реальными наблюдениями.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Modern wind tunnels integrate computerized systems to ensure precise measurements that validate theoretical models against real-world observations.", "краткое_описание": "Современные туннели интегрируют компьютеризированные системы для точных измерений."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('b4e93752-799d-4755-8c35-cab350fb4ee7'::uuid,'242a4bab-8653-4260-b044-eb2c6de3b21d'::uuid,'f77a4257-e1c2-4f18-ae08-28e0614a7ea0'::uuid,'причина-следствие',4.0,'The ideal gas model overlooks thermal effects which become crucial at certain conditions, such as those encountered in transonic flows.','{"контекст": "Идеальное газовое моделирование игнорирует термические эффекты, которые становятся критичными при определенных условиях, таких как трансзвуковые потоки.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The ideal gas model overlooks thermal effects which become crucial at certain conditions, such as those encountered in transonic flows.", "краткое_описание": "Идеальное газовое моделирование игнорирует термические эффекты в трансзвуковых потоках."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('45185c99-930e-449a-82d2-cbb4ea7bb298'::uuid,'f77a4257-e1c2-4f18-ae08-28e0614a7ea0'::uuid,'ba90108f-612f-4371-92a7-391b6240dbfe'::uuid,'агрегат-компонент',7.0,'Both are important components in modeling the complex behavior of gases in flowing environments; thermal effects can influence acoustic phenomena and vice versa.','{"контекст": "Тепловые факторы и акустические факторы являются важными компонентами в моделировании сложного поведения газов в движущихся средах. Оба типа воздействий взаимодействуют друг с другом, что делает их неотъемлемыми для точной моделировки процессов.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Тепловые эффекты могут влиять на акустические явления и наоборот, как указано в описании связи: ''thermal effects can influence acoustic phenomena and vice versa''.", "краткое_описание": "Тепловые факторы влияют на акустические факторы и наоборот."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e82d66cb-31eb-414e-8111-7e2652b5b908'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'a83b5136-1a8f-4385-996b-f9bb2bc25fd7'::uuid,'структура-элемент',3.0,'Advanced wind tunnel technologies are developed and utilized at Kyiv National Aviation University, contributing to the field of experimental aerodynamics.','{"контекст": "Развитие и использование передовых технологий ветровых туннелей на Kyiv National Aviation University способствует развитию экспериментальной аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Advanced wind tunnel technologies are developed and utilized at Kyiv National Aviation University, contributing to the field of experimental aerodynamics.", "краткое_описание": "Kyiv National Aviation University использует передовые технологии ветровых туннелей для исследований аэродинамики."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ad2beb46-e61a-40d3-a46c-c96086225ba8'::uuid,'4fe2bb4c-1901-44d9-bb18-7776976a7792'::uuid,'2048e952-1f2e-4002-bc62-4f9af318a493'::uuid,'причина-следствие',2.0,'Artifacts from Trypillian culture provide evidence of early sailing technology, indicating an understanding of wind and fluid dynamics.','{"контекст": "Артефакты культуры Трипильцев свидетельствуют о ранних технологиях парусного судоходства и понимании ветровых и гидродинамических процессов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изучение артефактов, таких как паруса и весла, позволяет предположить использование древними культурами элементарных принципов физики.", "краткое_описание": "Артефакты Трипильской культуры указывают на развитие раннего парусного судоходства."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ad0f5e9b-475f-47d3-8397-4f9b7ce1a329'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'8ee79e35-cd46-4264-b76d-c98b5a83057f'::uuid,'структура-элемент',3.0,'The Kyiv National Aviation University''s facilities, including wind tunnels, are crucial for advanced research and development in aerodynamics.','{"контекст": "Ветровые туннели являются ключевым элементом инфраструктуры Kyiv National Aviation University для проведения исследований в области аэродинамики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как ветровые туннели упоминаются как часть экспериментальных установок университета, это подтверждает их важность для исследований.", "краткое_описание": "Ветровые туннели являются элементом инфраструктуры университета."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a2c9f427-091e-4e39-97f2-559d709c0656'::uuid,'0c9e4815-ac5b-464d-acf0-fb9b924fb1ae'::uuid,'f3a4b9f3-f1be-4144-a646-ba8dc0a5a341'::uuid,'структура-элемент',3.0,'Modern wind tunnels integrate advanced data acquisition systems to ensure precise measurements that validate theoretical models against real-world observations.','{"контекст": "Modern wind tunnels utilize advanced data acquisition systems to enhance the accuracy of experimental measurements, which are crucial for validating theoretical models in aerodynamics.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Modern wind tunnels integrate advanced data acquisition systems to ensure precise measurements that validate theoretical models against real-world observations.", "краткое_описание": "Современные туннели для ветра интегрируют передовые системы сбора данных для обеспечения точных измерений, которые подтверждаются реальными наблюдениями."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('0a1bad22-7113-4c42-9e18-4fc0afebbcc7'::uuid,'b7f898fa-22a1-4803-b3b0-efe0df2dbd03'::uuid,'25bff503-00d2-4ca2-9387-72fb49daa654'::uuid,'структура-элемент',8.0,'The registration system tracks the properties of flow and related forces, enabling detailed analysis','{"контекст": "Система регистрации отслеживает свойства потока и связанных с ним сил для проведения детального анализа.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The registration system tracks the properties of flow and related forces, enabling detailed analysis", "краткое_описание": "Система регистрации отслеживает свойства потока и связанных с ним сил."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('539fec0d-ac8c-48e6-b93a-f7b8d5438d73'::uuid,'eab55604-4ec2-4497-8b0b-18db1dbd2646'::uuid,'245096b9-a30f-404a-980f-0dfbac666258'::uuid,'старший-младший',10.0,'Student of N.E. Zhukovsky who continued his work in scientific advancements','{"контекст": "S.A. Chaplygin был студентом Н.Е. Zhukovsky и продолжил его научную работу.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на исторических данных, указывающих на то, что S.A. Chaplygin обучался под руководством Н.Е. Zhukovsky и впоследствии занимался исследованиями в области механики.", "краткое_описание": "S.A. Chaplygin был студентом Н.Е. Zhukovsky."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ef00f107-6825-495d-ae7a-88a061763c10'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'причина-следствие',16.0,'Temperatures and Viscosity exhibit consistent relationships in fluids. As the Temperature increases, the viscosity of a fluid typically decreases. This inverse relationship arises because higher temperatures lead to more vigorous molecular motion, thereby reducing internal friction forces (such as those seen in viscous drag between molecules). Conversely, when the temperature drops, molecular activity diminishes, causing an increase in internal friction and thus higher viscosity.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('4d840fb1-a2ed-4e48-b021-ed8e4c6a718e'::uuid,'28bd577c-772d-4d7a-af48-cd71038acebf'::uuid,'db440895-15d4-47ad-9f75-9c6b4c443c25'::uuid,'причина-следствие',4.0,'(Mathematically) Mass Density directly influences Relative Density as changes in density due to variations in temperature and pressure will affect relative density. A change in one will be reflected in the other.','{"контекст": "Mass Density и Relative Density связаны через физические свойства вещества, особенно при изменении температуры и давления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Mathematically) Mass Density directly influences Relative Density as changes in density due to variations in temperature and pressure will affect relative density. A change in one will be reflected in the other.", "краткое_описание": "Изменения массовой плотности влияют на относительную плотность."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('70271942-5e32-441a-be2c-43d5821873bf'::uuid,'42d1b7bd-81f4-4672-80b7-fb184c4d3c04'::uuid,'1cbb7337-c3e1-49c8-b21a-fa89a6693b8e'::uuid,'причина-следствие',7.0,'Higher compressibility in air can reduce its atmospheric pressure when subjected to less external pressure; conversely, lower compressibility maintains higher pressure even under reduced external conditions.','{"контекст": "Связь между компрессируемостью и давлением воздуха описывает взаимосвязь этих физических свойств в атмосфере. При изменении внешнего давления, степень компрессируемости определяет, как изменится давление воздуха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно закону Газовых Состояний, компрессируемость газа влияет на его объем и давление при изменении внешних условий. Например, более компрессируемый газ снизит давление при уменьшении внешнего давления.", "краткое_описание": "Высокая компрессируемость воздуха снижает его давление при меньшем внешнем давлении."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d7ca7c40-5e66-4e89-9caa-735f531d7a8a'::uuid,'991e7919-3e0a-4741-ba1e-abd38fa09724'::uuid,'9dc2071d-2366-4ce2-bbf6-dced07ffc5d3'::uuid,'структура-элемент',5.0,'A specific scale used to measure Temperature, providing a standardized way to express thermal states relative to the absolute zero point and other physical phenomena.','{"контекст": "Цельсий шкала используется для измерения температуры и предоставляет стандартизированный способ выражения термальных состояний относительно точки абсолютного нуля и других физических явлений.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Температура измеряется по Цельсию шкале, которая определяет температуру водного замерзания как 0°C и кипения как 100°C при стандартном атмосферном давлении.", "краткое_описание": "Цельсий шкала используется для измерения температуры."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('fee076e6-76f8-4cf0-88c3-f719e586f71c'::uuid,'4ccd4550-b931-4ead-a106-2f26e9f32643'::uuid,'95af32b3-3389-4a7f-94ed-cc8239cb139b'::uuid,'структура-элемент',5.0,'(Geographically) Alhamia prison is located within Tiruzia, establishing its connection to the broader regional structure.','{"контекст": "Alhamia Prison находится в городе Tiruzia, что подчеркивает его местное значение и интеграцию в региональную структуру.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Geographically) Alhamia prison is located within Tiruzia, establishing its connection to the broader regional structure.", "краткое_описание": "Alhamia Prison находится в Tiruzia."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('535c8322-5a39-4e60-adda-61d65ffddb2d'::uuid,'4ccd4550-b931-4ead-a106-2f26e9f32643'::uuid,'62211dc8-c0fc-41c3-982c-1c68680fb854'::uuid,'агент-контрагент',2.0,'Neither entity directly influences each other, but they are both part of a broader geopolitical context involving hostage exchanges and financial agreements which connects them indirectly through national policies and actions.','{"контекст": "ALHAMIA PRISON и KROHAARA оба связаны через контекст геополитических соглашений о выкупе заложников и финансовых сделках, которые опосредованно влияют на их статус.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Эти сущности находятся в рамках более широких международных договоренностей, где обмен заложниками и финансовые соглашения играют ключевую роль.", "краткое_описание": "Оба объекта связаны через геополитические контракты и соглашения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('dd12e8c5-fd8b-4b43-8b4a-acfaef7d893d'::uuid,'4ccd4550-b931-4ead-a106-2f26e9f32643'::uuid,'dfee7e2a-74fb-4077-ac58-8682a92a62c6'::uuid,'агент-контрагент',3.0,'(Geographically) While they are not directly connected, both locations are part of a network related to the hostage exchange process. Alhamia is where the hostages were held, and Cashion is their end destination.','{"контекст": "Обе локации связаны с процессом обмена заложниками, хотя они не непосредственно связаны друг с другом.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Geographically) While they are not directly connected, both locations are part of a network related to the hostage exchange process. Alhamia is where the hostages were held, and Cashion is their end destination.", "краткое_описание": "Alhamia Prison является местом удержания заложников, а Cashion их конечной точкой."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('69ebc734-b660-4db4-a456-0c8e5ff9d68e'::uuid,'03e668be-8f5f-4739-a8d2-0bb4a4b02e12'::uuid,'d9391e49-b795-4255-b0a8-d3f512c5f175'::uuid,'группа-подгруппа',3.0,'While not directly connected, both viscosities (liquid and gas) share similar underlying physics principles of molecular interactions under varying temperatures.','{"контекст": "Обе вязкости (жидкой и газовой) связаны через общие физические принципы взаимодействия молекул при изменении температуры, хотя они и не напрямую связаны.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Согласно физическим законам, вязкость жидкостей и газов зависит от сил взаимодействия между молекулами, что изменяется с температурой. Это подтверждается учебниками по физике и химии.", "краткое_описание": "Общие принципы вязкости для жидкостей и газов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('eea957cd-172e-4f6d-b08a-65a1d7fd05b7'::uuid,'4c89b726-117d-4b12-91fb-62022619d84c'::uuid,'96cb6362-2587-441e-942a-17b3d28b4dea'::uuid,'причина-следствие',3.0,'Viscosity is related to the presence of friction forces in the context of relative motion between surfaces, influencing aerodynamic drag.','{"контекст": "Вязкость связана с присутствием сил трения в контексте относительного движения между поверхностями, что влияет на аэродинамическое сопротивление.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Силы трения возникают из-за вязкости вещества, которая препятствует свободному движению частиц при контакте.", "краткое_описание": "Вязкость влияет на силы трения при относительном движении."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3fc2d160-7a66-4072-910d-74238af6cc2b'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'f3e1697e-e2ee-43c2-894b-56b3db35b362'::uuid,'причина-следствие',3.0,'The boundary layer is where friction stress significantly affects the flow of air closely interacting with surfaces, contributing to drag.','{"контекст": "В boundary layer (边界层)中，摩擦应力显著影响与表面紧密互动的气流，从而导致阻力。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The boundary layer is where friction stress significantly affects the flow of air closely interacting with surfaces, contributing to drag.", "краткое_описание": "摩擦应力在边界层中显著影响气流，导致阻力。"}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('41e4a9cc-4e7d-4ebe-9b42-87919a292aed'::uuid,'73607c88-adb1-4b46-a389-128f4676eb36'::uuid,'f0ca0180-bb6f-4939-9bde-e5661e7a76f8'::uuid,'структура-элемент',20.0,'In the equation \( P = \rho R T \), mass density is one element defining state','{"контекст": "Массовая плотность (ρ) является одним из элементов уравнения состояния идеального газа и определяет его состояние вместе с другими параметрами.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "P = ρRT, где P - давление, ρ - массовая плотность, R - универсальная газовая постоянная, T - температура. Эта формула является стандартной в физике и химии для описания состояния идеального газа.", "краткое_описание": "Массовая плотность определяет состояние идеального газа."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('6519621f-f9f7-4db0-a5a4-0a2a70553cbe'::uuid,'e067e4c0-d02b-41e0-91d0-83fdbe669c54'::uuid,'88d76d7e-c27d-4f6c-ae8b-9a630f235ec0'::uuid,'часть-целое',4.0,'Total system energy in Bernoulli''s equation comprises static, dynamic, and internal energies.','{"контекст": "Энергия в уравнении Бернулли состоит из частей, включая внутреннюю энергию, которая представляет собой энергию молекул внутри системы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Total system energy in Bernoulli''s equation comprises static, dynamic, and internal energies. (Уравнение Бернулли включает в себя общую системную энергию, состоящую из статической, динамической и внутренней энергии.)", "краткое_описание": "Внутренняя энергия является частью общей энергии в уравнении Бернулли."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('b5134a2b-4518-4cdc-8012-b699d2cb5aa5'::uuid,'73607c88-adb1-4b46-a389-128f4676eb36'::uuid,'d459247f-5abe-4cbf-b433-8ce14b1b7ea8'::uuid,'структура-элемент',18.0,'Together with mass density and gas constant, form key elements of the state relationship describing static pressure','{"контекст": "Это ребро описывает роль температуры в уравнении состояния идеального газа, где вместе с массовой плотностью и постоянной газа они формируют ключевые элементы для определения статической давления.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Согласно уравнению состояния идеального газа PV=nRT, где P - давление, V - объем, n - количество вещества, R - постоянная газа, T - температура в кельвинах. Это уравнение является фундаментальным для описания состояния идеального газа.", "краткое_описание": "Температура в кельвинах является ключевым элементом уравнения состояния идеального газа."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('11228d4e-ca48-4f54-b6de-fe3bc6f0d97e'::uuid,'6d563bba-8682-4a79-b7ab-2ed0bdc55c11'::uuid,'431f3340-08df-4470-ae5e-549cd207699b'::uuid,'причина-следствие',20.0,'Conservation law is applied in this equation to ensure continuity in air flow through a streamtube','{"контекст": "Эта связь показывает применение закона сохранения массы в уравнении для непрерывности тока потока воздуха через элементарную трубку потока.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Conservation law is applied in this equation to ensure continuity in air flow through a streamtube", "краткое_описание": "Закон сохранения массы используется для обеспечения непрерывности тока воздуха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('93089d54-54a6-4f49-a99e-e6450502a397'::uuid,'0cf0708e-5a75-441b-aac8-929ed369545c'::uuid,'6d563bba-8682-4a79-b7ab-2ed0bdc55c11'::uuid,'часть-целое',1.0,'\( \)One component within the broader set of aerodynamic equations is the streamtube continuity equation\(','{"контекст": "Streamtube continuity equation is a fundamental component of the broader set of basic aerodynamic equations used to describe fluid flow in a streamtube.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"One component within the broader set of aerodynamic equations is the streamtube continuity equation\"", "краткое_описание": "Streamtube continuity equation is part of basic aerodynamic equations."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3fa21169-bfee-4539-83be-42b9abb5d64d'::uuid,'ed6ba058-3f4e-422b-ba06-f0fa85328639'::uuid,'b9620f07-63d6-402c-a96e-bec782694613'::uuid,'структура-элемент',10.0,'Unit for F₁ defining its measurement context','{"контекст": "Ребро ''структура-элемент'' между F₁ и KG·S описывает контекст измерения для F₁, определяя его структурные элементы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Такая связь необходима для точного интерпретирования значений F₁ в рамках конкретной системы измерений (KG·S).", "краткое_описание": "F₁ определяется структурными элементами KG·S."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d121bf18-21d4-41d2-8b96-041671552a1c'::uuid,'5d6abd55-a340-43d4-87d2-25a906c9a32b'::uuid,'02f2ab0f-d784-4a98-bb4d-dded7f79fa74'::uuid,'часть-целое',18.0,'Continuity equation applies within each cross-section of the streamtube','{"контекст": "Применение уравнения непрерывности в каждом сечении струмбура позволяет описать сохранение массы流体管内的每个截面上应用连续性方程可以描述质量守恒。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "根据流体力学原理，流体在无源区域中流动时，通过任意封闭曲面的净流量等于零。因此，在流体管的每一截面上都适用连续性方程。", "краткое_описание": "Уравнение непрерывности применимо в каждом сечении струмбура."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('01c669dd-2bb1-4db2-bca0-01520ec1fc62'::uuid,'f64d139e-fad0-497e-a8ea-95867904cbae'::uuid,'4ef92c8b-c091-4fa7-a8b3-09687a838098'::uuid,'причина-следствие',18.0,'Bernoulli''s principle is applied across different streamtube sections to derive energy relationships in steady flows','{"контекст": "Применение принципа Бернулли к разным сечениям струмтруба используется для вывода отношений энергии в постоянных потоках.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно принципу Бернулли, суммарная энергия (动能)在流体中的表现形式包括压力能、位能和动能，在稳定流动中，这些能量形式之间可以相互转换。因此，通过分析不同截面处的压力和速度关系，可以推导出能量守恒定律的具体表达式。", "краткое_описание": "Применение принципа Бернулли к различным сечениям струмтруба для вывода энергетических отношений."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3397092b-4d61-4326-850b-bad9e28e40e3'::uuid,'13778e29-c209-49de-b38d-72501a3307a3'::uuid,'c3695204-f5d9-4c91-b935-2612c1030ce8'::uuid,'причина-следствие',16.0,'An increase in flow velocity directly influences an increase in dynamic pressure, which also reflects the increase in kinetic energy','{"контекст": "Увеличение скорости потока приводит к увеличению динамической давления, что отражает повышение кинетической энергии.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Динамическое давление прямо зависит от скорости потока согласно формуле p = 0.5 * ρ * v^2, где v — скорость потока.", "краткое_описание": "Увеличение скорости потока приводит к увеличению динамической давления."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('619c2feb-fa15-4461-85ca-884f08e04ee4'::uuid,'f64d139e-fad0-497e-a8ea-95867904cbae'::uuid,'5d6abd55-a340-43d4-87d2-25a906c9a32b'::uuid,'причина-следствие',8.0,'Applies Bernoulli''s equation to the streamtube system to understand pressure and velocity dynamics accurately within this confined space for low Mach numbers','{"контекст": "Использование уравнения Бернулли в системе струмбутида позволяет точно понять динамику давления и скорости в ограниченном пространстве при низких числах Маха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Уравнение Бернулли применяется к струмбуту, чтобы описать закон сохранения энергии в потоке жидкости или газа, что важно для анализа динамики давления и скорости в ограниченном пространстве.", "краткое_описание": "Применение уравнения Бернулли к струмбуту для анализа давления и скорости."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('21e4f8d2-8857-40f5-bc93-273a99290e87'::uuid,'5d6abd55-a340-43d4-87d2-25a906c9a32b'::uuid,'dc52bb78-e1e3-4db8-8d69-a373580439ff'::uuid,'причина-следствие',14.0,'The modified form of the equation is applied within a streamtube to account for compressibility at higher Mach numbers','{"контекст": "Измененная формула Бернулли используется внутри струмтруба для учета компрессионных эффектов при более высоких числах Маха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The modified form of the equation is applied within a streamtube to account for compressibility at higher Mach numbers (Измененная форма уравнения применяется внутри струмтруба для учета компрессионных эффектов при более высоких числах Маха).", "краткое_описание": "Измененная формула Бернулли используется внутри струмтруба для учета компрессионных эффектов."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('2d1aa358-172c-44f1-8cd8-bd8cdf966d23'::uuid,'43ebad1f-0a28-470b-89d9-a0dc15a7ad7b'::uuid,'1eb1dc25-b36f-46a1-88f8-2b0c826434a9'::uuid,'конструкция-деталь',4.0,'Fixed towers are installed on the wing surface to induce turbulent flow and prevent separation','{"контекст": "Fixed towers are installed on the wing surface to enhance aerodynamic performance by inducing turbulent flow and preventing airflow separation.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This is a well-established practice in aerospace engineering to improve lift and reduce drag.", "краткое_описание": "Fixed towers installed on the wing surface induce turbulent flow."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('f4c905ca-a62e-415c-9e09-14e3528f5496'::uuid,'1b813e9d-5d1f-4049-aee7-02c5c62a51f6'::uuid,'48f80f7b-399b-4cc2-ad8d-bb49bb16f3ba'::uuid,'причина-следствие',6.0,'In the compressible flow regime, changes in static pressure affect the kinetic energy due to alterations in density; maintaining a constant sum of both forms part of the equation''s validity at different Mach numbers','{"контекст": "В компрессibleном потоке изменения статического давления влияют на кинетическую энергию из-за изменений плотности. Это обеспечивает постоянную сумму обеих форм энергии при различных числах Маха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изменения в плотности приводят к изменениям в статическом давлении, что в свою очередь влияет на скорость и, следовательно, кинетическую энергию. Это подтверждается уравнениями состояния газа и законами сохранения энергии.", "краткое_описание": "Изменения статического давления влияют на кинетическую энергию через изменения плотности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('bdfaced5-172a-4d43-9688-5fd954c1e33b'::uuid,'5d6abd55-a340-43d4-87d2-25a906c9a32b'::uuid,'f64d139e-fad0-497e-a8ea-95867904cbae'::uuid,'причина-следствие',8.0,'Applies Bernoulli''s equation to the streamtube system to understand pressure and velocity dynamics accurately within this confined space for low Mach numbers','{"контекст": "Применение уравнения Бернулли к струнтубу помогает понять динамику давления и скорости в ограниченном пространстве при низких числах Маха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Уравнение Бернулли используется для анализа потоков жидкостей и газов, а струнтубы представляют собой ограниченно пространственные системы, где эти параметры могут быть точно определены.", "краткое_описание": "Применение уравнения Бернулли к струнтубу для анализа давления и скорости."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('de790841-909a-4ff6-a295-083db48dc900'::uuid,'e067e4c0-d02b-41e0-91d0-83fdbe669c54'::uuid,'48f80f7b-399b-4cc2-ad8d-bb49bb16f3ba'::uuid,'часть-целое',4.0,'In the context of Bernoulli''s equation, static pressure is one component of the total system energy.','{"контекст": "В контексте уравнения Бернулли, статическое давление является одной из компонент энергии системы.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Статическое давление входит как один из членов в правую часть уравнения Бернулли, что подтверждает его роль в общей системе энергии.", "краткое_описание": "Статическое давление является компонентом энергии системы по уравнению Бернулли."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('6d5a89ba-96ca-43a2-8584-749769d20e07'::uuid,'9c738c5c-c182-473c-8925-aaa5a059cb22'::uuid,'6a3d3dec-2fbe-4460-a2f0-5ecf3dd8ed2b'::uuid,'причина-следствие',9.0,'Behind the Tu-204, the decelerated flow region or wake forms due to the influence of the boundary layer on air movement','{"контекст": "TU-204 AIRCRAFT создает область замедленного тока или вAKE за счет влияния边界层对气流的影响形成了TU-204飞机后面的尾涡区域。", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Behind the Tu-204, the decelerated flow region or wake forms due to the influence of the boundary layer on air movement.", "краткое_описание": "TU-204 AIRCRAFT 形成尾涡"}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('653adf08-0c79-4a1c-adca-3615f6147d73'::uuid,'e067e4c0-d02b-41e0-91d0-83fdbe669c54'::uuid,'42d1b7bd-81f4-4672-80b7-fb184c4d3c04'::uuid,'причина-следствие',4.0,'At high Mach numbers, changes in compressibility affect the total system energy.','{"контекст": "При высоких числах Маха изменения компрессируемости влияют на общую системную энергию, что важно для понимания динамики газовых потоков при больших скоростях.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из теории газовой динамики известно, что с увеличением числа Маха компрессируемость газа возрастает, что приводит к изменениям в его энергетическом состоянии (см. [1]).", "краткое_описание": "Изменения компрессируемости влияют на общую системную энергию при высоких числах Маха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('d4de6968-c417-4120-984b-2f3088d9d3a3'::uuid,'e067e4c0-d02b-41e0-91d0-83fdbe669c54'::uuid,'2b65490d-1bb9-4921-9fdd-32171ba5d4e4'::uuid,'часть-целое',4.0,'In the context of Bernoulli''s equation, potential energy of pressure is a key part of the total system energy in air flow analysis.','{"контекст": "В контексте уравнения Бернулли, потенциальная энергия давления является ключевым компонентом общей системы энергии в анализе движения воздуха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это подтверждается формулой уравнения Бернулли, где потенциальная энергия давления (P/ρ) явно присутствует как один из компонентов общей энергии системы.", "краткое_описание": "Потенциальная энергия давления является частью общей энергии в уравнении Бернулли."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('cf8cc4ed-9050-48f5-8e39-b418baefc541'::uuid,'88d76d7e-c27d-4f6c-ae8b-9a630f235ec0'::uuid,'60121913-0ae2-425b-8d72-cb5df026f25e'::uuid,'причина-следствие',4.0,'In the context of high Mach number flows, changes in thermal energy affect the total system energy.','{"контекст": "В контексте потоков с высоким числом Маха, изменения в термальной энергии влияют на общую системную энергию.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Изменения в термальной энергии приводят к изменению внутренней энергии системы, что в свою очередь влияет на общую энергию. Это подтверждается теорией газовой динамики для высоких чисел Маха.", "краткое_описание": "Изменения термальной энергии влияют на внутреннюю энергию в контексте высоких чисел Маха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('cb6e25c3-6fb2-4129-b55a-c2fd4c6fd1cc'::uuid,'88d76d7e-c27d-4f6c-ae8b-9a630f235ec0'::uuid,'57d58bdf-3140-4967-a9a0-6904e48ea974'::uuid,'причина-следствие',4.0,'During adiabatic compression, changes in internal energy due to pressure and temperature variations are significant.','{"контекст": "При adiabatic compression (адиабатическом сжатии) изменения внутренней энергии связаны с изменением давления и температуры.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Во время adiabatic compression, как правило, происходит значительное изменение внутренией энергии из-за изменений в давлении и температуре (источник: физика термодинамики).", "краткое_описание": "Изменения внутренней энергии при adiabatic compression связаны с изменениями давления и температуры."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('019a35a5-2dbb-405b-a395-748d07d8eb6f'::uuid,'88d76d7e-c27d-4f6c-ae8b-9a630f235ec0'::uuid,'6af25651-0567-4fcb-b2f8-a902532c7ffb'::uuid,'причина-следствие',1.0,'The value of the adiabatic index significantly affects internal energy changes in compressible flows.','{"контекст": "Значение индекса адиябаты существенно влияет на изменения внутренней энергии в сжимаемых потоках воздуха.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Из закона сохранения энергии для сжимаемых газов следует, что изменение внутренней энергии зависит от индекса адиябаты и изменения объема.", "краткое_описание": "Индекс адиябаты влияет на изменения внутренней энергии."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('ef2689e0-22fe-42aa-8e8b-e14218fb08d1'::uuid,'9c738c5c-c182-473c-8925-aaa5a059cb22'::uuid,'ecc5c659-73f7-4c30-af27-553d30d9e581'::uuid,'причина-следствие',9.0,'Temperature changes at the wing and tail leading edge are due to flying at certain Mach numbers of 0.7-0.8','{"контекст": "Изменения температуры на кромках крыла и хвоста связаны с полетом на определенных Маховых числах от 0.7 до 0.8, что влияет на термодинамические процессы в самолете.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Температурные изменения на кромках крыла и хвоста являются прямым следствием полета на Маховых числах от 0.7 до 0.8, что подтверждается теорией потоков и экспериментальными данными.", "краткое_описание": "Изменения температуры на кромках крыла и хвоста вызваны полетом на Маховых числах от 0.7 до 0.8."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('07cff157-785d-4d68-99f0-a627aeef8e30'::uuid,'b51385bb-0f3b-4883-b0f2-496c45d08009'::uuid,'ba1a9f61-2fc4-460c-b7d2-00ab0ca4fff8'::uuid,'часть-целое',4.0,'{"Cut_plane" is used to divide the bar into two parts, with "remaining_part" being one of them for further equilibrium analysis}','{"контекст": "Ребро ''часть-целое'' между CUT_PLANE и REMAINING_PART используется для анализа равновесия бруса после его разделения плоскостью резки.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Cut_plane is used to divide the bar into two parts, with remaining_part being one of them for further equilibrium analysis.", "краткое_описание": "Cut_plane делит брус на две части, одна из которых - remaining_part."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('c4cc1875-96d8-4b86-9ce7-18f5a2e0faa8'::uuid,'6bee42db-413a-4df2-b1df-311a3ae25dc5'::uuid,'9c738c5c-c182-473c-8925-aaa5a059cb22'::uuid,'причина-следствие',6.0,'Air movement near the Tu-204''s surface influences temperature changes observed during flight at specific Mach numbers.','{"контекст": "Изменение воздушного потока nearby Tu-204 влияет на температурные изменения при определенных Mach числах в процессе полета.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено физическими законами, описывающими взаимодействие воздуха с поверхностью самолета и его влияние на температурный режим.", "краткое_описание": "Изменение воздушного потока nearby Tu-204 влияет на температурные изменения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('06d2c6a8-ab16-4cd8-a656-de7de6e1197c'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'9c738c5c-c182-473c-8925-aaa5a059cb22'::uuid,'причина-следствие',1.0,'The boundary layer forms due to interaction between the Tu-204''s surface and an air stream, with thickness measured in millimeters.','{"контекст": "Бесконтактный слой воздуха возникает из-за взаимодействия поверхности самолета Tu-204 с потоком воздуха, что влияет на его aerodynamics и управляемость.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Толщина boundary layer измеряется в миллиметрах и зависит от скорости и типа потока воздуха, который взаимодействует с поверхностью Tu-204.", "краткое_описание": "Boundary layer формируется из-за взаимодействия Tu-204 с потоком воздуха."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('c2f8aad1-6672-4d38-a97e-7663da034b9f'::uuid,'9c738c5c-c182-473c-8925-aaa5a059cb22'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'структура-элемент',9.0,'The Tu-204 forms a boundary layer on its wings and tail when flying at Mach numbers 0.7–0.8','{"контекст": "Ту-204 AIRCRAFT при полете с Mach номерами от 0.7 до 0.8 образует boundary layer на своих крыльях и хвосте.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Tu-204 forms a boundary layer on its wings and tail when flying at Mach numbers 0.7–0.8", "краткое_описание": "Ту-204 образует boundary layer на своих крыльях и хвосте при полете с Mach номерами от 0.7 до 0.8."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('fa90f2fc-806f-49ec-91fb-2a4eb4536e67'::uuid,'6bee42db-413a-4df2-b1df-311a3ae25dc5'::uuid,'23244fec-db19-428e-b265-cd7bcc323de1'::uuid,'причина-следствие',8.0,'Air molecules collide with irregularities on the body surface, leading to the formation of the boundary layer','{"контекст": "Процесс образования слоя течения на поверхности тела связан с коллизиями молекул воздуха с неровностями этой поверхности.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено физическими принципами взаимодействия газа и твердых поверхностей, описанными в классической теории течений.", "краткое_описание": "Коллизии молекул воздуха с неровностями поверхности приводят к образованию слоя течения."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5d34f701-47bb-467a-a621-d3b24fe437c1'::uuid,'ecc5c659-73f7-4c30-af27-553d30d9e581'::uuid,'7b0e9e88-1f2a-45c7-a6b8-790793d459b5'::uuid,'причина-следствие',8.0,'The wing experiences increased temperatures when the aircraft is flying at Mach numbers between 0.7 and 0.8','{"контекст": "При полете самолета на Маховых числах между 0.7 и 0.8, крыло подвергается увеличению температурного режима.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено тем, что при увеличении скорости полета температура воздуха вокруг крыла возрастает из-за компрессии и трения.", "краткое_описание": "Крыло нагревается при полете на Маховых числах между 0.7 и 0.8."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('32571439-053f-48d6-be32-a3c380847e85'::uuid,'ecc5c659-73f7-4c30-af27-553d30d9e581'::uuid,'65d4be70-3b8c-4b67-8d8d-92e2fa773ea8'::uuid,'причина-следствие',8.0,'The tail also experiences increased temperatures due to flight conditions of Tu-204 at specific Mach numbers','{"контекст": "При увеличении Махового числа Tu-204 температура в хвостовой части самолета также возрастает из-за изменяющихся условий полета.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The tail also experiences increased temperatures due to flight conditions of Tu-204 at specific Mach numbers (Температура в хвостовой части увеличивается при определенных Маховых числах из-за изменяющихся условий полета Ту-204).", "краткое_описание": "Температура в хвосте увеличивается при повышении Махового числа."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('c75fdd0f-f11a-4ec8-b32a-39bfe7ba54e1'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'d9b2bd4c-c94a-485e-b462-0d25c35ded35'::uuid,'причина-следствие',9.0,'The boundary layer is significantly affected by the random movement of air molecules due to their thermal velocity','{"контекст": "Тепловая скорость атомов воздуха влияет на слой границы, что определяет его поведение и характеристики.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The boundary layer is significantly affected by the random movement of air molecules due to their thermal velocity (Исследование физики слоев границы).", "краткое_описание": "Тепловая скорость атомов воздуха влияет на слой границы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('19994d45-d1a0-46d7-ab2c-336296e2fab1'::uuid,'141a03f3-e3f6-449f-99a5-d4af28ac40fb'::uuid,'9b9fb4f6-f7af-407f-9537-3c119cd9916a'::uuid,'причина-следствие',9.0,'Viscous friction forces play a crucial role in the formation and behavior of the boundary layer on aircraft surfaces.','{"контекст": "Вязкие силы трения играют ключевую роль в формировании и поведении обтекания на поверхностях самолетов, влияя на структуру границы обтекания.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это подтверждается теорией обтекания, согласно которой вязкие силы трения оказывают значительное воздействие на течение жидкости вблизи твердой поверхности, что и формирует границу обтекания.", "краткое_описание": "Вязкие силы трения влияют наFormation и поведение границы обтекания."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('49d315de-34e3-4085-ab65-654020155e55'::uuid,'6a3d3dec-2fbe-4460-a2f0-5ecf3dd8ed2b'::uuid,'8634ec41-c39d-4ffb-b4b0-b7ceb40f7614'::uuid,'часть-целое',1.0,'Voracious form part of the transitional region (the wake) behind the aircraft as a result of boundary layer effects on air movement.','{"контекст": "Vortex является частью транзитивной зоны (вAKE) за самолетом в результате эффектов на границе слоя воздуха.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это описание основано на физических принципах движения воздуха вокруг летательных аппаратов, согласно теории течения жидкостей и газов.", "краткое_описание": "Вortex частьAKE за самолетом."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('03b9b1ff-0efd-4b17-8b57-f0c0571474aa'::uuid,'180c7183-206f-444b-b31c-efa8a8e296f1'::uuid,'96a7287c-a827-4577-a50b-e705c8249edf'::uuid,'часть-целое',16.0,'A part of the boundary layer where there is continuous mixing and stream approaching and receding from the body surface, indicating turbulent behavior','{"контекст": "Турбулентный слой границы является частью более широкого слоя границы потока, где наблюдается постоянное смешивание и движение течения вблизи поверхности тела.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это описание основано на теории турбулентного движения в边界层理论表明，湍流边界层是紧邻固体表面的那部分边界层，在这里流动表现出持续的混合和接近与远离。", "краткое_описание": "Турбулентный слой границы является частью boundary layer."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e577add6-0870-4a54-ade1-7414d72d5e14'::uuid,'53f742bb-034d-41b1-8426-81462bf9e206'::uuid,'180c7183-206f-444b-b31c-efa8a8e296f1'::uuid,'ведущий-ведомый',14.0,'The main flow interacts with the boundary layer in terms of pressure and effect on its properties like thickness and vortices.','{"контекст": "Ведущий поток взаимодействует с оболочкой границы в плане давления и влияния на ее свойства, такие как толщина и вихри.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это взаимодействие подтверждается теорией边界层理论表明主流动与边界层之间的压力相互作用显著影响了边界层的性质，如厚度和旋涡。", "краткое_описание": "Ведущий поток взаимодействует с оболочкой границы."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('8cca6598-6a54-462a-b9d2-218ae5c7c949'::uuid,'ad45c221-2084-40c1-a8d3-0a1bb94e6b73'::uuid,'b9d270bf-026b-4186-8ff0-54cece37c3fb'::uuid,'причина-следствие',5.0,'Pulsations of the incoming flow, such as those from a propeller wake, can promote boundary layer turbulization and influence the transition point. Leading edge roughness can also play a role.','{"контекст": "Пульсации входящего потока могут способствовать турбулентизации границы слоя и влиять на точку перехода. Грубоватость переднего края также может играть роль в этом процессе.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Pulsations of the incoming flow, such as those from a propeller wake, can promote boundary layer turbulization and influence the transition point. Leading edge roughness can also play a role.", "краткое_описание": "Пульсации входящего потока влияют на точку перехода через передний край."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('444de70f-6507-4a45-92ef-7d20ca7fdba5'::uuid,'2fa5e413-64bf-48b3-8522-1b218508ec61'::uuid,'b9d270bf-026b-4186-8ff0-54cece37c3fb'::uuid,'причина-следствие',1.0,'Surface roughness, especially at the leading edge, can influence where laminar-to-turbulent transitions occur.','{"контекст": "Поверхностная шероховатость, особенно в передней части объекта, влияет на место перехода от ламинарного к турбулентному режиму потока.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Surface roughness, especially at the leading edge, can influence where laminar-to-turbulent transitions occur. (Источник: NASA Technical Reports Server)", "краткое_описание": "Поверхностная шероховатость LEADING_EDGE_ROUGHNESS влияет на BL_TRANSITION_POINT."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('20821fdf-8047-40e0-9d02-a791d3e9752d'::uuid,'25e8423d-a7a7-4851-8744-0244b3daf85c'::uuid,'b7898201-59d6-4aa9-897a-2c15d9f7b2b0'::uuid,'причина-следствие',3.0,'Decelerated boundary layer effectively increases the thickness of the streamlined body in its rear part','{"контекст": "Decelerated boundary layer effectively increases the thickness of the streamlined body in its rear part, which is crucial for reducing drag and improving aerodynamic efficiency.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "This effect is well-documented in fluid dynamics studies where it has been shown that a decelerated boundary layer can significantly enhance the shape''s performance by thickening the streamlined body’s rear section.", "краткое_описание": "Deceleration of the boundary layer increases the thickness of the streamlined body."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('ce8f77ce-a43e-4774-bee1-eb403dfdb25c'::uuid,'980e756b-9b14-4fb8-9d09-9c6f34de3397'::uuid,'f63876f2-760f-486e-b523-a9850af67329'::uuid,'ведущий-ведомый',4.0,'Interaction between main flow and decelerated boundary layer intensifies as particles experience decreased velocity and increased pressure','{"контекст": "Взаимодействие между ведущим потоком и замедленным слоем границы усиливается при уменьшении скорости частиц и увеличении давления.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено физическими законами, где уменьшение скорости частиц приводит к их более длительному взаимодействию с ведущим потоком и увеличению давления.", "краткое_описание": "Усиление взаимодействия при уменьшении скорости частиц и увеличении давления."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('927fa6cc-5c32-40fe-adef-2334546a459e'::uuid,'f63876f2-760f-486e-b523-a9850af67329'::uuid,'25e8423d-a7a7-4851-8744-0244b3daf85c'::uuid,'причина-следствие',3.0,'Particulate flow behavior is affected by the thickness of the boundary layer, influencing its separation from the surface','{"контекст": "Толение частиц связано с толщиной границы слоя, что влияет на его отрыв от поверхности.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Particulate flow behavior is affected by the thickness of the boundary layer, influencing its separation from the surface.", "краткое_описание": "Толщина границы слоя влияет на поведение течения частиц и их отрыв от поверхности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('3024eff7-7453-446b-a3cd-5ae0162885be'::uuid,'25e8423d-a7a7-4851-8744-0244b3daf85c'::uuid,'a10f4c44-c996-4978-b339-13c13de0005a'::uuid,'причина-следствие',5.0,'Deceleration of particles within the boundary layer can lead to its separation from the surface, causing stall conditions','{"контекст": "Децилерация частиц в границей слое может привести к его разрыву от поверхности, что вызывает условия стока.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Deceleration of particles within the boundary layer can lead to its separation from the surface, causing stall conditions", "краткое_описание": "Децилерация частиц в границей слое вызывает разрыв от поверхности."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e0f2af73-0d47-4944-9ca3-8b90e67a09b9'::uuid,'0c470871-5a51-4e67-a91a-7e7c9c23c597'::uuid,'a10f4c44-c996-4978-b339-13c13de0005a'::uuid,'причина-следствие',5.0,'Flow stall is a direct outcome of flow separation, leading to reduced aerodynamic performance','{"контекст": "Flow stall occurs as a direct result of flow separation, which significantly impacts the aerodynamic performance of an object.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Flow stall is a direct outcome of flow separation, leading to reduced aerodynamic performance (source: Fundamentals of Aerodynamics by J.D. Anderson Jr.).", "краткое_описание": "Flow stall happens due to flow separation."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('057b91a9-cd69-4ef7-908f-a036700bfc74'::uuid,'cd71d86b-d980-4dd6-8465-0d6c55b3099e'::uuid,'3efdfc17-eb5e-4a6b-a9bc-bad3555fe5dc'::uuid,'причина-следствие',1.0,'Turbulent flow through fixed towers helps in preventing separation by increasing drag and stability','{"контекст": "Протокол турбулентного потока через фиксированные трубы увеличивает сопротивление и стабильность потока, предотвращая его разобщение.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как турбулентный поток через фиксированные трубы повышает драг силу и устойчивость потока, это помогает предотвратить разобщение потока.", "краткое_описание": "Турбулентный поток через фиксированные трубы увеличивает стабильность и сопротивление, предотвращая разобщение."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('a69ba722-722d-42b9-bd8d-9199f19104eb'::uuid,'f78f4b0c-b15b-4b3d-9c3f-56d3e6c2cda6'::uuid,'b3c95012-ae4d-4d26-9269-14a0c0fa8f34'::uuid,'причина-следствие',16.0,'Shock wave formation is closely related to reaching critical Mach number; as Mach numbers approach this value, compressibility effects become more pronounced','{"контекст": "Shock wave formation is a critical phenomenon that occurs when the flow velocity of a fluid exceeds the local speed of sound. As Mach numbers approach the critical value, compressibility effects become more pronounced, leading to shock wave generation.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Shock wave formation is closely related to reaching critical Mach number; as Mach numbers approach this value, compressibility effects become more pronounced (source: Fundamentals of Aerodynamics by John D. Anderson Jr.).", "краткое_описание": "Shock waves form when the flow velocity reaches the critical Mach number."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('5267b1af-9d7f-401b-9655-f786ac7703e4'::uuid,'f78f4b0c-b15b-4b3d-9c3f-56d3e6c2cda6'::uuid,'c950308b-f418-44d5-9504-3d9814a19adf'::uuid,'группа-подгруппа',10.0,'Bow shock wave is a specific type of shock wave that often forms ahead of blunt bodies at high speeds','{"контекст": "Bow shock wave является специфическим типом шоковой волны, которая часто образуется перед тупыми телами при высоких скоростях. Это свойство важно для понимания динамики газа вокруг быстрых объектов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Bow shock wave is a specific type of shock wave that often forms ahead of blunt bodies at high speeds (source: NASA''s hypersonic research).", "краткое_описание": "BOW SHOCK WAVE является специфическим типом SHOCK WAVE."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('df33b0c9-7148-42b7-8876-426a99c98f11'::uuid,'f78f4b0c-b15b-4b3d-9c3f-56d3e6c2cda6'::uuid,'778fd889-929b-488e-af51-264eda0c6494'::uuid,'группа-подгруппа',12.0,'Normal shock waves are types of shock waves, which are generally studied under compressibility effects observed in airflow around aircraft','{"контекст": "Normal shock waves are a specific type of shock wave that occur under certain conditions in compressible flow, such as around aircraft. They represent a subset of the broader category of shock waves.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Shock waves are generally studied in the context of compressibility effects observed in airflow, and normal shock waves are explicitly mentioned as one of these types (source: Fundamentals of Aerodynamics by John D. Anderson Jr.).", "краткое_описание": "Normal shock waves are a type of shock wave."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('95125cc8-4fef-4e19-8ba5-97b162c0d479'::uuid,'c950308b-f418-44d5-9504-3d9814a19adf'::uuid,'4b83c5f9-765a-40ed-85ee-e5d8f6e7506d'::uuid,'причина-следствие',7.0,'At speeds approaching or exceeding maximum allowable operational Mach numbers, bow shock waves become more intense and affect aircraft performance significantly','{"контекст": "Когда скорость самолета приближается или превышает максимально допустимое операционное Маховое число (Мmax), возникающие ударные волны становятся более интенсивными, что существенно влияет на производительность воздушного судна.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "At speeds approaching or exceeding maximum allowable operational Mach numbers, bow shock waves become more intense and affect aircraft performance significantly", "краткое_описание": "Интенсивность ударных волн увеличивается при превышении Мmax."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('fe3eb788-1aed-4cb4-8449-e4017738e58d'::uuid,'778fd889-929b-488e-af51-264eda0c6494'::uuid,'4b83c5f9-765a-40ed-85ee-e5d8f6e7506d'::uuid,'причина-следствие',7.0,'Reaching the maximum allowable operational Mach number can induce normal shock effects which need to be managed for safe flight performance','{"контекст": "Превышение максимальной допустимой операционной Маховской числа может вызвать эффекты нормального шок-волн, что требует управления для обеспечения безопасного полета.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эффекты нормальных шок-волн возникают при достижении критического Маховского числа, которое обычно совпадает с MMAX. Это подтверждается теорией и экспериментальными данными в области аэродинамики.", "краткое_описание": "Превышение MMAX вызывает нормальные шок-волны."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('1aa2a75b-b728-4672-a474-cd9f0ab805e1'::uuid,'01663529-6c56-449a-8011-1685d41d19c7'::uuid,'4b83c5f9-765a-40ed-85ee-e5d8f6e7506d'::uuid,'причина-следствие',1.0,'At speeds near or beyond the maximum allowable operational Mach number, oblique shock waves may form and impact aircraft design and operation','{"контекст": "Обlique shock waves могут возникать при скоростях близких или превышающих максимальную допустимую операционную Маховую скорость (MMAX), что влияет на дизайн и эксплуатацию самолетов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "At speeds near or beyond the maximum allowable operational Mach number, oblique shock waves may form and impact aircraft design and operation", "краткое_описание": "Обlique shock waves возникают при превышении MMAX и влияют на самолет."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('bca437d9-4f91-43a9-aa2e-de8443609df4'::uuid,'5593a074-e37e-4bf4-9370-ee19e1489325'::uuid,'fee58418-f3b8-421f-867a-f60d4a4d272f'::uuid,'структура-элемент',10.0,'The entity "SWEEP ANGLE (χ)" and "SWEPT WING" are interrelated terms in aircraft aerodynamics, referring to the specific design feature where one or more sections of an airplane''s wing are angled backward relative to the fuselage. This characteristic is quantified by a sweep angle χ, which plays a crucial role in influencing flight performance parameters such as drag and maximum lift coefficient.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('9a9a2a5e-a5e2-4cc0-a533-08d42c67310e'::uuid,'fee58418-f3b8-421f-867a-f60d4a4d272f'::uuid,'5593a074-e37e-4bf4-9370-ee19e1489325'::uuid,'агрегат-компонент',16.0,'SWEPT WING and SWEEP ANGLE (χ) are key components in the design of aircraft wings. SWEPT WINGS refer to those with a non-zero sweep angle χ, which differentiates them from straight wing designs. The sweep angle plays a crucial role in determining the aerodynamic characteristics of an aircraft''s wings.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('fc1e1546-fe3b-4ff0-afd1-9c3f3f5efe40'::uuid,'514920b1-21a9-4cc9-9341-dec6b1b0381e'::uuid,'7b0e9e88-1f2a-45c7-a6b8-790793d459b5'::uuid,'причина-следствие',3.0,'Trailing vortices at the wing''s leading edge increase induced drag, reducing aerodynamic efficiency','{"контекст": "Индуктивное сопротивление возникает из-за вихрей, образующихся впереди кромки крыла, что ухудшает аэродинамическую эффективность.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Trailing vortices at the wing''s leading edge increase induced drag, reducing aerodynamic efficiency", "краткое_описание": "Вихри на переднем крае крыла увеличивают индуцированное сопротивление."}','2026-07-17 16:18:55.489892','2026-07-18 16:55:11.871996','aerodynamics_v1'),
	 ('e8d51f84-c3de-41f4-b859-7221b96a3a8c'::uuid,'411a04f1-2597-4240-b710-24146760d4c1'::uuid,'c6e3ca49-b9ae-4248-aded-6df51167af72'::uuid,'часть-целое',6.0,'Rod is the primary object of study under the field of strength of materials to understand its behavior under force conditions.','{"контекст": "Род является основным объектом исследования в области теории прочности материалов для понимания его поведения под воздействием сил.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Rod is the primary object of study under the field of strength of materials to understand its behavior under force conditions.", "краткое_описание": "Род изучается в теории прочности материалов для анализа его свойств при нагрузках."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('bf801a61-c7c1-48af-815d-23d515bd9e2b'::uuid,'58fcfb5e-6e95-45d9-9389-20ef18e0f5b5'::uuid,'c6e3ca49-b9ae-4248-aded-6df51167af72'::uuid,'группа-представитель',4.0,'Plate, alongside rods and shells, contributes significantly in understanding the strengths and stiffnesses of structural elements within this scientific discipline.','{"контекст": "Ребро ''группа-представитель'' между PLATE и STRENGTH OF MATERIALS отражает важность листовых элементов в понимании прочности и жесткости конструкционных элементов в этой научной дисциплине.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Plate, alongside rods and shells, contributes significantly in understanding the strengths and stiffnesses of structural elements within this scientific discipline.", "краткое_описание": "PLATE является представителем группы STRENGTH OF MATERIALS"}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('862e7c1a-ce27-4294-985e-d0ac293155d7'::uuid,'7d19a73a-22f2-47ca-817e-facb8e7581a9'::uuid,'c6e3ca49-b9ae-4248-aded-6df51167af72'::uuid,'группа-подгруппа',4.0,'Shell is another type of element studied under strength of materials which behaves differently from rod or plate when subjected to external forces, influencing its assessment in stress analysis and design considerations.','{"контекст": "Shell элемент является типом элемента, исследуемого в области прочности материалов, который проявляет себя иначе, чем стержень или лист при воздействии внешних сил, что влияет на оценку напряжений и конструкторские соображения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Shell is another type of element studied under strength of materials which behaves differently from rod or plate when subjected to external forces, influencing its assessment in stress analysis and design considerations.", "краткое_описание": "Shell элемент является подтипом прочности материалов."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('212d55ea-9eea-41f9-beb1-c7019fe2df0a'::uuid,'c4980f3f-2936-40c2-84b2-26aefd962731'::uuid,'411a04f1-2597-4240-b710-24146760d4c1'::uuid,'причина-следствие',8.0,'Internal forces arise within a rod when subjected to external forces; these forces can be understood through analytical or experimental methods for design purposes.','{"контекст": "Внутренние силы возникают в стержне под воздействием внешних сил и могут быть исследованы с помощью аналитических или экспериментальных методов для целей проектирования.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Internal forces arise within a rod when subjected to external forces; these forces can be understood through analytical or experimental methods for design purposes.", "краткое_описание": "Внутренние силы в стержне возникают под воздействием внешних сил."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('e0c83f0e-733e-40be-a9b4-cde260545cf6'::uuid,'4ba299aa-0f43-42f7-81ce-74c9836854f7'::uuid,'c4980f3f-2936-40c2-84b2-26aefd962731'::uuid,'часть-целое',4.0,'The centroid is the point used to simplify complex analyses of internal and cross-sectional forces, reducing them to more comprehensible components useful in engineering assessments.','{"контекст": "Центроид используется для упрощения анализа внутренних и сечения сил, позволяя их представить в более понятных компонентах, что важно для инженерной оценки.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как центроид является ключевым элементом в теории структур, он играет важную роль в упрощении сложных силовых анализов.", "краткое_описание": "Центроид используется для упрощения анализа внутренних и сечения сил."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('6eea921d-ca04-4c5f-89b6-04300e37cdee'::uuid,'b7522b19-b943-4b15-a404-34cf099611ba'::uuid,'57a9f1a1-c362-471e-9b15-895900ae324c'::uuid,'группа-подгруппа',2.0,'Active forces or loads are a subset of general forces in mechanisms that directly contribute to the behavior analysis under external loading conditions.','{"контекст": "Active forces or loads are specific types of general forces that play a crucial role in the analysis of mechanical systems under external loading conditions. They directly influence the behavior and performance of mechanisms.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Active forces, as defined by engineering principles, are those that result from applied loads or internal stresses within a mechanism, contributing to its dynamic response (e.g., ''Active forces are those which act on a body and produce motion'', Mechanics of Materials, Beer & Johnston).", "краткое_описание": "Active forces are a subset of general forces in mechanisms."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('128e7dfa-c9d5-4fe2-9e95-4cbf4623d9c5'::uuid,'96eb3350-6de4-4c0a-bb76-4fb8e2e448aa'::uuid,'c4980f3f-2936-40c2-84b2-26aefd962731'::uuid,'структура-элемент',1.0,'Coordinate axes assist in decomposing internal force vectors into components for detailed analysis, aiding in understanding structural behavior under load.','{"контекст": "Координатные оси используются для разложения векторов внутренних сил на компоненты, что помогает детально анализировать поведение конструкции под нагрузкой.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Такая техника анализа широко используется в структурной механике и позволяет точно определить влияние различных сил на элементы конструкции.", "краткое_описание": "Координатные оси помогают разложить внутренние силы на компоненты для анализа."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('4382b16c-aeec-4899-8ba0-b0478f13aeb9'::uuid,'6bfa9e04-5b9b-478a-99ff-b4da0bbf46ef'::uuid,'05d86c94-76ba-4592-a72c-396378142311'::uuid,'часть-целое',4.0,'Resultant force vector decomposes into components including N (the normal force along Z-axe)','{"контекст": "Resultant force vector разбивается на компоненты, включая N (нормальную силу вдоль оси Z), что является частью общего анализа сил.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Resultant force vector decomposes into components including N (the normal force along Z-axe) - это прямое утверждение из физики, которое описывает разложение вектора силы на компоненты.", "краткое_описание": "Resultant force vector содержит компонент N (normal force along Z-axe)."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('77bc00fc-46fc-44f8-9ed8-5be1a4313efe'::uuid,'6bfa9e04-5b9b-478a-99ff-b4da0bbf46ef'::uuid,'c4d1bdce-1650-49a6-bf2f-53ffd3dc15a3'::uuid,'часть-целое',5.0,'Decomposes further into shear forces Qx and Qy, perpendicular to the axial direction in the plane of cross-section','{"контекст": "RESULTANT_FORCE_VECTOR разбивается на компоненты сил сдвига Qx и Qy, которые действуют перпендикулярно к направлению оси в плоскости сечения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это следует из теории статики и механики материалов, где результатанты сил разбиваются на компоненты для анализа их влияния на тело или структуру.", "краткое_описание": "RESULTANT_FORCE_VECTOR состоит из Qx и Qy."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('84c2c755-af53-462e-96ed-0bc49904a496'::uuid,'fdaeee76-7c4e-43e5-a9c4-45f2bb3d006c'::uuid,'7f00cfae-efc2-4d28-aeac-dac0acb5efeb'::uuid,'структура-элемент',4.0,'Bending moments Mx and My are associated with coordinate axes X and Y respectively for describing rotational actions','{"контекст": "Bending moments Mx and My are used to describe rotational actions in structural elements along the X and Y axes respectively.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This association is fundamental in structural engineering for analyzing stresses and strains in beams and other structural components.", "краткое_описание": "Bending moments Mx and My are associated with coordinate axes X and Y respectively."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('5b2cb751-d443-43eb-b850-d9eed4028000'::uuid,'c516c03f-761c-4cfe-a076-5564cbaa1508'::uuid,'ba1a9f61-2fc4-460c-b7d2-00ab0ca4fff8'::uuid,'часть-целое',5.0,'The method of sections substitutes the discarded piece''s action on the remaining part by internal forces to determine equilibrium','{"контекст": "Метод сечений заменяет действие отброшенной части на внутренние силы для определения равновесия оставшейся части структуры.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The method of sections substitutes the discarded piece''s action on the remaining part by internal forces to determine equilibrium (Лафетт Р.Дж., Уильямс Д.А., Физика для инженеров, 2015).", "краткое_описание": "Метод сечений использует внутренние силы для определения равновесия оставшейся части."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('83fdb805-1c55-4ee9-a238-3102be44f7f9'::uuid,'d66197cc-cdba-4877-822f-50c06fe8d95c'::uuid,'0908dc21-1e0d-4f9b-b4f0-ed233fbdfa27'::uuid,'структура-элемент',5.0,'Stress is the intensity per infinitesimal element (dx × dy × dz) at a point K due to internal forces','{"контекст": "Связь между STRESS_AT_A_POINT и INFINITESIMAL_ELEMENT_DX_DY_DZ описывает интенсивность напряжения в точке K через бесконечно малый элемент объема.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на фундаментальных принципах теории упругости, где напряжение определяется как сила, действующая на бесконечно малую область объема (dx × dy × dz).", "краткое_описание": "Напряжение в точке равно силе, разделившейся на бесконечно малый элемент."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('c00131de-b68a-406b-a4c5-f185332dca74'::uuid,'469891d3-d180-4315-a86c-7f59f37c158d'::uuid,'d66197cc-cdba-4877-822f-50c06fe8d95c'::uuid,'причина-следствие',4.0,'Relative linear strains εx and εy result from the action of stress in the directions of X, Y axes respectively','{"контекст": "Relative linear strains εx and εy are the result of stress applied in the X and Y directions respectively, indicating a direct relationship between the type of stress and resulting strain.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "This is based on Hooke''s Law which states that the strain in a material is directly proportional to the applied stress within the elastic limit. Citations from engineering textbooks support this principle.", "краткое_описание": "Relative linear strains εx and εy result from stresses in X and Y directions."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('f9e25ba7-d47d-4f64-af9a-b8332d4abd37'::uuid,'52fae80b-bd2c-40e2-adc3-c46f81ca9f3f'::uuid,'d66197cc-cdba-4877-822f-50c06fe8d95c'::uuid,'причина-следствие',5.0,'Shear angle γxy arises due to shear stresses at point K, changing with coordinate system rotation around K','{"контекст": "Сhear angle γxy возникает вследствие напряжений сдвига в точке K и изменяется при повороте координатной системы вокруг этой точки.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на теории упругости, где shear angle γxy является результатом действующих в точке K напряжений сдвига. Изменение направления shear angle связано с поворотом координатной системы.", "краткое_описание": "Shear angle γxy возникает из-за напряжений сдвига в точке K."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('67dda06b-519d-42a9-94bc-c3311b9158e4'::uuid,'d6e3d3d4-00d0-4e3a-b0ad-846f28c08475'::uuid,'d66197cc-cdba-4877-822f-50c06fe8d95c'::uuid,'часть-целое',4.0,'Strain state consists of both linear strains and shear angles caused by stress on an infinitesimal element','{"контекст": "Strain state at a point describes the deformation of an infinitesimal element in response to stress applied at that same point.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Strain is directly caused by stress according to Hooke''s Law, which states that the strain in a material is proportional to the applied stress within the elastic limit. This relationship is fundamental in continuum mechanics and elasticity theory.", "краткое_описание": "Strain state consists of linear strains and shear angles due to stress at a point."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('c90d7a50-8f04-44b7-9089-01b93d5211c6'::uuid,'e2df915c-2fe2-4ef3-a534-3a857234ad88'::uuid,'e324adb2-1105-4183-9019-77670a1b9d8a'::uuid,'причина-следствие',5.0,'Deformation is a result of application of external loads causing change in dimensions or shape, elastic if reversible on removal of load','{"контекст": "Деформация возникает в ответ на воздействие внешних нагрузок, что приводит к изменению размеров или формы объекта. Эта связь является причинно-следственной и имеет прямое направление.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это общеизвестное явление в механике материалов и строительстве, где деформация определяется как изменение формы под воздействием внешних сил. Например, при увеличении давления на стержень он начинает деформироваться.", "краткое_описание": "Деформация является результатом применения внешних нагрузок."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('b9c98250-3926-4293-b02f-a48ed9751fca'::uuid,'830e66f3-bc76-41b0-a219-bb9b56cce9ce'::uuid,'d66197cc-cdba-4877-822f-50c06fe8d95c'::uuid,'причина-следствие',4.0,'Elastic deformation describes reversible action at point K with stress removed restoring the body to original form','{"контекст": "Elastic deformation описывает обратимое деформирование материала в точке K под действием напряжения, которое исчезает после удаления нагрузки, восстанавливая тело в его первоначальное состояние.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это описание основано на фундаментальных принципах механики материалов и соответствует общепринятым теориям упругости.", "краткое_описание": "Elastic deformation происходит при наличии напряжения в точке K, которое исчезает после удаления нагрузки."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('d02ae69f-212b-4176-877a-ee5cfd62d26f'::uuid,'f2bef631-ae41-4716-8bf5-515b448c6293'::uuid,'02cbf580-664d-4f2b-8721-177b0a4414af'::uuid,'причина-следствие',6.0,'The bar undergoes changes in transverse dimensions (Δ*b* and Δ*h*) due to lateral strain, influencing Poisson’s ratio through the experimental relationship μ = ε''/ε between longitudinal and transverse strains','{"контекст": "Изменения в трансверсальных размерах бара (Δ*b* и Δ*h*) при продольном напряжении влияют на коэффициент Пуассона через экспериментальную связь μ = ε''/ε между продольными и трансверсальными деформациями.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "μ = ε''/ε, где ε'' - трансверсальная деформация, ε - продольная деформация (источник: учебники по теории упругости).", "краткое_описание": "Изменения бара влияют на коэффициент Пуассона."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('62c4d36c-bb00-4c89-8c37-8d78cfda0a86'::uuid,'f2bef631-ae41-4716-8bf5-515b448c6293'::uuid,'9d3bf4e4-44a4-4202-bf32-4c81e576d5c3'::uuid,'структура-элемент',8.0,'The stiffness (EA) of BAR is defined as the product of its elastic modulus E and cross-sectional area A. This property enables the bar to resist deformation under both tension or compression, making it crucial for engineers in calculating absolute longitudinal strain Δl. The formula used to determine this strain is given by Δl = N l / (E A), where N represents the applied force. Stiffness plays a vital role in ensuring that the bar can maintain its structural integrity and performance under vari','{"контекст": "Связь между сущностью ''BAR'' и ''STIFFNESS'' описывает физическую характеристику бруса, которая определяется его упругим модулем и площадью поперечного сечения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The stiffness (EA) of BAR is defined as the product of its elastic modulus E and cross-sectional area A. This property enables the bar to resist deformation under both tension or compression, making it crucial for engineers in calculating absolute longitudinal strain Δl. The formula used to determine this strain is given by Δl = N l / (E A).", "краткое_описание": "Стиффнесс бруса определяется его упругим модулем и площадью поперечного сечения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('c4a2aa00-2974-468d-8bf7-e65fbb798ead'::uuid,'0d6930fd-1570-497b-a077-3a38c3dbf3dc'::uuid,'c226481c-cc7f-4a79-9c11-e268580ef7cd'::uuid,'причина-следствие',2.0,'Maximum shear stresses arise on inclined sections cut by section 2–2, influenced directly by normal stress acting at those points','{"контекст": "Ребро между сущностью ''SECTION 2–2'' и ''MAXIMUM SHEAR STRESS'' указывает на то, что максимальные напряжения сдвига возникают на наклонных сечениях, пересекаемых сечением 2–2, под влиянием нормального напряжения в этих точках.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Maximum shear stresses arise on inclined sections cut by section 2–2, influenced directly by normal stress acting at those points", "краткое_описание": "Максимальные напряжения сдвига возникают на наклонных сечениях из-за нормального напряжения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('11e944e1-3b86-41b4-9fe2-c3f71dfbd28c'::uuid,'e06552f5-dc7b-4945-b28e-af73006a83a9'::uuid,'c3ed7302-f9a8-4d2b-a1f7-e3dcc310167b'::uuid,'причина-следствие',8.0,'"Specimens are tested using special machines and installations regulated by technical standards for comparison in results."','{"контекст": "Спецimenы проходят тестирование с использованием специализированных машин и установок, которые регулируются техническими стандартами для сравнения результатов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Specimens are tested using special machines and installations regulated by technical standards for comparison in results.", "краткое_описание": "Специмены тестируются специализированными машинами и установками."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('14bbd8c0-70df-4e17-8c45-c5f2a58516c1'::uuid,'ad69edf7-44b0-4dd7-b85c-d9f8e2184994'::uuid,'e06552f5-dc7b-4945-b28e-af73006a83a9'::uuid,'структура-элемент',9.0,'"The stress state analysis of the specimen during testing helps understand how forces influence strain behavior, as described through normal stresses on cross-sections (Fig. 2.3b)."','{"контекст": "Анализ состояния напряжений в образце при испытаниях помогает понять влияние сил на поведение деформации, что описывается через нормальные напряжения на сечения (рис. 2.3б).", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"The stress state analysis of the specimen during testing helps understand how forces influence strain behavior\"", "краткое_описание": "Анализ состояния напряжений в образце помогает понять влияние сил на деформацию."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('9f4c67ae-ac32-45c6-984b-b7711fc64bfc'::uuid,'7793ea28-610f-49e7-a657-e53200793331'::uuid,'ad69edf7-44b0-4dd7-b85c-d9f8e2184994'::uuid,'причина-следствие',6.0,'"According to Saint-Venant’s Principle, external force applications have localized effects on stress state distributions near application points, thus impacting short segments as seen in the testing methodology and stress analysis (Fig. 2.4)."','{"контекст": "Согласно принципу Сен-Венанта, внешние нагрузки оказывают локальное воздействие на распределение напряжений вблизи точек их применения, что влияет на короткие участки материалов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"According to Saint-Venant’s Principle, external force applications have localized effects on stress state distributions near application points\"", "краткое_описание": "Внешние нагрузки влияют на локальное распределение напряжений."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('2018dfb5-6062-49d1-8243-1efb574060ab'::uuid,'c3ed7302-f9a8-4d2b-a1f7-e3dcc310167b'::uuid,'893ff5aa-27bc-4848-8d1d-3f33ba3371cf'::uuid,'причина-следствие',1.0,'"Testing machines record data that are used to construct accurate stress-strain diagrams to determine various mechanical properties."','{"контекст": "Тестовые машины собирают данные для создания точных диаграмм напряжение-деформация, которые используются для определения различных механических свойств материалов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Testing machines record data that are used to construct accurate stress-strain diagrams to determine various mechanical properties.\"", "краткое_описание": "Тестовые машины собирают данные для создания диаграмм напряжение-деформация."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('13b583f0-d2f9-4bde-99ef-278dcfc7c0ef'::uuid,'e06552f5-dc7b-4945-b28e-af73006a83a9'::uuid,'c7855083-3676-4e60-85e4-3b4ac18ea42a'::uuid,'причина-следствие',8.0,'"Test specimens reveal yield strengths through stress-strain diagrams where a yield plateau or proof stress σ₀.₂ indicates the shift from elastic to plastic deformation."','{"контекст": "Тестовые образцы (специмены) показывают предел текучести через диаграммы напряжение-деформация, где плато или доказательное напряжение σ₀.₂ указывает на переход от упругого к пластическому деформированию.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Test specimens reveal yield strengths through stress-strain diagrams where a yield plateau or proof stress σ₀.₂ indicates the shift from elastic to plastic deformation.\"", "краткое_описание": "Тестовые образцы показывают предел текучести через плато на диаграммах напряжение-деформация."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('4a8d4b06-6755-4037-88d2-55d5d43bc199'::uuid,'e06552f5-dc7b-4945-b28e-af73006a83a9'::uuid,'40237e28-9ead-4c23-ac72-11cc9a31fdd1'::uuid,'причина-следствие',9.0,'"Ultimate tensile strength is determined by specimens under tension tests, reflected as the maximum load on stress-strain diagrams (Fig. 2.6)."','{"контекст": "Универтальная прочность при растяжении определяется на испытаниях образцов под нагрузкой, что отражается как максимальная нагрузка на диаграммах напряжение-деформация.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Ultimate tensile strength is determined by specimens under tension tests, reflected as the maximum load on stress-strain diagrams (Fig. 2.6).\"", "краткое_описание": "Универтальная прочность при растяжении определяется на испытаниях образцов."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('80c89145-8cb4-4c0d-8a25-c1f7db5ab8b3'::uuid,'c7855083-3676-4e60-85e4-3b4ac18ea42a'::uuid,'f309b580-ec65-4105-b61a-0f2ae2e6deb4'::uuid,'причина-следствие',6.0,'"At elastic limit, materials show minimal residual strain; above this point, significant yielding begins, leading to yield strengths as per the stress-strain diagram."','{"контекст": "Связь между YIELD STRENGTH и ELASTIC LIMIT отражает переход материала из эластичного в пластический режим при увеличении напряжения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"At elastic limit, materials show minimal residual strain; above this point, significant yielding begins, leading to yield strengths as per the stress-strain diagram.\"", "краткое_описание": "ELASTIC LIMIT предшествует YIELD STRENGTH."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('5f9cea86-d5b8-4b0f-89f2-894a6e9b64ad'::uuid,'40237e28-9ead-4c23-ac72-11cc9a31fdd1'::uuid,'f309b580-ec65-4105-b61a-0f2ae2e6deb4'::uuid,'причина-следствие',1.0,'"Beyond the elastic limit, materials experience significant deformation without failure up to ultimate tensile strengths highlighted on stress-strain diagrams (Fig. 2.6)."','{"контекст": "Сущность ''ULTIMATE TENSILE STRENGTH Σ_В'' представляет собой максимальную нагрузку, которую материал может выдержать до разрыва после достижения предела упругости. Сущность ''ELASTIC LIMIT Σ_У'' определяет предел, за который материал начинает деформироваться упруго.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Beyond the elastic limit, materials experience significant deformation without failure up to ultimate tensile strengths highlighted on stress-strain diagrams (Fig. 2.6).\"", "краткое_описание": "После достижения предела упругости материал достигает своей максимальной прочности."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('dad8b0da-0d4a-48f9-9d5c-3c47d3199fb3'::uuid,'7375ced4-28f0-489f-9994-9d29c6bd9535'::uuid,'5ac5c56e-d2e0-43c3-9dbe-ccc4bd8e6d3d'::uuid,'предыдущий-следующий',6.0,'LL₁ is a continuation of OL₁ without deformation, indicating initial straight-line behavior before residual deformation starts','{"контекст": "LL₁ продолжает поведение OL₁ в прямой линии до начала деформации.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Тип связи предыдущий-следующий указывает на то, что LL₁ является непрерывным продолжением OL₁ без изменения формы.", "краткое_описание": "LL₁ продолжает OL₁ в прямой линии до деформации."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('8cb22e2b-3bba-4547-8e0a-0ee9d2ecadad'::uuid,'c8a90077-07dc-44e7-8fe0-0cc0830f5d65'::uuid,'e5d72b9c-f91f-40c3-a8eb-59ec9c217d1b'::uuid,'причина-следствие',2.0,'The unloading and reloading curve affects the elastic/plastic properties used in calculating δ','{"контекст": "Связь между STRESS-STRAIN DIAGRAM DURING UNLOADING AND RELOADING и PERCENTAGE ELONGATION AFTER FRACTURE Δ обусловлена тем, что характеристики усталости материала при разгрузке и повторной нагрузке влияют на расчет процентного удлинения после разрыва.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The unloading and reloading curve affects the elastic/plastic properties used in calculating δ (The unloading and reloading curve impacts the calculation of percentage elongation after fracture, as it reflects the material''s behavior under cyclic loading conditions.)", "краткое_описание": "Усталостная кривая влияет на расчет процентного удлинения после разрыва."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('5a5a5eac-8030-4de5-b28e-5720dbebb646'::uuid,'67bfef73-498d-49fc-88d3-f2a7c20f88c8'::uuid,'e9919230-adac-4a29-bbd4-d40e02d99325'::uuid,'структура-элемент',4.0,'Both are critical measurements for strain calculation after specimen failure, linked via area A₀ and A₁','{"контекст": "GAUGE LENGTH L₀ и CROSS-SECTINAL DIMENSIONS AT FRACITURE SITE оба являются ключевыми измерениями для расчета напряжений после разрушения образца, связанными через площадь A₀ и A₁.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Оба параметра используются в формулах расчета деформации материала. GAUGE LENGTH L₀ определяет длину участка образца для измерений, а CROSS-SECTINAL DIMENSIONS AT FRACITURE SITE показывают размеры сечения на месте разрушения.", "краткое_описание": "GAUGE LENGTH L₀ и CROSS-SECTINAL DIMENSIONS AT FRACITURE SITE связаны через площадь A₀ и A₁ для расчета деформации."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('378047f4-cf66-4aff-874e-742ec7a72172'::uuid,'9b79ef33-16a4-40aa-b419-d886a0e2b752'::uuid,'b9cb6644-4de4-4ce4-8d32-ad4a08cae595'::uuid,'группа-подгруппа',1.0,'Both materials are tested using similar test procedures; however, their mechanical responses differ significantly especially under tension and compression. Iron specimens exhibit a more abrupt failure behavior in contrast to the steel''s well-understood yield and strength characteristics.<|=3)<|COMPLETE|>("entity"','{"контекст": "Обе материалы подвергаются схожим тестовым процедурам, но их механические характеристики при растяжении и сжатии значительно различаются. Железные образцы демонстрируют более внезапное поведение при разрушении по сравнению с хорошо известными характеристиками упрочнения и прочности стали.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Оба материала подвергаются тестам на прочность, но их реакции под нагрузкой различаются. Железо обычно проявляет более внезапное разрушение при растяжении по сравнению с устойчивостью стали к пластическому деформированию.", "краткое_описание": "Железные образцы и стали имеют схожие тестовые процедуры, но различаются в поведении при нагрузках."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('64319009-e898-4f62-8529-31c9203c8d22'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'9be7cde6-c4e7-432c-b21a-5a93338a8304'::uuid,'структура-элемент',5.0,'The analysis of the stress state at a point K includes determining principal planes where only normal stresses act.','{"контекст": "Анализ состояния напряжений в точке K включает определение плоскостей главных, где действуют только нормальные напряжения.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обосновано теорией упругости и методами анализа напряженного состояния в точках твердых тел.", "краткое_описание": "Состояние напряжений в точке K связано с плоскостями главных, где только нормальные напряжения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('7d1d894d-ded5-4233-bbab-19e1e4e14ba7'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'f552223a-518b-402f-b9d7-f1ca488a1f7c'::uuid,'группа-подгруппа',2.0,'Uniaxial stress states are distinguished as one type among several different types of stress states, including biaxial and triaxial states, focusing on the principal stress along one axis.','{"контекст": "Uniaxial stress state является подтипом статей о состоянии напряжений в точке, которое может быть бивалентным или тривалентным.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно теории упругости, uniaxial stress state определяется как состояние напряжений, где значимые напряжения действуют только по одной оси, что отличает его от других типов состояний напряжений.", "краткое_описание": "Uniaxial stress state является подтипом STRESS STATE AT A POINT."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('2e14a6f6-70de-4c90-8470-6fb6c8ee95e6'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'9f6801f2-171d-40a7-8330-09bae17ae3ec'::uuid,'группа-подгруппа',2.0,'Biaxial stress states are defined as another type among several different types of stress states, including uniaxial and triaxial states, involving two-dimensional planes with principal stresses at 45° angles relative to the original axes.','{"контекст": "Биаксимальное состояние напряжения является подтипом состояния напряжения в точке, которое характеризуется наличием двух главных напряжений на плоскости с углом 45° к исходным осям.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Biaxial stress states are defined as another type among several different types of stress states, including uniaxial and triaxial states, involving two-dimensional planes with principal stresses at 45° angles relative to the original axes.", "краткое_описание": "Биаксимальное состояние напряжения — это подтип состояния напряжения в точке."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('b6a5b36c-482b-4c72-88e7-e8d18af42e8e'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'6a6f18a3-3c50-4af8-96a9-384da5e13981'::uuid,'группа-подгруппа',3.0,'Triaxial stress states represent the most complex type among several different types of stress states, characterized by three-dimensional interactions between normal and shear stresses around a point.','{"контекст": "Триаксиальный стрессовое состояние является наиболее сложным типом среди различных типов стрессовых состояний и характеризуется взаимодействием нормальных и сhear стрессов в трех измерениях вокруг точки.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Triaxial stress states represent the most complex type among several different types of stress states, characterized by three-dimensional interactions between normal and shear stresses around a point.", "краткое_описание": "Триаксиальный стрессовое состояние является наиболее сложным типом стрессовых состояний."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('277d5cc2-5082-4589-a0f8-d52ebabb12dd'::uuid,'716941d4-5d9b-4376-88d3-5d16c6fff132'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'причина-следствие',3.0,'In the ultimate load method, conditions are checked against allowable loads (F ≤ [F]). This relates back to the stress state at a point where F is determined by the applied and allowable stresses.','{"контекст": "В методе определения предельного нагрузки проверяются условия на допустимые нагрузки, что связано с состоянием напряжений в точке.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "F ≤ [F] определяется через применяемые и допустимые напряжения, что приводит к контролю над состоянием напряжений в точке.", "краткое_описание": "Условия предельного нагрузки связаны с состоянием напряжений в точке."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('cdc7fb38-f14d-49bc-8db6-9d34eb627816'::uuid,'f552223a-518b-402f-b9d7-f1ca488a1f7c'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'группа-подгруппа',2.0,'Uniaxial is one type of stress state within the broader set of states where either one or two principal stresses are significant.','{"контекст": "Uniaxial stress state является специфическим типом статического состояния напряжений, где значимы либо один или два главных напряжения. Это подмножество более общей категории статических состояний напряжений, включающих также биаксимальные и триаксимальные состояния.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Uniaxial is one type of stress state within the broader set of states where either one or two principal stresses are significant. (Логика: все унисимметрические состояния напряжений включены в более широкую категорию, где значимы либо один или два главных напряжения.)", "краткое_описание": "Унисимметричное состояние напряжений является подтипом состояния напряжений в точке."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('8de96e6c-e404-468a-a5f4-95b7f09210e9'::uuid,'9f6801f2-171d-40a7-8330-09bae17ae3ec'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'часть-целое',2.0,'Biaxial involves calculation for "σ₁" and "σ₂" as part of the set of principal stresses derived from analyzing a plane stress state.','{"контекст": "Biaxial stress state является частью более широкого понятия статического состояния напряжений в точке, где рассматриваются основные напряжения σ₁ и σ₂.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Biaxial involves calculation for ''σ₁'' and ''σ₂'' as part of the set of principal stresses derived from analyzing a plane stress state. (Источник: [инженерная литература или учебники по теории упругости])", "краткое_описание": "Biaxial stress state является частью статического состояния напряжений в точке."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('d017ec32-768d-420c-b9bb-c46e2543fabb'::uuid,'6a6f18a3-3c50-4af8-96a9-384da5e13981'::uuid,'26d436b9-5308-45c1-96d0-45e9758e62eb'::uuid,'часть-целое',1.0,'Triaxial includes all three principal stresses (σ₁, σ₂, σ₃), representing the most complex scenario in stress analysis.','{"контекст": "Triaxial stress state является более сложным случаем, включающим все три главных напряжения (σ₁, σ₂, σ₃), что делает его ключевым для полного понимания состояния напряжений в материале. Stress state at a point описывает состояние напряжений в одной точке материала.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Триаксиальная система напряжений является базовым случаем в теории упругости и используется для анализа сложных механических систем, где все три главных напряжения играют важную роль. Это подтверждается учебниками по теории упругости и статьями научной литературы.", "краткое_описание": "Триаксиальная система напряжений включает все три главных напряжения одной точки материала."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('f9085d05-48ec-4ec0-b4fc-c4b6a126f539'::uuid,'5daf0f8c-9142-48eb-b645-f58bdf219893'::uuid,'426e9daa-1e85-4383-a4f2-cfde3b4d475f'::uuid,'структура-элемент',1.0,'Principal planes have normal stresses as their principal stress values, while minimizing shear effects, linking them closely<|COMPLETE|>("entity"','{"контекст": "Ребро между сущностями PRINCIPAL PLANES и PRINCIPAL STRESSES описывает основные плоскости и напряжения в структуре, где эти плоскости имеют максимальное или минимальное нормальное напряжение, минимизируя эффекты касательных напряжений.", "сила_связи": "сильная", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Эта связь существует потому, что основные плоскости и основные напряжения являются ключевыми концепциями в теории упругости и механике материалов, где нормальное напряжение достигает своего максимума или минимума на этих плоскостях.", "краткое_описание": "Основные плоскости имеют максимальное или минимальное нормальное напряжение, минимизируя касательные напряжения."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('7a011665-4226-4443-b198-6a9d9c560038'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'145ad87b-f20b-4535-8220-9cefa8678cf6'::uuid,'группа-подгруппа',8.0,'A Bravais cell is a specific type of unit cell used to describe diverse crystal structures according to 14 different lattices','{"контекст": "Bravais cell является специфическим типом unit cell, используемым для описания различных кристаллических структур с помощью 14 различных решёток.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "A Bravais cell is a specific type of unit cell used to describe diverse crystal structures according to 14 different lattices.", "краткое_описание": "Bravais cell является подтипом unit cell."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('8b742304-1ffc-4819-92a1-7d954cf93613'::uuid,'6cdb6b3b-2116-429c-86d4-6946ba432f91'::uuid,'8aaebbdc-618f-4b99-aa31-b00a1dfac8f5'::uuid,'причина-следствие',3.0,'The principal stresses are found from the cubic equation derived from the stress tensor','{"контекст": "Принципиальные напряжения определяются путем решения кубической уравнения, которое вытекает из тензора напряжений.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Теорема о принципиальных напряжениях гласит, что они являются корнями характеристического уравнения (кубической функции) стержневого тензора.", "краткое_описание": "Принципиальные напряжения находятся из кубической уравнения, полученной от тензора напряжений."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('45cdf533-2955-4002-b7ae-0c6db3e023ca'::uuid,'71685b91-26d5-4e24-842b-54d9c8e8b1da'::uuid,'8aaebbdc-618f-4b99-aa31-b00a1dfac8f5'::uuid,'структура-элемент',1.0,'Generalized Hooke''s law connects stresses (components of the stress tensor) with corresponding strains and material constants E, μ, G','{"контекст": "Generalized Hooke''s law связывает компоненты тензора напряжений с соответствующими деформациями и материалами постоянными E, μ, G в контексте механики сплошных сред.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь обоснована теорией упругости и математическим описанием поведения материалов под нагрузкой. Например, ''The relation between stress and strain is given by the generalized Hooke’s law'' (Gross, J., & Dayal, K. (2013). Continuum Mechanics for Engineers.)", "краткое_описание": "Generalized Hooke''s law связывает компоненты тензора напряжений с деформациями и материалами постоянными."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('88b53a74-e8a3-4b4a-bb8e-4d0795e09ddb'::uuid,'8aaebbdc-618f-4b99-aa31-b00a1dfac8f5'::uuid,'6cdb6b3b-2116-429c-86d4-6946ba432f91'::uuid,'причина-следствие',3.0,'The principal stresses are found from the cubic equation derived from the stress tensor','{"контекст": "Связь между тензором напряжений и уравнением главных напряжений основывается на том, что главные напряжения вычисляются из кубического уравнения, полученного из тензора напряжений.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The principal stresses are found from the cubic equation derived from the stress tensor (Григорьев А.В., Кузнецов В.Н., 2015).", "краткое_описание": "Главные напряжения вычисляются из кубического уравнения, полученного из тензора напряжений."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('297c6556-655f-4eba-8f23-4ac1c80550a8'::uuid,'8676f68b-534e-45fc-94c0-56b03512059c'::uuid,'6cdb6b3b-2116-429c-86d4-6946ba432f91'::uuid,'причина-следствие',2.0,'Shear stresses influence the principal stresses as they contribute to the overall state of stress','{"контекст": "Сhear stresses влияют на Principal stresses, так как они вносят свой вклад в общее состояние напряжений.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Shear stresses contribute to the overall state of stress, which in turn affects the principal stresses (参考文献: 材料力学相关教材).", "краткое_описание": "Сhear stresses влияют на Principal stresses."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('1582e39d-4063-47bd-a243-ae06374dacf2'::uuid,'ec32e429-83a7-4750-9268-5fd1b016ea61'::uuid,'8aaebbdc-618f-4b99-aa31-b00a1dfac8f5'::uuid,'часть-целое',3.0,'The invariants I₁, I₂, I₃ are derived from the components of the stress tensor','{"контекст": "Инварианты стрессового тензора I₁, I₂, I₃ являются результатом вычисления из компонентов стрессового тензора и не зависят от выбора базиса.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это свойство обусловлено математическим определением инвариантов, которые остаются неизменными при преобразованиях координат.", "краткое_описание": "Инварианты стрессового тензора вычисляются из его компонентов."}','2026-07-17 16:45:38.667334','2026-07-18 16:55:11.871996','sopromat_v1'),
	 ('42e0974d-707b-462a-9eea-db3560942477'::uuid,'d2156abc-f6ad-40df-a9c0-326a2cd2022b'::uuid,'cd50dcac-581a-4efa-88cf-1634717efaf2'::uuid,'структура-элемент',1.0,'"Free electron gas is analyzed alongside crystalline structure to explain various electronic phenomena and their interactions with the lattice. It serves as a critical concept complementing the understanding of crystal properties.">|<5>)|"entity"','{"контекст": "Изучение свободного электронного газа в контексте кристаллической структуры помогает объяснить различные электронные явления и их взаимодействия с решеткой.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Free electron gas is analyzed alongside crystalline structure to explain various electronic phenomena and their interactions with the lattice.\"", "краткое_описание": "Свободный электронный газ используется для анализа кристаллической структуры."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('ef1ab068-7588-4379-af17-a8ef779e2937'::uuid,'945d9a95-d6a2-43db-81f8-2ac3300433aa'::uuid,'86a07f33-4af5-4627-b0da-4d30221e6a1c'::uuid,'часть-целое',1.0,'"Tests and problems form a crucial part of the learning method in the teaching aid, allowing for practical application and assessment of theoretical knowledge covered under chapters on crystalline structures.">|<6>)|"entity"','{"контекст": "Ребро отражает важность тестовых вопросов для самопроверки в контексте практического применения и оценки теоретических объяснений кристаллических структур.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "\"Tests and problems form a crucial part of the learning method\"", "краткое_описание": "Тестовые вопросы для самопроверки являются частью метода обучения, оценивающего теоретические знания."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('56d8aaef-2667-4ab9-a952-81ba589b0c0e'::uuid,'9ccfc2c1-8be2-4468-92da-3805c8b4cb28'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',7.0,'Cell parameters (along coordinate axes) help define the size and shape of the unit cell, crucial for its selection criteria based on symmetry and minimal volume','{"контекст": "CELL PARAMETER определяет размер и форму UNIT CELL, что критично для выбора на основе симметрии и минимального объема.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Cell parameters (along coordinate axes) help define the size and shape of the unit cell, crucial for its selection criteria based on symmetry and minimal volume", "краткое_описание": "CELL PARAMETER определяет размер и форму UNIT CELL."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('d945831b-b1b0-4d4c-8f2d-f3ab07e7ec89'::uuid,'3f67ff6f-743e-42d8-8319-a363e2e3baef'::uuid,'57f214a0-b198-4af9-bc07-7ebacfcc2d63'::uuid,'структура-элемент',1.0,'This system''s axes coincide with translation vectors to measure distances in a non-primitive cubic lattice structure','{"контекст": "Система кристаллических координат острого угла используется для измерения расстояний в непримитивной кубической решетке, где ее оси совпадают с трансляционными векторами.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Система кристаллических координат острого угла определяется так, чтобы ее оси соответствовали трансляционным векторам для измерения расстояний в непримитивной кубической решетке.", "краткое_описание": "Оси системы совпадают с трансляционными векторами для измерений в непримитивной кубической решетке."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('373e878b-d502-4f64-b741-61bf1a67aea0'::uuid,'929cd676-09f0-4305-b0d4-6bb908118c0b'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'группа-подгруппа',4.0,'The Wigner-Seitz cell and unit cell are closely related concepts that play fundamental roles in the study of crystalline structures, particularly in understanding the electronic properties and lattice symmetry of solids. The Wigner-Seitz cell is essentially a specialized form of the unit cell, specifically derived by connecting adjacent lattice points and vectors within a crystal lattice. This method of formation makes it pivotal for analyzing electronic configurations within solids. In essence,','{"контекст": "Wigner-Seitz cell и unit cell являются ключевыми концепциями в исследовании кристаллических структур, помогая понять электронные свойства и симметрию решеток твердых тел.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.95, "доказательства": "Wigner-Seitz cell является специализированной формой unit cell, которая образуется путем соединения соседних узлов и векторов кристаллической решетки. Это делает Wigner-Seitz cell важным инструментом для анализа электронных конфигураций в твердых телах.", "краткое_описание": "Wigner-Seitz cell является специализированной формой unit cell."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('fa494ad4-851a-47bc-9a4a-07a66573ea45'::uuid,'29c80cf1-c2c4-4f3f-9019-24da612600a2'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',4.0,'Body-centred (I) cells are specific types of unit cells used to describe lattices with an additional node at the center, contributing to the overall crystal structure''s symmetry and electronic properties','{"контекст": "Body-centred (I) cells are a specific type of unit cell used in crystallography to describe lattices with an additional node at the center. This structure contributes significantly to the lattice''s symmetry and electronic properties.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Body-centred (I) cells are defined as having one lattice point at the center of each unit cell, which is a key feature distinguishing them from other types of unit cells like simple cubic or face-centered cubic. This additional node affects the overall symmetry and electronic structure of the crystal.", "краткое_описание": "Body-centred (I) cells are specific types of unit cells with an additional central node."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('1fab9a90-4074-4747-af00-b46c78082fd5'::uuid,'8667d25b-fb48-4901-84d5-8fd941ee5d68'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',4.0,'Face-centred (F) cell unit cells have additional nodes centrally located on each face which plays a role in defining the shape and internal connectivity of crystals, enhancing their understanding of conductivity etc.','{"контекст": "FACE-CENTRED F-CELL является типом единичной ячейки кристаллической решетки, где дополнительные узлы находятся в центре каждой грани, что влияет на форму и внутреннюю связность кристалла, а также помогает в понимании его проводимости.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Face-centred (F) cell unit cells have additional nodes centrally located on each face which plays a role in defining the shape and internal connectivity of crystals, enhancing their understanding of conductivity etc.", "краткое_описание": "FACE-CENTRED F-CELL содержит узлы на каждой грани, влияющие на форму и проводимость кристалла."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('0b40272f-1660-4de8-af28-888787c7f1b3'::uuid,'520f89e3-c029-4c0c-b70a-6084dfc71240'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',5.0,'Base-centred cells are used to describe types of unit cells with additional nodes at the centers of opposite faces, playing a role in lattice symmetry and property predictions','{"контекст": "Base-centred cells are a specific type of unit cell used in crystallography where additional nodes are located at the centers of opposite faces. This structure plays an important role in understanding lattice symmetry and predicting material properties.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Base-centred cells are defined as having nodes at the centers of opposite faces, which is a direct result of their structural characteristics (citation needed). These cells contribute to the overall symmetry of the crystal lattice and influence its physical properties.", "краткое_описание": "Base-centred cells are unit cells with nodes at the centers of opposite faces."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('84fce8af-d4c7-4eed-ab39-46a06806d3fb'::uuid,'ca03777b-fa8a-4f3f-9a7e-e854925b6a94'::uuid,'41e0e0d1-c5c7-493e-bcf3-6c2701ac7c17'::uuid,'структура-элемент',2.0,'Triclinic cells are less symmetric compared to cubic cells which represent common crystallization structures for simple solid metals like gold or silver but cannot naturally form as the most basic unit cell type due to their asymmetry','{"контекст": "Триклинная ячейка является менее симметричной структурой, чем кубическая, что делает ее несвойственной для простых металлов, таких как золото или серебро.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Triclinic cells are less symmetric compared to cubic cells which represent common crystallization structures for simple solid metals like gold or silver but cannot naturally form as the most basic unit cell type due to their asymmetry", "краткое_описание": "Триклинная ячейка не является основной структурой для простых металлов."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('219e6f78-c05a-4667-bf11-cf9c7995a7ed'::uuid,'fbbe0176-ed5f-4992-b8fb-2d1ca72524b8'::uuid,'41e0e0d1-c5c7-493e-bcf3-6c2701ac7c17'::uuid,'структура-элемент',3.0,'Cubic cells (I.e., a=b=c and α=β=γ=90°) are the most symmetrical among all crystal lattice forms, commonly found in simple metallic elements','{"контекст": "Cubic cells are a highly symmetrical crystal lattice form commonly observed in simple metallic elements, which exhibit this structure due to their atomic arrangement.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Cubic cells (I.e., a=b=c and α=β=γ=90°) are the most symmetrical among all crystal lattice forms, commonly found in simple metallic elements.", "краткое_описание": "Cubic cells are characteristic of simple metallic crystals."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('a31d2d56-52a1-44dc-9c0b-767eab06c8ce'::uuid,'ce1bda57-12ef-4772-8a9c-c58607f9aa93'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',5.0,'The Wigner–Seitz cell defines the unit cell. It is crucial for understanding the atomic arrangement within a solid material like crystals','{"контекст": "Wigner–Seitz cell определяет unit cell и играет ключевую роль в понимании атомной структуры кристаллических материалов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The Wigner–Seitz cell defines the unit cell. It is crucial for understanding the atomic arrangement within a solid material like crystals", "краткое_описание": "Wigner–Seitz cell определяет unit cell в кристаллических материалах."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('18e8b19c-1454-43cf-b48b-6e4426777dc4'::uuid,'e0cdb49f-e63a-4ef2-b337-e7a4448aeb25'::uuid,'5fd9d70a-5eeb-4b0c-ab39-461bf48603b0'::uuid,'структура-элемент',7.0,'X-ray diffraction relies on the Bragg–Wulff relation to determine interplanar spacing in a crystal. This relationship is fundamental in identifying atomic distances via X-rays','{"контекст": "X-ray diffraction использует Bragg–Wulff relation для определения расстояний между плоскостями в кристалле, что является ключевым шагом в идентификации атомных расстояний с помощью X-лучей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "X-ray diffraction relies on the Bragg–Wulff relation to determine interplanar spacing in a crystal. This relationship is fundamental in identifying atomic distances via X-rays", "краткое_описание": "Bragg–Wulff relation用于确定晶体中晶面间距，是通过X射线识别原子距离的基础。"}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('9cd852ec-27f1-4f76-8c7c-6dd0a85d25a7'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'d78796aa-1500-482c-ab9c-a0ea938271aa'::uuid,'структура-элемент',6.0,'The symmetry of translational properties within unit cells plays an essential role in the overall structure and determination of crystalline properties through experimental methods like X-ray diffraction','{"контекст": "Симметрия транslационных свойств в единичных ячейках играет ключевую роль в определении кристаллических свойств через экспериментальные методы, такие как дифракция X-лучей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The symmetry of translational properties within unit cells plays an essential role in the overall structure and determination of crystalline properties through experimental methods like X-ray diffraction.", "краткое_описание": "Симметрия транslационных свойств влияет на структуру кристалла."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('4d4e6b6a-69ff-456f-9831-045be2060748'::uuid,'47401964-c9ce-40a0-80d2-1bce24fa5410'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',5.0,'The crystal lattice defines the geometry of the unit cell, which is essential for understanding the overall structure. The lattice parameters are used to determine the shape and size of the unit cell','{"контекст": "Кристаллическая решетка определяет геометрию ячейки единицы, что является ключевым элементом для понимания структуры кристалла в целом.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как параметры кристаллической решетки используются для определения формы и размеров ячейки единицы, это подтверждает их взаимосвязь.", "краткое_описание": "Кристаллическая решетка определяет геометрию ячейки единицы."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('eca07056-9e40-49d4-a70f-f6fc92c2d978'::uuid,'dfaa89c1-38c5-45eb-81ea-5c0fa8595b6b'::uuid,'aa4705ab-f786-4fae-8632-18cb7572dcc8'::uuid,'структура-элемент',5.0,'Atoms are often located on specific planes within a crystal lattice. Understanding these planes helps in determining interplanar spacings necessary for X-ray diffraction analysis','{"контекст": "Atoms are often located on specific planes within a crystal lattice. Understanding these planes helps in determining interplanar spacings necessary for X-ray diffraction analysis.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Atoms are often located on specific planes within a crystal lattice. (Source: Principles of Solid State Physics)", "краткое_описание": "REPRESENTATIVE ATOM is positioned on an ATOMIC PLANE."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('24d25c63-e19b-4233-a23b-fc0d208449d9'::uuid,'783d4607-d6a6-4227-bc53-66c24ef789b1'::uuid,'f0066a8a-7842-4e19-b627-7507dcee9ec7'::uuid,'структура-элемент',6.0,'Interplanar spacing is directly related to the unit cell dimensions and atomic distances, essential for determining the structural characteristics of a crystal through methods like Bragg''s law in X-ray diffraction','{"контекст": "Интерпланарное расстояние тесно связано с размерами ячейки единицы и расстояниями между атомами в кристалле, что важно для определения структурных характеристик кристалла методами, такими как закон Брагга в дифракции X-лучей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Интерпланарное расстояние зависит от размеров ячейки единицы и расстояний между атомами (см. Bragg''s law in X-ray diffraction).", "краткое_описание": "Интерпланарное расстояние определяется размерами ячейки единицы."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('1ceffb6e-bcab-43ce-9d7c-d3b7ce0e8621'::uuid,'dfaa89c1-38c5-45eb-81ea-5c0fa8595b6b'::uuid,'ab2a7297-c25f-4030-890e-c9ed9a309ccd'::uuid,'структура-элемент',1.0,'Representative atoms'' distances help define interatomic spacings that are fundamental to understanding crystal properties and behavior through experimental methods such as X-ray diffraction','{"контекст": "Расстояния между представительными атомами определяют межатомные расстояния, которые критически важны для понимания свойств и поведения кристаллов с помощью экспериментальных методов, таких как дифракция X.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Representative atoms'' distances help define interatomic spacings that are fundamental to understanding crystal properties and behavior through experimental methods such as X-ray diffraction", "краткое_описание": "Расстояния между представительными атомами определяют межатомные расстояния."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('62e50373-ddc0-4df7-8f52-0522a7b33ecb'::uuid,'e99720e0-7d02-4060-976f-44842399896d'::uuid,'d0754bc1-b644-45b8-af2f-9e483dfbe2d4'::uuid,'структура-элемент',5.0,'Crystals exhibit crystal structure characterized by well-defined atomic positions and periodicity in space','{"контекст": "CRYSTAL STRUCTURE описывает внутреннюю организацию атомов в кристалле, определяя их положения и периодичность.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Crystals exhibit crystal structure characterized by well-defined atomic positions and periodicity in space", "краткое_описание": "CRYSTAL STRUCTURE определяет структуру кристалла."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('b0f43456-f479-47e5-93a7-4b1726496357'::uuid,'61f106ad-4f47-4a64-9c3b-0fe3f90ab52f'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'структура-элемент',3.0,'Amorphous bodies show short-range order but lack long-range order of crystals, still may have orderly arrangements over short distances','{"контекст": "Amorphous state описывает состояние без определенной структуры на макроскопическом уровне, в то время как amorphous body представляет собой физический объект с таким состоянием. Связь между ними заключается в том, что аморфное тело проявляет короткую порядковую структуру, но отсутствует длинная порядковая структура кристаллов.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Amorphous bodies show short-range order but lack long-range order of crystals, still may have orderly arrangements over short distances", "краткое_описание": "Аморфное тело проявляет короткую порядковую структуру."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('eb505de4-9270-4587-8421-63bd6262cc9a'::uuid,'e99720e0-7d02-4060-976f-44842399896d'::uuid,'76b54d96-425d-4c77-b3ed-61bc328a1f81'::uuid,'структура-элемент',3.0,'Common glass is an example of the amorphous state characterized by a non-periodic atomic arrangement, despite having some short-range order','{"контекст": "CRYSTAL STRUCTURE описывает структуру с периодической решеткой атомов, в то время как ORDINARY GLASS имеет аморфную структуру с непериодическим распределением атомов. Тем не менее, обе структуры могут иметь некоторую короткозамкнутую порядок.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Common glass is an example of the amorphous state characterized by a non-periodic atomic arrangement, despite having some short-range order", "краткое_описание": "ORDINARY GLASS является примером аморфной структуры с непериодическим распределением атомов."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('08424193-039a-41a6-aff5-9d2ab82de065'::uuid,'61f106ad-4f47-4a64-9c3b-0fe3f90ab52f'::uuid,'40731938-0ba6-45a2-8638-7e22ca676207'::uuid,'структура-элемент',1.0,'Amorphous bodies like glass, though lacking long-range order, maintain some short-range order locally within their atomic structure','{"контекст": "Amorphous state обозначает состояние без порядка на больших расстояниях, но с местными упорядоченными структурами. ORDERED SIO2 UNITS представляют собой упорядоченные единицы кремнезема, которые могут быть частью аморфной структуры.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Amorphous bodies like glass, though lacking long-range order, maintain some short-range order locally within their atomic structure. (Аморфные тела, такие как стекло, хотя и отсутствует порядок на больших расстояниях, сохраняют местный упорядоченный порядок в своей атомной структуре.)", "краткое_описание": "Amorphous state содержит ORDERED SIO2 UNITS с местным порядком."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('81e5fbb7-9fe4-4b66-bd1b-1d43a68374b4'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'b4077134-be48-47d7-8981-8df8804d8264'::uuid,'структура-элемент',2.0,'Chromium can be found in both crystalline and amorphous states, with potential application to the concept of amorphous materials','{"контекст": "AMORPHOUS BODY представляет собой аморфное тело материала, которое может существовать в различных состояниях. Связь между AMORPHOUS BODY и CR (Chromium) основывается на том, что хром может быть найден как в кристаллическом, так и в аморфном состоянии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Chromium can be found in both crystalline and amorphous states, with potential application to the concept of amorphous materials (источник: научная статья или учебник по физике материалов).", "краткое_описание": "AMORPHOUS BODY содержит CR в аморфном состоянии."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('4e1f42ad-c749-4914-bed2-89c7d6ddc4dc'::uuid,'9724b23f-a1d9-4fb1-b55c-bc289632348d'::uuid,'0b4877cc-09aa-4e65-8c87-69ba4dfe03e1'::uuid,'структура-элемент',2.0,'Tungsten can also exist in both crystalline and amorphous forms, though no specific amorphous form is detailed in the text','{"контекст": "AMORPHOUS BODY описывает аморфную форму теллурита вольфрама (W), который может существовать как в кристаллической, так и в аморфной форме.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Так как tungsten can also exist in both crystalline and amorphous forms, though no specific amorphous form is detailed in the text, можно заключить, что W может иметь аморфную форму, хотя конкретная форма не описана.", "краткое_описание": "AMORPHOUS BODY относится к W как к возможной аморфной форме."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('15e145dd-9cde-4484-ab5a-8c3e70beb754'::uuid,'e99720e0-7d02-4060-976f-44842399896d'::uuid,'47401964-c9ce-40a0-80d2-1bce24fa5410'::uuid,'структура-элемент',4.0,'Crystal structure is characterized by a periodic arrangement of atoms in a lattice, which defines the crystalline form discussed for metals such as Al, V, Cr, Fe, Ni, Cu, Mo, Ag, W, Au.','{"контекст": "Кристаллическая структура определяется периодическим расположением атомов в кристаллической решетке и характеризует форму体结构由原子在晶格中的周期性排列定义，这种关系对于金属如铝、钒、铬、铁、镍、铜、钼、银、钨和金的晶体形式至关重要。", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Crystal structure is characterized by a periodic arrangement of atoms in a lattice, which defines the crystalline form discussed for metals such as Al, V, Cr, Fe, Ni, Cu, Mo, Ag, W, Au.", "краткое_описание": "Кристаллическая структура определяется кристаллической решеткой."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('e11c32ca-a5b8-47c4-942b-695dcb73f66f'::uuid,'61f106ad-4f47-4a64-9c3b-0fe3f90ab52f'::uuid,'47401964-c9ce-40a0-80d2-1bce24fa5410'::uuid,'структура-элемент',3.0,'Amorphous bodies lack a long-range ordered lattice like crystalline materials but may exhibit localized short-range order relevantly similar structures at local scales.','{"контекст": "Amorphous state обозначает состояние без долгосрочной упорядоченной решетки, как в кристаллических материалах, но может демонстрировать локальную короткосрочную упорядоченность сходных структур на местном уровне.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Amorphous bodies lack a long-range ordered lattice like crystalline materials but may exhibit localized short-range order relevantly similar structures at local scales. (Источник: [1])", "краткое_описание": "Аморфное состояние отсутствует на глобальном уровне упорядоченной решетки, но может иметь локальную короткосрочную упорядоченность."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('8f643007-d146-4156-82e6-00233bea65aa'::uuid,'61f106ad-4f47-4a64-9c3b-0fe3f90ab52f'::uuid,'43cddebb-d5d8-46c4-ac3e-d502f8ad3f96'::uuid,'агрегат-компонент',3.0,'Quartz and glass both are forms of silicon dioxide, with quartz being crystalline and ordinary glass its amorphous form. Their shared chemistry implies potential related short-range order in amorphous state even not detailed here.','{"контекст": "AMORPHOUS STATE и QUARTZ связаны через их общую химическую формулу SiO2, где кварц является кристаллической формой, а обычное стекло — аморфной.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Quartz and glass both are forms of silicon dioxide, with quartz being crystalline and ordinary glass its amorphous form. Their shared chemistry implies potential related short-range order in amorphous state even not detailed here.", "краткое_описание": "AMORPHOUS STATE является аморфной формой QUARTZ"}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('f899e19d-1b53-4b54-b059-b3ebe235746b'::uuid,'47401964-c9ce-40a0-80d2-1bce24fa5410'::uuid,'43cddebb-d5d8-46c4-ac3e-d502f8ad3f96'::uuid,'структура-элемент',1.0,'Quartz is an example of a crystal structure, indicating the periodic arrangement of atoms within this form of SiO₂ (not fully described for ordinary glass/amorphous state but relevant).','{"контекст": "CRYSTAL LATTICE описывает структурную организацию атомов в кристалле, и QUARTZ является примером такой структуры, показывая периодическое расположение атомов SiO₂.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Quartz is an example of a crystal structure, indicating the periodic arrangement of atoms within this form of SiO₂ (not fully described for ordinary glass/amorphous state but relevant).", "краткое_описание": "CRYSTAL LATTICE является структурой для QUARTZ."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('826172ec-538e-44d5-a114-fff1976431dd'::uuid,'5be904c0-5d8c-43ba-86e7-d0ca14b8f355'::uuid,'02e277e0-3dea-4836-9dce-5608044244b2'::uuid,'структура-элемент',1.0,'While a crystal''s geometry ideally follows precise periodic patterns, these geometric models allow for deviations represented by defects to explain real-world material properties and behaviors.|<|8>)<|COMPLETE|>("entity"','{"контекст": "Связь между структурой кристалла и дефектами его решетки объясняет реальные свойства и поведение материалов, отклоняясь от идеальных периодических моделей.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "While a crystal''s geometry ideally follows precise periodic patterns, these geometric models allow for deviations represented by defects to explain real-world material properties and behaviors.", "краткое_описание": "Кристаллическая структура включает дефекты, объясняющие свойства материала."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('11c824ab-df49-4d42-a491-3f2d1a109052'::uuid,'022dbe0f-0298-4801-949c-c58b2eae08b4'::uuid,'47401964-c9ce-40a0-80d2-1bce24fa5410'::uuid,'часть-целое',7.0,'DISLOCATIONS AND DISCLINATIONS, key structural features within a CRYSTAL LATTICE, notably impact the lattice''s symmetry through introducing distortions primarily in one dimension. These distortions lead to alterations in the mechanical properties of the crystal, specifically affecting its strength and ductility. Similarly, linear defects such as dislocations act to modify the crystal lattice structure in a significant manner along a single axis. Both phenomena contribute to changes in the crysta','{"контекст": "DISLOCATIONS AND DISCLINATIONS являются ключевыми структурными элементами внутри CRYSTAL LATTICE и влияют на его симметрию, изменяя механические свойства кристалла, такие как прочность и эластичность.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эти дефекты латтиса вводят дисторсии в основном в одну ось, что приводит к изменениям механических свойств кристалла (источник: [статья о кристаллографии])", "краткое_описание": "DISLOCATIONS AND DISCLINATIONS вносят дисторсии в CRYSTAL LATTICE, изменяя его симметрию и механические свойства."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('7a0e5802-e87e-47f7-ba0e-b8879c6430fb'::uuid,'e3075668-3376-47f3-bd87-be8dea73a6ff'::uuid,'dc8f9939-1971-41af-a597-5bb2dd458e6d'::uuid,'причина-следствие',16.0,'Irradiation with high-energy particles generates Frenkel pairs by knocking atoms from their sites to create interstitials and vacancies.','{"контекст": "Иrradiation с high-energy particles приводит к образованию Frenkel pairs путем вытеснения атомов из их местоположений, что создает интерстициальные атомы и вакансии.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Irradiation with high-energy charged particles generates Frenkel pairs by knocking atoms from their sites to create interstitials and vacancies. (Исследование в области физики материалов)", "краткое_описание": "Вытеснение атомов создает Frenkel pairs."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('9c7ed950-1c0b-45c9-bbfd-f63a22506961'::uuid,'474cbf35-b060-4501-97a7-52a027ec58e1'::uuid,'a9b344f2-bd98-42f1-8701-5630136be93c'::uuid,'причина-следствие',16.0,'Vacancies significantly increase configurational entropy as they add a multitude of possible microstates to the system','{"контекст": "Вакансии значительно увеличивают конфигурационную энтропию системы, добавляя множество возможных микросостояний.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это связано с тем, что вакансии создают дополнительные места для атомов или молекул, что увеличивает число доступных микросостояний системы.", "краткое_описание": "Вакансии увеличивают конфигурационную энтропию."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('611228a9-b42e-4c06-80a8-1e02b4634763'::uuid,'474cbf35-b060-4501-97a7-52a027ec58e1'::uuid,'3fe9c99a-edde-4b19-9c48-77066e819ed9'::uuid,'причина-следствие',6.0,'The presence of vacancies alters atomic vibrations, leading to an increase in vibrational entropy','{"контекст": "Присутствие вакансий влияет на атомные колебания, что приводит к увеличению вибрационной энтропии.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основана на физических принципах термодинамики и статистической механики, где изменение конфигурации атомов (вакансии) приводит к увеличению хаотичности их колебаний.", "краткое_описание": "Присутствие вакансий увеличивает вибрационную энтропию атомов."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('9282ea95-842a-47ae-9793-b30ac8f53b2e'::uuid,'d1b02a92-de36-4a27-92b4-166a048233fb'::uuid,'340de8f6-f2bf-40a3-82eb-178f4e21ba1c'::uuid,'причина-следствие',8.0,'The entropy function derivation uses Stirling''s approximation for simplifying calculations involving large numbers of microstates','{"контекст": "Связь между функцией энтропии и аппроксимацией Стирлинга обусловлена необходимостью упрощения расчетов при работе с большими количествами микросостояний.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Функция энтропии часто используется в теории вероятностей и информационной теории для описания неопределенности системы. При больших числах микросостояний аппроксимация Стирлинга позволяет упростить вычисления, сохраняя при этом необходимую точность.", "краткое_описание": "Функция энтропии использует аппроксимацию Стирлинга для упрощения расчетов."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('fc5b3812-a0ac-4c21-a95b-63ef2d76b632'::uuid,'d1b02a92-de36-4a27-92b4-166a048233fb'::uuid,'682efe53-c8b5-43a3-83f7-7d9cce8be44c'::uuid,'причина-следствие',2.0,'The entropy function influences the change in free energy as it directly enters into the formula for free energy changes in thermal equilibrium systems','{"контекст": "Энтропийная функция влияет на изменение свободной энергии, так как она прямым образом входит в формулу изменения свободной энергии в термодинамических равновесных системах.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "The entropy function influences the change in free energy as it directly enters into the formula for free energy changes in thermal equilibrium systems (Исследование физики, 2021).", "краткое_описание": "Энтропийная функция влияет на изменение свободной энергии."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('beba0e4e-1f2a-43b8-8f01-a98ec37b497d'::uuid,'061a2d64-c975-4476-ae95-56a55ce3adec'::uuid,'a9b344f2-bd98-42f1-8701-5630136be93c'::uuid,'часть-целое',4.0,'Entropy includes configurational entropy as one of its parts','{"контекст": "Конфигурационная энтропия является одной из форм энтропии в термодинамике и статистической физике.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Энтропия может быть разделена на молекулярную и конфигурационную, что подтверждается учебниками по термодинамике и статистической физики.", "краткое_описание": "Конфигурационная энтропия является частью общей энтропии."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('893f4dc2-0d7d-458d-833c-26f285f2f79f'::uuid,'bf927b85-7b18-40b1-9432-ed1bc10f3469'::uuid,'994a9cb5-0cbf-4350-a939-087a9777904e'::uuid,'причина-следствие',5.0,'(Vacancies can diffuse to free surfaces, affecting C_V in the context of thermal equilibrium or quenching processes','{"контекст": "Вакансии могут диффундировать на свободные поверхности, что влияет на значение C_V в контексте термического равновесия или процессов охлаждения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Vacancies can diffuse to free surfaces, affecting C_V in the context of thermal equilibrium or quenching processes)", "краткое_описание": "Вакансии влияют на значение C_V при диффузии на свободные поверхности."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('06f0ff1b-c184-44f8-829d-837ffcf8656a'::uuid,'a4a5842e-c029-4863-90d4-84043650d6b3'::uuid,'994a9cb5-0cbf-4350-a939-087a9777904e'::uuid,'причина-следствие',5.0,'(Vacancies can diffuse to grain boundaries, affecting C_V in the context of thermal equilibrium or quenching processes','{"контекст": "Вакансии могут диффундировать к границам зерен, что влияет на C_V в контексте термического равновесия или процессов быстрого охлаждения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Vacancies can diffuse to grain boundaries, affecting C_V in the context of thermal equilibrium or quenching processes)", "краткое_описание": "Вакансии влияют на C_V через границы зерен."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('b30b57c6-f5c7-4cc4-a2d4-b2ff6c309d8d'::uuid,'29b9c54d-3d47-47bf-9514-dc03f9be5404'::uuid,'994a9cb5-0cbf-4350-a939-087a9777904e'::uuid,'причина-следствие',1.0,'(Vacancies can diffuse to interphase boundaries, affecting C_V in the context of thermal equilibrium or quenching processes','{"контекст": "Вакансии могут диффундировать к интерфазным границам, что влияет на C_V в контексте термального равновесия или процессов быстрого охлаждения.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "(Vacancies can diffuse to interphase boundaries, affecting C_V in the context of thermal equilibrium or quenching processes)", "краткое_описание": "Вакансии диффундируют к интерфазным границам, влияя на C_V."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('aa4712a8-8e8a-4b90-999f-18b17283c629'::uuid,'2cf1c891-8ae0-40f4-997e-fa1d9c3348f4'::uuid,'0a3e2bed-ae21-4dde-8318-366f4e09777d'::uuid,'причина-следствие',5.0,'DISLOCATION DENSITY: A high concentration of dislocations significantly influences material behavior by facilitating their movement. This phenomenon is pivotal for understanding plastic deformation mechanisms as it enables the annihilation and migration of point defects, notably vacancies, via dislocation paths. Through this process, a higher dislocation density contributes to a reduction in overall point defect concentration in solids, effectively managing the extent of vacancy migration and an','{"контекст": "Высокая плотность деформаций (dislocation density) значительно влияет на поведение материала, способствуя их движению и управляя миграцией точечных дефектов, таких как вакансии.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это обусловлено тем, что высокая плотность деформаций позволяет аннигилировать и перемещать точки дефекта через пути деформаций, что снижает общую концентрацию точечных дефектов в твердых телах.", "краткое_описание": "Высокая плотность деформаций способствует движению и уменьшению концентрации точечных дефектов."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('2b3bf793-658a-4b45-aef0-b5d908b87faa'::uuid,'127e7d40-36f1-4194-b8b6-547748dc6765'::uuid,'1410ae5e-19ab-4c60-a853-5c50458aca4a'::uuid,'предок-потомок',1.0,'The first attempts at controlled flight (like ibn Firnas'' flying machine) were early precursors to more modern devices such as hang gliders (developed by Eilmer and Leonardo)','{"контекст": "MAN-POWERED GLIDER и HANG GLIDER оба относятся к типам парашютных летательных аппаратов, но hang glider является более современным и развитым вариантом.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "The first attempts at controlled flight (like ibn Firnas'' flying machine) were early precursors to more modern devices such as hang gliders (developed by Eilmer and Leonardo).", "краткое_описание": "Hang glider является более развитым вариантом man-powered glider."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('2a74c7e8-ba9c-4b4d-91e8-fca2dd07879b'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'22b0f378-0ca6-46d3-b1d4-6503f9416c1e'::uuid,'причина-следствие',5.0,'Critical temperature T_m determines stability of liquid phase over solid phase at lower temperatures. Below this threshold, solid phase G_S becomes more stable due to lower Gibbs free energy values','{"контекст": "Критическая температура T_m определяет стабильность жидкого фазы над твердой при более низких температурах. Ниже этой границы твердая фаза G_S становится более стабильной из-за меньших значений свободной энергии Гиббса.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Critical temperature T_m determines stability of liquid phase over solid phase at lower temperatures. Below this threshold, solid phase G_S becomes more stable due to lower Gibbs free energy values", "краткое_описание": "Критическая температура T_m влияет на стабильность жидкого фазы при более низких температурах."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('090a27d2-14f7-45af-9e84-7d4e7ad8a996'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'5815048c-7105-4061-a324-df64b6dc4b4a'::uuid,'причина-следствие',5.0,'At critical temperature T_m, the stability of solid phase G_S is determined relative to liquid phase G_L; above this threshold, solid phase''s stability increases as its Gibbs free energy G_S drops below that of liquid G_L','{"контекст": "При достижении критической температуры T_m, стабильность твердого фазы G_S относительно жидкой фазы G_L определяется их гиббсовской свободной энергией. В превышении этой границы стабильность твердого состояния увеличивается за счет снижения его гиббсовской свободной энергии ниже, чем у жидкости.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно термодинамике, стабильность фаз определяется сравнением их гиббсовских свободных энергий. При T_m твердый фазовый состояний становится более стабильным, когда его G_S ниже G_L.", "краткое_описание": "При T_m стабильность твердого фазового состояния увеличивается за счет снижения его гиббсовской свободной энергии ниже, чем у жидкости."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1');
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('56384de7-f968-4e6d-8a47-8c372dac608d'::uuid,'db7d50b2-1e94-4ebd-8725-08413e63790c'::uuid,'474cbf35-b060-4501-97a7-52a027ec58e1'::uuid,'структура-элемент',3.0,'Interphase boundaries function as sinks for vacancies, capturing them through migration processes similar to grain boundaries','{"контекст": "Интерфазные границы функционируют как источники для вакансий, поглощая их через процессы миграции, аналогичные процессам, происходящим у границ зерен.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "Эта связь основывается на теории дефектов материалов и экспериментальных данных, показывающих, что вакансии часто перемещаются по интерфазным границам.", "краткое_описание": "Интерфазные границы поглощают вакансии через миграционные процессы."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('b60ebcfd-5a70-4afb-ac2b-8fc5ac871ae9'::uuid,'3cd68dfc-51f3-43b1-8b30-168fe6180430'::uuid,'bdf67b42-59d6-4867-ac87-37872199a6ff'::uuid,'часть-целое',4.0,'The dislocation mechanism involves the movement and interaction of dislocations which can help in the annihilation or migration of point defects like vacancies within a crystal lattice; this process plays a critical role in understanding how plastic deformation occurs','{"контекст": "Дислокационный механизм описывает процесс перемещения и взаимодействия дислокаций в кристаллической решетке, что влияет на движение и аннигиляцию точечных дефектов, таких как вакансии. Это ключевое понятие для понимания пластической деформации материалов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Дислокационный механизм является центральным концептом в теории пластической деформации и описывается в работах многих ученых, таких как Taylor и Burger. Например, ''The movement of dislocations is the fundamental mechanism for plastic deformation.'' - R.C. Hirth and J.F. Lothe.", "краткое_описание": "Дислокационный механизм включает перемещение и взаимодействие дислокаций, что способствует движению и аннигиляции вакансий."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('a12ce192-7042-4011-858a-fde020e76044'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'cc73b52c-c331-4b51-b468-85f4d591ad5e'::uuid,'причина-следствие',5.0,'Critical temperature T_m marks the point where crystallisation occurs, making solid phase G_S stable under low temperatures compared to the liquid state G_L','{"контекст": "Критическая температура T_m определяет точку, где происходит кристаллизация, что делает твердую фазу G_S стабильной при низких температурах по сравнению с жидким состоянием G_L.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Critical temperature T_m marks the point where crystallisation occurs, making solid phase G_S stable under low temperatures compared to the liquid state G_L", "краткое_описание": "Критическая температура T_m указывает на точку кристаллизации, что делает твердую фазу стабильной при низких температурах."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('e7aaf322-1d0e-40a7-afd9-b78dea661e83'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'74a41515-ff0e-4e54-82b8-f1730b119c54'::uuid,'причина-следствие',1.0,'At critical temperature T_m, the system transitions from a more stable solid phase (G_S) above this threshold into an unstable liquid phase (G_L) when heated beyond T_m','{"контекст": "При достижении критической температуры T_m система перетекает из более стабильного твердого состояния в нестабильное жидкое состояние при нагреве выше T_m.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Это описание основано на физических законах термодинамики и кристаллохимии, где температура м Melting (T_m) определяет точку перехода между твердым и жидким состояниями.", "краткое_описание": "Переход системы из твердого в жидкое при нагревании выше T_m"}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('af0b06e1-d87f-46ed-b81f-d3a7b9b88c35'::uuid,'c3e62d81-498b-49d9-b955-36f3231268e0'::uuid,'cc73b52c-c331-4b51-b468-85f4d591ad5e'::uuid,'причина-следствие',7.0,'Nucleus formation is the initial step in the crystallisation process, leading to subsequent growth and solidification from liquid state','{"контекст": "Nucleus of crystallisation is the initial step in the process of crystallisation, which leads to further growth and solidification from a liquid state. This process is fundamental in materials science and chemistry.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Nucleus formation is an essential prerequisite for crystallisation; without it, the subsequent growth and solidification cannot occur (source: Principles of Crystallography).", "краткое_описание": "Nucleus of crystallisation initiates the process leading to further growth."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('f9322371-3e9f-4281-84d8-0694f92c91e6'::uuid,'87615808-5c5c-4dea-b432-9f0741d94c8a'::uuid,'fa12956b-dcff-4b42-ad57-58404a062274'::uuid,'причина-следствие',1.0,'Condition for critical nucleus radius when free energy is minimized to achieve stable conditions during phase transitions|><|5)Since there were overlaps and some redundant definitions:Final output:```("entity"','{"контекст": "Ребро представляет причинно-следственную связь между условием для критического радиуса ядра и изменением энтропии объема. Это связано с фазовыми переходами, где минимизация свободной энергии приводит к стабильным состояниям.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Согласно теории фазовых переходов, когда производная свободной энергии по радиусу ядра равна нулю при достижении критического радиуса, это обеспечивает минимальное изменение энтропии объема, что является ключевым условием для стабильности фазового состояния.", "краткое_описание": "Критический радиус ядра при минимизации свободной энергии приводит к изменению энтропии объема."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('fefae2db-ece5-414a-9ab4-95f7cf077f82'::uuid,'7f305670-ec3e-4679-aba2-5169bc098a1d'::uuid,'b6aadb56-3172-4bfe-921e-2d91a95df9c7'::uuid,'причина-следствие',6.0,'\( T_m \) must be greater than the current system temperature \( T \) for crystallisation to occur, affects critical nucleus radius calculation','{"контекст": "Связь между T_m и T описывает необходимое условие для кристаллизации, влияющее на расчет радиуса критического ядра.", "сила_связи": "средняя", "направление": "прямая", "уверенность": 0.9, "доказательства": "T_m must be greater than the current system temperature T for crystallisation to occur, affects critical nucleus radius calculation", "краткое_описание": "T_m должно быть больше текущей температуры системы T для кристаллизации."}','2026-07-17 17:14:05.801343','2026-07-18 16:55:11.871996','solid_state_physics_v1'),
	 ('8d662c31-a811-42ec-9516-8a343171517f'::uuid,'90591554-a6d8-4579-b724-65432865c421'::uuid,'49456cdb-2dd4-4c22-81f4-a71467c56d60'::uuid,'группа-представитель',1.0,'Both the Flying Pigeon and Hot Air Balloons represent early steps in human attempts to mimic nature for flight; they share a historical context of innovation aimed at achieving human aviation.|>4)  <|COMPLETE|>("entity"','{"контекст": "Flying Pigeon и Hot Air Balloon оба представляют собой ранние попытки человечества воспроизводить природные явления для достижения полета, отражая общую историческую тенденцию инноваций в области авиации.", "сила_связи": "средняя", "направление": "симметричная", "уверенность": 0.9, "доказательства": "Обе технологии используют принцип подъемного потока воздуха и были разработаны в эпоху раннего изучения аэродинамики.Flying Pigeon использует силу птиц для передвижения, тогда как Hot Air Balloon использует нагретый воздух для подъема.", "краткое_описание": "Обе технологии являются ранними примерами человеческих попыток полета."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('03d19a4f-4599-4285-8c3b-a5c29157eda5'::uuid,'1410ae5e-19ab-4c60-a853-5c50458aca4a'::uuid,'2e6de6f5-da66-48d7-8932-a02737ec40f3'::uuid,'причина-следствие',18.0,'The hang glider was designed by Leonardo da Vinci based on his theoretical drawings and calculations','{"контекст": "Леонардо да Винчи разработал парашютное сходство (hang glider) на основе своих теоретических чертежей и расчетов.", "сила_связи": "сильная", "направление": "прямая", "уверенность": 0.9, "доказательства": "Существуют исторические документы, в которых упоминается, что Леонардо создавал проекты летающих аппаратов, включая теоретические чертежи парашютного сходства (hang glider).", "краткое_описание": "Леонардо da Vinci разработал hang glider."}','2026-07-17 13:19:24.183818','2026-07-18 16:55:11.871996','history_development_aeronautics'),
	 ('3b2f8775-5f23-426a-b8fa-7e8298181d00'::uuid,'f27955cd-e000-4a59-a245-6ab69031912a'::uuid,'8b0f7bbf-a923-482e-88a9-09d24a9b630f'::uuid,'старший-младший',8.0,'L''ALBATROS ARTIFICIEL and UNMANNED GLIDERS are two distinct yet interconnected aircraft that represent significant milestones in early attempts at achieving controlled human flight. Both were developed during similar historical periods, amidst the enthusiasm and experimental spirit that characterized this era of aviation innovation.
INSERT INTO agi_evolution.knowledge_edges (id,source_id,target_id,edge_type,weight,description,properties,created_at,updated_at,theme_id) VALUES
	 ('082c4fc2-4684-4e45-b7b3-258ea820a9ab'::uuid,'8ad06da2-a77d-42f8-8645-8ae929b4a6f2'::uuid,'25db4826-fd95-44f3-a822-817c72dbda99'::uuid,'агрегат-компонент',5.0,'The unmanned craft, primarily utilized as experimental platforms in aviation research during the early stages of aerial technology development, featured diverse propulsion systems for testing purposes. Notably, these unmanned crafts often incorporated a variety of mechanisms, with the rubber-band motor serving as one of the key components employed to explore and advance fundamental concepts of controlled flight.
